INSERT INTO public.tutorprofiles VALUES ('d39d256c-2fec-44d7-baf5-e26eb270ce4c', 'Sinh viên năm 4 Dược - ĐH Y Dược TP.HCM. Dạy Sinh Học cấp 3 và ôn thi ĐH khối B. Nắm vững kiến thức sinh học phân tử, di truyền học – nội dung hay ra thi nhất.', 'Sinh Học cấp 3 & Ôn thi ĐH | Sinh viên Y Dược', NULL, 'Dược sĩ đại học (đang học năm 4) - ĐH Y Dược TP.HCM', 10, 8, '3 năm dạy Sinh cấp 3. 8 học viên vào Y Dược trong mùa thi gần nhất.', 'TP.HCM', 'quan-3', 'active', true, 4.6, 26, 290, '2026-06-09 10:09:36.038244', '2026-06-09 10:09:36.038244', NULL, 'standard', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'offline');
INSERT INTO public.tutorprofiles VALUES ('df16d9a9-c8e4-4e7c-bde8-b3920bec8016', 'Kỹ sư Xây dựng - ĐH Kiến trúc TP.HCM. Dạy Toán cấp 2. Thích hướng dẫn học sinh giải bài theo nhiều cách. Học phí hợp lý, phù hợp gia đình có thu nhập trung bình.', 'Toán cấp 2 | Học phí hợp lý, nhiều cách giải', NULL, 'Kỹ sư Xây dựng - ĐH Kiến trúc TP.HCM', 4, 2.8, '3 năm dạy Toán cấp 2 tại TP.HCM.', 'TP.HCM', 'binh-chanh', 'active', true, 4, 12, 130, '2026-06-09 10:09:36.485489', '2026-06-09 10:09:36.485489', NULL, 'standard', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'both');
