INSERT INTO public.tutorprofiles VALUES ('35512af0-0ebd-46f1-b88c-c76e23020da8', 'Giáo viên tiểu học 4 năm kinh nghiệm. Dạy Tiếng Anh lớp 1-5 theo chương trình chuẩn Bộ GD. Trẻ em thích học vì cô dùng game và flashcard để dạy từ vựng.', 'Tiếng Anh Tiểu học | Game & Flashcard', NULL, 'Cử nhân Tiểu học Anh ngữ - ĐH Văn Hiến', 4, 3, '4 năm dạy tiếng Anh tiểu học tại TP.HCM.', 'TP.HCM', 'quan-7', 'active', true, 4.5, 21, 260, '2026-06-09 10:09:37.286688', '2026-06-09 10:09:37.286688', NULL, 'standard', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'both');
INSERT INTO public.tutorprofiles VALUES ('08b9dd4c-5785-4863-98ad-1d20d477a19b', 'Cử nhân Hóa học - ĐH KHTN TP.HCM. 5 năm dạy Hóa cấp 2 và cấp 3. Giỏi hóa hữu cơ và vô cơ, cách học theo phương trình hóa học có hệ thống.', 'Hóa Học cấp 2 & 3 | Hệ thống theo phương trình', NULL, 'Cử nhân Hóa học - ĐH KHTN TP.HCM', 4, 3.1, '5 năm dạy Hóa. Học sinh thi đậu nhiều trường ĐH khối A1.', 'TP.HCM', 'tp-thu-duc', 'active', true, 4.3, 29, 350, '2026-06-09 10:09:38.216043', '2026-06-09 10:09:38.216043', NULL, 'standard', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'offline');
INSERT INTO public.tutorprofiles VALUES ('947c315a-bb22-4977-b01a-c3238db23f43', 'Cử nhân Sư phạm Toán - ĐHSP TP.HCM. 8 năm kinh nghiệm luyện thi THPT Quốc Gia môn Toán. Tỷ lệ học sinh đạt 8+ điểm là 85%. Phương pháp dạy logic, hệ thống theo dạng bài.', 'Chuyên luyện thi Toán THPT - 8 năm kinh nghiệm', NULL, 'Đại học Sư phạm TP.HCM - Cử nhân Toán học', 4, 3.8, '8 năm dạy Toán cấp 3. Đã dạy hơn 200 học sinh, 85% đạt điểm 8+. Từng là giáo viên trợ giảng tại Trường THPT chuyên Lê Hồng Phong.', 'TP.HCM', 'quan-3', 'active', true, 4.9, 87, 1240, '2026-06-09 10:08:28.37808', '2026-06-09 10:08:28.37808', NULL, 'premium', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'offline');
INSERT INTO public.tutorprofiles VALUES ('4a544ed1-2f8b-4d0b-9db9-4302ff5dd7f3', 'IELTS 8.5. Thạc sĩ Ngôn ngữ Anh - ĐH KHXH&NV. Chuyên luyện IELTS từ 6.0 lên 7.5+. Học viên thi đậu vào các trường ĐH nước ngoài (Úc, Canada). Lớp tối đa 1 kèm 1.', 'IELTS 8.5 – Luyện thi IELTS, giao tiếp chuyên sâu', NULL, 'Thạc sĩ Ngôn ngữ Anh - ĐH KHXH&NV TP.HCM', 4, 3.9, '6 năm luyện IELTS 1-1. Hơn 150 học viên đạt band 6.5+. 30 học viên đạt 7.5+.', 'TP.HCM', 'quan-1', 'active', true, 4.8, 63, 890, '2026-06-09 10:08:29.71224', '2026-06-09 10:08:29.71224', NULL, 'premium', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'offline');
