INSERT INTO public.tutorprofiles VALUES ('e90400be-c8c8-48b3-b7dc-612c896727c1', 'Cử nhân Ngữ văn - ĐH Sư phạm TP.HCM. Chuyên dạy Văn cấp 2 và cấp 3. Đặc biệt giỏi hướng dẫn viết văn nghị luận, phân tích tác phẩm. Lớp nhỏ (1-2 học sinh), chú trọng cá nhân hóa.', 'Ngữ Văn cấp 2 & 3 | Nghị luận - Phân tích', NULL, 'Cử nhân Sư phạm Ngữ văn - ĐH Sư phạm TP.HCM', 4, 3.6, '5 năm dạy Văn. Học sinh thi HSG cấp quận 2 lần. Nhiều em vào ĐH Nhân văn, Sư phạm.', 'TP.HCM', 'go-vap', 'active', true, 4.7, 41, 510, '2026-06-09 10:09:24.183503', '2026-06-09 10:09:24.183503', NULL, 'pro', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'both');
