INSERT INTO public.tutorprofiles VALUES ('97c6c385-fb22-4e11-88cd-a8be6dfb7583', 'Hướng dẫn học sinh kỹ năng đọc bản đồ, phân tích số liệu và khai thác tối đa Atlat để ăn trọn điểm môn Địa. Khóa học được thiết kế ngắn gọn, tập trung trọng tâm ôn thi tốt nghiệp THPT. Thích hợp cho các sĩ tử cần ôn luyện cấp tốc.', 'Gia sư Địa Lý - Khai thác hiệu quả Atlat Địa lý VN', NULL, 'Đại học Sư phạm TP.HCM - Cử nhân Sư phạm Địa lý', NULL, NULL, '5 năm giảng dạy tại trường THCS và làm gia sư tại Biên Hòa.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.6, 22, 160, '2026-06-17 22:47:52.425592', '2026-06-17 22:47:52.425592', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('1d937e23-f2d6-475a-85a4-c1bf6ccf6b49', 'Chuyên dạy kèm cho học sinh mất gốc, sợ học Toán hoặc mất tập trung. Tôi áp dụng các trò chơi trí tuệ và bài toán thực tế giúp các em tìm lại hứng thú học tập. Sự kiên nhẫn và thấu hiểu tâm lý trẻ là thế mạnh lớn nhất của tôi.', 'Gia sư Toán Tiểu học và THCS - Kiên nhẫn, vững nền tảng', NULL, 'Đại học Sài Gòn - Sư phạm Tiểu học', NULL, NULL, '3 năm kinh nghiệm kèm cặp học sinh tiểu học và chuẩn bị vào lớp 6.', 'Hà Nội', 'Hai Bà Trưng', 'active', true, 4.8, 31, 210, '2026-06-17 22:47:52.577264', '2026-06-17 22:47:52.577264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('f7bbc3b3-aa3b-4d3f-b7e8-77b30af3c891', 'Học tiếng Anh chuẩn bản xứ thông qua phản xạ tự nhiên và ngữ âm chuẩn. Tôi tập trung xây dựng nền tảng ngữ pháp vững chắc kết hợp luyện đề thi vào 10 sát với cấu trúc thực tế của Bộ Giáo dục. Tương tác 100% bằng tiếng Anh nếu phụ huynh yêu cầu.', 'Tiếng Anh trẻ em và ôn thi vào lớp 10 công lập', NULL, 'Đại học Ngoại ngữ ĐHQG Hà Nội - Sư phạm Tiếng Anh', NULL, NULL, '4 năm dạy học tại hệ thống trường quốc tế và gia sư tại nhà.', 'TP.HCM', 'Quận 3', 'active', true, 4.7, 40, 280, '2026-06-17 22:47:52.734063', '2026-06-17 22:47:52.734063', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('18e828f1-9ca6-47a3-9c23-36c7304617df', 'Khóa học tập trung giải các bộ đề thi thử của các trường chuyên trên cả nước. Tôi cung cấp phương pháp loại trừ đáp án nhanh và kỹ thuật bấm máy tính Casio tối ưu cho môn Vật lý. Cam kết đồng hành cùng học sinh đến ngày thi cuối cùng.', 'Luyện thi đại học Vật Lý cấp tốc hiệu quả cao', NULL, 'Đại học Bách khoa Hà Nội - Kỹ sư Vật lý kỹ thuật', NULL, NULL, '7 năm kinh nghiệm luyện thi, có nhiều học sinh đỗ trường top đầu.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.9, 88, 490, '2026-06-17 22:47:52.885197', '2026-06-17 22:47:52.885197', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('d7e481d0-5674-4231-bd5d-399b702dbf69', 'Phương pháp giảng dạy từng bước một, không nhảy cóc kiến thức giúp học sinh hiểu rõ bản chất phản ứng. Tôi thiết kế hệ thống bài tập tự luyện từ cực dễ đến trung bình để học sinh xây dựng lại sự tự tin. Thân thiện, coi học sinh như người em trong nhà.', 'Xóa tan nỗi sợ môn Hóa học từ lớp 8 đến lớp 11', NULL, 'Đại học Sư phạm Đà Nẵng - Cử nhân Sư phạm Hóa học', NULL, NULL, '3 năm dạy kèm các nhóm học sinh yếu, mất căn bản môn Hóa.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.5, 14, 110, '2026-06-17 22:47:53.035536', '2026-06-17 22:47:53.035536', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('828da2c0-e540-4c42-86fc-e4917b2209da', 'Dành cho các bạn học sinh chuyên Toán hoặc sinh viên đại học đang gặp khó khăn với môn Toán cao cấp, Đại số tuyến tính. Bài giảng logic, nghiêm túc và có chiều sâu học thuật cao. Sẵn sàng giải đáp mọi thắc mắc bài tập qua Zalo 24/7.', 'Gia sư Toán cao cấp và Giải tích chuyên sâu', NULL, 'Đại học Bách khoa TP.HCM - Kỹ sư Khoa học Máy tính', NULL, NULL, '4 năm trợ giảng tại trường đại học và gia sư Toán nâng cao.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.6, 25, 195, '2026-06-17 22:47:53.181383', '2026-06-17 22:47:53.181383', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('08b2da01-4290-4c78-829a-a6ef990b85b2', 'Nghiêm túc, chỉn chu trong từng bài viết của học sinh. Tôi chú trọng rèn luyện kỹ năng phân tích luận điểm, tư duy phản biện và cách sử dụng từ ngữ sắc bén, giàu cảm xúc. Rất phù hợp với những học sinh có mục tiêu thi vào các trường chuyên Văn.', 'Gia sư Ngữ Văn - Ôn thi vào chuyên và THPT', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG TP.HCM - Ngành Văn học', NULL, NULL, '5 năm dạy kèm chuyên Văn và chấm bài thi thử cho các trung tâm.', 'Hà Nội', 'Đống Đa', 'active', true, 4.8, 37, 260, '2026-06-17 22:47:53.332278', '2026-06-17 22:47:53.332278', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('a8e3b5d7-fb6f-49dc-a7b6-c6e0c7d0423a', 'Lấy học sinh làm trung tâm, khuyến khích các em tự tìm tòi dưới sự định hướng của giáo viên. Tôi sử dụng nhiều video mô phỏng 3D về tế bào và cơ thể sống để bài học trở nên trực quan sinh động nhất. Cam kết cải thiện điểm số đáng kể sau một học kỳ.', 'Gia sư Sinh học THCS & THPT - Học nhẹ nhàng, thi điểm cao', NULL, 'Đại học Quốc tế ĐHQG TP.HCM - Kỹ thuật Sinh học', NULL, NULL, '3 năm làm nghiên cứu viên phòng thí nghiệm và gia sư bán thời gian.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.7, 18, 140, '2026-06-17 22:47:53.487192', '2026-06-17 22:47:53.487192', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('28db456e-5a98-4a70-92e9-631e98dddbae', 'Chào các bậc phụ huynh và các em học sinh, mình là Trần Minh Công, giáo viên môn Vật lý chuyên gia sư cho khối lớp 7 và 8. Với phương pháp giảng dạy tập trung vào bản chất hiện tượng và tư duy logic, mình sẽ giúp các em nắm vững kiến thức, tự tin giải quyết các dạng bài tập từ cơ bản đến nâng cao mà không còn cảm thấy áp lực.
INSERT INTO public.tutorprofiles VALUES ('71d7af05-4415-4cc7-a277-cce1ffbfbfdc', 'Với 5 năm kinh nghiệm đứng lớp và gia sư, tôi luôn áp dụng phương pháp tư duy logic thay vì học vẹt. Các bài giảng được thiết kế cá nhân hóa theo học lực của từng em để đảm bảo tiến bộ nhanh nhất. Tôi cam kết giúp học sinh mất gốc lấy lại căn bản trong vòng 1 tháng.', 'Gia sư chuyên Toán Chuyên và Luyện thi THPT Quốc gia', NULL, 'Đại học Khoa học Tự nhiên ĐHQG TP.HCM - Cử nhân Toán học', NULL, NULL, '5 năm kinh nghiệm gia sư tự do và luyện thi tại các trung tâm lớn.', 'TP.HCM', 'Quận 3', 'active', true, 4.8, 42, 320, '2026-06-17 22:47:51.33691', '2026-06-17 22:47:51.33691', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('49719ae0-576e-42bc-8e69-616c445d9211', 'Sở hữu chứng chỉ IELTS 8.5 cùng phong cách giảng dạy năng động, truyền cảm hứng. Tôi tập trung tối ưu hóa hai kỹ năng Nói và Viết thông qua các chủ đề thực tế đời sống. Lớp học luôn vui vẻ, giảm áp lực tâm lý cho học viên.', 'Chuyên gia luyện thi IELTS và Tiếng Anh giao tiếp', NULL, 'Đại học Ngoại thương Hà Nội - Cử nhân Kinh tế đối ngoại', NULL, NULL, '3 năm giảng dạy tại trung tâm Anh ngữ và 2 năm gia sư 1 kèm 1.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.9, 65, 450, '2026-06-17 22:47:51.503412', '2026-06-17 22:47:51.503412', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('80cd2635-1522-487b-bb27-74a4bea5e368', 'Tôi biến các công thức Vật Lý khô khan thành những hiện tượng gần gũi trong cuộc sống hàng ngày. Phương pháp này giúp học sinh nhớ lâu và hiểu sâu bản chất vấn đề. Thích hợp cho cả học sinh cần lấy gốc và học sinh giỏi muốn luyện đề chuyên sâu.', 'Gia sư Vật Lý cấp 3 - Vui vẻ, thực tế, dễ hiểu', NULL, 'Đại học Bách khoa Đà Nẵng - Kỹ sư Điện tử Viễn thông', NULL, NULL, '4 năm kinh nghiệm dạy kèm Vật lý lớp 10, 11, 12.', 'Hà Nội', 'Nam Từ Liêm', 'active', true, 4.6, 28, 180, '2026-06-17 22:47:51.662864', '2026-06-17 22:47:51.662864', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('c92310fe-f0e5-457a-9b11-38a9032ca77f', 'Chuyên trị các dạng bài tập đồ thị và chuỗi phản ứng Hóa học phức tạp. Tôi hướng dẫn học sinh các mẹo giải nhanh trắc nghiệm bằng sơ đồ tư duy giúp tiết kiệm 50% thời gian làm bài. Kiên nhẫn, tận tâm và sát sao tình hình học tập của từng em.', 'Gia sư Hóa Học - Luyện thi Đại học điểm 8+', NULL, 'Đại học Sư phạm TP.HCM - Cử nhân Sư phạm Hóa học', NULL, NULL, '6 năm là giáo viên tự do và cộng tác viên các trang học trực tuyến.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.7, 51, 390, '2026-06-17 22:47:51.815434', '2026-06-17 22:47:51.815434', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('7b32a048-d79d-4574-8c9b-9f0423f87914', 'Văn học không phải là học thuộc lòng văn mẫu mà là cách cảm nhận và tư duy sáng tạo. Tôi hướng dẫn học sinh phương pháp lập luận logic, xây dựng luận điểm rõ ràng để đạt điểm cao trong các kỳ thi. Nhận dạy từ lớp 6 đến lớp 12.', 'Khơi nguồn đam mê Ngữ Văn và luyện viết luận', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Sư phạm Ngữ văn', NULL, NULL, '2 năm thực tập tại trường THPT và 3 năm làm gia sư tại nhà.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.5, 19, 120, '2026-06-17 22:47:51.964338', '2026-06-17 22:47:51.964338', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('8a00edc4-c52f-4f10-8bdd-dc21673841a9', 'Hệ thống hóa kiến thức Sinh học bằng sơ đồ tư duy trực quan, sinh động. Tôi tập trung giải quyết triệt để các dạng bài tập di truyền biến dị từ cơ bản đến nâng cao. Phong cách giảng dạy nhẹ nhàng, thân thiện, tạo không gian thoải mái cho học sinh đặt câu hỏi.', 'Gia sư Sinh Học - Ôn thi THPT và thi đánh giá năng lực', NULL, 'Đại học Y Dược Cần Thơ - Bác sĩ Đa khoa', NULL, NULL, '4 năm dạy kèm môn Sinh cho học sinh khối B ôn thi ngành Y Dược.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.7, 34, 240, '2026-06-17 22:47:52.116532', '2026-06-17 22:47:52.116532', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('b214c91e-ec24-4290-a837-bd4c5f764b92', 'Học Lịch sử qua những câu chuyện kể và dòng thời gian trực quan thay vì học thuộc lòng máy móc. Tôi giúp học sinh hiểu rõ bản chất, nguyên nhân và kết quả của các sự kiện lịch sử để làm tốt bài thi trắc nghiệm. Phương pháp dạy sáng tạo, lôi cuốn.', 'Biến Lịch Sử thành những câu chuyện sống động', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG Hà Nội - Ngành Lịch sử', NULL, NULL, '3 năm nghiên cứu và giảng dạy tự do môn Lịch sử.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.4, 15, 95, '2026-06-17 22:47:52.269397', '2026-06-17 22:47:52.269397', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('1c08d485-228f-4608-ad73-8a6d28b94540', 'Phương pháp ôn tập cuốn chiếu, học đến đâu chắc đến đấy bằng hệ thống câu hỏi trắc nghiệm thực tế. Tôi giúp học sinh ghi nhớ các mốc thời gian quan trọng một cách tự nhiên thông qua sơ đồ liên kết lịch sử thế giới và lịch sử Việt Nam.', 'Gia sư Lịch Sử - Ôn thi tốt nghiệp cam kết trên 8 điểm', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Lịch sử', NULL, NULL, '8 năm dạy học tại trường THPT và luyện thi khối C.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.9, 74, 410, '2026-06-17 22:47:53.64069', '2026-06-17 22:47:53.64069', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('4e53976b-9960-4d06-a97b-cb5782b99fc0', 'Giảng dạy nhiệt tình, phong cách hiện đại và luôn cập nhật những số liệu kinh tế - xã hội mới nhất. Tôi giúp học sinh làm quen với mọi dạng biểu đồ và câu hỏi phân tích trong đề thi đánh giá năng lực ĐHQG. Thích hợp cho cả học sinh khối C và D.', 'Gia sư Địa Lý lý thú - Hiểu sâu, nhớ lâu', NULL, 'Đại học Sư phạm Đà Nẵng - Địa lý học', NULL, NULL, '4 năm dạy kèm tại các trung tâm gia sư uy tín tại Đà Nẵng.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.5, 20, 130, '2026-06-17 22:47:53.795735', '2026-06-17 22:47:53.795735', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('00d07ed8-5455-49ab-9e94-a6b4442d4efb', 'Lớp học định hướng chuyên sâu dành cho học sinh có mục tiêu thi vào các trường THPT chuyên hoặc thi học sinh giỏi cấp tỉnh/thành phố. Giáo trình nâng cao tập trung vào ngữ pháp nâng cao, từ vựng theo chủ đề khó và kỹ năng viết luận học thuật sắc bén.', 'Gia sư Tiếng Anh - Ôn thi vào Chuyên và Học sinh giỏi', NULL, 'Đại học Ngoại ngữ - Đại học Đà Nẵng - Ngôn ngữ Anh', NULL, NULL, '6 năm kinh nghiệm luyện đội tuyển học sinh giỏi môn Tiếng Anh.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.9, 58, 380, '2026-06-17 22:47:53.950256', '2026-06-17 22:47:53.950256', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('0a0bc91b-f084-4fc6-9833-6de6f363a6c7', 'Từng là học sinh mất gốc Toán nên tôi hiểu rất rõ những khó khăn mà các em gặp phải. Phương pháp giảng dạy của tôi tập trung vào việc đơn giản hóa các định lý phức tạp thành quy tắc dễ nhớ. Cam kết giúp học sinh tiến bộ rõ rệt chỉ sau 8 buổi học.', 'Gia sư Toán THPT - Lấy gốc siêu tốc và luyện đề thi', NULL, 'Đại học Cần Thơ - Sư phạm Toán học', NULL, NULL, '4 năm dạy kèm gia sư và giảng dạy tại trung tâm luyện thi Cần Thơ.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.7, 39, 270, '2026-06-17 22:47:54.10401', '2026-06-17 22:47:54.10401', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('68762cd2-f3da-4b2e-ad8f-ccb8fb15e336', 'Giúp học sinh rèn luyện kỹ năng viết câu đúng ngữ pháp, diễn đạt trôi chảy và biết cách quan sát thế giới xung quanh để làm bài văn miêu tả, tự sự sinh động. Phong cách dạy nhẹ nhàng, tạo không gian mở để học sinh tự tin nói lên suy nghĩ cá nhân.', 'Gia sư Ngữ Văn Tiểu học và THCS - Sáng tạo, cảm xúc', NULL, 'Đại học Sư phạm TP.HCM - Cử nhân Giáo dục Tiểu học', NULL, NULL, '3 năm giảng dạy tại trường quốc tế và làm gia sư tự do.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.6, 17, 115, '2026-06-17 22:47:54.253958', '2026-06-17 22:47:54.253958', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('a5979f7c-7f12-4b76-aa57-1a2c6fed41eb', 'Khóa học tập trung tối ưu hóa thời gian làm bài trắc nghiệm thông qua các phương pháp độc quyền: Vòng tròn lượng giác nâng cao, giải nhanh đồ thị dòng điện xoay chiều. Thích hợp cho học sinh hướng tới mục tiêu điểm 9, 10 trong kỳ thi THPTQG.', 'Chuyên gia giải nhanh trắc nghiệm Vật Lý 12', NULL, 'Đại học Bách khoa TP.HCM - Kỹ sư Điện - Điện tử', NULL, NULL, '5 năm kinh nghiệm luyện thi đại học môn Vật lý tại các trung tâm uy tín.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.8, 46, 310, '2026-06-17 22:47:54.408301', '2026-06-17 22:47:54.408301', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('1a7692d8-9f4f-49fc-a640-6644d6a9a0ca', 'Nhận dạy kèm mọi trình độ từ mất gốc đến nâng cao. Giáo trình được biên soạn riêng theo năng lực bẩm sinh của học sinh, kết hợp kiểm tra định kỳ hàng tuần để báo cáo kết quả cho phụ huynh. Đảm bảo đạt điểm số mong muốn trong các kỳ thi học kỳ.', 'Gia sư Hóa Học THCS & THPT - Tận tâm, trách nhiệm', NULL, 'Đại học Khoa học Tự nhiên ĐHQG Hà Nội - Cử nhân Hóa học', NULL, NULL, '4 năm làm gia sư tại nhà và ôn thi tốt nghiệp THPT.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.6, 23, 175, '2026-06-17 22:47:54.559619', '2026-06-17 22:47:54.559619', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('3756591c-d865-45e5-95d0-306f61fdd102', 'Phương pháp phản xạ ngôn ngữ hiện đại giúp học viên tự tin nói tiếng Anh sau 3 tháng. Tôi tập trung sửa lỗi phát âm, ngữ điệu chuẩn Mỹ và cung cấp các chiến thuật làm bài thi TOEIC đạt điểm cao một cách tối ưu nhất. Nhận dạy kèm tại nhà hoặc online.', 'Tiếng Anh giao tiếp mọi lứa tuổi & Luyện thi TOEIC', NULL, 'Đại học Hà Nội - Ngôn ngữ Anh', NULL, NULL, '3 năm giảng dạy tại trung tâm tiếng Anh và 2 năm gia sư doanh nghiệp.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.7, 32, 220, '2026-06-17 22:47:54.712907', '2026-06-17 22:47:54.712907', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('3d2f6b51-3948-4c9a-87a6-75d66e2e3270', 'Hệ thống bài tập di truyền cấp độ vận dụng cao được giải chi tiết bằng phương pháp toán học hóa. Tôi giúp học sinh hiểu bản chất cơ chế sinh học thay vì ghi nhớ công thức một cách rập khuôn. Phù hợp cho mục tiêu xét tuyển đại học y dược.', 'Gia sư Sinh Học ôn thi chuyên sâu khối B', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Sinh học', NULL, NULL, '6 năm kinh nghiệm dạy đội tuyển học sinh giỏi và luyện thi đại học.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.9, 53, 420, '2026-06-17 22:47:54.862662', '2026-06-17 22:47:54.862662', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('9c4488fb-69aa-4d08-9868-6a5cd7854735', 'Giúp học sinh nắm vững toàn bộ kiến thức lịch sử lớp 11 và 12 thông qua sơ đồ tư duy ngắn gọn, súc tích. Tôi hướng dẫn kỹ năng loại trừ đáp án nhiễu trong đề thi trắc nghiệm để đạt kết quả tối đa. Nhiệt tình, có tinh thần trách nhiệm cao.', 'Gia sư Lịch Sử khối C - Ôn tập trọng tâm bài bản', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Lịch sử', NULL, NULL, '4 năm giảng dạy tự do và luyện thi khối C tại Đà Nẵng.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.5, 16, 110, '2026-06-17 22:47:55.017118', '2026-06-17 22:47:55.017118', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('3399e732-f8bd-4b92-a405-163b09f450b4', 'Lồng ghép kiến thức kinh tế, khí hậu thực tế vào bài học môn Địa Lý giúp học sinh tiếp thu bài dễ dàng mà không thấy nhàm chán. Hướng dẫn chi tiết cách vẽ và nhận dạng mọi loại biểu đồ thi THPT Quốc gia. Cam kết đầu ra tiến bộ rõ rệt.', 'Gia sư Địa Lý năng động - Kết nối thực tế đời sống', NULL, 'Đại học Sư phạm TP.HCM - Cử nhân Địa lý học', NULL, NULL, '3 năm kinh nghiệm làm gia sư tại khu vực Biên Hòa.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.6, 12, 85, '2026-06-17 22:47:55.172844', '2026-06-17 22:47:55.172844', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('79a5e44f-41b0-4b10-98d3-8b32d11757c3', 'Chuyên luyện thi môn Toán vào lớp 10 các trường công lập top đầu. Tôi nắm rất rõ cấu trúc đề thi và các lỗi sai kinh điển học sinh thường mắc phải gây mất điểm đáng tiếc. Phong cách giảng dạy nghiêm khắc nhưng vô cùng tận tâm, sát sao.', 'Gia sư Toán cấp 2 - Ôn thi vào lớp 10 công lập bài bản', NULL, 'Đại học Sư phạm Hà Nội - Sư phạm Toán học', NULL, NULL, '7 năm kinh nghiệm đứng lớp và chấm thi học kỳ, thi thử.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.8, 61, 370, '2026-06-17 22:47:55.322829', '2026-06-17 22:47:55.322829', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('320bc3d2-20a4-49a0-bbd1-b9c2b06ce06c', 'Phương pháp dạy học tương tác cao, khơi gợi trí tò mò của học sinh thay vì ép buộc làm bài tập. Tôi áp dụng các ví dụ hài hước và thực tiễn để giải thích các định luật cơ học, quang học phức tạp. Đảm bảo học sinh sẽ thích học môn Lý sau vài buổi.', 'Gia sư Vật Lý vui tính - Chuyên trị học sinh lười học', NULL, 'Đại học Cần Thơ - Kỹ sư Cơ khí', NULL, NULL, '4 năm dạy kèm Vật lý cấp 3 tại khu vực Cần Thơ.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.7, 29, 200, '2026-06-17 22:47:55.47788', '2026-06-17 22:47:55.47788', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('f68e5d00-1e8d-40c1-8e33-eab6ffdd033f', 'Từng đạt giải Nhì Học sinh giỏi Quốc gia môn Hóa học và là Thủ khoa đầu ra sư phạm. Tôi sở hữu kho tài liệu đề thi phong phú và phương pháp giải toán hữu cơ độc đáo, ngắn gọn. Sẵn sàng truyền đạt mọi bí quyết học tập hiệu quả nhất cho các em.', 'Nữ thủ khoa Hóa Học nhận dạy kèm ôn thi đại học', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Sư phạm Hóa học xuất sắc', NULL, NULL, '3 năm kinh nghiệm luyện thi học sinh giỏi và ôn thi THPTQG.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.9, 44, 290, '2026-06-17 22:47:55.632598', '2026-06-17 22:47:55.632598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('aa25290a-b644-4d08-82bb-1d1628199a5b', 'Học tiếng Anh thông qua việc tư duy bằng chính ngôn ngữ đó thay vì dịch từ tiếng Việt sang. Lớp học của tôi tập trung phát triển toàn diện 4 kỹ năng Nghe-Nói-Đọc-Viết với giáo trình chuẩn quốc tế Cambridge. Thích hợp cho học sinh định hướng du học sớm.', 'Gia sư Tiếng Anh phản xạ và luyện thi chứng chỉ quốc tế', NULL, 'Đại học RMIT Việt Nam - Cử nhân Quản trị Kinh doanh', NULL, NULL, '5 năm dạy kèm tiếng Anh cho học sinh trường quốc tế và người đi làm.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.8, 38, 250, '2026-06-17 22:47:55.781729', '2026-06-17 22:47:55.781729', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('effc88ba-9916-4bf5-b405-430e7f614456', 'Chuyên luyện thi môn Ngữ Văn vào lớp 10 công lập với lộ trình tinh gọn, trọng tâm. Tôi hướng dẫn học sinh phương pháp tư duy và làm bài văn nghị luận xã hội sắc bén, cập nhật hơi thở thời đại. Kiên nhẫn, tinh tế và luôn đồng hành sát sao cùng học trò.', 'Thổi hồn vào từng trang văn lớp 9 ôn thi vào 10', NULL, 'Đại học Sài Gòn - Sư phạm Ngữ văn', NULL, NULL, '4 năm kinh nghiệm làm gia sư luyện thi cấp tốc môn Văn lớp 9.', 'TP.HCM', 'Quận 1', 'active', true, 4.7, 27, 190, '2026-06-17 22:47:55.934132', '2026-06-17 22:47:55.934132', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('22ab78ac-899b-4645-bd75-b0ec36951a22', 'Bài giảng chuyên sâu về cơ chế di truyền phân tử, tiến hóa và sinh thái học cấp độ nâng cao. Tôi cung cấp các chuyên đề tự biên soạn sát với ma trận đề thi chọn học sinh giỏi cấp tỉnh/thành phố. Phong cách làm việc chuyên nghiệp, nghiêm túc và khoa học.', 'Gia sư Sinh Học ôn thi Học sinh giỏi các cấp', NULL, 'Đại học Khoa học Tự nhiên ĐHQG TP.HCM - Thạc sĩ Sinh học', NULL, NULL, '8 năm kinh nghiệm giảng dạy và bồi dưỡng đội tuyển học sinh giỏi.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.9, 81, 460, '2026-06-17 22:47:56.085131', '2026-06-17 22:47:56.085131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('1e5a591f-d937-4b94-8103-0977fa285ee2', 'Giúp học sinh đánh tan nỗi sợ lượng kiến thức khổng lồ của môn Lịch sử 12. Tôi sử dụng sơ đồ tư duy liên kết và các mẹo nhớ mốc sự kiện siêu tốc giúp tối ưu hóa điểm số thi trắc nghiệm. Phương pháp thực tế, bám sát cấu trúc đề minh họa mới nhất.', 'Gia sư Lịch Sử - Hệ thống hóa kiến thức thi THPT Quốc gia', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Sư phạm Lịch sử', NULL, NULL, '4 năm kinh nghiệm dạy kèm gia sư và luyện thi tại các trung tâm lớn.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.6, 21, 140, '2026-06-17 22:47:56.245433', '2026-06-17 22:47:56.245433', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('7f768c8c-a9a3-40df-883c-8bb7551dbe82', 'Chuyên luyện thi môn Địa Lý cho học sinh khối C và ôn thi tốt nghiệp cấp tốc. Phương pháp dạy logic, dễ hiểu, chú trọng thực hành đọc Atlat và phân tích bảng số liệu để ghi điểm tuyệt đối phần trắc nghiệm kỹ năng. Nhiệt tình, thân thiện với học sinh.', 'Gia sư Địa Lý thi THPT Quốc gia - Cam kết tiến bộ', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Địa lý', NULL, NULL, '5 năm giảng dạy tự do môn Địa lý cho học sinh cấp 3.', 'Hà Nội', 'Đống Đa', 'active', true, 4.5, 19, 135, '2026-06-17 22:47:56.405761', '2026-06-17 22:47:56.405761', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('0ae1b48c-d81d-4b48-a174-a5e8c04999e5', 'Khơi dậy niềm đam mê Toán học thông qua các phương pháp tư duy hình học và đại số hiện đại. Tôi chuyên bồi dưỡng học sinh khá giỏi thi vào các lớp chuyên Toán của thành phố Đà Nẵng. Giáo trình cập nhật liên tục các dạng toán mới lạ và thử thách.', 'Gia sư Toán tư duy nâng cao cho học sinh cấp 2', NULL, 'Đại học Sư phạm Đà Nẵng - Cử nhân Toán học chất lượng cao', NULL, NULL, '4 năm dạy kèm chuyên sâu môn Toán cho học sinh khối THCS.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.8, 33, 230, '2026-06-17 22:47:56.56148', '2026-06-17 22:47:56.56148', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('eb850604-5ed9-4f4b-9ab7-0a84ce347e7e', 'Sở hữu chứng chỉ IELTS 8.0 và SAT 1520, tôi chia sẻ các chiến thuật làm bài thi chuẩn hóa quốc tế hiệu quả nhất. Tập trung cải thiện tư duy phản biện trong bài đọc và cấu trúc bài viết đạt điểm tối đa. Lộ trình học rõ ràng, cam kết đầu ra bằng văn bản.', 'Chuyên gia luyện thi SAT và IELTS cấp tốc', NULL, 'Đại học Ngoại thương TP.HCM - Kinh tế đối ngoại', NULL, NULL, '3 năm kinh nghiệm giảng dạy tại trung tâm quốc tế và ôn thi SAT.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.9, 50, 340, '2026-06-17 22:47:56.712891', '2026-06-17 22:47:56.712891', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('5d22e513-463e-43dd-96a5-17b9cc970689', 'Hệ thống bài giảng tập trung phát triển năng lực tư duy khoa học, giải quyết vấn đề thực tiễn môn Vật lý. Tôi cung cấp ngân hàng câu hỏi trắc nghiệm đa dạng bám sát cấu trúc đề thi Đánh giá năng lực của ĐHQG. Phong cách dạy lôi cuốn, thực tế.', 'Gia sư Vật Lý ôn thi đánh giá năng lực ĐHQG', NULL, 'Đại học Bách khoa TP.HCM - Thạc sĩ Vật lý kỹ thuật', NULL, NULL, '6 năm kinh nghiệm giảng dạy lý thuyết và thực hành Vật lý cấp 3.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.7, 41, 290, '2026-06-17 22:47:56.868189', '2026-06-17 22:47:56.868189', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('6b8f6581-e001-484c-866f-352f729c93e2', 'Chuyên dạy kèm cho học sinh học yếu môn Hóa lớp 10, 11 vươn lên đạt điểm khá, giỏi. Phương pháp giảng dạy chậm rãi, chắc chắn, tập trung củng cố lý thuyết gốc trước khi làm bài tập vận dụng. Luôn lắng nghe và thấu hiểu tâm lý áp lực của học sinh cấp 3.', 'Gia sư Hóa Học THPT - Dễ hiểu, chu đáo và sát sao', NULL, 'Đại học Cần Thơ - Sư phạm Hóa học', NULL, NULL, '5 năm dạy kèm học sinh ôn thi tốt nghiệp THPT môn Hóa tại Cần Thơ.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.6, 24, 180, '2026-06-17 22:47:57.024637', '2026-06-17 22:47:57.024637', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('c3b19319-011f-4c6e-94d7-a157d54e5c69', 'Áp dụng phương pháp sơ đồ tư duy trong phân tích tác phẩm văn học giúp học sinh không phải học thuộc lòng máy móc. Hướng dẫn chi tiết cách viết mở bài, kết bài ấn tượng thu hút người chấm thi. Rất thích hợp cho học sinh ôn thi tốt nghiệp THPT môn Văn.', 'Gia sư Ngữ Văn - Đổi mới tư duy, nâng tầm ngòi bút', NULL, 'Đại học Sư phạm Hà Nội - Khoa Ngữ văn', NULL, NULL, '4 năm giảng dạy tự do và làm cộng tác viên biên soạn sách tham khảo.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.5, 18, 130, '2026-06-17 22:47:57.172997', '2026-06-17 22:47:57.172997', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('74c5ef49-f8b3-457d-b589-22d68e9d478a', 'Giúp học sinh nắm vững kiến thức Sinh học 11, 12 thông qua sơ đồ hình ảnh trực quan sinh động. Tôi chia sẻ các mẹo làm bài tập trắc nghiệm di truyền quần thể nhanh chóng, chính xác không cần dùng nhiều công thức toán học phức tạp. Thân thiện, tận tâm.', 'Gia sư Sinh Học THPT - Ôn thi nhẹ nhàng, hiệu quả cao', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Sinh học', NULL, NULL, '3 năm kinh nghiệm dạy kèm ôn thi tốt nghiệp môn Sinh tại Đà Nẵng.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.6, 15, 105, '2026-06-17 22:47:57.320986', '2026-06-17 22:47:57.320986', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('6e1fb08a-d9ca-4dc4-8456-fdc1d617622d', 'Khóa học tập trung phân tích sâu bản chất các sự kiện lịch sử, xu hướng ra đề thi trắc nghiệm của Bộ Giáo dục. Tôi hướng dẫn kỹ năng đọc hiểu câu hỏi phân hóa cao để đạt điểm 9, 10. Giờ học nghiêm túc, khoa học, đạt hiệu quả tối ưu.', 'Gia sư Lịch Sử khối C - Luyện thi đại học chuyên sâu', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Lịch sử', NULL, NULL, '6 năm kinh nghiệm luyện thi khối C, giúp nhiều học sinh đỗ trường top.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.8, 47, 310, '2026-06-17 22:47:57.478302', '2026-06-17 22:47:57.478302', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('76fa2ded-02d3-4ba9-b660-c2f8c92aa408', 'Nhận dạy kèm môn Địa Lý từ lớp 10 đến lớp 12 tại Biên Hòa. Bài giảng sinh động kết hợp Atlat trực quan giúp học sinh ghi nhớ bài ngay tại lớp mà không cần tốn nhiều thời gian học thuộc tại nhà. Kiểm tra, đánh giá học lực định kỳ bài bản.', 'Gia sư Địa Lý Biên Hòa - Tận tụy vì sự tiến bộ của trò', NULL, 'Đại học Đồng Nai - Sư phạm Địa lý', NULL, NULL, '4 năm kinh nghiệm làm gia sư tại nhà và giáo viên dạy thay tại trường THPT.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.7, 22, 150, '2026-06-17 22:47:57.631371', '2026-06-17 22:47:57.631371', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('5c2fd56f-21ab-427c-8b86-fb21d7aa3360', 'Chuyên luyện thi trắc nghiệm Toán giải tích, hình học không gian mức độ vận dụng và vận dụng cao. Phương pháp tư duy đột phá kết hợp kỹ thuật Casio giải toán đỉnh cao giúp học sinh chinh phục các câu hỏi phân hóa trong đề thi THPT Quốc gia.', 'Gia sư Toán cấp 3 lý tưởng cho mục tiêu 8.5+', NULL, 'Đại học Bách khoa Hà Nội - Kỹ sư Hệ thống Điện', NULL, NULL, '5 năm kinh nghiệm gia sư chuyên sâu môn Toán ôn thi đại học.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.9, 55, 360, '2026-06-17 22:47:57.785878', '2026-06-17 22:47:57.785878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('3a09c0e4-1ed8-4212-989e-4ae17d7e0226', 'Học tiếng Anh thông qua bài hát, trò chơi và truyện tranh giúp trẻ em mầm non và tiểu học yêu thích môn học tự nhiên. Sửa ngọng phát âm chuẩn quốc tế ngay từ nhỏ. Tôi coi trọng sự vui vẻ, thoải mái và tiến bộ tự nhiên của các con.', 'Gia sư Tiếng Anh trẻ em ôn hòa, kiên nhẫn', NULL, 'Đại học Ngoại ngữ ĐHQG Hà Nội - Sư phạm tiếng Anh tiểu học', NULL, NULL, '3 năm dạy học tại trung tâm Anh ngữ quốc tế nổi tiếng.', 'Hà Nội', 'Cầu Giấy', 'active', true, 4.8, 29, 190, '2026-06-17 22:47:57.939429', '2026-06-17 22:47:57.939429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('295e9607-4adf-4310-b76c-369826053d81', 'Khóa học thiết kế chuyên biệt cho học sinh lổng khổng kiến thức Vật Lý căn bản. Tôi hệ thống lại lý thuyết nền tảng cốt lõi bằng sơ đồ ngắn gọn kết hợp bài tập mẫu tương ứng để học sinh hiểu bài ngay lập tức. Cam kết lấy lại căn bản sau 10 buổi.', 'Gia sư Vật Lý cấp tốc lấy gốc cho học sinh lớp 11, 12', NULL, 'Đại học Bách khoa Đà Nẵng - Kỹ sư Nhiệt lạnh', NULL, NULL, '4 năm dạy kèm tự do Vật lý cấp 3 tại khu vực Đà Nẵng.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.6, 16, 120, '2026-06-17 22:47:58.086273', '2026-06-17 22:47:58.086273', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('a4870df9-eed1-4464-a570-5433c213953a', 'Giải quyết triệt để nỗi sợ phần Hóa học hữu cơ cực kỳ phức tạp của lớp 11 và 12. Tôi cung cấp phương pháp bảo toàn khối lượng, bảo toàn electron tối ưu giúp giải các bài toán hỗn hợp hữu cơ nhanh gọn trong 1 dòng. Tận tâm, chu đáo.', 'Gia sư Hóa Học chuyên sâu hữu cơ lớp 11, 12', NULL, 'Đại học Sư phạm TP.HCM - Thạc sĩ Hóa lý học', NULL, NULL, '7 năm kinh nghiệm giảng dạy tại trường THPT danh tiếng.', 'TP.HCM', 'Gò Vấp', 'active', true, 4.9, 68, 430, '2026-06-17 22:47:58.235155', '2026-06-17 22:47:58.235155', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('e1a01ac2-cb42-46ce-81a6-53001b643048', 'Học Văn không cần học vẹt, hãy học phương pháp lập luận logic và tư duy phản biện sắc sảo. Tôi hướng dẫn học sinh cách khai triển ý tưởng độc đáo, viết văn nghị luận xã hội thu hút, giàu hình ảnh thực tế. Phù hợp cho ôn thi THPTQG đạt điểm cao.', 'Gia sư Ngữ Văn khơi gợi cảm xúc và tư duy nghị luận', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG Hà Nội - Ngành Văn học', NULL, NULL, '4 năm kinh nghiệm làm gia sư môn Ngữ Văn và biên tập viên báo chí.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.7, 25, 170, '2026-06-17 22:47:58.387173', '2026-06-17 22:47:58.387173', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('59f4b9e1-7b0d-44ac-91dd-a5945e6239a1', 'Phương pháp độc quyền liên kết dòng sự kiện lịch sử bằng hình ảnh mindmap giúp ghi nhớ siêu nhanh, nhớ lâu đến ngày thi. Chuyên luyện đề thi thử bám sát ma trận đề của Bộ Giáo dục để tối đa hóa điểm số trắc nghiệm. Phong cách dạy quyết liệt, đầy lửa.', 'Gia sư Lịch Sử - Cam kết phá đảo kỳ thi THPT Quốc gia', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG TP.HCM - Ngành Lịch sử', NULL, NULL, '5 năm kinh nghiệm chuyên luyện thi khối C đạt nhiều thành tích tốt.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.8, 39, 260, '2026-06-17 22:47:58.612268', '2026-06-17 22:47:58.612268', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('c4d2cc1c-bb6b-4b49-8d55-6ebec6a761a9', 'Hệ thống hóa toàn bộ kiến thức Địa Lý kinh tế vùng, Địa lý tự nhiên Việt Nam cực kỳ ngắn gọn, dễ hiểu. Rèn luyện thành thạo kỹ năng phân tích biểu đồ và sử dụng Atlat để lấy trọn điểm số cơ bản trong đề thi THPTQG. Tận tâm, sát sao học sinh.', 'Gia sư Địa Lý ôn thi Đại học bao đỗ tốt nghiệp', NULL, 'Đại học Sư phạm Hà Nội - Sư phạm Địa lý', NULL, NULL, '4 năm dạy kèm và đứng lớp tại trung tâm ôn thi khu vực Hà Đông.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.6, 18, 125, '2026-06-17 22:47:58.760087', '2026-06-17 22:47:58.760087', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('fad7ea3d-af76-4370-98f8-1a02c8cd2f62', 'Chuyên bồi dưỡng Toán tư duy nâng cao cho học sinh lớp 4, lớp 5 có mục tiêu thi vào lớp 6 trường chuyên, trường điểm. Bài giảng thiết kế hiện đại, kích thích sự sáng tạo và tư duy logic độc lập của trẻ. Đồng hành gắn kết thân thiết cùng phụ huynh.', 'Gia sư Toán Tiểu học ôn thi vào các trường điểm lớp 6', NULL, 'Đại học Sư phạm TP.HCM - Giáo dục Tiểu học', NULL, NULL, '6 năm giảng dạy chuyên sâu luyện thi học sinh giỏi tiểu học môn Toán.', 'Hà Nội', 'Hai Bà Trưng', 'active', true, 4.9, 52, 350, '2026-06-17 22:47:58.910661', '2026-06-17 22:47:58.910661', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('f8c73b80-afb4-4d0b-9f5c-0f3c6490f9df', 'Chuyên ôn tập ngữ pháp nâng cao, kho từ vựng phong phú bám sát đề thi tuyển sinh vào lớp 10 của các tỉnh thành lớn. Phương pháp dạy nghiêm khắc, rèn luyện làm đề liên tục để tạo phản xạ làm bài nhanh, chính xác tuyệt đối. Cam kết học sinh tiến bộ.', 'Gia sư Tiếng Anh luyện thi vào 10 chuyên sâu mục tiêu 9+', NULL, 'Đại học Hà Nội - Ngôn ngữ Anh chất lượng cao', NULL, NULL, '5 năm kinh nghiệm chuyên luyện thi học sinh lớp 9 thi vào lớp 10 công lập.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.8, 43, 280, '2026-06-17 22:47:59.061703', '2026-06-17 22:47:59.061703', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('d7872c81-0242-408a-a63d-d56837a4fc41', 'Học Vật lý chuẩn bản chất bản lĩnh giúp tự tin chinh phục mọi dạng đề thi trắc nghiệm hiện đại. Tôi hướng dẫn kỹ thuật đọc hiểu đồ thị dao động, dòng điện xoay chiều cực nhanh và tối ưu hóa thao tác máy tính Casio. Bài giảng rõ ràng, lôi cuốn.', 'Gia sư Vật Lý THPT - Giải mã đồ thị và toán thực tế', NULL, 'Đại học Bách khoa TP.HCM - Kỹ sư Điện tử viễn thông', NULL, NULL, '4 năm dạy kèm Vật lý cho học sinh THPT chuyên và trường điểm.', 'TP.HCM', 'Gò Vấp', 'active', true, 4.7, 31, 210, '2026-06-17 22:47:59.213061', '2026-06-17 22:47:59.213061', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('bbfb921b-07e0-40f3-9928-9a87ac98cc55', 'Giải cứu học sinh lười học, sợ mất gốc môn Hóa học một cách bài bản nhất. Giúp các em hiểu rõ cách cân bằng phương trình, tính toán số mol, giải bài toán vô cơ cơ bản từ những bước đi chập chững đầu tiên. Kiên nhẫn, ngọt ngào, tạo động lực tốt.', 'Gia sư Hóa Học chuyên lấy gốc lớp 8, 9, 10 siêu tốc', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Hóa học', NULL, NULL, '3 năm kinh nghiệm lấy gốc môn Hóa cấp tốc cho học sinh THCS.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.6, 16, 110, '2026-06-17 22:47:59.365189', '2026-06-17 22:47:59.365189', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('d3af758b-a347-4c3a-85ec-eb0b624b46c1', 'Dạy học bằng cả cái tâm và chiều sâu kiến thức văn học xã hội phong phú. Hướng dẫn học sinh phương pháp tư duy làm bài thi tự luận đạt điểm cao bám sát barem chấm điểm của Bộ Giáo dục. Theo sát tình hình học tập và tương tác chặt chẽ với phụ huynh.', 'Gia sư Ngữ Văn Biên Hòa - Luyện thi THPT bao chuẩn', NULL, 'Đại học Đồng Nai - Sư phạm Ngữ văn', NULL, NULL, '5 năm dạy kèm gia sư và luyện thi tại các trung tâm Biên Hòa.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.7, 23, 160, '2026-06-17 22:47:59.513972', '2026-06-17 22:47:59.513972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('f789dfe6-262a-442a-8c9f-656d4bde5e32', 'Phương pháp giảng dạy trực quan, sinh động bằng hình ảnh sinh học thực tiễn giúp học sinh nắm trọn điểm lý thuyết Sinh học THPTQG chiếm đến 60% đề thi. Đồng thời hỗ trợ rèn luyện tư duy giải nhanh toán phả hệ nâng cao. Chu đáo, trách nhiệm.', 'Gia sư Sinh Học THPT - Học sâu bản chất lý thuyết', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Sinh học', NULL, NULL, '4 năm dạy học tại nhà và cộng tác biên soạn tài liệu ôn thi.', 'TP.HCM', 'Quận 1', 'active', true, 4.6, 19, 140, '2026-06-17 22:47:59.665694', '2026-06-17 22:47:59.665694', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('9b7b047b-2847-4891-9295-125b8d13f4b0', 'Khóa học chuyên sâu dành cho học sinh có nguyện vọng xét tuyển đại học khối C trường top đầu. Tôi cung cấp ma trận câu hỏi trắc nghiệm phân hóa nâng cao và kỹ thuật giải nhanh câu hỏi loại trừ đáp án nhiễu. Phương pháp dạy khoa học, dứt khoát.', 'Gia sư Lịch Sử - Đột phá điểm số khối C ôn thi đại học', NULL, 'Đại học Sư phạm Hà Nội - Sư phạm Lịch sử', NULL, NULL, '6 năm giảng dạy luyện thi khối C tại các trung tâm ôn thi lớn Hà Nội.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.8, 36, 250, '2026-06-17 22:47:59.81311', '2026-06-17 22:47:59.81311', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('a87c7e83-0997-468d-b04c-3ca0d16e9f95', 'Nhận dạy kèm môn Địa Lý ôn thi tốt nghiệp THPT cấp tốc đạt điểm 8+. Phương pháp dạy học nhẹ nhàng, thực tế giúp học sinh nhớ lâu lý thuyết kinh tế vùng và nắm vững kỹ năng sử dụng Atlat thành thạo lấy điểm tuyệt đối. Thân thiện, tận tâm với học trò.', 'Gia sư Địa Lý Cần Thơ - Ôn thi hiệu quả, bám sát đề', NULL, 'Đại học Cần Thơ - Sư phạm Địa lý', NULL, NULL, '4 năm làm gia sư tại nhà và giáo viên dạy kèm tự do tại Cần Thơ.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.5, 13, 90, '2026-06-17 22:47:59.958894', '2026-06-17 22:47:59.958894', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('4c24a581-f47c-4447-8839-9e4b6101abb0', 'Chuyên dạy toán trắc nghiệm nâng cao hình học không gian, hàm số và tích phân vận dụng cao cho học sinh lớp 12. Phương pháp tư duy độc đáo kích thích sáng tạo phá vỡ các giới hạn tư duy cũ kỹ của học sinh. Giờ học nghiêm túc chất lượng cao.', 'Gia sư Toán THPT - Luyện thi Đại học mục tiêu điểm 9+', NULL, 'Đại học Khoa học Tự nhiên ĐHQG TP.HCM - Cử nhân Toán - Tin', NULL, NULL, '5 năm dạy kèm chuyên toán nâng cao và ôn thi tốt nghiệp THPT.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.9, 48, 330, '2026-06-17 22:48:00.107919', '2026-06-17 22:48:00.107919', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('146cf42d-bac4-4895-811b-a19d68cf1f76', 'Sở hữu IELTS 8.0 cùng 4 năm kinh nghiệm giảng dạy tiếng Anh giao tiếp cho người đi làm và ôn thi chứng chỉ quốc tế. Giáo trình thiết kế cá nhân hóa bám sát nhu cầu công việc thực tế hoặc lộ trình thi cử tăng điểm thần tốc. Thân thiện, năng động.', 'Gia sư Tiếng Anh giao tiếp công sở & Luyện thi IELTS', NULL, 'Đại học Ngoại thương Hà Nội - Kinh tế đối ngoại', NULL, NULL, '4 năm làm gia sư tiếng Anh nâng cao và giảng viên trung tâm Anh ngữ.', 'Đà Nẵng', 'Thanh Khê', 'active', true, 4.8, 40, 270, '2026-06-17 22:48:00.262976', '2026-06-17 22:48:00.262976', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('5b20a3a8-f20d-425e-b423-9214858d5aa1', 'Giảng dạy nhiệt tình, dễ hiểu, biến mọi bài toán Vật lý điện xoay chiều, sóng cơ phức tạp trở nên đơn giản thông qua hình ảnh bản chất. Rèn luyện kỹ năng bấm máy tính giải toán siêu nhanh và chính xác. Sát sao kèm cặp từng học sinh tiến bộ.', 'Gia sư Vật Lý cấp 3 - Vững nền tảng, bứt phá điểm số', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Vật lý', NULL, NULL, '5 năm làm gia sư tại nhà và giáo viên dạy bổ túc văn hóa.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.7, 26, 190, '2026-06-17 22:48:00.421681', '2026-06-17 22:48:00.421681', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('cb11b66b-482a-4eb4-ab61-60e261a8b0af', 'Nhận dạy kèm môn Hóa học cho mọi đối tượng học sinh THPT từ yếu kém đến khá giỏi. Phương pháp giảng dạy khoa học, súc tích giúp học sinh hệ thống hóa toàn bộ phương trình phản ứng hóa học vô cơ, hữu cơ bản bản nhất. Chu đáo và cực kỳ trách nhiệm.', 'Gia sư Hóa Học THPT - Học là hiểu, thi là đỗ', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Hóa học', NULL, NULL, '6 năm giảng dạy tự do môn Hóa học ôn thi đại học tại TP.HCM.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.8, 35, 240, '2026-06-17 22:48:00.575763', '2026-06-17 22:48:00.575763', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('c7e4332d-f385-4ad3-b3f8-a01672dde0bd', 'Văn học không chỉ cần cảm xúc mà cần cấu trúc lập luận logic sắc bén để thuyết phục người chấm thi. Tôi hướng dẫn học sinh kỹ năng khai thác luận điểm độc đáo trong văn học hiện đại và văn học trung đại. Giúp tự tin chinh phục kỳ thi THPT Quốc gia.', 'Gia sư Ngữ Văn - Viết văn logic đạt điểm tuyệt đối', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG Hà Nội - Ngành Văn học', NULL, NULL, '4 năm kinh nghiệm làm gia sư môn Văn và chấm thi thử THPT.', 'Hà Nội', 'Hai Bà Trưng', 'active', true, 4.6, 22, 150, '2026-06-17 22:48:00.732389', '2026-06-17 22:48:00.732389', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
