INSERT INTO public.tutorprofiles VALUES ('bfe0901a-43f7-45dc-9f76-7c7a0b3ae906', 'Giúp học sinh tổng hợp nhanh toàn bộ kiến thức Lịch sử Việt Nam và thế giới ôn thi tốt nghiệp THPT cấp tốc. Hướng dẫn kỹ năng phân tích câu hỏi trắc nghiệm loại trừ đáp án nhiễu đạt điểm 8+. Giờ học thoải mái, lôi cuốn bằng câu chuyện kể sinh động.', 'Gia sư Lịch Sử khối C - Luyện thi cấp tốc hiệu quả tốt', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Lịch sử', NULL, NULL, '4 năm kinh nghiệm làm gia sư luyện thi khối C cấp tốc tại Đà Nẵng.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.6, 17, 120, '2026-06-17 22:48:01.031324', '2026-06-17 22:48:01.031324', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('fb6831db-8930-493d-981c-fd75bc9aab16', 'Phương pháp dạy học Địa lý bám sát ma trận cấu trúc đề minh họa mới nhất của Bộ Giáo dục. Tận tình hướng dẫn học sinh kỹ năng khai thác Atlat Địa lý Việt Nam đạt điểm tối đa phần kỹ năng trắc nghiệm cơ bản. Tận tâm và sát sao kèm cặp từng học sinh.', 'Gia sư Địa Lý thi tốt nghiệp THPT - Ôn tập trọng tâm', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Sư phạm Địa lý', NULL, NULL, '5 năm dạy kèm gia sư và luyện đề thi thử môn Địa lý cấp 3.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.7, 21, 145, '2026-06-17 22:48:01.182577', '2026-06-17 22:48:01.182577', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('5c825064-b80f-43b9-a386-c8149c341462', 'Chuyên luyện thi môn Toán cho học sinh lớp 9 thi vào các trường THPT công lập top đầu tại Cần Thơ. Phương pháp giảng dạy bài bản, nghiêm túc, rèn luyện kỹ năng trình bày tự luận mạch lạc tránh mất điểm đáng tiếc. Cam kết đầu ra tiến bộ vượt bậc.', 'Gia sư Toán cấp 2 - Ôn thi vào lớp 10 chất lượng cao', NULL, 'Đại học Cần Thơ - Sư phạm Toán học', NULL, NULL, '6 năm kinh nghiệm đứng lớp luyện thi vào 10 chuyên sâu môn Toán.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.9, 50, 340, '2026-06-17 22:48:01.340518', '2026-06-17 22:48:01.340518', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('08f01f2f-7444-4c1b-ae3b-a031f65db40b', 'Hệ thống hóa toàn bộ mảng ngữ pháp trọng tâm, từ vựng theo chủ đề thường gặp và phương pháp làm bài đọc hiểu tiếng Anh đạt kết quả tốt nhất. Giáo trình biên soạn cập nhật liên tục sát với xu hướng ra đề thi thực tế. Chu đáo, nhiệt huyết vì học sinh.', 'Gia sư Tiếng Anh - Ôn thi tốt nghiệp THPT quốc gia mục tiêu 8+', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Tiếng Anh', NULL, NULL, '4 năm kinh nghiệm làm gia sư môn Tiếng Anh ôn thi tốt nghiệp đại học.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.8, 33, 220, '2026-06-17 22:48:01.502342', '2026-06-17 22:48:01.502342', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('13bf4f0c-2533-4553-aff6-852bb174640b', 'Cung cấp các bí quyết giải bài tập trắc nghiệm Vật lý siêu tốc bằng kỹ thuật Casio nâng cao và sơ đồ vòng tròn lượng giác đột phá. Giúp học sinh tự tin bứt phá điểm số môn Vật lý 12 trong các kỳ thi học kỳ và kỳ thi quốc gia quan trọng. Tận tâm.', 'Gia sư Vật Lý THPT - Giải toán trắc nghiệm bằng mẹo nhanh', NULL, 'Đại học Bách khoa Hà Nội - Kỹ sư Điện tử viễn thông', NULL, NULL, '5 năm kinh nghiệm gia sư chuyên sâu môn Vật lý ôn thi đại học.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.7, 28, 195, '2026-06-17 22:48:01.653071', '2026-06-17 22:48:01.653071', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('bdb18557-9261-4946-b555-9e22c079af77', 'Nhận dạy kèm củng cố lại toàn bộ kiến thức gốc môn Hóa học cho học sinh THPT học lực yếu kém lổng khổng căn bản. Phương pháp dạy chậm, tỉ mỉ, tập trung bài tập mẫu cơ bản giúp các em tìm lại sự tự tin học tập môn Hóa. Thân thiện, chu đáo.', 'Gia sư Hóa Học chuyên lấy gốc lớp 10, 11 siêu nhanh', NULL, 'Đại học Khoa học Tự nhiên ĐHQG TP.HCM - Cử nhân Hóa học', NULL, NULL, '3 năm kinh nghiệm lấy gốc môn Hóa cấp tốc cho học sinh cấp 3.', 'TP.HCM', 'Gò Vấp', 'active', true, 4.6, 15, 110, '2026-06-17 22:48:01.809259', '2026-06-17 22:48:01.809259', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('e7857ee1-4e7c-4532-8695-47ef55602e8d', 'Hướng dẫn học sinh kỹ năng khai triển ý tưởng độc đáo sắc bén cho bài văn nghị luận xã hội mang đậm hơi thở cuộc sống hiện đại. Giúp rũ bỏ thói quen học vẹt văn mẫu cũ kỹ để bứt phá điểm số cao môn Ngữ Văn trong đề thi THPTQG. Tận tụy vì học trò.', 'Gia sư Ngữ Văn - Đổi mới cách viết văn nghị luận xã hội', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Ngữ văn', NULL, NULL, '4 năm giảng dạy tự do môn Văn ôn thi tốt nghiệp tại Đà Nẵng.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.5, 18, 125, '2026-06-17 22:48:01.967893', '2026-06-17 22:48:01.967893', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('7ec52d69-75cc-4b45-8d29-2aab8c0fa271', 'Chuyên luyện thi môn Sinh học nâng cao cho học sinh có mục tiêu xét tuyển đại học khối B vào các trường đại học Y Dược danh tiếng. Lộ trình học bài bản từ lý thuyết cơ chế di truyền đến các dạng bài toán phả hệ vận dụng cao phức tạp cực nhanh. Nghiêm túc.', 'Gia sư Sinh Học THPT - Ôn thi khối B ngành Y Dược', NULL, 'Đại học Y Hà Nội - Bác sĩ Răng Hàm Mặt', NULL, NULL, '5 năm kinh nghiệm dạy kèm gia sư chuyên sinh khối B ôn thi đại học.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.9, 42, 300, '2026-06-17 22:48:02.118006', '2026-06-17 22:48:02.118006', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('89a3d78e-40aa-41ad-b057-e33af9a99031', 'Biến môn Lịch sử học thuộc lòng khô khan thành các buổi học kể chuyện lịch sử sống động hấp dẫn liên kết tư duy logic. Hướng dẫn chi tiết chiến thuật làm bài trắc nghiệm nhanh, chuẩn bám sát cấu trúc đề minh họa mới nhất. Cam kết học sinh tiến bộ.', 'Gia sư Lịch Sử khối C - Khơi nguồn cảm hứng thi cử', NULL, 'Đại học Khoa học Xã hội và Nhân văn ĐHQG TP.HCM - Ngành Lịch sử', NULL, NULL, '4 năm làm gia sư tại nhà ôn thi khối C tốt tốt tại TP.HCM.', 'Biên Hòa', 'Biên Hòa', 'active', true, 4.6, 20, 135, '2026-06-17 22:48:02.268544', '2026-06-17 22:48:02.268544', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('7c96fdb1-d584-4d69-b0f4-5300e0f77a88', 'Nhận dạy kèm môn Địa Lý ôn thi tốt nghiệp THPT cho học sinh tại khu vực Biên Hòa. Giáo trình tinh gọn trọng tâm kết hợp rèn luyện thành thạo kỹ năng Atlat Địa lý Việt Nam giúp lấy điểm trắc nghiệm nhanh chóng, nhẹ nhàng. Chu đáo, nhiệt tình.', 'Gia sư Địa Lý Biên Hòa - Ôn thi tốt nghiệp hiệu quả cao', NULL, 'Đại học Đồng Nai - Cử nhân Địa lý học', NULL, NULL, '3 năm kinh nghiệm làm gia sư dạy kèm tự do môn Địa lý cấp 3.', 'Cần Thơ', 'Bình Thủy', 'active', true, 4.6, 13, 90, '2026-06-17 22:48:02.420918', '2026-06-17 22:48:02.420918', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('1732bee5-e2d8-46b5-930c-43e5047ea965', 'Khóa học được thiết kế chuyên biệt dành riêng cho học sinh lớp 12 bị mất gốc Toán trầm trọng cần ôn thi tốt nghiệp THPT cấp tốc. Hệ thống lại lý thuyết căn bản cốt lõi kết hợp giải bài tập mẫu sát sườn đề thi giúp lấy lại căn bản nhanh chóng sau 12 buổi học.', 'Gia sư Toán THPT - Lấy gốc siêu tốc cho học sinh lớp 12', NULL, 'Đại học Sư phạm Hà Nội - Sư phạm Toán học', NULL, NULL, '5 năm dạy kèm học sinh yếu kém môn Toán bứt phá điểm số khá giỏi.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.7, 27, 185, '2026-06-17 22:48:02.573842', '2026-06-17 22:48:02.573842', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('28c92176-13ba-45df-867d-1fbf6ad7d1f4', 'Sở hữu chứng chỉ IELTS 8.5 cùng lộ trình giảng dạy chuyên sâu toàn diện 4 kỹ năng chuẩn quốc tế. Tập trung rèn tư duy phản biện sắc bén phần Speaking và kỹ thuật viết luận Task 2 mạch lạc thu hút giám khảo chấm thi đạt điểm tối ưu. Nghiêm túc, chuyên nghiệp.', 'Gia sư Tiếng Anh luyện thi IELTS đạt mục tiêu Cam kết đầu ra', NULL, 'Đại học Ngoại thương TP.HCM - Kinh tế đối ngoại', NULL, NULL, '6 năm giảng dạy tại trung tâm Anh ngữ lớn quốc tế và gia sư IELTS nâng cao.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.9, 58, 400, '2026-06-17 22:48:02.734881', '2026-06-17 22:48:02.734881', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('7fa3cb09-38aa-4e5a-9025-c465975389c2', 'Nhận dạy kèm môn Vật lý lớp 10, 11, 12 tại khu vực Cần Thơ. Bài giảng logic, dễ hiểu, biến mọi công thức cơ học điện xoay chiều khô khan thành ví dụ thực tế trực quan giúp học sinh tiếp thu bài nhanh ngay tại lớp học. Thân thiện, nhiệt huyết vì học sinh.', 'Gia sư Vật Lý Cần Thơ - Ôn thi THPT bài bản dễ hiểu', NULL, 'Đại học Cần Thơ - Kỹ sư Điện tử viễn thông', NULL, NULL, '4 năm làm gia sư tại nhà môn Vật lý cho học sinh THPT Cần Thơ.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.6, 19, 140, '2026-06-17 22:48:02.883125', '2026-06-17 22:48:02.883125', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('b37a2162-2415-4554-8eb3-7a5850125bc4', 'Chuyên bồi dưỡng toán Hóa trắc nghiệm vô cơ và hữu cơ lớp 12 phục vụ tốt nhất kỳ thi tốt nghiệp THPTQG. Phương pháp giảng dạy khoa học, hướng dẫn giải nhanh bài toán đồ thị, chuỗi phản ứng phức tạp tiết kiệm 50% thời gian làm bài thi. Chu đáo, tận tâm.', 'Gia sư Hóa Học THPT - Luyện thi Đại học điểm số 8+', NULL, 'Đại học Sư phạm Đà Nẵng - Sư phạm Hóa học', NULL, NULL, '5 năm kinh nghiệm gia sư luyện thi đại học môn Hóa tại Đà Nẵng.', 'Đà Nẵng', 'Ngũ Hành Sơn', 'active', true, 4.8, 32, 210, '2026-06-17 22:48:03.036046', '2026-06-17 22:48:03.036046', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('82ffa6a8-5772-4419-adc1-f97d85912ba2', 'Chuyên luyện thi môn Ngữ Văn lớp 9 vào lớp 10 các trường THPT công lập bám sát tốt ma trận chấm thi tự luận của Sở Giáo dục. Giúp học sinh nắm vững phương pháp viết văn nghị luận văn học giàu cảm xúc sâu sắc. Kiên nhẫn, tinh tế, theo sát tiến độ học.', 'Gia sư Ngữ Văn - Khơi dậy tình yêu tác phẩm văn học lớp 9', NULL, 'Đại học Sài Gòn - Sư phạm Ngữ văn', NULL, NULL, '4 năm kinh nghiệm làm gia sư luyện thi môn Văn lớp 9 cấp tốc tại TP.HCM.', 'TP.HCM', 'Quận 1', 'active', true, 4.7, 24, 165, '2026-06-17 22:48:03.182951', '2026-06-17 22:48:03.182951', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('827cfcdc-45ff-46c6-be8c-3a548bf8409f', 'Nhận dạy kèm môn Lịch sử lớp 11, 12 cho các thí sinh ôn thi khối C tại khu vực Biên Hòa. Phương pháp giảng dạy logic liên kết dòng sự kiện lịch sử thế giới và lịch sử Việt Nam giúp học bài nhanh hiệu quả cao ngay trên lớp học. Trách nhiệm, sát sao.', 'Gia sư Lịch Sử khối C Biên Hòa - Luyện ôn bài bản', NULL, 'Đại học Đồng Nai - Sư phạm Lịch sử', NULL, NULL, '5 năm làm gia sư tại nhà luyện thi khối C đạt kết quả cao tại Biên Hòa.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.6, 22, 150, '2026-06-17 22:48:03.403158', '2026-06-17 22:48:03.403158', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('96826487-fafc-4551-b780-47a20b7e4d0d', 'Nhận dạy kèm luyện thi môn Địa Lý tốt nghiệp THPT quốc gia cấp tốc tại Cần Thơ. Hướng dẫn chi tiết kỹ năng khai thác và lấy điểm tuyệt đối phần trắc nghiệm Atlat Địa lý Việt Nam nhanh chóng dễ dàng nhất. Phong cách dạy vui vẻ thân thiện nhiệt huyết.', 'Gia sư Địa Lý Cần Thơ - Ôn thi bám sát cấu trúc đề tốt', NULL, 'Đại học Cần Thơ - Sư phạm Địa lý', NULL, NULL, '4 năm kinh nghiệm làm gia sư tự do môn Địa lý ôn thi cấp 3 tại Cần Thơ.', 'Hà Nội', 'Đống Đa', 'active', true, 4.6, 14, 95, '2026-06-17 22:48:03.555173', '2026-06-17 22:48:03.555173', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('85cd0600-960a-441f-be88-10d7437ca7a9', 'Phương pháp giảng dạy phản xạ ngôn ngữ hiện đại chuẩn Mỹ giúp học sinh tự tin giao tiếp thành thạo sau 3 tháng học tập tích cực. Hỗ trợ ôn luyện củng cố ngữ pháp căn bản làm đề thi tốt nghiệp THPT đạt kết quả cao tối ưu. Thân thiện, năng động, chu đáo.', 'Gia sư Tiếng Anh - Tiếng Anh giao tiếp và ôn thi chứng chỉ', NULL, 'Đại học Hà Nội - Ngôn ngữ Anh', NULL, NULL, '4 năm giảng dạy tại trung tâm tiếng Anh lớn và gia sư tại nhà Hà Nội.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.7, 29, 195, '2026-06-17 22:48:03.7808', '2026-06-17 22:48:03.7808', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('f287259f-61d0-44a0-8607-531cf3407823', 'Chuyên trị học sinh lười học học lực yếu kém mất căn bản môn Vật lý cấp 3 vươn lên đạt điểm khá giỏi nhanh chóng. Hệ thống lại lý thuyết nền tảng cơ bản ngắn gọn súc tích kết hợp bài tập vận dụng mẫu trực quan dễ hiểu nhất. Cam kết tiến bộ rõ rệt.', 'Gia sư Vật Lý THPT - Lấy gốc siêu tốc lớp 11, 12 tốt nhất', NULL, 'Đại học Sư phạm TP.HCM - Sư phạm Vật lý', NULL, NULL, '4 năm dạy kèm gia sư tại nhà môn Vật lý lớp 10, 11, 12 tại TP.HCM.', 'TP.HCM', 'Quận 3', 'active', true, 4.6, 21, 150, '2026-06-17 22:48:03.93271', '2026-06-17 22:48:03.93271', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('59f4a610-194a-4939-a9c4-84d6045c8d57', 'Nhận dạy kèm môn Hóa học ôn thi đại học bám sát ma trận cấu trúc đề thi thực tế của Bộ Giáo dục. Chia sẻ phương pháp bảo toàn khối lượng, phương pháp đồ thị giải toán hữu cơ phức tạp siêu nhanh siêu chuẩn xác. Chu đáo, tận tâm với học sinh.', 'Gia sư Hóa Học chuyên sâu hữu cơ và vô cơ ôn thi tốt nghiệp', NULL, 'Đại học Sư phạm Hà Nội - Cử nhân Sư phạm Hóa học', NULL, NULL, '6 năm giảng dạy luyện thi đại học môn Hóa học tại khu vực Thanh Xuân.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.8, 41, 280, '2026-06-17 22:48:04.083598', '2026-06-17 22:48:04.083598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-1', 'Chào các bạn, mình là Trang. Mình tin rằng học Tiếng Anh không hề khô khan như nhiều người nghĩ. Phương pháp của mình tập trung vào sự tương tác, giao tiếp thực tế và khơi gợi niềm yêu thích ngôn ngữ. Mình có kinh nghiệm dạy cho học sinh các cấp và cả người đi làm muốn cải thiện kỹ năng. Nếu bạn đang tìm kiếm một người bạn đồng hành vui vẻ và hiệu quả trên con đường học Tiếng Anh, hãy liên hệ với mình nhé!', 'Giáo viên Tiếng Anh giàu kinh nghiệm, giúp bạn chinh phục mọi kỳ thi!', NULL, 'Tốt nghiệp Đại học Sư phạm Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Tiếng Anh tại các trung tâm uy tín. Tỷ lệ học sinh đạt điểm cao trong các kỳ thi quốc tế lên đến 90%. Đã đào tạo thành công nhiều lớp luyện thi TOEIC, TOEFL và IELTS.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4, 23, 363, '2026-06-19 02:50:23.884626', '2026-06-19 02:50:23.884626', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-2', 'Chào mọi người, mình là Khôi, sinh viên năm cuối ngành Toán Tin. Mình muốn chia sẻ niềm đam mê với Toán học và giúp các bạn thấy rằng Toán không hề đáng sợ. Phương pháp của mình là đi từ bản chất vấn đề, áp dụng nhiều ví dụ minh họa và bài tập vận dụng thực tế. Mình rất kiên nhẫn và luôn tạo không khí học tập thoải mái, khuyến khích học sinh đặt câu hỏi. Rất phù hợp với các bạn học sinh mất gốc hoặc muốn nâng cao kiến thức Toán.', 'Thầy Khôi - Toán THPT: Biến những con số phức tạp thành bài toán dễ hiểu.', NULL, 'Sinh viên năm cuối ngành Toán Tin, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy Toán cho học sinh THPT, đặc biệt là ôn thi Đại học. Tỷ lệ học sinh đỗ nguyện vọng mong muốn đạt hơn 85%. Thường xuyên được học sinh khen là thầy giáo dễ gần và có cách giảng bài dễ hiểu.', 'Cần Thơ', 'Quận 1', 'active', true, 4.8, 53, 121, '2026-06-19 02:50:23.884626', '2026-06-19 02:50:23.884626', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-3', 'Xin chào, mình là Mai Anh. Mình đã chinh phục IELTS với band điểm 8.0 và mong muốn giúp bạn làm được điều tương tự. Mình hiểu những khó khăn khi học IELTS, vì vậy mình xây dựng lộ trình cá nhân hóa, tập trung vào kỹ năng yếu của từng học viên. Mình luôn khuyến khích sự chủ động và cung cấp phản hồi chi tiết để bạn tiến bộ nhanh chóng. Mình tin rằng với sự nỗ lực và phương pháp đúng đắn, bạn hoàn toàn có thể đạt được mục tiêu IELTS của mình.', 'Chuyên gia IELTS 8.0, đồng hành cùng bạn đạt band điểm mơ ước.', NULL, 'Tốt nghiệp loại Giỏi ngành Ngôn ngữ Anh, Đại học Ngoại thương.', NULL, NULL, 'Có 4 năm kinh nghiệm luyện thi IELTS cho học viên ở nhiều lứa tuổi và trình độ. Giúp nhiều học viên đạt target 6.5 - 7.5 chỉ sau 3-6 tháng ôn luyện. Thành tích nổi bật là giúp một học sinh 17 tuổi đạt 7.5 IELTS ngay lần thi đầu tiên.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4.5, 37, 88, '2026-06-19 02:50:23.884626', '2026-06-19 02:50:23.884626', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-12', 'Xin chào! Mình là Minh Quân, một người đam mê khám phá những câu chuyện lịch sử. Mình tin rằng học Lịch sử không chỉ là học thuộc những ngày tháng, sự kiện mà là thấu hiểu nguyên nhân, diễn biến và ý nghĩa của nó. Mình sẽ dẫn dắt các bạn đi qua những dòng chảy thời gian bằng cách kể chuyện hấp dẫn, liên hệ thực tế để Lịch sử trở nên sống động và gần gũi hơn.', 'Lịch Sử - Kể chuyện quá khứ, hiểu sâu sắc từng giai đoạn!', NULL, 'Cử nhân ngành Lịch sử, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh có cái nhìn toàn diện và sâu sắc về các giai đoạn lịch sử, cải thiện đáng kể điểm số môn học.', 'TP.HCM', 'Phú Nhuận', 'active', true, 5, 15, 104, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-4', 'Chào các em, thầy là Hùng. Thầy có cách tiếp cận Vật Lý theo hướng tư duy hệ thống, giúp các em hiểu sâu bản chất thay vì chỉ học thuộc lòng công thức. Thầy thường sử dụng các thí nghiệm mô phỏng và ví dụ thực tế để làm bài học trở nên sinh động hơn. Thầy rất kiên nhẫn, luôn sẵn sàng giải đáp mọi thắc mắc và giúp các em xây dựng sự tự tin khi làm bài tập Vật Lý.', 'Thầy Hùng Vật Lý: Giải thích định luật bằng tư duy logic, gần gũi.', NULL, 'Thạc sĩ Vật lý Kỹ thuật, Đại học Bách khoa Hà Nội.', NULL, NULL, 'Đã có 6 năm kinh nghiệm giảng dạy Vật Lý tại trường THPT và các trung tâm luyện thi. Tỷ lệ học sinh đạt điểm khá giỏi môn Vật Lý luôn ở mức cao. Có kinh nghiệm bồi dưỡng học sinh giỏi Vật Lý cấp thành phố.', 'Bình Dương', 'Quận 1', 'active', true, 4.4, 22, 232, '2026-06-19 02:50:23.884626', '2026-06-19 02:50:23.884626', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-5', 'Xin chào các em học sinh yêu văn! Mình là Lan Hương, giáo viên Ngữ văn. Mình tin rằng Văn học là hành trang quý giá nuôi dưỡng tâm hồn. Phương pháp dạy của mình là kết hợp phân tích tác phẩm sâu sắc với việc đồng cảm, chia sẻ cảm xúc, giúp các em cảm thụ văn chương một cách tinh tế. Mình muốn tạo ra một không gian học tập mở, nơi các em có thể tự do bày tỏ suy nghĩ và phát triển khả năng diễn đạt của mình. Rất phù hợp với các bạn muốn cải thiện điểm số, yêu thích môn Văn hoặc chuẩn bị cho các kỳ thi quan trọng.', 'Cô Hương Văn Học: Khơi gợi cảm xúc, nâng niu từng câu chữ.', NULL, 'Cử nhân Ngữ văn, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Ngữ văn cho học sinh THCS và THPT. Giúp nhiều học sinh cải thiện đáng kể điểm số, đặc biệt là trong các bài văn nghị luận. Kinh nghiệm ôn thi vào lớp 10 và kỳ thi tốt nghiệp THPT.', 'Đồng Nai', 'Quận 3', 'active', true, 4.3, 19, 326, '2026-06-19 02:50:23.884626', '2026-06-19 02:50:23.884626', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-6', 'Chào các bạn, mình là Minh Anh, sinh viên năm 3 ngành Toán Tin tại ĐH Khoa học Tự nhiên. Mình có cách truyền đạt kiến thức rất dễ hiểu, biến những bài toán khó thành những câu chuyện thú vị. Đặc biệt, mình rất kiên nhẫn và luôn tìm hiểu nguyên nhân vì sao học sinh gặp khó khăn để có phương pháp hỗ trợ tốt nhất. Mình nhận dạy cho học sinh lớp 10, 11, 12.', 'Gia sư Toán 12 - Chinh phục mọi dạng bài, điểm cao trong tầm tay!', NULL, 'Sinh viên năm 3, ngành Toán Tin, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy kèm Toán THPT. Tỷ lệ học sinh đạt điểm 8+ trên 90%. Thường xuyên bồi dưỡng đội tuyển HSG Toán của trường.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.9, 35, 389, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-7', 'Xin chào! Mình là Thu Hà, tốt nghiệp chuyên ngành Ngôn ngữ Anh với niềm đam mê bất tận với việc chia sẻ kiến thức ngoại ngữ. Phương pháp của mình tập trung vào việc tạo môi trường học tập vui vẻ, tương tác, giúp học viên tự tin sử dụng Tiếng Anh trong mọi tình huống. Mình tin rằng ai cũng có thể nói Tiếng Anh lưu loát nếu có lộ trình phù hợp và sự kiên trì.', 'Tiếng Anh Giao tiếp & Thi chứng chỉ - Fluency is Key!', NULL, 'Cử nhân chuyên ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho người đi làm và sinh viên. Thành tích nổi bật là giúp nhiều học viên đạt điểm IELTS từ 6.0 lên 7.0. Dạy cả online và offline.', 'Biên Hòa', 'Bình Thạnh', 'active', true, 4.4, 65, 316, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-8', 'Tôi là Văn Hoàng, cựu học sinh chuyên Lý trường THPT Chuyên Amsterdam. Mình luôn tâm niệm Vật Lý không hề khô khan mà chứa đựng những quy luật vô cùng logic và đẹp đẽ. Mình sẽ giúp các bạn nhìn Vật Lý dưới một góc độ mới, với phương pháp dạy bám sát chương trình, nhiều ví dụ thực tế và bài tập ứng dụng. Mình đặc biệt phù hợp với các bạn đang gặp khó khăn trong việc nắm bắt bản chất.', 'Gia sư Vật Lý THPT - Giải thích cặn kẽ, làm chủ kiến thức!', NULL, 'Thủ khoa đầu vào ngành Sư phạm Vật lý, Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy kèm Vật Lý THPT. Nhiều học sinh đã cải thiện điểm số rõ rệt, có em đạt điểm 10 trong kỳ thi tốt nghiệp. Phù hợp với lớp 10, 11, 12.', 'Bình Dương', 'Quận 1', 'active', true, 4.1, 46, 108, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-9', 'Xin chào các em! Mình là Mai, sinh viên Y Đa khoa. Mình biết Hóa học có thể hơi "nhằn" với nhiều bạn, nhưng đừng lo! Mình sẽ giúp các em xây dựng nền tảng vững chắc, hiểu rõ bản chất các phản ứng và có những mẹo làm bài hiệu quả. Mình dạy theo hướng giúp học sinh tự tư duy, chứ không chỉ học thuộc lòng. Mình rất vui khi thấy các em tiến bộ từng ngày.', 'Hóa Học THPT - Tư duy phản ứng, bứt phá điểm số!', NULL, 'Sinh viên Y Đa khoa, Đại học Y Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa THPT. Giúp nhiều học sinh từ điểm trung bình vươn lên khá, giỏi. Chuyên ôn luyện cho kỳ thi THPT Quốc gia môn Hóa.', 'Bình Dương', 'Quận 7', 'active', true, 4.1, 33, 149, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-10', 'Tôi là Tuấn Kiệt, một người yêu văn chương sâu sắc. Tôi tin rằng mỗi bài văn, bài thơ đều ẩn chứa những tầng ý nghĩa sâu sắc và vẻ đẹp riêng. Tôi không dạy theo lối nhồi nhét kiến thức mà tập trung khơi gợi sự tò mò, cảm xúc và tư duy phân tích cho học sinh. Chúng ta sẽ cùng nhau khám phá thế giới văn học đầy màu sắc, từ đó nâng cao khả năng cảm thụ và viết văn.', 'Ngữ Văn - Khơi nguồn cảm hứng, cảm thụ văn chương tinh tế!', NULL, 'Thạc sĩ chuyên ngành Văn học Việt Nam, Đại học Văn hóa.', NULL, NULL, '5 năm kinh nghiệm giảng dạy và luyện thi môn Ngữ văn. Đã hướng dẫn thành công nhiều học sinh đạt điểm cao trong các kỳ thi học sinh giỏi và thi Đại học.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.4, 56, 223, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-11', 'Chào các bạn, mình là Lan Anh, sinh viên năm cuối ngành Sinh học Phân tử. Mình có niềm yêu thích đặc biệt với thế giới vi mô của tế bào và sự kỳ diệu của di truyền. Mình sẽ giúp các bạn xây dựng kiến thức Sinh học một cách logic, dễ nhớ thông qua sơ đồ tư duy và các ví dụ minh họa sinh động. Mình kiên nhẫn, nhiệt tình và luôn sẵn sàng giải đáp mọi thắc mắc của các bạn.', 'Sinh Học THPT - Chinh phục cấu trúc tế bào & di truyền học!', NULL, 'Sinh viên năm cuối ngành Sinh học Phân tử, Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học cho học sinh THPT. Giúp nhiều em vượt qua nỗi sợ môn Sinh và đạt kết quả tốt trong các bài kiểm tra, thi học kỳ.', 'TP.HCM', 'Quận 3', 'active', true, 4.1, 5, 351, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-13', 'Chào mừng các bạn đến với lớp học Địa lý của mình! Mình là Bích Ngọc, một người yêu thích khám phá thế giới qua những tấm bản đồ. Mình sẽ giúp các bạn hiểu về các quy luật tự nhiên, kinh tế - xã hội của Việt Nam và thế giới một cách trực quan, sinh động. Phương pháp của mình là kết hợp lý thuyết với hình ảnh, video và các bài tập thực hành để các bạn dễ dàng hình dung và ghi nhớ.', 'Địa Lý THPT - Khám phá thế giới qua bản đồ & tư duy không gian!', NULL, 'Cử nhân ngành Địa lý học, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý THPT. Giúp học sinh nắm vững kiến thức, kỹ năng phân tích bản đồ và biểu đồ, cải thiện kết quả học tập.', 'Bình Dương', 'Quận 7', 'active', true, 4.7, 33, 63, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-14', 'Mình là Gia Huy, một lập trình viên trẻ tuổi với niềm đam mê công nghệ. Mình tin rằng ai cũng có thể học lập trình nếu có phương pháp đúng. Mình sẽ hướng dẫn các bạn từ những khái niệm cơ bản nhất, giúp các bạn xây dựng tư duy logic và kỹ năng giải quyết vấn đề thông qua các ngôn ngữ lập trình phổ biến như Python. Học với mình sẽ rất vui và đầy thử thách!', 'Tin Học Căn Bản & Lập Trình Nhập Môn - Code dễ hiểu, tư duy logic!', NULL, 'Kỹ sư Công nghệ Thông tin, Học viện Công nghệ Bưu chính Viễn thông.', NULL, NULL, '1 năm kinh nghiệm dạy Tin học cơ bản và lập trình Python cho học sinh THCS & THPT. Giúp nhiều em tiếp cận và yêu thích lập trình.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.6, 28, 231, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-15', 'Hello everyone! Mình là Thảo, mình đã đạt IELTS 7.5 overall và rất hào hứng được chia sẻ kinh nghiệm luyện thi cùng các bạn. Mình hiểu những khó khăn mà các bạn gặp phải trong từng kỹ năng, đặc biệt là Speaking và Writing. Phương pháp của mình tập trung vào việc cá nhân hóa lộ trình, cung cấp các tips làm bài hiệu quả và rèn luyện phản xạ. Mình rất nhiệt tình và luôn đồng hành cùng học viên.', 'IELTS 7.5 - Luyện band điểm mục tiêu, tự tin du học!', NULL, 'IELTS 7.5 (8.0 Listening, 7.0 Reading, 7.0 Writing, 7.0 Speaking).', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS cho học viên từ 15-25 tuổi. Nhiều học viên đạt mục tiêu band điểm mong muốn trong lần thi đầu.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.2, 12, 252, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-16', 'Chào các bạn sinh viên và học sinh lớp 12! Mình là Đức Long, mình sẽ giúp các bạn chinh phục các chủ đề Toán học phức tạp như Đại số Tuyến tính, Giải tích, Lượng giác. Mình có khả năng biến những khái niệm trừu tượng trở nên dễ hiểu bằng các ví dụ trực quan và phương pháp chứng minh logic. Mình rất kiên nhẫn và mong muốn trang bị cho các bạn nền tảng toán học vững chắc.', 'Toán Cao Cấp & Lượng Giác - Nền tảng vững chắc cho tương lai!', NULL, 'Thạc sĩ Toán học Ứng dụng, Đại học Bách Khoa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán cao cấp cho sinh viên các trường ĐH. Giúp nhiều học sinh lớp 12 ôn thi đại học khối A, A1 hiệu quả.', 'Hà Nội', 'Hải Châu', 'active', true, 4, 15, 352, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-17', 'Xin chào ba mẹ và các con! Mình là Thúy An, mình có 4 năm kinh nghiệm dạy Tiếng Anh cho lứa tuổi nhỏ. Mình luôn tạo ra môi trường học tập vui vẻ, tràn đầy năng lượng với các bài hát, trò chơi và hoạt động tương tác. Mục tiêu của mình là giúp các con làm quen và yêu thích môn Tiếng Anh một cách tự nhiên, xây dựng sự tự tin khi giao tiếp.', 'Tiếng Anh Tiểu học & THCS - Vừa học vừa chơi, yêu tiếng Anh!', NULL, 'Cử nhân Sư phạm Tiếng Anh, Đại học Sư phạm TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh cho học sinh tiểu học và THCS. Giúp các em phát âm chuẩn, cải thiện kỹ năng nghe-nói và tạo hứng thú học tập.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 5, 57, 275, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-18', 'Chào các bạn! Mình là Minh Đạt, mình hiểu rằng Vật Lý có thể là một thử thách với nhiều sĩ tử. Mình tập trung vào việc phân tích kỹ đề bài, hướng dẫn phương pháp giải nhanh các dạng bài tập thường gặp trong đề thi Đại học. Mình sẽ giúp các bạn xây dựng sự tự tin và khả năng làm bài hiệu quả dưới áp lực thời gian. Chúng ta sẽ cùng nhau chinh phục mục tiêu điểm cao!', 'Vật Lý 11 & 12 - Ôn thi Đại học, nắm chắc kiến thức cốt lõi!', NULL, 'Cựu sinh viên ngành Kỹ thuật Hàng không, Đại học Bách Khoa TP.HCM.', NULL, NULL, '3 năm kinh nghiệm luyện thi Vật Lý cho kỳ thi THPT Quốc gia. Giúp nhiều học sinh đạt điểm 7-9 môn Vật Lý.', 'TP.HCM', 'Quận 3', 'active', true, 5, 39, 168, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-19', 'Chào các bạn sinh viên và học sinh! Mình là Phương Linh, mình có kinh nghiệm giảng dạy Hóa học từ cơ bản đến nâng cao. Mình đặc biệt giỏi trong việc giải thích các khái niệm Hóa học phức tạp, đặc biệt là Hóa học Hữu cơ, một cách logic và dễ hiểu. Mình sẽ giúp các bạn rèn luyện kỹ năng phân tích cấu trúc, dự đoán phản ứng và giải các dạng bài tập từ cơ bản đến chuyên sâu.', 'Hóa Học Đại Cương & Hữu Cơ - Tư duy phản ứng, giải bài tập dễ dàng!', NULL, 'Thạc sĩ Hóa học, Đại học Khoa học Tự nhiên.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa học cho sinh viên đại học và học sinh PTTH. Giúp nhiều học viên nắm vững kiến thức và đạt kết quả cao.', 'Hà Nội', 'Quận 7', 'active', true, 4.1, 55, 327, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-20', 'Xin chào! Tôi là Quốc Anh, một người say mê văn chương và luôn tìm tòi những giá trị nhân văn sâu sắc trong các tác phẩm văn học. Tôi sẽ giúp các bạn không chỉ học thuộc mà còn cảm thụ tinh tế các tác phẩm Văn học Việt Nam, đặc biệt là giai đoạn hiện đại. Phương pháp của tôi là khơi gợi tư duy phản biện, giúp các bạn hình thành lập luận chặt chẽ và viết bài văn nghị luận sắc sảo.', 'Văn Học Việt Nam Hiện Đại - Phân tích sâu tác phẩm, viết văn nghị luận sắc bén!', NULL, 'Cử nhân Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, '3 năm kinh nghiệm luyện thi môn Văn. Giúp học sinh nâng cao kỹ năng phân tích, cảm thụ văn học và đạt điểm cao trong các kỳ thi.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4.6, 44, 252, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-21', 'Chào các bạn trẻ yêu khoa học! Mình là Thúy Vy, mình rất thích khám phá những điều kỳ diệu của thế giới sinh vật và các vấn đề môi trường. Mình muốn chia sẻ kiến thức Sinh học một cách gần gũi, thực tế, giúp các bạn hiểu rõ hơn về cơ thể mình và hành tinh chúng ta đang sống. Mình dạy theo phương pháp tương tác, khuyến khích học sinh đặt câu hỏi và tự khám phá.', 'Sinh Học Ứng Dụng & Môi Trường - Hiểu biết về thế giới tự nhiên!', NULL, 'Cử nhân Khoa học Môi trường, Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học và Khoa học Môi trường cho học sinh THCS & THPT. Giúp các em có cái nhìn tổng quan và hứng thú hơn với môn học.', 'Đồng Nai', 'Quận 3', 'active', true, 4.3, 53, 172, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-22', 'Tôi là Minh Hiếu, một người luôn bị cuốn hút bởi những sự kiện lịch sử đã định hình nên thế giới hiện đại. Tôi sẽ giúp các bạn hiểu rõ hơn về các cuộc cách mạng, chiến tranh và các phong trào xã hội đã diễn ra trên thế giới. Phương pháp của tôi là sử dụng bản đồ, tư liệu lịch sử và các câu chuyện để làm cho môn học trở nên hấp dẫn và dễ tiếp thu hơn.', 'Lịch Sử Thế Giới Cận Đại - Khám phá các biến động lịch sử quan trọng!', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử thế giới cho học sinh THPT. Giúp học sinh nắm bắt mạch logic của các sự kiện lịch sử phức tạp.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.1, 48, 82, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-23', 'Xin chào! Mình là Phương Mai, mình có niềm đam mê đặc biệt với Địa lý Việt Nam. Mình tin rằng hiểu về địa lý quê hương sẽ giúp chúng ta thêm yêu và có ý thức bảo vệ đất nước. Mình sẽ cùng các bạn khám phá các đặc điểm tự nhiên, sự phân bố dân cư, phát triển kinh tế của các vùng miền trên khắp đất nước một cách trực quan và sinh động.', 'Địa Lý Tự Nhiên & Kinh Tế Việt Nam - Hiểu về đất nước mình!', NULL, 'Cử nhân Địa lý học, Đại học Sư phạm Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý Việt Nam cho học sinh THCS & THPT. Giúp học sinh nắm chắc kiến thức, kỹ năng đọc bản đồ và biểu đồ.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.6, 5, 132, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-24', 'Chào mọi người! Mình là Tuấn Minh, mình giúp các bạn làm quen với thế giới công nghệ. Mình dạy Tin học văn phòng (Word, Excel, PowerPoint) một cách hiệu quả và cả những kiến thức lập trình cơ bản (Python). Mình có cách giải thích đơn giản, dễ hiểu, phù hợp với cả những người mới bắt đầu. Học với mình sẽ giúp các bạn tự tin hơn khi làm việc với máy tính.', 'Tin Học Văn Phòng & Lập Trình Cơ Bản - Công cụ số cho mọi người!', NULL, 'Sinh viên ngành Hệ thống Thông tin Quản lý, Đại học Kinh tế Quốc dân.', NULL, NULL, '1 năm kinh nghiệm dạy Tin học văn phòng và lập trình cơ bản cho người đi làm và học sinh. Giúp nhiều người nâng cao kỹ năng sử dụng máy tính.', 'Đồng Nai', 'Quận 1', 'active', true, 4.3, 34, 51, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-25', 'Hello! Mình là Bảo Ngọc, mình đã chinh phục IELTS với điểm cao ở hai kỹ năng Writing và Speaking. Mình hiểu rõ những ''bẫy'' và yêu cầu của từng phần thi. Mình sẽ cung cấp cho bạn những cấu trúc câu, từ vựng ''ăn điểm'' và phương pháp luyện tập hiệu quả để bạn có thể diễn đạt ý tưởng một cách mạch lạc, tự tin và chính xác nhất. Mình rất nhiệt huyết và luôn động viên học viên của mình.', 'IELTS Writing & Speaking - Phản xạ, từ vựng, cấu trúc bài thi!', NULL, 'IELTS 8.0 (Writing 7.5, Speaking 8.0). Cử nhân ngành Kinh tế đối ngoại.', NULL, NULL, '2 năm kinh nghiệm chuyên sâu luyện thi IELTS Writing & Speaking. Giúp học viên cải thiện band điểm rõ rệt, tự tin tham gia phỏng vấn học bổng.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.4, 20, 426, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-26', 'Chào các em học sinh lớp 10! Mình là Duy Khang, mình rất vui được đồng hành cùng các em trong năm học đầu tiên đầy thử thách này. Mình sẽ giúp các em nắm vững các kiến thức về Đại số và Hình học, xây dựng tư duy logic và phương pháp học tập hiệu quả. Mình luôn tạo không khí lớp học thoải mái, khuyến khích các em đặt câu hỏi và cùng nhau tìm ra lời giải.', 'Toán 10 - Xây dựng nền tảng vững chắc cho 3 năm THPT!', NULL, 'Sinh viên ngành Toán học, Đại học Khoa học Tự nhiên.', NULL, NULL, '1 năm kinh nghiệm dạy kèm Toán lớp 10. Giúp nhiều học sinh làm quen và yêu thích môn Toán ngay từ đầu.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.3, 61, 344, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-27', 'Xin chào! Mình là Bích Thủy, mình có niềm yêu thích đặc biệt với Tiếng Anh và mong muốn giúp mọi người có thể sử dụng ngôn ngữ này một cách tự tin. Mình sẽ tập trung vào việc xây dựng nền tảng vững chắc về từ vựng, ngữ pháp và đặc biệt là phát âm chuẩn. Phương pháp của mình là kết hợp lý thuyết với các hoạt động thực hành đa dạng, giúp việc học trở nên thú vị và hiệu quả.', 'Tiếng Anh Tổng Quát - Từ vựng, Ngữ pháp & Phát âm chuẩn!', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp và luyện thi chứng chỉ A2, B1. Giúp học viên cải thiện sự tự tin và khả năng sử dụng Tiếng Anh.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.8, 26, 187, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-28', 'Chào các em! Mình là Minh Khôi, mình muốn mang đến cho các em một cái nhìn mới mẻ và thú vị về Vật Lý. Mình sẽ giúp các em hiểu rõ các khái niệm cơ bản, thực hiện các thí nghiệm mô phỏng và giải các bài tập ứng dụng. Mình có cách dạy gần gũi, kiên nhẫn, phù hợp với lứa tuổi THCS và lớp 10. Cùng nhau khám phá những điều kỳ diệu của Vật Lý nhé!', 'Vật Lý THCS & Lớp 10 - Khám phá thế giới khoa học!', NULL, 'Sinh viên ngành Kỹ thuật Điện tử - Viễn thông, Đại học Công nghệ.', NULL, NULL, '1 năm kinh nghiệm dạy Vật Lý cho học sinh THCS và lớp 10. Giúp các em tiếp cận môn học một cách dễ dàng và hứng thú.', 'Bình Dương', 'Quận 1', 'active', true, 4.6, 13, 285, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-29', 'Xin chào các em! Cô là Thuỳ Trang, cô rất vui được đồng hành cùng các em trong môn Hóa học. Cô hiểu rằng Hóa học đôi khi có vẻ khó hiểu, nhưng cô sẽ giúp các em làm quen với nó thông qua các thí nghiệm đơn giản, hình ảnh minh họa sinh động và các hoạt động tương tác. Mục tiêu của cô là giúp các em xây dựng sự yêu thích và nền tảng vững chắc cho môn học này.', 'Hóa Học THCS - Làm quen với hóa học một cách vui vẻ!', NULL, 'Cử nhân Sư phạm Hóa học, Đại học Sư phạm TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa học cho học sinh THCS. Giúp các em tiếp cận môn học một cách tự tin và hào hứng.', 'Bình Dương', 'Quận 1', 'active', true, 4.8, 55, 344, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-30', 'Chào các em! Mình là Gia Bảo, mình thích đọc sách và viết lách. Mình tin rằng Ngữ văn là môn học giúp chúng ta hiểu sâu sắc hơn về con người và cuộc sống. Mình sẽ giúp các em nắm vững kiến thức sách giáo khoa, phát triển khả năng phân tích, cảm thụ và diễn đạt. Lớp học của mình sẽ luôn vui vẻ, sáng tạo và đầy cảm hứng.', 'Ngữ Văn THCS - Phát triển tư duy ngôn ngữ, yêu thích văn chương!', NULL, 'Sinh viên ngành Báo chí, Học viện Báo chí và Tuyên truyền.', NULL, NULL, '1 năm kinh nghiệm dạy Ngữ văn cho học sinh THCS. Giúp các em cải thiện kỹ năng đọc hiểu và viết văn.', 'TP.HCM', 'Hải Châu', 'active', true, 4.6, 19, 96, '2026-06-19 02:51:20.01028', '2026-06-19 02:51:20.01028', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-56', 'Chào các bạn, mình là Mai Anh, cô giáo Tiếng Anh đầy nhiệt huyết! Mình tin rằng học ngôn ngữ là một hành trình khám phá thú vị, không hề khô khan. Phương pháp của mình tập trung vào việc tạo môi trường học tập cởi mở, khuyến khích học viên đặt câu hỏi và tự tin thể hiện bản thân. Mình đặc biệt yêu thích việc giúp các bạn mất gốc lấy lại căn bản và chinh phục mục tiêu.', 'Tiếng Anh giao tiếp & luyện thi chứng chỉ, 5 năm kinh nghiệm', NULL, 'Tốt nghiệp Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Tiếng Anh cho mọi lứa tuổi. Từng phụ trách các lớp luyện thi IELTS và TOEFL, giúp nhiều học viên đạt điểm cao. Am hiểu tâm lý học sinh phổ thông và sinh viên.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.4, 14, 318, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-57', 'Mình là Hùng, một cựu học sinh chuyên Toán với kinh nghiệm giảng dạy nhiều năm. Mình muốn chia sẻ những phương pháp giải Toán hiệu quả, giúp các em học sinh hiểu bản chất vấn đề thay vì học thuộc lòng. Mình kiên nhẫn, kỹ tính và luôn cố gắng tìm ra cách tiếp cận phù hợp nhất cho từng bạn, đặc biệt là những bạn đang gặp khó khăn với môn Toán.', 'Gia sư Toán THPT - Bí quyết đạt điểm cao dễ dàng', NULL, 'Thủ khoa đầu vào ngành Toán Tin, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Đã đồng hành cùng hơn 50 học sinh chinh phục thành công các kỳ thi học kỳ và thi THPTQG. Giúp các em cải thiện điểm số trung bình từ 3-4 điểm. Có kinh nghiệm dạy kèm các dạng bài từ cơ bản đến nâng cao.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.7, 20, 346, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-58', 'Xin chào, mình là Trang. Mình yêu văn chương và mong muốn truyền tình yêu đó đến với các bạn học sinh. Mình áp dụng phương pháp học tập chủ động, giúp các bạn phân tích đề bài sâu sắc, xây dựng dàn ý logic và viết bài văn giàu cảm xúc. Mình tin rằng mỗi học sinh đều có khả năng cảm thụ văn học, chỉ cần có người dẫn đường phù hợp.', 'Ngữ văn THPT - Khơi nguồn cảm hứng, đạt điểm tối đa', NULL, 'Sinh viên năm cuối ngành Sư phạm Ngữ văn, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có kinh nghiệm 3 năm dạy kèm môn Ngữ văn. Giúp nhiều học sinh cải thiện đáng kể điểm số, đặc biệt là các bài văn nghị luận. Thường xuyên cập nhật các dạng đề mới và phương pháp làm bài hiệu quả.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.2, 29, 322, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-59', 'Chào các bạn, mình là Đức. Mình có niềm đam mê lớn với Vật Lý và mong muốn giúp các bạn thấy được vẻ đẹp logic, khoa học của môn học này. Phương pháp của mình nhấn mạnh vào việc xây dựng nền tảng kiến thức vững chắc, rèn luyện kỹ năng phân tích, suy luận và áp dụng công thức một cách sáng tạo. Mình rất kiên nhẫn và sẵn sàng giải thích lại mọi thứ cho đến khi bạn hiểu rõ.', 'Vật Lý THPT - Giải thích mạch lạc, tư duy phản biện', NULL, 'Cựu sinh viên ngành Kỹ thuật Hạt nhân, Viện Nghiên cứu Hạt nhân Đà Lạt.', NULL, NULL, 'Đã có 4 năm kinh nghiệm dạy Vật Lý THPT. Thành tích nổi bật là giúp nhiều học sinh đạt điểm giỏi, xuất sắc trong các kỳ thi. Có kinh nghiệm dạy các dạng bài tập từ cơ bản đến Olympic.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.6, 8, 205, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-60', 'Mình là Ngọc, cô giáo Hóa học yêu thích sự tương tác và khám phá. Mình tin rằng học Hóa không chỉ là học công thức mà còn là hiểu về thế giới xung quanh. Mình thường sử dụng các ví dụ thực tế, thí nghiệm minh họa (nếu có thể) và bài tập ứng dụng để giúp các bạn nắm vững kiến thức một cách sinh động nhất. Mình là người vui vẻ, hòa đồng và luôn tạo không khí học tập thoải mái.', 'Hóa Học THPT - Thực hành, trực quan, dễ hiểu', NULL, 'Tốt nghiệp ngành Hóa học, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, '2 năm kinh nghiệm gia sư Hóa học cho học sinh lớp 10-12. Giúp các em vượt qua nỗi sợ Hóa và đạt kết quả tốt. Có khả năng hệ thống hóa kiến thức, bài tập theo từng chuyên đề.', 'TP.HCM', 'Hải Châu', 'active', true, 4.8, 51, 167, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-61', 'Hello mọi người, mình là Khang. Mình đã trải qua quá trình ôn luyện IELTS và hiểu rõ những khó khăn, áp lực mà các bạn đang đối mặt. Mình sẽ chia sẻ những bí quyết, chiến lược làm bài hiệu quả cho từng kỹ năng (Listening, Reading, Writing, Speaking) dựa trên kinh nghiệm thực tế và các tài liệu uy tín. Mình rất thân thiện, dễ gần và sẵn sàng hỗ trợ các bạn 24/7.', 'IELTS 7.5 - Tăng band điểm nhanh chóng, chiến lược hiệu quả', NULL, 'Đạt IELTS 7.5 overall (Listening 8.5, Reading 8.0, Writing 7.0, Speaking 7.0). Hiện đang học ngành Kinh tế đối ngoại, Đại học Ngoại thương.', NULL, NULL, 'Có kinh nghiệm 2 năm luyện thi IELTS cho sinh viên và người đi làm. Giúp nhiều học viên tăng band điểm trung bình từ 1-2.5 điểm chỉ sau 3 tháng. Chuyên luyện Writing và Speaking.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4, 63, 236, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-62', 'Chào các bạn, mình là Yến Nhi. Mình yêu thích Sinh học và muốn truyền cảm hứng cho các bạn khám phá những điều kỳ diệu của sự sống. Mình có phương pháp dạy logic, hệ thống hóa kiến thức từ dễ đến khó, kết hợp sơ đồ tư duy và hình ảnh minh họa để bài học trở nên sinh động và dễ nhớ hơn. Mình rất kiên nhẫn và luôn khuyến khích học viên chủ động trong việc học.', 'Sinh Học THPT - Từ cơ bản đến nâng cao, ôn thi hiệu quả', NULL, 'Sinh viên năm cuối ngành Công nghệ Sinh học, Học viện Nông nghiệp Việt Nam.', NULL, NULL, 'Gia sư Sinh học được 3 năm. Giúp học sinh nắm vững kiến thức, ôn thi hiệu quả các kỳ thi học kỳ và thi THPTQG. Có kinh nghiệm dạy các chương khó như Di truyền và Sinh thái.', 'Hà Nội', 'Quận 3', 'active', true, 4.1, 40, 179, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-63', 'Hi, mình là Tuấn Anh. Mình đam mê công nghệ và muốn chia sẻ những kiến thức Tin học hữu ích trong cuộc sống và học tập. Mình tập trung vào việc thực hành, giúp các bạn làm quen nhanh chóng với các công cụ văn phòng (Word, Excel, PowerPoint) và các kiến thức lập trình cơ bản (Python, C++). Mình là người thẳng thắn, dễ hiểu và luôn sẵn sàng giải đáp mọi thắc mắc.', 'Tin Học văn phòng & Lập trình cơ bản - Thực hành là chính', NULL, 'Tốt nghiệp ngành Khoa học Máy tính, Trường Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Tin học. Giúp sinh viên năm nhất làm quen với lập trình và học sinh THPT sử dụng máy tính hiệu quả. Đã hướng dẫn nhiều khóa học ngắn hạn về Excel nâng cao.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 5, 13, 330, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-64', 'Xin chào, mình là Minh Khuê. Mình tin rằng lịch sử không chỉ là những con số và sự kiện khô khan mà là những câu chuyện đầy ý nghĩa về quá khứ. Mình áp dụng phương pháp kể chuyện sinh động, kết hợp sử dụng bản đồ, tranh ảnh và các nguồn tư liệu thú vị để giúp các bạn yêu thích và ghi nhớ lịch sử một cách tự nhiên. Mình là người có giọng văn truyền cảm, dễ gần.', 'Lịch Sử THPT - Kể chuyện lịch sử, ghi nhớ dễ dàng', NULL, 'Cựu sinh viên ngành Việt Nam học, chuyên ngành Lịch sử Việt Nam, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh hiểu sâu sắc các giai đoạn lịch sử, đặc biệt là Lịch sử Việt Nam. Có kinh nghiệm ôn thi THPTQG, nhiều học viên đạt điểm trên 8.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.8, 45, 159, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-65', 'Chào mọi người, mình là Quang. Mình yêu thích việc khám phá thế giới qua những tấm bản đồ và các số liệu địa lý. Mình muốn chia sẻ niềm đam mê đó bằng cách dạy Địa lý một cách trực quan, dễ hiểu, tập trung vào việc phân tích mối quan hệ giữa các yếu tố tự nhiên, kinh tế, xã hội. Mình là người có kiến thức sâu rộng, kiên nhẫn và luôn tìm cách làm cho bài giảng trở nên sinh động.', 'Địa Lý THPT - Khám phá thế giới qua bản đồ và số liệu', NULL, 'Tốt nghiệp ngành Địa lý tự nhiên, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Có kinh nghiệm 3 năm dạy Địa lý cho học sinh THPT. Giúp các em nắm vững kiến thức sách giáo khoa và kiến thức thực tế. Có kinh nghiệm ôn thi THPTQG môn Địa Lý.', 'Bình Dương', 'Hải Châu', 'active', true, 4.2, 46, 150, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-66', 'Xin chào bố mẹ và các con, mình là Lan Anh. Mình có kinh nghiệm giảng dạy Tiếng Anh cho lứa tuổi nhỏ. Mình tin rằng việc học ngoại ngữ cần sự vui vẻ và hứng thú. Phương pháp của mình tập trung vào việc sử dụng các hoạt động tương tác, trò chơi, bài hát và hình ảnh sinh động để các con tiếp thu kiến thức một cách tự nhiên và không áp lực. Mục tiêu của mình là giúp các con hình thành phản xạ giao tiếp cơ bản.', 'Tiếng Anh Tiểu học & THCS - Vui học, tự tin giao tiếp', NULL, 'Cử nhân Sư phạm Tiếng Anh, Đại học Sài Gòn.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho học sinh cấp 1 và cấp 2. Giúp các em làm quen với bảng chữ cái, từ vựng cơ bản và các mẫu câu giao tiếp đơn giản. Có chứng chỉ TESOL.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 5, 27, 54, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-67', 'Chào các em, anh là Bảo. Anh hiểu rằng giai đoạn THCS là nền tảng quan trọng cho môn Toán. Anh sẽ giúp các em nắm chắc kiến thức từ cơ bản đến nâng cao, rèn luyện kỹ năng giải toán logic và phương pháp trình bày bài khoa học. Anh là người vui tính, dễ gần, luôn tạo không khí thoải mái để các em không ngại đặt câu hỏi và tiến bộ.', 'Toán 6-9 - Xây dựng nền tảng vững chắc, ôn thi vào 10', NULL, 'Sinh viên năm 3, ngành Toán Tin ứng dụng, Trường Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Toán cho học sinh THCS. Giúp nhiều học sinh cải thiện kết quả học tập và tự tin ôn thi vào các trường chuyên, trường THPT chất lượng cao.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 5, 61, 176, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-68', 'Mình là Diệp, một người yêu văn chương tha thiết. Mình muốn giúp các bạn học sinh nhìn thấy vẻ đẹp và sức hấp dẫn của môn Ngữ văn. Mình có phương pháp dạy chi tiết, tập trung vào việc phân tích tác phẩm, rèn luyện kỹ năng viết luận văn thuyết phục và giàu cảm xúc. Mình là người tỉ mỉ, nghiêm túc trong giảng dạy và luôn động viên học trò.', 'Ngữ văn THCS & THPT - Phân tích sâu, văn hay, điểm cao', NULL, 'Tốt nghiệp ngành Sư phạm Ngữ văn, Đại học Sài Gòn.', NULL, NULL, 'Đã có 4 năm kinh nghiệm dạy kèm Ngữ văn cho học sinh THCS và THPT. Giúp các em đạt điểm cao trong các bài kiểm tra, thi học kỳ và thi THPTQG. Có kinh nghiệm bồi dưỡng học sinh giỏi Văn.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.3, 59, 382, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-69', 'Chào các em, anh là Long. Anh có kiến thức chuyên sâu về Vật Lý và kinh nghiệm luyện thi đại học. Anh sẽ giúp các em hệ thống lại kiến thức một cách khoa học, tập trung vào các chuyên đề quan trọng và các dạng bài tập thường gặp trong đề thi. Phương pháp của anh là đi từ bản chất, sau đó mới đến công thức và bài tập. Anh nghiêm khắc nhưng luôn công bằng và quan tâm đến sự tiến bộ của từng em.', 'Vật Lý 11-12 - Luyện thi đại học, giải bài tập khó', NULL, 'Cựu sinh viên ngành Kỹ thuật Y sinh, Đại học Y Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý THPT, chuyên ôn thi đại học. Giúp nhiều học sinh đạt điểm môn Vật Lý trên 8. Có khả năng ra đề kiểm tra sát với cấu trúc thi.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.5, 55, 82, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-70', 'Xin chào, mình là Thanh Mai. Mình có niềm yêu thích đặc biệt với Hóa học và mong muốn chia sẻ kiến thức với các bạn. Mình có phương pháp dạy dễ hiểu, bám sát chương trình, kết hợp lý thuyết và bài tập một cách cân đối. Mình luôn cố gắng tạo ra các bài giảng sinh động, giúp các bạn liên hệ kiến thức với thực tế cuộc sống. Mình là người kiên nhẫn và luôn lắng nghe.', 'Hóa Học 10-12 - Nắm vững lý thuyết, thành thạo bài tập', NULL, 'Tốt nghiệp ngành Hóa phân tích, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Giúp các em nắm vững kiến thức, làm quen với các dạng bài tập từ cơ bản đến nâng cao. Nhiều học viên đạt điểm khá, giỏi.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4, 48, 62, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-71', 'Hey guys, I''m Tuan. If you''re struggling with IELTS Speaking or Writing, I''m here to help! I focus on practical strategies, common mistakes, and how to achieve a higher band score. My teaching style is direct, encouraging, and tailored to your specific needs. Let''s work together to boost your confidence and get the score you deserve!', 'IELTS Speaking & Writing - Luyện thi cấp tốc, điểm cao', NULL, 'IELTS 8.0 (Speaking 8.5, Writing 7.5). Currently pursuing a Master''s degree in International Business.', NULL, NULL, 'Over 3 years of experience coaching IELTS students. Specializes in improving Speaking fluency and Writing coherence for IELTS candidates. Helped numerous students reach their target scores quickly.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.5, 55, 410, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-72', 'Chào các em, mình là Quỳnh Anh. Mình rất thích tìm hiểu về thế giới sống, từ những sinh vật nhỏ bé đến các cơ chế phức tạp trong cơ thể. Mình sẽ cùng các em khám phá những điều thú vị trong môn Sinh học THCS qua các hình ảnh trực quan, thí nghiệm đơn giản và những câu chuyện khoa học hấp dẫn. Mình là người vui vẻ, gần gũi và luôn sẵn sàng giải đáp mọi thắc mắc của các em.', 'Sinh Học THCS - Khám phá thế giới vi sinh vật, tế bào', NULL, 'Sinh viên năm 2, ngành Công nghệ Sinh học, Trường Đại học Công nghệ TP.HCM.', NULL, NULL, 'Có 1 năm kinh nghiệm làm gia sư Sinh học cho học sinh lớp 7, 8. Giúp các em làm quen với các khái niệm cơ bản về tế bào, sinh trưởng, phát triển. Đã hỗ trợ các em cải thiện điểm số.', 'Bình Dương', 'Quận 7', 'active', true, 4.6, 11, 294, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-73', 'Hi mọi người, mình là Nhật. Mình đam mê lập trình và muốn truyền cảm hứng cho các bạn trẻ khám phá thế giới công nghệ. Mình có kinh nghiệm dạy các kiến thức Tin học từ cơ bản cho đến lập trình Scratch, Python cho học sinh THCS. Phương pháp của mình là thực hành nhiều, học đi đôi với hành, giúp các bạn tự tay xây dựng sản phẩm. Mình là người nhiệt tình và luôn kiên nhẫn.', 'Tin Học 6-12 - Nhập môn lập trình, ứng dụng công nghệ', NULL, 'Sinh viên năm 3, ngành Kỹ thuật Phần mềm, Trường Đại học FPT.', NULL, NULL, 'Có kinh nghiệm 2 năm dạy Tin học cho học sinh THCS. Giúp các em làm quen với máy tính, lập trình Scratch và các thuật toán cơ bản. Nhiều em đã tự tin làm các dự án nhỏ.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.5, 60, 180, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-74', 'Xin chào, mình là Thảo Vy. Mình tin rằng học Lịch sử giúp chúng ta hiểu hơn về hiện tại và định hình tương lai. Mình sẽ giúp các bạn tiếp cận Lịch sử một cách mới mẻ, không chỉ học thuộc mà còn biết cách phân tích, đánh giá sự kiện và liên hệ với các vấn đề xã hội đương đại. Mình có giọng văn rõ ràng, dễ hiểu và rất thích thảo luận với học trò.', 'Lịch Sử 10-12 - Tư duy phản biện, liên hệ thực tế', NULL, 'Tốt nghiệp ngành Lịch sử Đảng Cộng sản Việt Nam, Học viện Báo chí và Tuyên truyền.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh có cái nhìn sâu sắc về các giai đoạn lịch sử, đặc biệt là Lịch sử Việt Nam hiện đại. Có kinh nghiệm ôn thi THPTQG.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.5, 64, 58, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-75', 'Chào các bạn, mình là Minh Hiếu. Mình yêu thích khám phá thế giới và Địa lý chính là chìa khóa để mở ra cánh cửa đó. Mình sẽ giúp các bạn hiểu rõ hơn về các yếu tố tự nhiên, dân cư, kinh tế của các khu vực trên thế giới thông qua bản đồ và các số liệu thực tế. Phương pháp của mình là tương tác, đặt câu hỏi để các bạn tự suy luận và ghi nhớ kiến thức lâu hơn. Mình là người vui vẻ, hoạt bát.', 'Địa Lý 6-9 - Bản đồ, thế giới tự nhiên, kinh tế', NULL, 'Sinh viên năm 3, ngành Quản lý Tài nguyên và Môi trường, Trường Đại học Tài nguyên và Môi trường Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý THCS. Giúp các em nắm vững kiến thức sách giáo khoa, hiểu mối liên hệ giữa các yếu tố địa lý. Có kinh nghiệm sử dụng các công cụ trực quan để giảng dạy.', 'Cần Thơ', 'Hải Châu', 'active', true, 4.8, 34, 407, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-76', 'Xin chào các bậc phụ huynh và các em học sinh, mình là Bích Hằng. Mình có kinh nghiệm dạy Toán cho lứa tuổi nhỏ. Mình tin rằng Toán học có thể trở nên thú vị và dễ hiểu nếu có phương pháp phù hợp. Mình tập trung vào việc xây dựng nền tảng vững chắc, phát triển tư duy logic và khả năng giải quyết vấn đề cho các em. Mình là người kiên nhẫn, yêu trẻ và luôn tạo không khí học tập tích cực.', 'Toán Tiểu học & THCS - Phương pháp mới, tư duy logic', NULL, 'Cử nhân Sư phạm Toán học, Đại học Sư phạm TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Toán tiểu học và THCS. Giúp nhiều học sinh cải thiện kết quả học tập, vượt qua nỗi sợ Toán. Có kinh nghiệm dạy các chương trình nâng cao và ôn thi lớp 6.', 'Bình Dương', 'Quận 3', 'active', true, 5, 63, 201, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-77', 'Hello everyone! I''m Duc. I specialize in helping learners improve their English communication skills and prepare for A2 and B1 exams. My approach is practical, focusing on real-life conversations and essential grammar. I''m patient, encouraging, and committed to making learning enjoyable and effective. Let''s start your English journey together!', 'Tiếng Anh giao tiếp & Luyện thi A2, B1', NULL, 'Bachelor of Arts in English Linguistics, University of Foreign Language Studies.', NULL, NULL, '3 years of teaching experience, focusing on beginner and intermediate English learners. Successfully guided students to pass A2 and B1 certification exams. Experienced in online tutoring.', 'Hà Nội', 'Hải Châu', 'active', true, 4.8, 28, 284, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-78', 'Chào các bạn, mình là Thu Hà. Mình yêu văn học và mong muốn chia sẻ niềm đam mê đó. Mình áp dụng phương pháp dạy sáng tạo, giúp các bạn phân tích sâu sắc các tác phẩm văn học, rèn luyện kỹ năng viết văn nghị luận và văn thuyết minh. Mình chú trọng việc khơi gợi sự sáng tạo và tư duy phản biện cho học sinh. Mình là người nghiêm túc, có trách nhiệm và luôn truyền cảm hứng học tập.', 'Ngữ văn THPT - Phân tích tác phẩm, bồi dưỡng năng khiếu', NULL, 'Thạc sĩ Văn học Việt Nam, Trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '5 năm kinh nghiệm giảng dạy và gia sư Ngữ văn THPT. Giúp nhiều học sinh đạt điểm cao trong kỳ thi THPTQG. Có kinh nghiệm bồi dưỡng đội tuyển học sinh giỏi Văn cấp tỉnh.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.7, 38, 169, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-79', 'Chào các em, anh là Minh Quân. Anh có kiến thức vững chắc về Vật Lý và kinh nghiệm truyền đạt lại cho các bạn. Anh sẽ giúp các em hiểu bản chất của các hiện tượng vật lý, nắm vững công thức và giải quyết các dạng bài tập từ cơ bản đến nâng cao. Phương pháp của anh là đi từ ví dụ thực tế, sau đó là lý thuyết và bài tập áp dụng. Anh là người vui tính, dễ gần nhưng cũng rất nghiêm túc trong việc học.', 'Vật Lý THPT - Giải thích rõ ràng, bài tập đa dạng', NULL, 'Cựu sinh viên ngành Kỹ thuật Hàng không, Học viện Kỹ thuật Quân sự.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý THPT. Giúp học sinh cải thiện kết quả học tập và tự tin hơn với môn học. Có kinh nghiệm dạy kèm các bài tập khó và ôn thi học kỳ.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.5, 53, 240, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-80', 'Xin chào, mình là Kim Ngân. Mình có niềm yêu thích Hóa học và mong muốn giúp các bạn chinh phục môn học này. Mình có phương pháp dạy rõ ràng, dễ hiểu, tập trung vào việc hệ thống hóa kiến thức một cách logic và cung cấp các bài tập thực hành đa dạng. Mình tin rằng với sự kiên trì và phương pháp đúng đắn, ai cũng có thể học tốt Hóa học. Mình là người vui vẻ, nhiệt tình.', 'Hóa Học 10-12 - Dễ hiểu, hệ thống kiến thức, ôn thi hiệu quả', NULL, 'Sinh viên năm cuối ngành Hóa Dược, Trường Đại học Dược Hà Nội.', NULL, NULL, '2 năm kinh nghiệm gia sư Hóa học. Giúp học sinh nắm vững kiến thức, làm bài tập hiệu quả và đạt kết quả tốt trong các kỳ thi. Có kinh nghiệm dạy các chương khó như Đại cương và Hữu cơ.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.2, 38, 207, '2026-06-19 02:52:14.769796', '2026-06-19 02:52:14.769796', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-81', 'Chào bạn, mình là Minh Anh. Mình tin rằng học Tiếng Anh là một hành trình thú vị chứ không hề khô khan. Mình thích tạo không khí lớp học vui vẻ, khuyến khích học viên nói nhiều hơn, sửa lỗi sai một cách nhẹ nhàng và hiệu quả. Rất phù hợp với các bạn mất gốc, muốn cải thiện phản xạ giao tiếp.', 'Tiếng Anh giao tiếp tự tin - Cùng bạn chinh phục mọi cuộc trò chuyện!', NULL, 'Tốt nghiệp chuyên ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho người đi làm và sinh viên. Từng giúp nhiều học viên đạt được chứng chỉ A2, B1. Thành thạo nhiều phương pháp dạy tương tác, tạo hứng thú.', 'Hà Nội', 'Bình Thạnh', 'active', true, 4.2, 18, 330, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-82', 'Xin chào, mình là Hùng. Mình không dạy theo kiểu nhồi nhét mà tập trung vào việc giúp học sinh hiểu bản chất vấn đề. Mình thường dùng các ví dụ thực tế, hình ảnh sinh động để bài toán trở nên gần gũi hơn. Mình rất kiên nhẫn, phù hợp với các bạn gặp khó khăn với môn Toán, kể cả các bạn học kém.', 'Toán tư duy - Giúp con bạn yêu thích và học tốt môn Toán!', NULL, 'Thạc sĩ Toán học, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '2 năm làm trợ giảng Toán tại trường, 5 năm kinh nghiệm dạy thêm. Nhiều học sinh của mình đã có sự tiến bộ rõ rệt, từ điểm trung bình lên điểm khá, giỏi.', 'Biên Hòa', 'Bình Thạnh', 'active', true, 4.8, 52, 353, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-83', 'Chào các bạn, mình là Bích Ngọc. Mình yêu văn chương và mong muốn lan tỏa tình yêu ấy đến các bạn học sinh. Mình hướng dẫn cách cảm thụ văn học tinh tế, phương pháp phân tích tác phẩm sâu sắc, viết văn mạch lạc, giàu hình ảnh. Mình hợp với các bạn muốn nâng cao điểm số môn Văn, đặc biệt là phần nghị luận văn học.', 'Ngữ Văn - Khơi nguồn cảm xúc, bay bổng cùng trang viết!', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Giáo viên Ngữ văn THPT 4 năm kinh nghiệm. Đã có nhiều học sinh đạt điểm cao trong các kỳ thi tuyển sinh vào lớp 10, thi tốt nghiệp THPT.', 'Đồng Nai', 'Quận 1', 'active', true, 4.9, 63, 385, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-84', 'Hùng Khang đây! Vật Lý không chỉ có công thức, mà còn là những hiện tượng thú vị xung quanh ta. Mình thích cách tiếp cận vấn đề từ gốc rễ, giải thích bằng ngôn ngữ dễ hiểu, liên hệ với đời sống. Mình sẽ giúp bạn phá tan nỗi sợ Vật Lý, tìm thấy sự hứng thú thực sự.', 'Vật Lý thực tế - Từ công thức khô khan đến ứng dụng cuộc sống!', NULL, 'Sinh viên năm cuối ngành Vật lý Kỹ thuật, Đại học Bách Khoa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Vật Lý cho học sinh THPT. Giúp nhiều bạn cải thiện đáng kể kết quả học tập, đặc biệt là các phần khó như Điện học, Cơ học.', 'Hà Nội', 'Quận 3', 'active', true, 4.8, 44, 201, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-85', 'Hi there, I''m Yến! Mình hiểu rằng mỗi bạn có một điểm mạnh yếu và mục tiêu riêng khi học IELTS. Mình sẽ cùng bạn xây dựng chiến lược ôn luyện hiệu quả, tập trung vào cải thiện kỹ năng Speaking và Writing một cách tự nhiên, logic. Mình rất vui khi thấy học trò của mình tự tin hơn mỗi ngày.', 'IELTS Speaking & Writing - Bứt phá điểm số với lộ trình cá nhân hóa!', NULL, 'Thạc sĩ TESOL, University of Melbourne (Australia).', NULL, NULL, '4 năm kinh nghiệm luyện thi IELTS. Giúp nhiều học viên đạt mục tiêu 6.5 - 7.5+ overall. Chuyên sâu vào các dạng bài Speaking Part 2&3 và Writing Task 1&2.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.1, 6, 313, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-86', 'Chào mọi người, mình là Minh Triết. Mình có niềm đam mê với công nghệ và mong muốn chia sẻ kiến thức đó. Mình dạy Tin học văn phòng, lập trình Python từ cơ bản đến nâng cao theo hướng thực hành, dự án nhỏ. Mình thích cách dạy tương tác, giúp học viên tự tay code và giải quyết vấn đề.', 'Tin Học cơ bản & Lập trình Python - Khám phá thế giới số cùng Triết!', NULL, 'Tốt nghiệp ngành Khoa học Máy tính, Đại học Công nghệ, ĐHQG Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học cho học sinh, sinh viên. Đã hướng dẫn nhiều bạn hoàn thành các dự án lập trình cá nhân đầu tiên.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.1, 45, 56, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-87', 'Mình là Hà Vy, rất vui được đồng hành cùng bạn trên con đường chinh phục Hóa học. Mình luôn cố gắng giải thích các khái niệm hóa học phức tạp một cách đơn giản nhất, dễ hình dung nhất thông qua các ví dụ minh họa. Mình tin rằng ai cũng có thể học tốt Hóa nếu có phương pháp đúng.', 'Hóa Học dễ hiểu - Từ khái niệm đến bài tập vận dụng!', NULL, 'Sinh viên năm 3 ngành Hóa dược, Đại học Dược Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Hóa học cho học sinh THPT. Tập trung vào việc xây dựng nền tảng vững chắc và rèn luyện kỹ năng giải đề thi.', 'Biên Hòa', 'Hải Châu', 'active', true, 4, 19, 266, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-88', 'Hello, tôi là Gia Bảo. Sinh học là môn học về chính sự sống, về thế giới muôn màu xung quanh ta. Tôi thích cách tiếp cận kiến thức một cách trực quan, kết hợp hình ảnh, video và các thí nghiệm đơn giản. Tôi muốn giúp các bạn thấy Sinh học không hề nhàm chán mà vô cùng hấp dẫn.', 'Sinh Học sinh động - Khám phá thế giới sống đầy bất ngờ!', NULL, 'Sinh viên năm cuối ngành Sinh học Phân tử, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '1 năm kinh nghiệm làm gia sư Sinh học. Giúp học sinh nắm vững kiến thức sách giáo khoa và chuẩn bị tốt cho các kỳ kiểm tra.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.8, 6, 103, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-89', 'Mình là Kim Chi. Thay vì học thuộc lòng một cách nhàm chán, mình muốn cùng các bạn khám phá Lịch Sử như một dòng chảy sự kiện hấp dẫn, đầy kịch tính. Mình sẽ giúp bạn liên kết các sự kiện, hiểu rõ nguyên nhân - kết quả và phát triển tư duy phản biện.', 'Lịch Sử không khô khan - Cùng nhau giải mã những câu chuyện quá khứ!', NULL, 'Cử nhân Lịch sử Đảng Cộng sản Việt Nam, Học viện Báo chí và Tuyên truyền.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch Sử cho học sinh THPT. Đã giúp nhiều bạn cải thiện sự yêu thích và kết quả học tập môn Lịch Sử.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.1, 22, 91, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-90', 'Chào bạn, mình là Duy Anh. Mình có kinh nghiệm giảng dạy Toán cho sinh viên các ngành kỹ thuật và ôn thi Đại học. Mình có khả năng phân tích đề thi, đưa ra những phương pháp giải nhanh, hiệu quả. Mình chú trọng vào việc rèn luyện tư duy logic và kỹ năng làm bài, giúp học viên tự tin vượt vũ môn.', 'Toán Cao Cấp & Ôn Thi Đại Học - Chuẩn bị hành trang vững chắc!', NULL, 'Thạc sĩ Toán học Ứng dụng, Đại học Bách Khoa TP.HCM.', NULL, NULL, '5 năm kinh nghiệm dạy Toán Cao cấp và Toán ôn thi Đại học. Tỷ lệ học viên đỗ nguyện vọng 1 cao.', 'Biên Hòa', 'Quận 7', 'active', true, 4.5, 38, 389, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-91', 'Xin chào, mình là Thu Trang! Mình yêu thích sự tự do trong giao tiếp Tiếng Anh và muốn chia sẻ điều đó với các bạn. Mình tập trung vào việc luyện phản xạ, giúp bạn nói trôi chảy và tự nhiên hơn. Mình tạo môi trường học thoải mái, không áp lực, phù hợp với mọi trình độ.', 'Tiếng Anh Giao Tiếp - Tự tin nói chuyện mọi lúc, mọi nơi!', NULL, 'Cử nhân ngành Kinh tế Đối ngoại, Đại học Ngoại Thương.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp và Tiếng Anh thương mại. Đã giúp nhiều học viên tự tin phỏng vấn xin việc và du lịch nước ngoài.', 'Đồng Nai', 'Quận 7', 'active', true, 4.2, 8, 270, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-92', 'Chào bạn, mình là Minh Hoàng. Mình có phương pháp giảng dạy Vật Lý bám sát chương trình THPT, giúp học sinh hiểu sâu bản chất từng phần kiến thức. Mình luôn nhấn mạnh vào việc luyện tập các dạng bài tập từ cơ bản đến nâng cao, đảm bảo nắm chắc kiến thức để đạt điểm cao.', 'Vật Lý THPT - Nắm vững lý thuyết, chinh phục mọi bài tập!', NULL, 'Cựu học sinh chuyên Lý THPT Chuyên Hà Nội - Amsterdam.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Vật Lý cho học sinh cuối cấp. Nhiều học sinh đã đạt điểm 9, 10 môn Lý trong các bài kiểm tra và thi.', 'Hà Nội', 'Quận 7', 'active', true, 4.9, 6, 63, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-93', 'Mình là Mai Phương. Mình tin rằng mỗi tác phẩm văn học đều chứa đựng những tầng ý nghĩa sâu sắc chờ đợi chúng ta khám phá. Mình sẽ hướng dẫn bạn cách đọc hiểu tinh tế, xây dựng dàn ý logic và viết bài văn nghị luận sắc sảo, giàu cảm xúc. Phù hợp với các bạn muốn cải thiện điểm số môn Văn.', 'Văn Học Phân Tích - Làm chủ bài văn nghị luận sâu sắc!', NULL, 'Sinh viên năm cuối ngành Văn học, Đại học Văn hóa Hà Nội.', NULL, NULL, '1.5 năm kinh nghiệm dạy Văn tại trung tâm luyện thi. Giúp học sinh phát triển kỹ năng phân tích đề và viết bài văn theo yêu cầu.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.1, 55, 84, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-94', 'Hello, tôi là Quốc Bảo. Tôi hiểu những khó khăn khi luyện thi IELTS, đặc biệt là kỹ năng Writing và Reading. Tôi sẽ giúp bạn tối ưu hóa thời gian học, cung cấp các chiến lược làm bài hiệu quả, mẹo làm bài và bài tập thực hành phù hợp. Mục tiêu của tôi là giúp bạn đạt điểm số mong muốn một cách bền vững.', 'IELTS Writing & Reading - Lộ trình 6.0+ hiệu quả, bứt phá từng band điểm!', NULL, 'IELTS 8.0 (Listening 9.0, Reading 8.5, Writing 7.0, Speaking 7.0).', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS, tập trung vào Writing và Reading. Đã giúp hàng trăm học viên đạt band điểm mục tiêu.', 'Đồng Nai', 'Quận 1', 'active', true, 4.7, 52, 321, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-95', 'Xin chào, mình là Thanh Huyền. Mình có kinh nghiệm dạy Toán cho các em học sinh cấp 1 và cấp 2. Mình luôn cố gắng làm cho Toán học trở nên gần gũi, dễ hiểu nhất với các em qua các trò chơi, ví dụ thực tế. Mình tin rằng việc tạo sự yêu thích ngay từ đầu sẽ giúp các em học tốt hơn rất nhiều.', 'Toán tiểu học & THCS - Xây nền tảng vững chắc cho tương lai!', NULL, 'Cử nhân Sư phạm Toán học, Đại học Giáo dục, ĐHQG Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Toán cấp 1, cấp 2. Nhiều em học sinh đã tiến bộ vượt bậc, tự tin hơn trong học tập.', 'Biên Hòa', 'Thủ Đức', 'active', true, 4.6, 50, 408, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-96', 'Chào các bạn, mình là Gia Huy. Mình đã từng trải qua giai đoạn ôn thi Đại học môn Tiếng Anh và hiểu rõ những gì các bạn cần. Mình sẽ giúp bạn hệ thống lại kiến thức ngữ pháp, từ vựng theo từng chuyên đề, luyện tập các dạng bài thi một cách hiệu quả. Cùng nhau đặt mục tiêu và đạt được nó nhé!', 'Tiếng Anh THPT & Luyện thi Đại học - Tự tin chinh phục điểm 9+!', NULL, 'Tốt nghiệp ngành Ngôn ngữ Anh, Đại học Sư phạm Ngoại ngữ, ĐHQG Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh ôn thi Đại học. Nhiều học sinh của mình đạt điểm cao trong kỳ thi tốt nghiệp THPT.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.4, 56, 122, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-97', 'Mình là Lan Anh, rất mong được đồng hành cùng các bạn học sinh lớp 10, 11, 12. Mình có phương pháp dạy dễ hiểu, bám sát sách giáo khoa và các dạng bài tập thường gặp trong đề thi. Mình sẽ giúp bạn ôn tập kiến thức một cách hệ thống, hiệu quả, chuẩn bị tốt cho các kỳ thi quan trọng.', 'Sinh Học THPT - Hiểu sâu kiến thức, làm chủ bài tập!', NULL, 'Tốt nghiệp ngành Sư phạm Sinh học, Đại học Sư phạm TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Sinh học THPT. Giúp học sinh cải thiện điểm số và có cái nhìn tổng quan về môn học.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.4, 45, 116, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-98', 'Xin chào, tôi là Quang Huy. Nếu bạn yêu thích và muốn tìm hiểu sâu hơn về Vật Lý, muốn khám phá những kiến thức vượt ra ngoài sách giáo khoa, tôi rất sẵn lòng chia sẻ. Tôi có khả năng giải thích các hiện tượng phức tạp một cách mạch lạc, đưa ra các bài tập thách thức tư duy.', 'Vật Lý chuyên sâu - Khám phá bí ẩn của vũ trụ và thế giới!', NULL, 'Nghiên cứu sinh ngành Vật lý thiên văn, Viện Vật lý, Viện Hàn lâm KH&CN Việt Nam.', NULL, NULL, '4 năm kinh nghiệm hướng dẫn nghiên cứu và giảng dạy các lớp chuyên đề Vật Lý nâng cao.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4, 23, 182, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-99', 'Mình là Thảo My. Mình tin rằng Hóa học không khó nếu chúng ta học đúng cách. Mình sẽ giúp bạn hệ thống lại kiến thức từ cơ bản đến nâng cao, luyện tập giải các dạng bài tập từ dễ đến khó một cách khoa học. Mình sẽ là người bạn đồng hành tin cậy của bạn trên con đường chinh phục môn Hóa.', 'Hóa Học THPT - Giải bài tập dễ dàng, tự tin đạt điểm cao!', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa cho học sinh THPT. Nhiều học sinh đã đạt điểm 8, 9 trong các kỳ thi quan trọng.', 'Bình Dương', 'Hải Châu', 'active', true, 4.9, 28, 207, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-100', 'Chào bạn, mình là Minh Khôi. Mình sẽ giúp bạn sử dụng thành thạo các công cụ Tin học văn phòng (Word, Excel, PowerPoint) và làm quen với lập trình cơ bản bằng Python. Phương pháp của mình là thực hành nhiều, tập trung vào ứng dụng thực tế để bạn có thể áp dụng ngay vào công việc hoặc học tập.', 'Tin Học văn phòng & Lập trình cơ bản - Làm chủ công cụ số!', NULL, 'Tốt nghiệp ngành Kỹ thuật Máy tính, Đại học FPT.', NULL, NULL, '3 năm kinh nghiệm đào tạo Tin học văn phòng cho người đi làm và sinh viên mới ra trường.', 'Bình Dương', 'Hải Châu', 'active', true, 5, 19, 311, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-101', 'Mình là Thu Hà. Mình yêu thích việc kể chuyện và mong muốn chia sẻ những câu chuyện lịch sử một cách sinh động, hấp dẫn nhất. Mình sẽ giúp bạn không chỉ nhớ các mốc thời gian mà còn hiểu được bối cảnh, ý nghĩa của các sự kiện lịch sử. Hãy cùng khám phá Lịch Sử một cách thú vị nhé!', 'Lịch Sử Việt Nam & Thế Giới - Hiểu quá khứ, định hình tương lai!', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội & Nhân văn, ĐHQG TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch Sử cho học sinh THPT. Giúp các bạn có cái nhìn hệ thống và yêu thích môn học hơn.', 'TP.HCM', 'Hải Châu', 'active', true, 4.3, 35, 249, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-102', 'Xin chào, mình là Văn Long. Mình tập trung vào việc củng cố kiến thức Toán lớp 9 và lớp 10, đặc biệt là các dạng toán thi tuyển sinh vào lớp 10. Mình có phương pháp dạy dễ hiểu, giúp học sinh nắm chắc lý thuyết và luyện tập thành thạo các dạng bài tập, đảm bảo kết quả tốt nhất.', 'Toán 9 & 10 - Chuẩn bị vững vàng cho kỳ thi vào lớp 10!', NULL, 'Giáo viên Toán tại trường THCS Nguyễn Du.', NULL, NULL, '6 năm kinh nghiệm giảng dạy và luyện thi Toán lớp 9. Tỷ lệ học sinh đỗ vào các trường chuyên, trường công lập tốt luôn đạt mức cao.', 'Đồng Nai', 'Quận 7', 'active', true, 4.2, 24, 92, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-103', 'Mình là Bích Hảo, rất yêu trẻ con và thích dạy Tiếng Anh cho các bé. Mình sử dụng các bài hát, trò chơi, truyện kể để tạo không khí học tập vui vẻ, giúp các con tiếp thu từ vựng và cấu trúc câu một cách tự nhiên nhất. Mình kiên nhẫn, yêu thương và luôn tạo động lực cho các con.', 'Tiếng Anh Thiếu Nhi - Bé vui học, cha mẹ an tâm!', NULL, 'Cao đẳng Sư phạm Mầm non.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh cho trẻ em từ 5-10 tuổi tại các trung tâm ngoại ngữ.', 'TP.HCM', 'Quận 7', 'active', true, 4.8, 11, 155, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-104', 'Chào bạn, mình là Minh Đạt. Mình tin rằng học Vật Lý qua thực hành và thí nghiệm sẽ giúp các bạn hiểu bài sâu sắc hơn rất nhiều. Mình sẽ cùng bạn thực hiện các thí nghiệm đơn giản tại nhà hoặc mô phỏng các hiện tượng vật lý. Cách học này sẽ mang lại sự hứng thú và kiến thức bền vững.', 'Vật Lý thực hành & thí nghiệm - Trải nghiệm để hiểu sâu!', NULL, 'Kỹ sư Điện – Điện tử, Đại học Bách Khoa TP.HCM.', NULL, NULL, '2 năm kinh nghiệm hướng dẫn các câu lạc bộ Khoa học, dạy kèm Vật Lý cho học sinh THPT.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.8, 62, 233, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-105', 'Hello! Mình là Phương Thảo. Nếu bạn mới bắt đầu học IELTS hoặc muốn củng cố lại kiến thức căn bản, mình rất vui được giúp đỡ. Mình sẽ cùng bạn đi từ những điều cơ bản nhất về ngữ pháp, từ vựng, cấu trúc câu, đến các chiến lược làm bài cho từng kỹ năng. Chúng ta sẽ cùng nhau xây dựng nền tảng thật vững chắc nhé!', 'IELTS Foundation - Xây dựng nền tảng vững chắc cho band điểm mơ ước!', NULL, 'IELTS 7.0 (Listening 8.0, Reading 7.5, Writing 6.5, Speaking 6.5).', NULL, NULL, '2 năm kinh nghiệm dạy IELTS cho người mới bắt đầu và trình độ intermediate.', 'Biên Hòa', 'Quận 7', 'active', true, 4.5, 5, 99, '2026-06-19 02:52:43.171499', '2026-06-19 02:52:43.171499', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-106', 'Chào các em, thầy An đây! Với kinh nghiệm 5 năm dạy Toán, thầy luôn cố gắng tạo ra những giờ học vui vẻ, dễ hiểu nhất. Thầy tin rằng ai cũng có thể giỏi Toán nếu có phương pháp đúng và sự kiên trì. Đặc biệt phù hợp với các bạn mất gốc hoặc muốn bứt phá điểm số.', 'Thầy An - Chinh phục Toán học từ cơ bản đến nâng cao, giúp học sinh tự tin!', NULL, 'Tốt nghiệp Đại học Sư phạm Hà Nội, chuyên ngành Sư phạm Toán học.', NULL, NULL, '5 năm kinh nghiệm giảng dạy Toán phổ thông và luyện thi. Đã giúp nhiều học sinh cải thiện từ 2-3 điểm lên 8-9 điểm. Có kinh nghiệm dạy kèm online và offline cho học sinh THPT.', 'TP.HCM', 'Quận 7', 'active', true, 4.6, 39, 292, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-107', 'Xin chào, mình là Bình. Mình có niềm đam mê lớn với Tiếng Anh và muốn lan tỏa điều đó đến các bạn. Phương pháp của mình tập trung vào thực hành giao tiếp, xây dựng phản xạ tự nhiên và sửa lỗi phát âm chuẩn. Mình rất kiên nhẫn và yêu trẻ con, nên các em nhỏ đừng ngại nhé!', 'Cô Bình - Tiếng Anh giao tiếp tự tin, phát âm chuẩn bản ngữ cho mọi lứa tuổi.', NULL, 'Cử nhân ngành Ngôn ngữ Anh, Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh cho người mất gốc và luyện thi chứng chỉ A2, B1. Từng làm trợ giảng tại một trung tâm Anh ngữ uy tín. Giúp học sinh tự tin hơn khi nói chuyện với người nước ngoài.', 'TP.HCM', 'Quận 1', 'active', true, 5, 13, 352, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-108', 'Chào các bạn, mình là Cường. Mình thích Vật Lý vì nó giải thích thế giới xung quanh ta. Mình sẽ giúp các bạn học Vật Lý không còn khô khan bằng cách liên hệ với các hiện tượng thực tế, sử dụng sơ đồ tư duy và bài tập ứng dụng. Phù hợp với học sinh THPT đang gặp khó khăn với các định luật phức tạp.', 'Thầy Cường - Giải thích Vật Lý bằng tư duy logic, kết nối thực tế sinh động.', NULL, 'Thạc sĩ Vật lý Lý thuyết, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy kèm Vật Lý cho học sinh THPT. Nhiều học sinh đạt điểm cao trong các kỳ thi học kỳ và thi tốt nghiệp. Có khả năng truyền cảm hứng và khơi gợi sự tò mò về môn học.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.7, 65, 220, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-109', 'Mình là Hà, một người yêu Văn chương tha thiết. Mình tin rằng mỗi câu chuyện, mỗi bài thơ đều ẩn chứa những điều thú vị. Với phương pháp giảng dạy gần gũi, mình sẽ giúp các bạn phân tích tác phẩm sâu sắc, rèn luyện khả năng diễn đạt và viết văn theo phong cách riêng. Rất vui được đồng hành cùng các em trên con đường khám phá vẻ đẹp của Ngữ văn.', 'Cô Hà - Khơi dậy niềm yêu Văn học, rèn luyện kỹ năng viết văn sáng tạo, mạch lạc.', NULL, 'Cử nhân Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, '6 năm kinh nghiệm dạy Văn cho học sinh THCS và THPT. Giúp nhiều học sinh đạt giải trong các cuộc thi học sinh giỏi Văn. Chuyên luyện viết văn nghị luận và văn xuôi sáng tạo.', 'Cần Thơ', 'Quận 7', 'active', true, 4.3, 28, 120, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-110', 'Xin chào, mình là Dũng. Mình làm việc trong lĩnh vực Công nghệ thông tin và rất thích chia sẻ kiến thức. Mình sẽ hướng dẫn các bạn sử dụng máy tính hiệu quả, các phần mềm văn phòng và cả lập trình cơ bản bằng Python. Phương pháp của mình là thực hành nhiều, bám sát mục tiêu của người học. Phù hợp với mọi người muốn làm chủ công nghệ.', 'Thầy Dũng - Tin học ứng dụng thực tế, lập trình cơ bản cho mọi lứa tuổi.', NULL, 'Kỹ sư Công nghệ Thông tin, Học viện Công nghệ Bưu chính Viễn thông.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học văn phòng và lập trình Python cho người mới bắt đầu. Hỗ trợ nhiều sinh viên năm nhất làm quen với các môn học chuyên ngành. Đã từng đào tạo cho các khóa học ngắn hạn về lập trình web.', 'Đồng Nai', 'Quận 3', 'active', true, 4.1, 12, 57, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-111', 'Hi mọi người, mình là Giang! Mình có kinh nghiệm 4 năm ôn luyện IELTS và đã giúp hàng trăm bạn đạt band điểm mong muốn. Phương pháp của mình là đi thẳng vào trọng tâm, cung cấp các mẹo làm bài hiệu quả cho từng kỹ năng (Reading, Listening, Writing, Speaking) và luyện tập đều đặn. Mình sẽ là người đồng hành nhiệt huyết, giúp bạn xây dựng sự tự tin cho kỳ thi IELTS.', 'Cô Giang - Luyện IELTS điểm cao, chiến lược thông minh, tự tin chinh phục mục tiêu.', NULL, 'IELTS 8.0, Tốt nghiệp Đại học Kinh tế Quốc dân.', NULL, NULL, '4 năm kinh nghiệm luyện thi IELTS. Tỷ lệ học sinh đạt mục tiêu trên 90%. Có kinh nghiệm dạy kèm cá nhân và nhóm nhỏ, tập trung vào các kỹ năng còn yếu của học viên.', 'Bình Dương', 'Quận 1', 'active', true, 4.2, 51, 187, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-112', 'Xin chào, mình là Ngọc Hà. Mình yêu thích Sinh học vì nó giúp mình hiểu rõ hơn về sự sống. Mình sẽ sử dụng hình ảnh, video minh họa và các thí nghiệm đơn giản để bài học trở nên sinh động. Mình thích phương pháp dạy tương tác, khuyến khích học sinh đặt câu hỏi và tự tìm tòi. Phù hợp với các bạn học sinh THPT muốn nắm vững kiến thức Sinh học.', 'Cô Hà - Sinh học trực quan, dễ hiểu, khám phá thế giới vi sinh và cơ thể người.', NULL, 'Cử nhân Sinh học, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Giúp học sinh hiểu sâu các chuyên đề khó như Di truyền học, Sinh thái học. Có kinh nghiệm ôn thi Đại học khối B.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.9, 41, 183, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-113', 'Chào các con, thầy Huy đây! Thầy muốn mang đến cho các con những giờ học Toán thật vui và bổ ích. Thay vì chỉ học thuộc công thức, chúng ta sẽ cùng nhau khám phá, suy luận để tìm ra lời giải. Thầy tin rằng Toán học không chỉ là những con số mà còn là cách rèn luyện tư duy logic, sự sáng tạo. Rất phù hợp với các bé Tiểu học và THCS muốn xây dựng nền tảng vững chắc.', 'Thầy Huy - Toán tư duy, phát triển kỹ năng giải quyết vấn đề cho trẻ.', NULL, 'Cử nhân Toán học ứng dụng, Đại học Bách Khoa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán cho học sinh Tiểu học và THCS. Tập trung vào phát triển tư duy logic và kỹ năng giải toán có lời văn. Nhiều học sinh tiến bộ vượt bậc về khả năng tư duy.', 'Cần Thơ', 'Quận 1', 'active', true, 4.5, 49, 101, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-114', 'Hello! Mình là Hương. Nếu bạn cảm thấy Tiếng Anh thật khó khăn, đừng lo nhé, mình ở đây để giúp bạn! Mình sẽ bắt đầu từ những kiến thức cơ bản nhất, giúp bạn xây dựng vốn từ vựng, ngữ pháp vững chắc và quan trọng nhất là sự tự tin khi giao tiếp. Mình rất kiên nhẫn và luôn tạo không khí học tập thoải mái, vui vẻ.', 'Cô Hương - Tiếng Anh căn bản, xây dựng sự tự tin, giao tiếp trôi chảy.', NULL, 'Cử nhân ngành Sư phạm Tiếng Anh, Đại học Vinh.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người lớn và thiếu niên. Tập trung vào cải thiện phát âm và phản xạ nghe-nói. Giúp học viên vượt qua rào cản tâm lý khi sử dụng ngoại ngữ.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.7, 22, 435, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-115', 'Chào các bạn, mình là Khôi. Hóa học có thể rất thú vị nếu bạn biết cách tiếp cận! Mình sẽ giúp các bạn hiểu bản chất các phản ứng hóa học, ghi nhớ công thức và phương trình một cách logic, không còn là những con số vô nghĩa. Mình thích sử dụng các ví dụ thực tế và thí nghiệm ảo để minh họa. Phù hợp cho học sinh THPT ôn thi học kỳ và tốt nghiệp.', 'Thầy Khôi - Hóa học thực tế, dễ nhớ, giải mã các phản ứng kỳ diệu.', NULL, 'Cử nhân Hóa học, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Chuyên sâu vào các dạng bài tập định lượng và định tính. Đã giúp nhiều học sinh cải thiện đáng kể điểm số môn Hóa.', 'Đồng Nai', 'Phú Nhuận', 'active', true, 4.7, 27, 179, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-116', 'Xin chào, mình là Lan Anh. Mình tin rằng Văn học là một thế giới đầy cảm xúc và trí tuệ. Mình sẽ cùng các bạn khám phá chiều sâu của từng tác phẩm, rèn luyện kỹ năng phân tích, bình giảng và viết văn giàu cảm xúc. Phương pháp của mình đề cao sự thấu hiểu và cảm thụ cá nhân. Rất vui được chia sẻ niềm đam mê này với các bạn yêu Văn.', 'Cô Lan Anh - Ngữ văn cảm thụ, phân tích văn học sâu sắc, chinh phục điểm cao.', NULL, 'Thạc sĩ Văn học Việt Nam, Đại học Văn hóa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm giảng dạy và luyện thi môn Ngữ văn. Có kinh nghiệm bồi dưỡng học sinh giỏi Văn cấp tỉnh. Giúp học sinh nâng cao điểm số và kỹ năng làm bài thi THPT Quốc gia.', 'Cần Thơ', 'Hải Châu', 'active', true, 4.2, 6, 165, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-117', 'Hello, I''m Minh! Mình chuyên sâu vào IELTS Speaking và Writing, hai kỹ năng thường gây nhiều thử thách nhất. Mình sẽ giúp bạn phát triển ý tưởng, cấu trúc bài nói/viết mạch lạc, sử dụng từ vựng và ngữ pháp học thuật. Quan trọng là, mình sẽ rèn cho bạn phản xạ nhanh và sự tự tin khi đối mặt với giám khảo. Let''s smash your target score!', 'Thầy Minh - IELTS Speaking & Writing chuyên sâu, luyện kỹ năng phản xạ nhanh.', NULL, 'IELTS 8.5 Overall, Cử nhân ngành Kinh tế đối ngoại, Đại học Ngoại Thương.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS, đặc biệt là Speaking và Writing. Tỷ lệ học sinh đạt IELTS 7.0+ rất cao. Có phương pháp luyện tập cá nhân hóa, bám sát điểm yếu của từng học viên.', 'Hà Nội', 'Quận 7', 'active', true, 5, 32, 227, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-118', 'Chào các con, cô Ngọc đây ạ! Cô biết học Toán đôi khi hơi khó với các bạn nhỏ. Nhưng đừng lo, cô sẽ làm cho môn Toán trở nên thật gần gũi và thú vị qua các trò chơi, hình ảnh sinh động. Mục tiêu của cô là giúp các con hiểu bài, yêu thích môn Toán và tự tin hơn. Ba mẹ yên tâm, con sẽ học mà như chơi ạ!', 'Cô Ngọc - Toán lớp 1-5, xây dựng nền tảng vững chắc, bé học vui mỗi ngày.', NULL, 'Cử nhân Sư phạm Toán Tiểu học, Đại học Thủ đô Hà Nội.', NULL, NULL, '7 năm kinh nghiệm dạy Toán Tiểu học. Chuyên bồi dưỡng học sinh năng khiếu và phụ đạo học sinh yếu kém. Có nhiều kinh nghiệm soạn giáo án phù hợp với từng đối tượng học sinh.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.9, 14, 340, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-119', 'Chào các bạn, mình là Nam. Mình muốn giúp các bạn vượt qua nỗi sợ Vật Lý. Mình sẽ tập trung vào việc giúp các bạn nắm vững bản chất lý thuyết, sau đó áp dụng vào giải các dạng bài tập từ cơ bản đến nâng cao. Phương pháp của mình nhấn mạnh vào việc tự học và rèn luyện tư duy phản biện. Cùng nhau chinh phục Vật Lý nhé!', 'Thầy Nam - Vật lý THPT, bứt phá điểm số với phương pháp học thông minh.', NULL, 'Kỹ sư Vật lý Kỹ thuật, Trường Đại học Khoa học và Công nghệ Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Thành tích nổi bật là giúp nhiều học sinh từ điểm trung bình vươn lên điểm giỏi trong các kỳ thi quan trọng. Có kinh nghiệm luyện thi Đại học khối A, A1.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.2, 44, 193, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-120', 'Xin chào, mình là Mai Phương. Mình có niềm yêu thích đặc biệt với Hóa học và đã chinh phục nó bằng phương pháp học tập khoa học. Mình sẽ hướng dẫn các bạn cách hệ thống hóa kiến thức, làm chủ các dạng bài tập từ dễ đến khó và đặc biệt là các mẹo giải nhanh trắc nghiệm. Mình rất nhiệt tình và luôn sẵn sàng giải đáp mọi thắc mắc của các bạn.', 'Cô Phương - Hóa học 10-12, ôn thi hiệu quả, giải bài tập nhanh chóng.', NULL, 'Cử nhân Hóa vô cơ, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Giúp nhiều học sinh cải thiện điểm số môn Hóa trong các kỳ thi học kỳ và thi thử. Có kinh nghiệm dạy online hiệu quả.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.5, 43, 228, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-121', 'Chào các bạn, mình là Quý. Lịch sử không hề nhàm chán như bạn nghĩ! Mình sẽ giúp các bạn hình dung lại các sự kiện lịch sử một cách sinh động, có hệ thống, dễ nhớ. Phương pháp của mình kết hợp kể chuyện, sơ đồ tư duy và liên hệ thực tế. Phù hợp với các bạn học sinh THCS, THPT muốn yêu thích và học tốt môn Lịch sử.', 'Thầy Quý - Lịch sử hấp dẫn, khắc sâu kiến thức, dễ dàng chinh phục mọi bài kiểm tra.', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Lịch sử. Giúp học sinh nắm vững kiến thức cơ bản và mở rộng hiểu biết về các giai đoạn lịch sử. Có kinh nghiệm luyện thi THPT môn Lịch sử theo hình thức tự luận và trắc nghiệm.', 'Đồng Nai', 'Phú Nhuận', 'active', true, 4.2, 18, 71, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-122', 'Xin chào, mình là Thu Trang. Mình yêu thích Địa lý vì nó giúp chúng ta hiểu về Trái Đất, con người và môi trường sống. Mình sẽ sử dụng bản đồ, hình ảnh, video để bài học trở nên thú vị và dễ hình dung. Phương pháp của mình là giúp các bạn kết nối kiến thức, ghi nhớ một cách tự nhiên. Rất phù hợp với các bạn học sinh muốn khám phá thế giới xung quanh.', 'Cô Trang - Địa lý trực quan, dễ nhớ, khám phá thế giới qua bản đồ.', NULL, 'Cử nhân ngành Địa lý học, Đại học Khoa học Tự nhiên, Đại học Quốc gia TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý cho học sinh THCS và THPT. Giúp học sinh nắm vững kiến thức địa lý tự nhiên và kinh tế - xã hội. Có kinh nghiệm bồi dưỡng học sinh giỏi Địa lý.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.9, 62, 296, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-123', 'Hello mọi người, mình là Duy Anh. Mình có kinh nghiệm nhiều năm trong việc luyện thi Tiếng Anh các cấp độ, từ chứng chỉ A2 đến các kỳ thi quan trọng. Mình tập trung vào việc xây dựng nền tảng ngữ pháp vững chắc, cung cấp vốn từ vựng theo chủ đề và rèn luyện kỹ năng làm bài thi. Mình luôn cập nhật các dạng bài mới nhất để giúp học viên đạt kết quả tốt nhất.', 'Thầy Duy Anh - Tiếng Anh luyện thi, ngữ pháp chuẩn, từ vựng phong phú.', NULL, 'Cử nhân ngành Ngôn ngữ Anh, Đại học Sư phạm Ngoại ngữ, Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm luyện thi Tiếng Anh các chứng chỉ. Giúp nhiều học sinh đạt điểm cao trong kỳ thi tốt nghiệp THPT và thi chứng chỉ quốc tế. Có phương pháp giảng dạy khoa học, bám sát đề thi.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.5, 30, 316, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-124', 'Chào các em, cô là Hoàng Yến. Cô biết rằng giai đoạn THCS là bước ngoặt quan trọng để các em làm quen với Toán học ở mức độ mới. Cô sẽ giúp các em làm quen dần với các dạng toán, nắm vững công thức và phương pháp giải. Quan trọng hơn, cô sẽ giúp các em xây dựng sự tự tin và yêu thích môn Toán. Ba mẹ có thể hoàn toàn tin tưởng gửi gắm con em mình ạ.', 'Cô Yến - Toán THCS, phương pháp giảng dạy khoa học, giúp con tự tin vào lớp.', NULL, 'Cử nhân Sư phạm Toán học, Đại học Giáo dục, Đại học Quốc gia Hà Nội.', NULL, NULL, '6 năm kinh nghiệm dạy Toán cho học sinh THCS. Chuyên sâu vào các chuyên đề Đại số và Hình học. Giúp học sinh có nền tảng vững chắc cho chương trình THPT.', 'Biên Hòa', 'Thủ Đức', 'active', true, 4.5, 52, 219, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-125', 'Xin chào, mình là Minh Tuấn. Mình có kinh nghiệm giảng dạy Vật Lý cho học sinh THPT và ôn thi Đại học. Mình tin rằng Vật Lý có thể trở nên dễ hiểu nếu chúng ta tiếp cận nó một cách có hệ thống và logic. Mình sẽ giúp các bạn xây dựng tư duy phân tích vấn đề, kỹ năng giải bài tập và phương pháp làm bài thi hiệu quả. Cùng nhau chinh phục thử thách Vật Lý!', 'Thầy Tuấn - Vật lý cơ bản & nâng cao, rèn luyện tư duy phân tích, giải đề hiệu quả.', NULL, 'Cử nhân Vật lý, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy kèm Vật Lý. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi quan trọng. Có khả năng giải thích các khái niệm Vật Lý phức tạp một cách dễ hiểu.', 'Đồng Nai', 'Quận 3', 'active', true, 4.9, 17, 388, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-126', 'Chào các bạn, mình là Thu Thảo. Mình yêu Văn học và muốn chia sẻ tình yêu đó với các bạn. Mình sẽ giúp các bạn cảm nhận vẻ đẹp của từng bài văn, bài thơ, rèn luyện kỹ năng phân tích và viết văn sáng tạo. Phương pháp của mình là làm cho việc học Văn trở nên thú vị, gần gũi, giúp các bạn tự tin thể hiện suy nghĩ và cảm xúc của mình.', 'Cô Thảo - Văn học THCS, khơi gợi cảm xúc, làm bài văn hay, điểm cao.', NULL, 'Cử nhân Ngữ văn, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Văn cho học sinh THCS. Tập trung vào bồi dưỡng kỹ năng đọc hiểu, cảm thụ văn học và kỹ năng viết văn theo yêu cầu của đề bài.', 'Hà Nội', 'Hải Châu', 'active', true, 4.1, 48, 201, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-127', 'Hello, mình là Anh Khoa. Nếu bạn muốn bước vào thế giới lập trình, mình có thể giúp bạn bắt đầu với Python và các kiến thức cơ bản về web. Mình thích dạy bằng cách thực hành, đưa ra các bài tập ứng dụng thực tế để bạn vừa học vừa làm. Phương pháp của mình là kiên nhẫn, giải thích cặn kẽ và khuyến khích học viên tự tìm tòi. Phù hợp cho mọi lứa tuổi muốn làm quen với lập trình.', 'Thầy Khoa - Lập trình Python, Web cơ bản, tư duy thuật toán cho người mới.', NULL, 'Kỹ sư Phần mềm, Học viện Công nghệ CMC.', NULL, NULL, '2 năm kinh nghiệm dạy lập trình Python và HTML/CSS cho người mới bắt đầu. Hỗ trợ nhiều bạn học sinh, sinh viên xây dựng website đầu tay. Có kinh nghiệm hướng dẫn các dự án nhỏ.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4, 56, 380, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-128', 'Xin chào, mình là Mai. Mình chuyên giúp các bạn mới bắt đầu với IELTS hoặc muốn củng cố lại kiến thức nền tảng. Mình sẽ tập trung vào việc xây dựng vốn từ vựng, ngữ pháp cần thiết và các kỹ năng cơ bản cho từng phần thi. Phương pháp của mình là chậm mà chắc, đảm bảo các bạn hiểu rõ từng bước. Mình sẽ là người bạn đồng hành kiên nhẫn trên hành trình chinh phục IELTS của bạn.', 'Cô Mai - IELTS Foundation, xây dựng nền tảng vững chắc, tự tin giao tiếp.', NULL, 'IELTS 7.0, Cử nhân ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy IELTS cho học viên mất gốc và trình độ sơ cấp. Giúp nhiều học viên vượt qua rào cản ban đầu và tự tin hơn khi sử dụng Tiếng Anh.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.5, 53, 406, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-129', 'Chào các bạn, mình là Văn Thành. Mình có kinh nghiệm dạy Sinh học cho học sinh THCS và THPT. Mình tin rằng Sinh học là môn học khám phá sự kỳ diệu của thế giới tự nhiên và cơ thể con người. Phương pháp của mình là bám sát chương trình sách giáo khoa, giải thích rõ ràng các khái niệm khó, và cung cấp bài tập để củng cố kiến thức. Mục tiêu là giúp các bạn nắm chắc kiến thức và đạt kết quả tốt.', 'Thầy Thành - Sinh học cơ bản, bám sát chương trình, giúp học sinh hiểu sâu bài.', NULL, 'Cử nhân Khoa học Môi trường, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Sinh học. Giúp học sinh hiểu rõ các kiến thức về Tế bào, Di truyền, Sinh thái. Có kinh nghiệm ôn thi học kỳ và thi tốt nghiệp THPT.', 'Hà Nội', 'Quận 7', 'active', true, 4.7, 58, 258, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-130', 'Xin chào, mình là Bích Thủy. Mình đam mê Toán học và luôn tìm tòi những phương pháp giải toán sáng tạo, hiệu quả. Mình sẽ cùng các bạn chinh phục những bài toán khó, rèn luyện tư duy logic và khả năng phân tích vấn đề. Phương pháp của mình là thách thức, nhưng luôn đi kèm với sự hỗ trợ tận tình để các bạn có thể bứt phá giới hạn của bản thân.', 'Cô Thủy - Toán nâng cao, tư duy logic, phát triển kỹ năng giải quyết vấn đề phức tạp.', NULL, 'Thạc sĩ Toán học Lý thuyết, Viện Toán học, Viện Hàn lâm Khoa học Việt Nam.', NULL, NULL, '5 năm kinh nghiệm dạy Toán nâng cao và luyện thi Olympic Toán cho học sinh THPT. Nhiều học sinh đạt giải trong các kỳ thi học sinh giỏi cấp quốc gia. Có kinh nghiệm đào tạo đội tuyển học sinh giỏi.', 'Cần Thơ', 'Quận 7', 'active', true, 4.8, 9, 125, '2026-06-19 02:53:17.374005', '2026-06-19 02:53:17.374005', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-131', 'Chào các em! Cô Thuý đây. Cô có phương pháp dạy rất cuốn hút, luôn tạo không khí học tập vui vẻ, hứng thú. Cô tin rằng mỗi học sinh đều có thể giỏi Tiếng Anh nếu được khơi dậy đúng cách. Phù hợp với các bạn mất gốc hoặc muốn nâng cao trình độ.', 'Giáo viên Tiếng Anh giàu kinh nghiệm, giúp học sinh chinh phục mọi cấp độ.', NULL, 'Tốt nghiệp Đại học Ngoại ngữ - ĐHQGHN, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy tại trung tâm Anh ngữ uy tín. Nhiều học sinh của cô đã đạt điểm cao trong các kỳ thi chứng chỉ quốc tế và thi đại học.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.2, 14, 365, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-132', 'Xin chào phụ huynh và các con! Mình là Quân, mình rất yêu thích Toán học và luôn muốn truyền lửa đam mê đó cho các em nhỏ. Phương pháp của mình là biến những con số khô khan thành những câu chuyện thú vị. Mình kiên nhẫn, vui vẻ và luôn lắng nghe các con.', 'Chuyên gia Toán Tiểu học, giúp con bạn yêu thích và học tốt môn Toán.', NULL, 'Sinh viên năm 3, ngành Sư phạm Toán, trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Đã có 2 năm kinh nghiệm dạy kèm cho học sinh cấp 1. Giúp nhiều em từ chán ghét môn Toán trở nên yêu thích và tiến bộ rõ rệt.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.9, 24, 244, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-133', 'Chào mọi người, mình là Hoàng Anh. Mình có khả năng làm cho những định luật vật lý phức tạp trở nên dễ hiểu bằng các ví dụ thực tế. Mình nghiêm túc, có trách nhiệm và luôn tìm tòi những cách dạy mới hiệu quả nhất. Thích hợp cho các bạn ôn thi THPT Quốc gia.', 'Thầy Anh: Gia sư Vật Lý THPT, giải thích cặn kẽ, bám sát đề thi.', NULL, 'Cựu sinh viên ngành Kỹ thuật Y sinh, trường Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Từng là gia sư Vật Lý cho nhiều học sinh khối 12, giúp các em đạt điểm thi đại học cao. Có kinh nghiệm luyện đề thi thử các trường chuyên.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.1, 9, 245, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-134', 'Ngữ văn không chỉ là học chữ mà còn là học làm người. Mình muốn mang đến cho các em những giờ học văn đầy cảm hứng, khơi gợi sự đồng cảm và tư duy phản biện. Mình nhẹ nhàng, tinh tế và có khả năng phân tích văn học sâu sắc.', 'Cô Lan - Ngữ văn sâu sắc, bồi đắp tâm hồn và kỹ năng làm bài.', NULL, 'Thạc sĩ Ngữ văn Việt Nam, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Giảng dạy Ngữ văn tại trường THPT công lập được 7 năm. Kinh nghiệm bồi dưỡng học sinh giỏi Văn và luyện thi vào lớp 10 chuyên Văn.', 'Bình Dương', 'Quận 3', 'active', true, 4.8, 31, 58, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-135', 'Xin chào các bạn! Mình là Duy Khang, mình hiểu rõ những khó khăn khi chinh phục IELTS. Mình sẽ xây dựng cho bạn một lộ trình học tập khoa học, tập trung vào điểm yếu và tối ưu hóa chiến thuật làm bài. Mình nhiệt huyết, kỷ luật và luôn đồng hành cùng bạn.', 'Chuyên gia IELTS 8.0, lộ trình cá nhân hóa, cam kết điểm số.', NULL, 'Điểm IELTS 8.0, tốt nghiệp ngành Kinh tế Quốc tế, trường Đại học Kinh tế Quốc dân.', NULL, NULL, 'Có hơn 3 năm kinh nghiệm luyện thi IELTS cho người đi làm và sinh viên. Nhiều học viên đã đạt mục tiêu 6.5, 7.0 và cao hơn.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.8, 6, 150, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-136', 'Hóa học có thể rất thú vị nếu chúng ta nhìn thấy nó trong cuộc sống! Cô Hà sẽ giúp các em nắm vững kiến thức từ cơ bản đến nâng cao, rèn luyện kỹ năng giải bài tập nhanh và chính xác. Cô tỉ mỉ, kiên nhẫn và luôn động viên học trò.', 'Cô Hà: Hóa học dễ hiểu, lý thuyết vững, bài tập bám sát.', NULL, 'Sinh viên năm cuối, ngành Hóa học, trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Gia sư Hóa học cho học sinh THPT được 3 năm. Giúp nhiều em cải thiện điểm số và tự tin hơn với môn học.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4, 36, 81, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-137', 'Chào mọi người, mình là Hùng. Mình có thể giúp bạn thành thạo Tin học văn phòng (Word, Excel, PowerPoint) hoặc làm quen với những kiến thức lập trình đầu tiên. Mình dạy dễ hiểu, thực hành nhiều và luôn kiên nhẫn với người mới bắt đầu.', 'Tin học văn phòng & Lập trình cơ bản cho mọi lứa tuổi.', NULL, 'Tốt nghiệp ngành Công nghệ Thông tin, trường Đại học FPT.', NULL, NULL, 'Có kinh nghiệm 4 năm làm IT và 2 năm dạy Tin học cho các trung tâm đào tạo ngắn hạn.', 'TP.HCM', 'Hoàng Mai', 'active', true, 5, 58, 118, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-138', 'Chào các em, cô Mai đây! Sinh học là môn học về chính sự sống, thật tuyệt vời phải không? Cô sẽ giúp các em khám phá thế giới sinh vật kỳ diệu qua những bài giảng dễ nhớ, hình ảnh trực quan và các câu hỏi ôn tập bổ ích. Cô nhiệt tình, gần gũi và luôn tạo cảm hứng học tập.', 'Cô Mai: Sinh học từ cơ bản đến chuyên sâu, ôn thi hiệu quả.', NULL, 'Sinh viên năm 3, ngành Công nghệ Sinh học, trường Đại học Nông Lâm TP.HCM.', NULL, NULL, 'Đã dạy kèm Sinh học cho học sinh cấp 2 và cấp 3 trong 3 năm. Giúp các em nắm chắc kiến thức và đạt kết quả tốt trong các kỳ kiểm tra.', 'TP.HCM', 'Quận 1', 'active', true, 4.1, 21, 176, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-139', 'Bạn thấy Lịch sử khô khan và khó nhớ? Hãy để mình giúp bạn thay đổi suy nghĩ đó! Mình có cách kể chuyện lịch sử sống động, gắn kết các sự kiện và nhân vật với nhau. Mình năng động, ham học hỏi và muốn chia sẻ niềm yêu thích sử học với mọi người.', 'Lịch sử không còn nhàm chán với thầy Tuấn, phương pháp mới lạ.', NULL, 'Cựu sinh viên ngành Lịch sử, trường Đại học Khoa học Xã hội và Nhân văn TP.HCM.', NULL, NULL, 'Đã hỗ trợ ôn tập Lịch sử cho nhiều học sinh THPT, giúp các em có cái nhìn mới mẻ và hứng thú hơn với môn học.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.1, 35, 117, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-140', 'Địa lý là thế giới xung quanh ta! Cô Bích sẽ cùng các em khám phá các châu lục, quốc gia, các hiện tượng tự nhiên và xã hội một cách trực quan, sinh động. Cô sử dụng sơ đồ tư duy và các hoạt động tương tác để bài học thêm phần hấp dẫn.', 'Địa lý thú vị, bản đồ tư duy, kiến thức thực tế.', NULL, 'Tốt nghiệp ngành Địa lý học, trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Địa lý tại trung tâm luyện thi, giúp học sinh hiểu bài nhanh và nhớ lâu hơn.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.9, 6, 347, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-141', 'Xin chào! Mình là Kim Chi. Mình giúp các bạn xây dựng nền tảng Tiếng Anh vững chắc, từ ngữ pháp đến từ vựng, và đặc biệt là sự tự tin khi giao tiếp. Mình có phương pháp học linh hoạt, nhiều hoạt động tương tác và luôn tạo môi trường thoải mái để học viên thực hành.', 'Tiếng Anh giao tiếp & Ngữ pháp vững chắc, tự tin nói chuyện.', NULL, 'Du học sinh ngành Marketing tại Úc, điểm IELTS 7.5.', NULL, NULL, 'Đã dạy Tiếng Anh giao tiếp cho nhiều học viên từ 16-30 tuổi, giúp họ cải thiện kỹ năng nghe nói đáng kể.', 'Đồng Nai', 'Quận 1', 'active', true, 4.3, 54, 223, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-142', 'Chào các bạn, mình là Đức Thắng. Mình chuyên dạy Toán cao cấp và các chuyên đề ôn thi Đại học. Mình có khả năng phân tích đề thi, hệ thống kiến thức một cách logic và đưa ra các phương pháp giải nhanh. Mình nghiêm túc, có kỷ luật và luôn thúc đẩy học sinh đạt mục tiêu.', 'Thầy Thắng: Toán Cao cấp & Lượng giác, ôn thi Đại học.', NULL, 'Thạc sĩ Toán học ứng dụng, trường Đại học Bách Khoa TP.HCM.', NULL, NULL, 'Đã có 6 năm kinh nghiệm dạy Toán cho sinh viên và học sinh lớp 11, 12. Tỷ lệ học sinh đỗ nguyện vọng mong muốn rất cao.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.2, 60, 275, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-143', 'Văn học là cánh cửa tâm hồn. Mình mong muốn cùng các em khám phá vẻ đẹp của ngôn từ, cảm nhận sâu sắc các tác phẩm văn chương và rèn luyện kỹ năng viết bài văn hay, có chiều sâu. Mình có sự nhạy cảm với ngôn ngữ và cách diễn đạt tinh tế.', 'Ngữ văn cô đọng, phân tích sâu, bài văn giàu cảm xúc.', NULL, 'Sinh viên năm 3, ngành Sư phạm Ngữ văn, trường Đại học Sư phạm TP.HCM.', NULL, NULL, 'Gia sư Ngữ văn cho học sinh THCS và THPT, đặc biệt là luyện viết cho các kỳ thi tuyển sinh.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.2, 61, 97, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-144', 'Mình là Minh Khang. Mình tin rằng Vật Lý sẽ trở nên hấp dẫn khi ta hiểu bản chất và thấy nó ứng dụng trong đời sống. Mình sử dụng nhiều ví dụ minh họa, thí nghiệm ảo và cách tiếp cận vấn đề sáng tạo để các bạn học một cách tự nhiên nhất.', 'Vật Lý thực tế, thí nghiệm vui, giải thích tường tận.', NULL, 'Sinh viên năm 4, ngành Vật lý Kỹ thuật, trường Đại học Công nghệ - ĐHQGHN.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy kèm Vật Lý THPT, giúp học sinh hiểu sâu và có hứng thú với môn học.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.2, 35, 177, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-145', 'Hello! Mình là Thanh. Nếu bạn đang tìm kiếm một lộ trình học IELTS hiệu quả, bám sát mục tiêu 7.0, mình tin rằng mình có thể giúp bạn. Mình tập trung vào chiến lược làm bài, luyện tập cường độ cao và sửa lỗi chi tiết. Mình rất nhiệt tình và có khả năng truyền động lực.', 'Tiếng Anh luyện thi Target Band 7.0+ IELTS.', NULL, 'Cựu sinh viên ngành Kinh tế, điểm IELTS 8.0, từng sống và học tập tại Canada.', NULL, NULL, 'Có 4 năm kinh nghiệm luyện thi IELTS, giúp hàng trăm học viên đạt được band điểm mong muốn cho mục đích du học và công việc.', 'Hà Nội', 'Quận 1', 'active', true, 4.5, 26, 164, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-146', 'Chào các bạn, mình là Anh Tuấn. Nếu bạn muốn học lập trình một cách bài bản, từ những khái niệm cơ bản đến việc tự tay tạo ra một website đơn giản hay một ứng dụng nhỏ bằng Python, hãy tìm đến mình. Mình dạy theo dự án, thực hành nhiều và kiên nhẫn giải đáp mọi thắc mắc.', 'Lập trình Python & Web cơ bản, tạo ra sản phẩm đầu tay.', NULL, 'Tốt nghiệp ngành Khoa học Máy tính, trường Đại học Công nghệ FPT.', NULL, NULL, 'Đã làm việc trong ngành phát triển phần mềm 5 năm và có kinh nghiệm giảng dạy lập trình cho sinh viên.', 'Hà Nội', 'Hải Châu', 'active', true, 4.2, 16, 182, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-147', 'Hóa học không chỉ có công thức. Cô Ánh sẽ cùng các em khám phá những phản ứng hóa học kỳ diệu qua các ví dụ thực tế, thí nghiệm đơn giản và các bài tập vận dụng. Cô luôn tạo không khí lớp học sôi nổi, khích lệ sự tò mò và sáng tạo của học sinh.', 'Cô Ánh: Hóa học vui nhộn, dễ nhớ, tăng cường thực hành.', NULL, 'Sinh viên năm 3, ngành Hóa dược, trường Đại học Dược Hà Nội.', NULL, NULL, 'Gia sư Hóa học THPT trong 3 năm, giúp các em có phương pháp học tập hiệu quả và cải thiện điểm số rõ rệt.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.4, 23, 190, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-148', 'Chào các em, mình là Minh Hoàng. Mình có niềm đam mê với việc khám phá những bài toán hay và thách thức. Mình sẽ giúp các em phát triển tư duy logic, khả năng sáng tạo và kỹ năng giải quyết vấn đề phức tạp. Phù hợp với các bạn học sinh khá, giỏi muốn bứt phá.', 'Toán Tư duy & Khai thác chuyên sâu cho học sinh giỏi.', NULL, 'Thủ khoa ngành Toán Tin, trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Có kinh nghiệm 5 năm luyện thi học sinh giỏi Toán các cấp và ôn luyện cho các kỳ thi vào trường chuyên.', 'Hà Nội', 'Hải Châu', 'active', true, 4.3, 25, 228, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-149', 'Hello các con và bố mẹ! Cô Trang có kinh nghiệm dạy Tiếng Anh cho các bạn nhỏ từ 6-15 tuổi. Cô sử dụng phương pháp học qua trò chơi, bài hát và hoạt động tương tác để các con tiếp thu từ vựng và ngữ pháp một cách tự nhiên, vui vẻ. Cô yêu trẻ và kiên nhẫn.', 'Tiếng Anh tiểu học & THCS, xây dựng nền tảng vững chắc.', NULL, 'Cử nhân Sư phạm Tiếng Anh, trường Đại học Sài Gòn.', NULL, NULL, 'Đã dạy Tiếng Anh tại trường tiểu học 3 năm và có 4 năm kinh nghiệm dạy thêm cho học sinh các cấp.', 'Hà Nội', 'Quận 1', 'active', true, 4.9, 57, 105, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-150', 'Mình là Bảo, mình sẽ giúp các bạn chinh phục môn Sinh học một cách nhẹ nhàng. Mình có khả năng hệ thống hóa kiến thức, đưa ra những ví dụ thực tế giúp dễ hình dung và ghi nhớ. Mình tập trung vào việc giúp các bạn nắm vững kiến thức để đạt điểm cao trong các bài kiểm tra và thi cử.', 'Sinh học THPT: Dễ hiểu, bám sát chương trình, ôn thi hiệu quả.', NULL, 'Sinh viên năm cuối, ngành Sinh học Phân tử, trường Đại học Khoa học Tự nhiên - ĐHQGHN.', NULL, NULL, 'Đã dạy kèm Sinh học cho học sinh khối 10, 11, 12 trong 3 năm, giúp nhiều em tiến bộ.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.1, 56, 51, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-151', 'Lịch sử không chỉ là học thuộc lòng. Mình sẽ cùng các bạn tìm hiểu các sự kiện lịch sử một cách logic, phân tích nguyên nhân - kết quả và mối liên hệ giữa các giai đoạn. Phương pháp của mình giúp các bạn hiểu sâu, nhớ lâu và làm bài thi hiệu quả.', 'Thầy Đức: Lịch sử thi THPT Quốc gia, phân tích sự kiện và nhân vật.', NULL, 'Cựu sinh viên ngành Lịch sử Đảng Cộng sản Việt Nam, trường Học viện Báo chí và Tuyên truyền.', NULL, NULL, 'Có kinh nghiệm 4 năm luyện thi Lịch sử THPT, giúp học sinh nắm vững các dạng câu hỏi và đạt điểm cao.', 'Biên Hòa', 'Thủ Đức', 'active', true, 4.5, 55, 344, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-152', 'Địa lý là môn học kết nối ta với thế giới. Cô Sương sẽ mang đến cho các em những bài học sống động về địa lý Việt Nam và thế giới, không chỉ trong sách vở mà còn qua những câu chuyện thực tế. Cô giúp các em có cái nhìn tổng quan và kỹ năng phân tích bản đồ, số liệu.', 'Địa lý thực tế, kiến thức mở rộng, ôn thi hiệu quả.', NULL, 'Cử nhân Địa lý, trường Đại học Sài Gòn.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy Địa lý cho học sinh THCS, THPT, giúp các em tự tin hơn với môn học.', 'Hà Nội', 'Bình Thạnh', 'active', true, 4.4, 12, 239, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-153', 'Chào mọi người, mình là Gia Bảo. Mình có kinh nghiệm giúp học sinh nắm vững kiến thức Vật Lý từ cơ bản đến nâng cao, đặc biệt là các dạng bài tập thường gặp trong đề thi đại học. Mình có phương pháp giảng dạy rõ ràng, logic và luôn sẵn sàng giải đáp mọi thắc mắc của học trò.', 'Vật Lý nền tảng & nâng cao, luyện thi đại học điểm cao.', NULL, 'Sinh viên năm 4, ngành Vật lý, trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Đã dạy kèm Vật Lý cho học sinh THPT được 4 năm, giúp nhiều em đạt điểm 8+ trong các kỳ thi quan trọng.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4, 46, 250, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-154', 'Chào bố mẹ và các con! Con là Hà My, con rất yêu quý trẻ nhỏ và muốn giúp các bé có những trải nghiệm học Toán thật vui vẻ. Con sử dụng nhiều hình ảnh, trò chơi và hoạt động thực tế để bé vừa chơi vừa học. Con kiên nhẫn, ân cần và luôn động viên các bé.', 'Toán Tiểu học vui nhộn, khơi dậy hứng thú học tập cho bé.', NULL, 'Sinh viên năm 2, ngành Giáo dục Tiểu học, trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Tình nguyện viên dạy Toán tại trung tâm hỗ trợ trẻ em khó khăn trong 1 năm, có kinh nghiệm làm quen và giảng dạy cho học sinh tiểu học.', 'Bình Dương', 'Hoàng Mai', 'active', true, 5, 25, 250, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-155', 'Xin chào! Mình là Trung Kiên. Mình tập trung vào hai kỹ năng quan trọng nhất là Writing và Speaking để giúp bạn đạt điểm cao trong IELTS. Mình có những mẹo nhỏ, cấu trúc bài viết hiệu quả và phương pháp luyện nói tự nhiên, mạch lạc. Mình nghiêm túc, có phản hồi chi tiết và luôn tạo điều kiện để bạn thực hành.', 'Luyện thi IELTS Writing & Speaking - Tự tin giao tiếp, bài viết mạch lạc.', NULL, 'Thạc sĩ Ngôn ngữ Anh, Đại học City, London (UK), điểm IELTS 8.0.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy IELTS, chuyên sâu về kỹ năng Viết và Nói, giúp nhiều học viên đạt mục tiêu 7.0 trở lên.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.7, 55, 200, '2026-06-19 02:53:47.62878', '2026-06-19 02:53:47.62878', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-156', 'Chào bạn, mình là Minh Anh, một người yêu Toán và thích chia sẻ kiến thức. Mình tin rằng Toán học không hề khô khan nếu có phương pháp học đúng đắn. Mình thường sử dụng các ví dụ thực tế và bài tập ứng dụng để các bạn dễ hình dung. Nếu bạn đang vật lộn với Toán hoặc muốn đạt điểm cao hơn, mình rất sẵn lòng đồng hành.', 'Gia sư Toán - Giúp bạn chinh phục mọi dạng bài từ cơ bản đến nâng cao!', NULL, 'Sinh viên năm 3, Khoa Toán - Tin, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Toán cho học sinh cấp 2 và cấp 3. Từng giúp nhiều bạn cải thiện điểm số đáng kể, có bạn từ 4 lên 8 chỉ sau 1 học kỳ. Phù hợp với các bạn cần ôn thi học kỳ và thi tốt nghiệp.', 'Cần Thơ', 'Quận 3', 'active', true, 4.2, 13, 251, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-157', 'Xin chào! Mình là Thu Hà, mình yêu thích việc giúp mọi người giao tiếp Tiếng Anh một cách tự nhiên và tự tin nhất. Phương pháp của mình là kết hợp học qua các hoạt động thú vị, trò chuyện và sửa lỗi trực tiếp. Mình đặc biệt kiên nhẫn và luôn tạo không khí học thoải mái, phù hợp với những bạn ngại nói hoặc mới bắt đầu.', 'Tiếng Anh giao tiếp tự tin - Luyện thi chứng chỉ uy tín.', NULL, 'Cử nhân chuyên ngành Ngôn ngữ Anh, Trường Đại học Hà Nội.', NULL, NULL, 'Đã có 5 năm kinh nghiệm dạy Tiếng Anh cho mọi lứa tuổi, từ mất gốc đến luyện thi IELTS. Giúp nhiều học viên đạt điểm cao trong các kỳ thi chứng chỉ A2, B1, B2. Kinh nghiệm dạy online và offline.', 'Biên Hòa', 'Quận 7', 'active', true, 4.8, 7, 206, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-158', 'Mình là Quang Dũng, một người đam mê Vật Lý và luôn tìm cách giải thích mọi thứ thật logic, dễ hiểu. Mình thích đi sâu vào bản chất vấn đề thay vì học thuộc lòng công thức. Mình sẽ giúp bạn xây dựng nền tảng vững chắc, làm bài tập từ cơ bản đến nâng cao, và quan trọng là hiểu vì sao lại có những định luật đó.', 'Giải thích Vật Lý từ gốc rễ - Làm chủ các định luật cơ bản.', NULL, 'Thạc sĩ Vật lý Kỹ thuật, Trường Đại học Bách khoa Hà Nội.', NULL, NULL, '6 năm kinh nghiệm dạy Vật Lý THPT. Thành tích nổi bật là giúp học sinh đạt điểm thi Đại học cao, đặc biệt là khối A. Kinh nghiệm dạy ôn thi Tốt nghiệp và các lớp chuyên Vật Lý.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4.2, 49, 144, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-159', 'Chào các bạn, mình là Bích Ngọc. Mình tin rằng Hóa Học không chỉ là những phương trình khô khan mà còn là những phản ứng thú vị diễn ra xung quanh ta. Mình sẽ giúp bạn nắm vững kiến thức, luyện tập các dạng bài tập từ nhận biết đến tính toán phức tạp, và kết nối kiến thức với đời sống thực tế. Mình rất vui khi được đồng hành cùng bạn khám phá thế giới Hóa học.', 'Hóa Học - Từ lý thuyết đến thực hành, dễ hiểu và sinh động.', NULL, 'Cử nhân Hóa học, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa cho học sinh THPT. Nhiều học sinh của mình đã đạt điểm giỏi môn Hóa trong các kỳ thi quan trọng. Phương pháp giảng dạy linh hoạt, bám sát chương trình.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.1, 5, 85, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-160', 'Xin chào! Mình là Minh Đức. Mình yêu Văn học và tin rằng mỗi tác phẩm đều ẩn chứa những câu chuyện, bài học sâu sắc. Mình sẽ cùng bạn phân tích tác phẩm, rèn luyện kỹ năng viết văn sáng tạo và mạch lạc, đặc biệt là cách xây dựng bài nghị luận chặt chẽ. Mình thích sự tương tác, trao đổi, phù hợp với những bạn muốn nâng cao cảm thụ văn học và kỹ năng làm bài thi.', 'Ngữ Văn - Khơi nguồn cảm hứng, chinh phục điểm cao.', NULL, 'Sinh viên năm 4, Khoa Ngữ văn, Trường Đại học Văn hóa Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Văn cho học sinh THPT. Giúp các bạn đạt điểm cao trong các kỳ thi học sinh giỏi và thi Tốt nghiệp. Có kinh nghiệm soạn giáo án, bài tập bám sát yêu cầu của Bộ Giáo dục.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.2, 18, 231, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-161', 'Chào bạn, mình là Mai Phương! Mình yêu thích Sinh học và luôn muốn chia sẻ sự kỳ diệu của thế giới tự nhiên. Mình sẽ giúp bạn hiểu rõ các khái niệm phức tạp, làm quen với các dạng bài tập từ cơ bản đến nâng cao, và đặc biệt là cách liên hệ kiến thức Sinh học với cuộc sống. Mình luôn cố gắng tạo không khí học tập vui vẻ, khuyến khích sự tò mò của học viên.', 'Sinh Học - Khám phá thế giới sống muôn màu.', NULL, 'Sinh viên năm 3, Khoa Sinh học, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Sinh học THCS và THPT. Giúp học sinh nắm vững kiến thức, cải thiện kết quả học tập và chuẩn bị tốt cho các kỳ thi. Phù hợp với các bạn cần ôn tập kiến thức nền tảng.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4.9, 51, 387, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-162', 'Chào mọi người, mình là Văn Hùng. Mình tin rằng Lịch sử không phải là những con số và sự kiện khô khan, mà là những câu chuyện đầy hấp dẫn về con người và thời đại. Mình sẽ giúp bạn tìm hiểu các giai đoạn lịch sử một cách logic, dễ nhớ, và đặc biệt là rút ra những bài học ý nghĩa. Mình là người kiên nhẫn, thích thảo luận, phù hợp với những bạn muốn hiểu sâu hơn về cội nguồn dân tộc.', 'Lịch Sử - Từ những câu chuyện quá khứ đến bài học cho hiện tại.', NULL, 'Cử nhân Lịch sử, Trường Đại học Sư phạm TP.HCM.', NULL, NULL, '5 năm kinh nghiệm dạy Lịch sử THPT. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi, hiểu và yêu thích môn Lịch sử hơn. Có kinh nghiệm dạy ôn thi Tốt nghiệp và các lớp chuyên Sử.', 'Hà Nội', 'Hải Châu', 'active', true, 4.1, 60, 225, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-163', 'Xin chào! Mình là Lan Anh, một cô gái yêu thích Địa lý và luôn muốn chia sẻ những điều thú vị về thế giới xung quanh chúng ta. Mình sẽ giúp bạn hình dung rõ hơn về các hiện tượng địa lý, các quốc gia, vùng lãnh thổ thông qua bản đồ, hình ảnh và các ví dụ thực tế. Mình mong muốn khơi dậy sự tò mò và niềm yêu thích môn Địa lý ở các bạn.', 'Địa Lý - Hành trình khám phá thế giới.', NULL, 'Sinh viên năm 4, Khoa Địa lý, Trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý THCS và THPT. Giúp học sinh cải thiện điểm số, hiểu bản chất các hiện tượng địa lý và chuẩn bị tốt cho kỳ thi. Phương pháp giảng dạy trực quan, sinh động.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.9, 41, 255, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-164', 'Chào bạn, mình là Tuấn Khải. Mình yêu thích công nghệ và lập trình. Mình sẽ giúp bạn làm quen với các kiến thức cơ bản về Tin học, từ tin học văn phòng đến các khái niệm về lập trình. Mình có kinh nghiệm hướng dẫn các bạn làm quen với các ngôn ngữ lập trình phổ biến như Python, C++. Phương pháp của mình là thực hành nhiều, làm quen với các dự án nhỏ để tăng tính ứng dụng.', 'Tin Học - Nền tảng vững chắc, sẵn sàng cho kỷ nguyên số.', NULL, 'Kỹ sư Công nghệ Thông tin, Trường Đại học Công nghệ, Đại học Quốc gia Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Tin học cho học sinh THCS và THPT. Hỗ trợ các bạn làm quen với lập trình, các cuộc thi Tin học trẻ. Giúp học sinh làm quen với các phần mềm chuyên dụng.', 'Bình Dương', 'Quận 7', 'active', true, 4.1, 18, 181, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-165', 'Hello! Mình là Mỹ Linh, một người có kinh nghiệm dày dặn trong việc ôn luyện IELTS. Mình hiểu rõ những khó khăn và áp lực khi chuẩn bị cho kỳ thi này. Phương pháp của mình là tập trung vào từng kỹ năng, cung cấp chiến lược làm bài hiệu quả và luyện tập đều đặn. Mình rất vui khi được chia sẻ kinh nghiệm và giúp bạn đạt được mục tiêu điểm số của mình.', 'IELTS - Chinh phục band điểm mơ ước.', NULL, 'IELTS 8.0, Cử nhân Kinh tế Đối ngoại, Học viện Ngoại giao.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS cho sinh viên và người đi làm. Tỷ lệ học viên đạt mục tiêu trên 90%. Kinh nghiệm dạy các khóa cấp tốc và lộ trình dài hạn.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.3, 28, 79, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-166', 'Chào bạn, mình là Minh Quân. Mình có niềm đam mê với Toán học và mong muốn truyền lửa cho các bạn học sinh. Mình tập trung vào việc xây dựng tư duy logic, phương pháp giải toán hiệu quả và luyện tập đa dạng các dạng đề. Mình là người kiên nhẫn, lắng nghe và luôn sẵn sàng giải đáp mọi thắc mắc của học viên.', 'Toán THPT - Nắm chắc kiến thức, tự tin vượt vũ môn.', NULL, 'Sinh viên năm 3, Khoa Sư phạm Toán, Trường Đại học Sư phạm Hà Nội 2.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Toán THPT. Giúp học sinh nắm vững kiến thức sách giáo khoa, luyện thi Tốt nghiệp và Đại học. Nhiều học trò đạt điểm 8+.', 'Bình Dương', 'Quận 3', 'active', true, 4, 52, 52, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-167', 'Xin chào! Mình là Phương Thảo. Mình hiểu rằng bắt đầu học Tiếng Anh có thể rất khó khăn. Mình có kinh nghiệm dạy cho những bạn hoàn toàn mất gốc, giúp các bạn xây dựng lại từ vựng, ngữ pháp một cách bài bản. Phương pháp của mình là tạo môi trường học tập thoải mái, sử dụng nhiều hình ảnh, bài hát và các hoạt động tương tác để việc học trở nên thú vị hơn.', 'Tiếng Anh cho người mất gốc - Tự tin giao tiếp từ con số 0.', NULL, 'Cử nhân Ngôn ngữ Anh, Trường Đại học Ngoại ngữ - Tin học TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người mới bắt đầu. Giúp hàng trăm học viên vượt qua rào cản ngôn ngữ. Phương pháp cực kỳ kiên nhẫn và chi tiết.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.3, 45, 180, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-168', 'Chào các bạn, mình là Mạnh Cường. Mình muốn cho các bạn thấy Vật Lý không chỉ có trong sách vở mà còn hiện diện khắp nơi. Mình sẽ dùng các thí nghiệm đơn giản, các ví dụ thực tế để minh họa các định luật, giúp các bạn hiểu sâu sắc hơn và không còn sợ môn học này nữa. Mình thích cách học chủ động, khuyến khích học viên đặt câu hỏi.', 'Vật Lý thực tế - Kết nối kiến thức với cuộc sống quanh ta.', NULL, 'Kỹ sư Cơ khí, Trường Đại học Công nghiệp TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý cho học sinh THCS. Giúp các em có cái nhìn mới mẻ về môn học và cải thiện kết quả học tập. Thường xuyên đưa ra các bài tập ứng dụng đời sống.', 'Biên Hòa', 'Quận 1', 'active', true, 4, 53, 220, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-169', 'Xin chào! Mình là Thanh Trúc. Mình yêu Văn học và tin rằng nó giúp chúng ta hiểu thêm về con người và cuộc sống. Mình sẽ cùng các bạn phân tích các tác phẩm văn học, rèn luyện kỹ năng cảm thụ và diễn đạt. Mình đặc biệt chú trọng vào việc làm cho bài văn của các bạn trở nên sinh động, giàu cảm xúc và có chiều sâu hơn. Phù hợp với các bạn muốn yêu thích môn Văn.', 'Ngữ Văn THCS - Khám phá vẻ đẹp ngôn từ và cảm xúc.', NULL, 'Sinh viên năm 3, Khoa Văn học, Trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '3 năm kinh nghiệm dạy Văn THCS. Giúp các bạn học sinh có hứng thú hơn với môn học, cải thiện kỹ năng đọc hiểu và viết văn. Luôn tạo không khí học tập vui vẻ, gần gũi.', 'Cần Thơ', 'Quận 7', 'active', true, 4.8, 64, 446, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-170', 'Hello! Mình là Gia Bảo. Nếu bạn đang tò mò về thế giới lập trình và muốn tạo ra những sản phẩm của riêng mình, mình rất sẵn lòng hướng dẫn. Mình chuyên dạy các ngôn ngữ cơ bản như Scratch, Python cho các bạn nhỏ và mới bắt đầu. Phương pháp của mình là học đi đôi với hành, thông qua các dự án nhỏ, trò chơi và các bài tập thực tế để các bạn thấy hứng thú.', 'Lập trình căn bản cho giới trẻ - Khởi đầu hành trình sáng tạo.', NULL, 'Sinh viên năm 2, Khoa Công nghệ Thông tin, Trường Đại học FPT.', NULL, NULL, '2 năm kinh nghiệm dạy lập trình cho học sinh tiểu học và THCS. Đã giúp nhiều em làm quen với tư duy thuật toán và lập trình cơ bản. Có kinh nghiệm tổ chức các buổi workshop ngắn.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.9, 31, 201, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-171', 'Chào các bậc phụ huynh và các em nhỏ! Mình là Mai, mình rất yêu trẻ con và yêu môn Toán. Mình tin rằng Toán học có thể rất vui và bổ ích cho các con nếu được tiếp cận đúng cách. Mình sẽ giúp các con làm quen với các con số, phép tính, các dạng toán cơ bản qua các trò chơi, hình ảnh sinh động và phương pháp giảng dạy gần gũi, kiên nhẫn.', 'Toán Tiểu học - Xây dựng nền tảng vững chắc cho bé.', NULL, 'Cử nhân Giáo dục Tiểu học, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán Tiểu học. Giúp nhiều học sinh yêu thích môn Toán, cải thiện kết quả học tập và có nền tảng tốt cho các cấp học tiếp theo. Phương pháp nhẹ nhàng, phù hợp với tâm lý trẻ.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.6, 58, 252, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-172', 'Hi! Mình là Minh Khôi. Mình đã có kinh nghiệm chinh chiến nhiều kỳ thi IELTS và hiểu rõ những tiêu chí chấm điểm. Mình sẽ giúp bạn cải thiện khả năng nói trôi chảy, phát âm chuẩn và xây dựng các bài viết mạch lạc, logic, đúng cấu trúc. Mình thích phương pháp thực hành nhiều, sửa lỗi chi tiết và cung cấp feedback mang tính xây dựng.', 'IELTS Speaking & Writing - Luyện phản xạ, cấu trúc bài chuẩn.', NULL, 'IELTS 8.5, Cử nhân Tài chính Ngân hàng, Trường Đại học Kinh tế Quốc dân.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS, đặc biệt là Speaking và Writing. Từng đào tạo cho nhiều nhóm học sinh và cá nhân. Giúp học viên nâng cao đáng kể band điểm ở hai kỹ năng này.', 'Biên Hòa', 'Quận 3', 'active', true, 4.5, 36, 324, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-173', 'Chào các em! Cô là Thu Trang. Cô tin rằng Hóa Học không hề khó nếu các em nắm vững những khái niệm cơ bản. Cô sẽ giúp các em hiểu rõ từng phản ứng, từng công thức, làm quen với các dạng bài tập và cách trình bày lời giải sao cho logic và chính xác nhất. Cô luôn tạo không khí học tập thân thiện, khuyến khích các em đặt câu hỏi.', 'Hóa Học THCS - Hiểu bản chất, tự tin chinh phục.', NULL, 'Sinh viên năm 3, Khoa Hóa học, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa học THCS. Giúp các em nắm vững kiến thức sách giáo khoa, cải thiện điểm số và có hứng thú hơn với môn học. Kinh nghiệm bồi dưỡng học sinh giỏi cấp trường.', 'TP.HCM', 'Quận 1', 'active', true, 4.6, 36, 339, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-174', 'Chào bạn, mình là Hoàng Nam. Sinh học là một môn học vô cùng thú vị, giúp chúng ta hiểu về chính bản thân mình và thế giới tự nhiên. Mình sẽ giúp bạn làm rõ các kiến thức từ cơ bản đến nâng cao, tập trung vào việc xây dựng tư duy hệ thống và khả năng phân tích. Mình thích phương pháp trao đổi hai chiều, đảm bảo bạn hiểu bài trước khi chuyển sang nội dung mới.', 'Sinh Học THPT - Từ tế bào đến hệ sinh thái.', NULL, 'Cử nhân Sinh học Phân tử, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, '3 năm kinh nghiệm dạy Sinh học THPT. Giúp học sinh ôn thi Tốt nghiệp và Đại học, đặc biệt là các dạng bài tập về di truyền và sinh thái. Có kinh nghiệm làm câu hỏi đánh giá năng lực.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.8, 18, 331, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-175', 'Xin chào! Mình là Thuý Quỳnh. Mình có một tình yêu đặc biệt với Lịch sử Việt Nam. Mình tin rằng hiểu về lịch sử giúp chúng ta có cái nhìn sâu sắc hơn về dân tộc và đất nước mình. Mình sẽ cùng bạn khám phá những trang sử hào hùng, những câu chuyện của cha ông một cách sinh động, dễ nhớ. Mình thích phương pháp kể chuyện kết hợp với phân tích để bài học thêm phần hấp dẫn.', 'Lịch Sử Việt Nam - Tìm hiểu cội nguồn, trân trọng quá khứ.', NULL, 'Cử nhân Lịch sử Đảng, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh yêu thích môn học, ghi nhớ kiến thức một cách hệ thống và đạt kết quả tốt trong các kỳ thi. Chuyên sâu về Lịch sử Việt Nam giai đoạn cận đại.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.9, 62, 322, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-176', 'Hi everyone, I''m Huy Hoàng. Mình có kinh nghiệm dày dặn trong việc luyện thi các chứng chỉ Tiếng Anh như TOEIC, TOEFL. Mình tập trung vào việc cung cấp kiến thức ngữ pháp, từ vựng chuyên sâu và chiến lược làm bài hiệu quả cho từng kỹ năng. Mình là người khá nghiêm túc trong việc học nhưng luôn tạo động lực và hỗ trợ học viên hết mình để đạt mục tiêu.', 'Tiếng Anh luyện thi - Grammar, Vocabulary, và kỹ năng.', NULL, 'TOEIC 950, Cử nhân Kinh tế, Trường Đại học Kinh tế TP.HCM.', NULL, NULL, '5 năm kinh nghiệm luyện thi Tiếng Anh. Giúp nhiều học viên đạt điểm cao trong các kỳ thi chuẩn hóa. Có kinh nghiệm dạy online và offline, phù hợp với sinh viên và người đi làm.', 'TP.HCM', 'Thủ Đức', 'active', true, 5, 31, 177, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-177', 'Chào các bạn yêu Toán! Mình là Thuỳ Linh. Nếu bạn đang tìm kiếm thử thách và muốn bứt phá trong môn Toán, mình rất vui được đồng hành. Mình chuyên sâu vào các dạng toán tư duy, logic và các bài toán trong kỳ thi học sinh giỏi, thi chuyên. Phương pháp của mình là tập trung vào xây dựng nền tảng tư duy, rèn luyện kỹ năng giải các bài toán khó, đòi hỏi sự sáng tạo.', 'Toán nâng cao - Chuẩn bị cho kỳ thi chuyên và Olympic.', NULL, 'Thạc sĩ Toán học Lý thuyết, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, '6 năm kinh nghiệm dạy Toán nâng cao cho học sinh THPT. Tỷ lệ học sinh đậu vào các trường chuyên và đạt giải các kỳ thi Toán học cao. Có kinh nghiệm bồi dưỡng đội tuyển.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.6, 60, 406, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-178', 'Xin chào! Mình là Anh Tuấn. Mình thích cách Vật Lý giải thích các hiện tượng tự nhiên một cách khoa học. Mình sẽ giúp các bạn nắm vững kiến thức chương trình THPT, hiểu rõ bản chất các định luật và luyện tập thành thạo các dạng bài tập có trong đề thi. Mình là người hướng dẫn chi tiết, kiên nhẫn và luôn cố gắng làm cho bài giảng trở nên dễ tiếp thu nhất.', 'Vật Lý THPT - Giải thích cặn kẽ, bám sát đề thi.', NULL, 'Sinh viên năm 4, Khoa Vật lý, Trường Đại học Sư phạm Kỹ thuật Hưng Yên.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý THPT. Giúp học sinh ôn thi Tốt nghiệp và Đại học, đặc biệt là các phần kiến thức khó. Phương pháp giảng dạy bám sát cấu trúc đề thi.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.4, 7, 412, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-179', 'Chào các bạn! Mình là Minh Thư. Mình tin rằng Văn học là một thế giới đầy cảm xúc và trí tuệ. Mình sẽ giúp các bạn phân tích sâu sắc các tác phẩm văn chương, rèn luyện kỹ năng cảm thụ văn học và đặc biệt là kỹ năng viết bài nghị luận sắc bén, có luận điểm rõ ràng. Mình thích cùng học viên trao đổi, thảo luận để khơi gợi ý tưởng và phát triển bài viết.', 'Ngữ Văn THPT - Phân tích tác phẩm sâu sắc, viết văn mạch lạc.', NULL, 'Cử nhân Văn học, Trường Đại học Văn hóa TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Ngữ văn THPT. Giúp học sinh đạt điểm cao trong các kỳ thi, cải thiện kỹ năng làm văn và hiểu sâu hơn về các tác phẩm văn học kinh điển. Phương pháp giảng dạy sáng tạo, gợi mở.', 'TP.HCM', 'Quận 3', 'active', true, 4.6, 42, 328, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-180', 'Chào mọi người, mình là Văn Bình. Mình có kiến thức tốt về Địa lý tự nhiên và kinh tế Việt Nam cũng như thế giới. Mình sẽ giúp các bạn hiểu rõ hơn về bản đồ, các yếu tố tự nhiên ảnh hưởng đến đời sống và hoạt động kinh tế. Mình thích phương pháp học qua sơ đồ tư duy, hình ảnh trực quan và các câu hỏi gợi mở để các bạn tự suy luận.', 'Địa Lý THCS & THPT - Bản đồ, khí hậu, kinh tế.', NULL, 'Cử nhân Địa lý học, Trường Đại học Khoa học Tự nhiên, Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý THCS và THPT. Giúp học sinh nắm vững kiến thức, cải thiện kết quả học tập và làm quen với các dạng bài thi trắc nghiệm, tự luận. Có kinh nghiệm làm câu hỏi ôn tập.', 'Đồng Nai', 'Quận 1', 'active', true, 4.4, 27, 402, '2026-06-19 02:54:19.701695', '2026-06-19 02:54:19.701695', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-181', 'Chào các bạn, mình là Mai. Mình yêu thích việc chia sẻ kiến thức Tiếng Anh, đặc biệt là cách phát âm chuẩn và giao tiếp tự tin. Mình thường sử dụng phương pháp học qua tình huống thực tế, giúp các bạn tiếp thu kiến thức một cách tự nhiên và hiệu quả nhất. Mình rất vui khi được đồng hành cùng các bạn trên con đường chinh phục Tiếng Anh.', 'Tiếng Anh giao tiếp & luyện thi chứng chỉ A2, B1', NULL, 'Tốt nghiệp Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho học sinh THCS và người đi làm. Tỉ lệ học viên đạt chứng chỉ sau khóa học là 95%. Thích tạo không khí lớp học vui vẻ, năng động.', 'Đồng Nai', 'Quận 3', 'active', true, 4.7, 20, 418, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-182', 'Xin chào, mình là An. Mình tin rằng Toán học không hề khô khan nếu có phương pháp tiếp cận đúng. Mình tập trung vào việc xây dựng nền tảng vững chắc và rèn luyện kỹ năng giải quyết vấn đề cho học sinh. Với mình, mỗi bài toán là một câu chuyện thú vị chờ được khám phá. Mình luôn kiên nhẫn và tìm cách truyền cảm hứng học tập cho các em.', 'Toán tư duy cho học sinh lớp 6-9, bứt phá điểm số', NULL, 'Thủ khoa ngành Sư phạm Toán học, trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Đã có 5 năm kinh nghiệm dạy Toán chất lượng cao. Giúp hơn 200 học sinh cải thiện rõ rệt kết quả học tập, nhiều em đạt điểm 9-10 trong các bài kiểm tra và thi cuối kỳ. Từng dạy các lớp luyện thi vào lớp 10 chuyên Toán.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.1, 16, 286, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-183', 'Hà xin chào! Văn học là cả thế giới thu nhỏ đầy cảm xúc. Mình muốn mang đến cho các bạn niềm vui khám phá vẻ đẹp của từng câu chữ, từng tác phẩm. Phương pháp của mình là kết hợp phân tích sâu sắc với liên hệ thực tế, giúp các bạn hiểu và cảm thụ văn chương một cách tinh tế. Mình mong các bạn sẽ tìm thấy sự đồng cảm và yêu thích môn Văn qua những buổi học thú vị.', 'Ngữ văn 6-12: Chinh phục điểm cao, yêu văn chương', NULL, 'Cử nhân Ngữ văn, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Gia sư Văn được 10 năm, chuyên luyện thi THPT Quốc gia. Hỗ trợ nhiều học sinh đạt điểm Văn trên 8.5. Có kinh nghiệm dạy kèm các bạn gặp khó khăn trong việc phân tích đề và cảm thụ văn học.', 'Bình Dương', 'Quận 3', 'active', true, 4, 12, 218, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-184', 'Chào bạn, mình là Đức. Mình có niềm đam mê mãnh liệt với Vật lý và muốn lan tỏa điều đó. Mình dạy theo hướng tư duy hệ thống, giúp bạn nắm vững bản chất thay vì học thuộc lòng. Mình tin rằng với sự kiên trì và phương pháp phù hợp, bất kỳ ai cũng có thể làm chủ môn Vật Lý. Mình sẵn sàng giải đáp mọi thắc mắc của bạn.', 'Vật Lý THPT: Khai sáng tư duy, làm chủ kiến thức', NULL, 'Sinh viên năm cuối ngành Kỹ thuật Điện tử, trường Đại học Bách Khoa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý cho học sinh lớp 10-12. Giúp nhiều học sinh hiểu sâu kiến thức, cải thiện điểm số từ trung bình lên khá, giỏi. Thích sử dụng ví dụ minh họa gần gũi, dễ hiểu.', 'Biên Hòa', 'Quận 7', 'active', true, 4.7, 24, 137, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-185', 'Xin chào, mình là Nhi. Mình đã từng trải qua hành trình chinh phục IELTS và hiểu rõ những khó khăn, áp lực. Mình muốn chia sẻ kinh nghiệm và xây dựng một lộ trình học tập cá nhân hóa, phù hợp với mục tiêu của từng bạn. Mình tập trung vào chiến thuật làm bài hiệu quả cho cả 4 kỹ năng. Hãy cùng mình đạt được band điểm mơ ước nhé!', 'IELTS 7.0+: Lộ trình hiệu quả, target band điểm', NULL, 'Đạt IELTS 8.0, từng du học ngắn hạn tại Anh.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS cho mọi trình độ. Giúp nhiều học viên đạt band điểm mục tiêu chỉ sau 3-6 tháng. Có kinh nghiệm dạy online và offline, sửa phát âm, ngữ pháp và cách diễn đạt.', 'Hà Nội', 'Bình Thạnh', 'active', true, 4.2, 45, 253, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-186', 'Chào mọi người, mình là Khang. Mình rất thích công nghệ và lập trình. Mình muốn chia sẻ niềm yêu thích đó với các bạn, đặc biệt là những ai mới bắt đầu với Tin học và Python. Mình dạy theo kiểu ''cầm tay chỉ việc'', tập trung vào thực hành để các bạn nhanh chóng làm quen và tự tin xây dựng những chương trình nhỏ. Mình kiên nhẫn và giải thích mọi thứ thật dễ hiểu.', 'Tin học cơ bản & lập trình Python cho người mới bắt đầu', NULL, 'Sinh viên ngành Khoa học Máy tính, trường Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, '1 năm kinh nghiệm dạy lập trình Python cho các bạn học sinh THPT và sinh viên. Đã giúp các bạn hoàn thành các dự án cá nhân đầu tiên. Có khả năng truyền đạt kiến thức công nghệ một cách sinh động.', 'Hà Nội', 'Bình Thạnh', 'active', true, 4.3, 61, 67, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-187', 'Xin chào, mình là Lan Anh. Hóa học có thể rất thú vị nếu bạn hiểu được các phản ứng và nguyên lý đằng sau nó. Mình giúp học sinh xây dựng kiến thức nền tảng vững chắc, từ đó tự tin giải quyết các dạng bài tập từ cơ bản đến nâng cao. Mình luôn khuyến khích học sinh đặt câu hỏi và chủ động tìm tòi. Cùng mình khám phá thế giới Hóa học nhé!', 'Hóa Học THPT: Nắm vững bản chất, bứt phá điểm 9+', NULL, 'Tốt nghiệp Đại học Khoa học Tự nhiên, chuyên ngành Hóa học.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa cho học sinh lớp 10-12. Đã giúp nhiều học sinh cải thiện điểm số đáng kể và đạt kết quả cao trong kỳ thi tốt nghiệp. Phương pháp giảng dạy khoa học, dễ hiểu.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.3, 45, 396, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-188', 'Chào bạn, mình là Long. Sinh học là môn học về chính cuộc sống, và mình muốn giúp bạn khám phá những điều kỳ diệu đó. Mình có cách diễn đạt kiến thức sinh học một cách mạch lạc, logic, giúp bạn dễ dàng ghi nhớ và áp dụng. Mình tin rằng với sự tò mò và phương pháp học đúng, bạn sẽ yêu thích môn Sinh. Mình rất mong được đồng hành cùng bạn.', 'Sinh Học THPT: Giải thích dễ hiểu, ghi nhớ lâu', NULL, 'Sinh viên Y Đa khoa, trường Đại học Y Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Giúp nhiều học sinh nắm vững kiến thức và đạt điểm cao trong các bài kiểm tra. Thích dùng hình ảnh và sơ đồ tư duy để hỗ trợ việc học.', 'Biên Hòa', 'Quận 1', 'active', true, 4.6, 23, 122, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-189', 'Chào các bạn, mình là Quỳnh. Mình yêu thích Lịch sử và muốn chia sẻ những câu chuyện hào hùng, ý nghĩa của dân tộc với các bạn. Mình không dạy theo kiểu thuộc lòng niên đại, mà giúp các bạn hiểu bối cảnh, nguyên nhân - kết quả của các sự kiện lịch sử. Mình tin rằng học Sử sẽ trở nên thú vị và đáng nhớ hơn rất nhiều.', 'Lịch Sử THPT: Kể chuyện lịch sử, nhớ sự kiện', NULL, 'Cử nhân Lịch sử, trường Đại học Sư phạm.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử cho học sinh THCS và THPT. Giúp học sinh có cái nhìn tổng quan và sâu sắc hơn về lịch sử. Có khả năng liên hệ kiến thức với thực tế, làm bài giảng sinh động.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.8, 5, 168, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-190', 'Xin chào, mình là Quang. Địa lý không chỉ là bản đồ và số liệu, mà là cách chúng ta hiểu về thế giới xung quanh. Mình giúp các bạn kết nối kiến thức Địa lý với các vấn đề thời sự, kinh tế, xã hội. Phương pháp của mình là khơi gợi sự tò mò và tư duy phản biện. Mình tin rằng bạn sẽ thấy Địa lý thật gần gũi và hữu ích.', 'Địa Lý THPT: Liên hệ thực tế, hiểu thế giới', NULL, 'Sinh viên ngành Địa lý học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, '1 năm kinh nghiệm dạy Địa lý cho học sinh lớp 10-12. Giúp học sinh tiếp cận môn học một cách mới mẻ, dễ hiểu hơn. Thích sử dụng bản đồ, số liệu thống kê và các ví dụ thực tế.', 'TP.HCM', 'Quận 1', 'active', true, 4.6, 56, 123, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-191', 'Mình là Ngọc, một người yêu trẻ và yêu Tiếng Anh. Mình tin rằng việc học ngôn ngữ ở lứa tuổi nhỏ cần sự vui vẻ và khích lệ. Mình sử dụng các hoạt động tương tác, bài hát, trò chơi để tạo hứng thú cho các con. Mình giúp các con làm quen với Tiếng Anh một cách tự nhiên, xây dựng nền tảng vững chắc và sự tự tin khi sử dụng ngôn ngữ.', 'Tiếng Anh tiểu học & THCS: Vui học, tự tin giao tiếp', NULL, 'Tốt nghiệp Đại học Sư phạm Ngoại ngữ, ngành Sư phạm Tiếng Anh.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho học sinh tiểu học và THCS. Có kinh nghiệm làm trợ giảng tại các trung tâm Anh ngữ uy tín. Giúp các em tiếp thu từ vựng, ngữ pháp một cách nhẹ nhàng.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.2, 50, 162, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-192', 'Chào bạn, mình là Tùng. Mình có kinh nghiệm dạy Toán cho các em nhỏ lứa tuổi tiểu học. Mình tập trung vào việc giúp các em làm quen với các con số, các phép tính cơ bản một cách vui vẻ và trực quan. Mình sử dụng các công cụ hỗ trợ như hình ảnh, que tính để các em dễ hình dung. Mục tiêu của mình là giúp các em có nền tảng Toán học tốt và yêu thích môn học này.', 'Toán lớp 1-5: Làm quen số học, tư duy logic', NULL, 'Sinh viên ngành Giáo dục Tiểu học, trường Đại học Sư phạm.', NULL, NULL, '1.5 năm kinh nghiệm dạy Toán tiểu học. Giúp các em làm quen với chương trình mới, cải thiện kỹ năng tính toán. Nhiệt tình, kiên nhẫn với học sinh nhỏ tuổi.', 'Biên Hòa', 'Quận 1', 'active', true, 4.1, 46, 323, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-193', 'Xin chào, mình là Thanh Mai. Mình có kinh nghiệm dày dặn trong việc ôn luyện kỹ năng Speaking và Writing cho kỳ thi IELTS. Mình sẽ bật mí những cấu trúc câu hay, từ vựng học thuật và cách triển khai ý tưởng sao cho mạch lạc, thuyết phục. Cùng mình luyện tập để tự tin chinh phục điểm số mong muốn nhé!', 'IELTS Speaking & Writing: Bí quyết đạt điểm cao', NULL, 'IELTS 7.5 Overall, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, '4 năm kinh nghiệm luyện thi IELTS, tập trung vào 2 kỹ năng Speaking và Writing. Giúp hàng trăm học viên cải thiện rõ rệt khả năng diễn đạt và cấu trúc bài viết. Có khả năng chữa bài chi tiết và đưa ra lời khuyên hữu ích.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.8, 27, 258, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-194', 'Chào bạn, mình là Tuấn Anh. Mình có kiến thức sâu rộng về Vật Lý và đã luyện thi đại học môn này nhiều năm. Mình có phương pháp giảng dạy logic, giúp bạn hiểu rõ bản chất vấn đề và áp dụng linh hoạt vào các bài tập. Mình tin rằng với sự hướng dẫn đúng đắn, bạn có thể vượt qua mọi thử thách trong môn Vật Lý.', 'Vật Lý THPT: Từ cơ bản đến nâng cao, thi đại học', NULL, 'Cựu sinh viên ngành Vật lý Kỹ thuật, trường Đại học Bách Khoa.', NULL, NULL, '6 năm kinh nghiệm dạy Vật Lý, chuyên luyện thi THPT Quốc gia và đánh giá năng lực. Tỷ lệ học sinh đỗ nguyện vọng 1 cao. Có kinh nghiệm dạy kèm các bạn mất gốc.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.8, 34, 197, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-195', 'Chào các bạn, mình là Minh Ngọc. Mình yêu văn chương và mong muốn truyền ngọn lửa đó tới các bạn. Mình tập trung vào việc phân tích sâu các tác phẩm văn học, rèn luyện kỹ năng nghị luận sắc bén. Mình tin rằng mỗi bài học Văn là một cơ hội để khám phá bản thân và thế giới. Cùng mình làm cho môn Văn trở nên thật ý nghĩa nhé!', 'Ngữ văn 10-12: Phân tích tác phẩm, nghị luận sâu sắc', NULL, 'Thạc sĩ Lý luận và Phê bình Văn học, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '5 năm kinh nghiệm dạy Ngữ văn THPT. Hỗ trợ học sinh xây dựng kỹ năng phân tích, cảm thụ văn học và viết luận. Nhiều học sinh đạt điểm cao trong các kỳ thi quan trọng.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.9, 30, 345, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-196', 'Xin chào, mình là Bình. Mình có kinh nghiệm giảng dạy Hóa học ở cả cấp THPT và Đại học. Mình giúp học sinh hiểu rõ các khái niệm Hóa học, từ đó áp dụng vào giải các dạng bài tập từ cơ bản đến phức tạp. Phương pháp của mình là kết hợp lý thuyết chặt chẽ với thực hành nhiều ví dụ. Mình luôn kiên nhẫn và giải thích cặn kẽ.', 'Hóa Học THPT & Đại cương: Nắm vững lý thuyết, thành thạo bài tập', NULL, 'Cựu sinh viên ngành Hóa học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học. Đã giúp nhiều học sinh lấy lại kiến thức và cải thiện điểm số. Có kinh nghiệm dạy Hóa Đại cương cho sinh viên năm nhất.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.4, 41, 239, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-197', 'Chào bạn, mình là Trang. Mình có phương pháp dạy Toán hiệu quả, giúp học sinh xây dựng nền tảng vững chắc và phát triển tư duy logic. Mình tập trung vào các dạng bài thi đại học, trang bị cho bạn những kỹ năng giải toán nhanh và chính xác. Mình tin rằng Toán học có thể trở nên thú vị và dễ dàng hơn với phương pháp phù hợp.', 'Toán 10-12: Luyện thi Đại học, tư duy đột phá', NULL, 'Thạc sĩ Toán học ứng dụng, trường Đại học Công nghệ.', NULL, NULL, '5 năm kinh nghiệm dạy Toán THPT và luyện thi đại học. Giúp nhiều học sinh đạt điểm cao môn Toán trong kỳ thi tốt nghiệp THPT. Có kinh nghiệm dạy các lớp học nhóm nhỏ.', 'Bình Dương', 'Hải Châu', 'active', true, 4.6, 21, 144, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-198', 'Hi there, I''m Bao. I''m passionate about helping you improve your English communication skills. I focus on practical conversation, vocabulary building, and pronunciation correction. My goal is to make learning English fun and effective, so you can speak with confidence in any situation. Let''s practice together!', 'Tiếng Anh giao tiếp & Luyện thi chứng chỉ B2, C1', NULL, 'Bachelor''s Degree in English Linguistics.', NULL, NULL, '4 years of experience teaching English for adults and young professionals. Helped numerous students achieve their target scores for B2 and C1 certifications. Specializes in conversational English and exam preparation.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4.7, 13, 361, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-199', 'Xin chào, mình là Hồng. Mình có cách tiếp cận môn Sinh học rất trực quan, giúp các bạn dễ dàng hình dung và ghi nhớ kiến thức. Mình tập trung vào việc giải thích các khái niệm phức tạp một cách đơn giản và có hệ thống. Mình tin rằng với sự kiên nhẫn và phương pháp đúng, các bạn sẽ thấy môn Sinh học thật sự hấp dẫn.', 'Sinh học THPT: Giải thích chi tiết, hình dung kiến thức', NULL, 'Sinh viên năm cuối ngành Công nghệ Sinh học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, '1.5 năm kinh nghiệm dạy Sinh học cho học sinh lớp 10-12. Giúp các bạn nắm vững kiến thức cơ bản và nâng cao. Có khả năng sử dụng các công cụ trực quan để giảng dạy.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.5, 30, 51, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-200', 'Chào bạn, mình là Nam. Mình chuyên dạy Tin học văn phòng (Word, Excel, PowerPoint) và những kiến thức lập trình cơ bản nhất. Mình có phương pháp giảng dạy dễ hiểu, phù hợp với cả những người mới bắt đầu và người lớn tuổi. Mình tin rằng Tin học là công cụ hữu ích, giúp cuộc sống và công việc của chúng ta trở nên thuận tiện hơn.', 'Tin học văn phòng & Lập trình cơ bản cho mọi lứa tuổi', NULL, 'Tốt nghiệp ngành Công nghệ Thông tin.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học. Đã hỗ trợ nhiều người làm quen và sử dụng thành thạo các phần mềm văn phòng. Có kinh nghiệm dạy lập trình Scratch, Python cho học sinh.', 'Đồng Nai', 'Quận 7', 'active', true, 4.4, 16, 228, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-201', 'Chào mọi người, mình là Thủy. Mình có niềm yêu thích đặc biệt với Lịch sử Việt Nam và muốn chia sẻ những câu chuyện lịch sử đầy cảm hứng, ý nghĩa tới các bạn. Mình dạy theo cách kể chuyện sinh động, giúp các bạn hiểu rõ bối cảnh và bài học từ quá khứ. Mình tin rằng học Lịch sử là cách để hiểu về cội nguồn và xây dựng tương lai.', 'Lịch sử Việt Nam: Kể chuyện hấp dẫn, liên hệ hiện tại', NULL, 'Cử nhân Lịch sử Đảng, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch sử. Giúp học sinh có cái nhìn sâu sắc và thú vị hơn về môn học. Có khả năng kết nối kiến thức lịch sử với các vấn đề xã hội đương đại.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.2, 35, 266, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-202', 'Chào bạn, mình là Tuấn. Mình có kinh nghiệm nhiều năm trong việc ôn luyện Toán cho học sinh THPT, đặc biệt là ôn thi vào lớp 10 và luyện thi đại học. Mình tập trung vào việc rèn luyện kỹ năng giải đề, nắm vững các dạng toán trọng tâm. Mình luôn cố gắng truyền đạt kiến thức một cách rõ ràng, logic và hiệu quả nhất.', 'Toán THPT: Ôn thi vào lớp 10, luyện thi Đại học', NULL, 'Cựu học sinh trường THPT Chuyên, tốt nghiệp ngành Toán học.', NULL, NULL, '5 năm kinh nghiệm dạy Toán THPT. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi quan trọng. Có khả năng phát hiện và khắc phục lỗ hổng kiến thức của học sinh.', 'Cần Thơ', 'Quận 3', 'active', true, 4.3, 54, 358, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-203', 'Xin chào, mình là Thúy An. Nếu bạn đang gặp khó khăn với Tiếng Anh, đặc biệt là ngữ pháp và giao tiếp cơ bản, mình có thể giúp bạn. Mình có phương pháp tiếp cận nhẹ nhàng, giúp bạn từng bước lấy lại sự tự tin. Mình tập trung vào việc xây dựng nền tảng vững chắc và thực hành thường xuyên. Hãy cùng nhau chinh phục Tiếng Anh nhé!', 'Tiếng Anh giao tiếp & Ngữ pháp cho người mất gốc', NULL, 'Tốt nghiệp Đại học Khoa học Xã hội và Nhân văn, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh, chuyên hỗ trợ người mất gốc. Giúp học viên cải thiện rõ rệt khả năng hiểu ngữ pháp và giao tiếp. Phương pháp dạy kiên nhẫn, dễ hiểu.', 'Cần Thơ', 'Quận 3', 'active', true, 4.2, 17, 168, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-204', 'Chào bạn, mình là Duy. Mình có niềm đam mê với Vật lý và mong muốn truyền đạt kiến thức một cách dễ hiểu nhất cho học sinh. Mình tập trung vào việc giúp các bạn nắm vững bản chất của các hiện tượng vật lý, từ đó giải quyết các bài tập một cách tự tin. Mình luôn sẵn sàng giải đáp mọi thắc mắc và hỗ trợ các bạn học tập.', 'Vật Lý THCS & THPT: Giúp hiểu sâu, làm tốt bài tập', NULL, 'Sinh viên ngành Vật lý, trường Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý cho học sinh THCS và THPT. Giúp học sinh cải thiện điểm số và có cái nhìn tích cực hơn về môn học. Phương pháp giảng dạy gần gũi, dễ tiếp thu.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.4, 5, 319, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-299', 'Chào các em, mình là Quang Vinh. Mình muốn giúp các em không còn e ngại môn Tiếng Anh. Mình sẽ cùng các em ôn tập ngữ pháp, từ vựng và luyện tập các kỹ năng nghe, nói, đọc, viết. Phương pháp của mình là kết hợp lý thuyết và thực hành, giúp các em tiến bộ nhanh chóng.', 'Tiếng Anh THPT, cải thiện điểm số, giao tiếp tự tin.', NULL, 'Cựu sinh viên ngành Tiếng Anh Thương mại, Đại học Kinh tế TP. Hồ Chí Minh.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho học sinh THPT. Giúp các em cải thiện điểm số trên lớp và tự tin hơn khi giao tiếp.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.2, 20, 418, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-205', 'Chào các bạn nhỏ, mình là Phương. Mình yêu thích môn Văn và muốn giúp các bạn có những trải nghiệm học tập thật vui vẻ và ý nghĩa. Mình tập trung vào việc giúp các bạn hiểu bài, cảm thụ văn chương và rèn luyện kỹ năng diễn đạt. Mình tin rằng với sự khích lệ và phương pháp phù hợp, các bạn sẽ ngày càng yêu thích môn Văn.', 'Ngữ văn THCS: Xây dựng nền tảng, yêu văn học', NULL, 'Cử nhân Sư phạm Ngữ văn, trường Đại học Sư phạm.', NULL, NULL, '3 năm kinh nghiệm dạy Ngữ văn THCS. Giúp học sinh nắm vững kiến thức cơ bản, cải thiện kỹ năng làm văn. Nhiệt tình, yêu trẻ và có khả năng tạo không khí học tập tích cực.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.8, 19, 207, '2026-06-19 02:54:38.935479', '2026-06-19 02:54:38.935479', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-231', 'Chào các bạn, mình là Minh Anh. Mình có niềm đam mê đặc biệt với những con số và mong muốn lan tỏa tình yêu đó đến các bạn học sinh. Phương pháp của mình là tập trung vào việc xây dựng nền tảng vững chắc, giúp các bạn hiểu sâu bản chất thay vì học thuộc lòng. Mình tin rằng Toán học không hề khô khan nếu chúng ta tìm được cách tiếp cận phù hợp. Mình rất vui được đồng hành cùng các bạn, đặc biệt là các bạn gặp khó khăn với môn Toán.', 'Chinh phục Toán học cùng thầy Anh - Nắm chắc kiến thức, tự tin chinh phục mọi bài toán!', NULL, 'Tốt nghiệp Đại học Khoa học Tự nhiên, chuyên ngành Sư phạm Toán học.', NULL, NULL, 'Mình có 4 năm kinh nghiệm dạy Toán cho học sinh cấp 2 và cấp 3. Từng giúp nhiều học sinh cải thiện điểm số từ trung bình lên khá, giỏi. Mình quen thuộc với các dạng bài thi và chương trình học phổ thông.', 'TP.HCM', 'Hải Châu', 'active', true, 4.5, 33, 319, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-232', 'Xin chào! Mình là Thuỳ Linh, một người yêu thích ngôn ngữ Anh và văn hóa quốc tế. Mình luôn cố gắng tạo ra một không khí học tập thoải mái, vui vẻ để các bạn không còn sợ hãi khi nói tiếng Anh. Mình thích sử dụng các hoạt động tương tác, trò chơi và những câu chuyện thực tế để bài học thêm sinh động. Mình hướng đến việc phát triển toàn diện 4 kỹ năng Nghe - Nói - Đọc - Viết, đặc biệt là khả năng giao tiếp.', 'Giáo viên Tiếng Anh trẻ trung, nhiệt huyết. Cam kết giúp bạn nói tiếng Anh trôi chảy!', NULL, 'Cử nhân ngành Ngôn ngữ Anh, trường Đại học Ngoại ngữ Quốc gia.', NULL, NULL, 'Mình đã có 3 năm kinh nghiệm dạy Tiếng Anh cho mọi lứa tuổi, từ người mới bắt đầu đến nâng cao. Nhiều học sinh của mình đã tự tin giao tiếp sau khóa học. Mình cũng từng dạy theo nhóm nhỏ và lớp online.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.2, 54, 249, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-233', 'Chào các em, thầy là Quốc Bảo. Vật Lý luôn ẩn chứa những điều kỳ diệu của thế giới tự nhiên và thầy muốn chia sẻ điều đó với các em. Phương pháp dạy của thầy là đi từ những ví dụ thực tế, trực quan sinh động, sau đó mới đi vào công thức và định luật. Mục tiêu của thầy là giúp các em không chỉ học thuộc mà còn thực sự hiểu và yêu thích Vật Lý. Thầy rất kiên nhẫn và luôn sẵn sàng giải đáp mọi thắc mắc.', 'Thầy giáo Vật Lý tâm huyết. Biến những khái niệm phức tạp thành bài học dễ hiểu.', NULL, 'Thạc sĩ ngành Vật lý Kỹ thuật, Đại học Bách Khoa.', NULL, NULL, 'Thầy có 5 năm kinh nghiệm giảng dạy Vật Lý tại trung tâm luyện thi. Nhiều học sinh của thầy đạt điểm cao trong các kỳ thi quan trọng. Thầy đã làm việc với nhiều nhóm học sinh có trình độ và mục tiêu khác nhau.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.4, 51, 360, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-234', 'Chào các bạn, mình là Mai. Hóa học có thể hơi đáng sợ với một số bạn, nhưng mình tin rằng với cách tiếp cận đúng đắn, nó sẽ trở nên thật thú vị. Mình thích sử dụng các thí nghiệm minh họa (qua mô phỏng hoặc video), sơ đồ tư duy và bài tập ứng dụng để giúp các bạn ghi nhớ kiến thức lâu hơn. Mình hướng dẫn theo sát chương trình, tập trung vào các dạng bài hay thi. Bạn nào cần lấy lại gốc hay muốn bứt phá, mình đều sẵn sàng hỗ trợ.', 'Chinh phục Hóa học cùng cô Mai. Học vui, hiểu sâu, thi tốt!', NULL, 'Cử nhân Hóa học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Mình đã có 3 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Mình đã giúp nhiều bạn đạt điểm 8, 9 trong các bài kiểm tra và thi học kỳ. Mình quen với việc dạy kèm cá nhân và nhóm nhỏ.', 'Cần Thơ', 'Hoàng Mai', 'active', true, 4.5, 59, 130, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-235', 'Chào các em, thầy là Duy Khang. Ngữ văn không chỉ là những con chữ, mà là cả một thế giới cảm xúc và tư tưởng. Thầy tin rằng mỗi bạn đều có khả năng cảm thụ và sáng tạo văn học. Phương pháp của thầy là khuyến khích các em đọc nhiều, cảm nhận sâu sắc và diễn đạt bằng lời văn của chính mình. Thầy sẽ cùng các em khám phá vẻ đẹp của từng tác phẩm, trau chuốt từng câu chữ để bài văn thêm phần sinh động và ý nghĩa.', 'Thầy Khang - Gia sư Ngữ văn. Khơi nguồn cảm hứng, nâng tầm bài viết.', NULL, 'Tốt nghiệp chuyên ngành Sư phạm Ngữ văn, trường Đại học Sư phạm.', NULL, NULL, 'Với 4 năm kinh nghiệm, thầy đã đồng hành cùng nhiều thế hệ học sinh. Đặc biệt, thầy có kinh nghiệm bồi dưỡng học sinh giỏi Văn và luyện viết cho các kỳ thi. Nhiều học sinh tiến bộ rõ rệt về cách phân tích và diễn đạt.', 'Biên Hòa', 'Quận 1', 'active', true, 4.4, 22, 159, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-236', 'Xin chào các bạn! Mình là Minh Hằng, một người say mê khám phá sự sống quanh ta. Mình tin rằng Sinh học không chỉ có trong sách vở mà còn hiện hữu trong cuộc sống hàng ngày. Phương pháp dạy của mình là kết hợp hình ảnh trực quan, sơ đồ tư duy và các ví dụ thực tế để các bạn dễ hình dung và ghi nhớ. Mình đặc biệt chú trọng rèn luyện kỹ năng phân tích, suy luận và giải các dạng bài tập Sinh học. Cùng mình làm chủ môn Sinh nhé!', 'Cô Hằng - Sinh học dễ hiểu. Khám phá thế giới sống động, chinh phục mọi đề thi.', NULL, 'Cử nhân Sinh học Phân tử, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Mình đã giúp nhiều bạn cải thiện kết quả học tập, đặc biệt là các phần kiến thức khó như Di truyền, Sinh thái. Mình có kinh nghiệm dạy cả online và offline.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.8, 35, 239, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-237', 'Chào các em! Thầy là Tuấn Huy. Nhiều bạn cảm thấy Lịch sử nhàm chán, nhưng thầy tin rằng mỗi câu chuyện lịch sử đều ẩn chứa những bài học quý giá. Thầy dạy Lịch sử bằng cách kể chuyện, liên hệ với các sự kiện, địa điểm và nhân vật có thật, giúp các em hình dung rõ hơn về quá khứ. Mục tiêu của thầy là khơi gợi sự tò mò, giúp các em hiểu và yêu thích môn Sử. Thầy rất kiên nhẫn và luôn tạo không khí học tập hứng thú.', 'Thầy Huy - Lịch sử không khô khan. Học bằng cả trái tim và trí óc.', NULL, 'Tốt nghiệp ngành Sư phạm Lịch sử, trường Đại học Sư phạm.', NULL, NULL, 'Với 4 năm kinh nghiệm dạy Lịch sử, thầy đã giúp nhiều học sinh nắm vững kiến thức, tự tin làm bài thi. Thầy có kinh nghiệm dạy theo chương trình mới và ôn thi THPT Quốc gia. Nhiều học sinh của thầy đã có sự tiến bộ vượt bậc.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.8, 33, 321, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-238', 'Xin chào các bạn! Mình là Bích Ngọc. Mình yêu thích Địa lý vì nó giúp chúng ta hiểu hơn về thế giới xung quanh, từ những dãy núi hùng vĩ đến các nền văn hóa đa dạng. Phương pháp dạy của mình là sử dụng bản đồ, hình ảnh, video và các hoạt động tương tác để bài học thêm phần sinh động và dễ nhớ. Mình muốn giúp các bạn không chỉ học thuộc kiến thức mà còn biết cách phân tích, liên hệ các yếu tố địa lý. Cùng nhau khám phá Trái Đất nào!', 'Địa lý thú vị cùng cô Ngọc. Khám phá thế giới rộng lớn ngay tại nhà!', NULL, 'Cử nhân ngành Địa lý học, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy kèm Địa lý cho học sinh cấp 2 và cấp 3. Mình đã giúp các bạn củng cố kiến thức, cải thiện điểm số và phát triển kỹ năng đọc bản đồ. Mình quen với việc dạy theo yêu cầu cá nhân.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.3, 31, 296, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-239', 'Chào các bạn! Mình là Văn Hoàng. Mình đam mê công nghệ và mong muốn chia sẻ kiến thức Tin học một cách dễ hiểu và thực tế nhất. Phương pháp của mình là đi từ những khái niệm cơ bản, kèm theo ví dụ minh họa và bài tập thực hành ngay trên máy tính. Mình không chỉ dạy lý thuyết mà còn hướng dẫn các bạn ứng dụng vào học tập và cuộc sống. Mình rất vui được giúp các bạn làm quen, làm chủ các công cụ số.', 'Thầy Hoàng - Tin học thực tế. Từ cơ bản đến nâng cao, làm chủ công nghệ.', NULL, 'Tốt nghiệp Đại học Công nghệ Thông tin, chuyên ngành Kỹ thuật Phần mềm.', NULL, NULL, 'Mình có 5 năm kinh nghiệm làm việc trong ngành IT và 2 năm kinh nghiệm dạy Tin học cho học sinh, sinh viên. Mình đã hướng dẫn nhiều bạn sử dụng thành thạo Word, Excel, PowerPoint, lập trình cơ bản và thiết kế đồ họa đơn giản. Mình có thể dạy kèm cá nhân hoặc nhóm nhỏ.', 'Đồng Nai', 'Quận 7', 'active', true, 4.5, 34, 128, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-240', 'Xin chào các bạn! Mình là Thuỳ Dương. Mình hiểu rằng IELTS Listening & Reading có thể là một thử thách, nhưng mình tin rằng với chiến lược phù hợp, bạn hoàn toàn có thể đạt điểm số mong muốn. Phương pháp của mình là tập trung vào việc xây dựng vốn từ vựng học thuật, luyện tập các dạng câu hỏi thường gặp và rèn luyện kỹ năng đọc hiểu nhanh. Mình sẽ chia sẻ những mẹo và chiến thuật hiệu quả nhất, giúp bạn tối ưu hóa thời gian và tự tin bước vào phòng thi.', 'Chinh phục IELTS Listening & Reading cùng cô Dương. Điểm cao trong tầm tay!', NULL, 'Đạt IELTS 8.0 (Listening 9.0, Reading 8.5), tốt nghiệp ngành Kinh tế Đối ngoại.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy luyện thi IELTS, tập trung vào kỹ năng Listening và Reading. Mình đã giúp nhiều học viên tăng band điểm đáng kể trong thời gian ngắn. Mình hiểu rõ các tiêu chí chấm điểm và các lỗi sai phổ biến.', 'Bình Dương', 'Hải Châu', 'active', true, 4.3, 14, 294, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-241', 'Chào các con! Thầy là Gia Bảo. Toán học rất vui và bổ ích, thầy sẽ giúp các con khám phá điều đó. Thầy thích dùng các trò chơi, ví dụ thực tế và hình ảnh sinh động để các con hiểu bài nhanh và nhớ lâu. Mục tiêu của thầy là giúp các con không còn sợ Toán, mà còn thấy môn học này thật thú vị. Thầy rất kiên nhẫn và luôn động viên các con cố gắng.', 'Thầy Bảo - Gia sư Toán tiểu học. Xây dựng nền tảng vững chắc, yêu Toán từ nhỏ.', NULL, 'Sinh viên năm 3, ngành Sư phạm Toán học, trường Đại học Sư phạm.', NULL, NULL, 'Mình đã có 2 năm kinh nghiệm dạy kèm Toán cho học sinh tiểu học. Mình giúp các con nắm vững các phép tính, kiến thức cơ bản và làm quen với các dạng toán tư duy. Nhiều phụ huynh đánh giá con tiến bộ rõ rệt.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.7, 46, 172, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-242', 'Xin chào! Mình là Thu Hương. Nếu bạn muốn cải thiện khả năng giao tiếp Tiếng Anh để đi du lịch, học tập hay làm việc, mình tin rằng mình có thể giúp bạn. Mình tập trung vào việc thực hành nói, sửa lỗi phát âm và ngữ pháp một cách tự nhiên. Mình thường sử dụng các tình huống giao tiếp thực tế, bài hát, phim ảnh để buổi học thêm phần sinh động. Bạn đừng ngại mắc lỗi, quan trọng là chúng ta dám nói!', 'Cô Hương - Tiếng Anh giao tiếp. Tự tin nói, tự tin tỏa sáng!', NULL, 'Cử nhân ngành Ngôn ngữ Anh, trường Đại học Hà Nội.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm và sinh viên. Mình đã giúp nhiều học viên vượt qua rào cản ngôn ngữ và tự tin hơn khi sử dụng Tiếng Anh. Mình có kinh nghiệm dạy lớp online và offline.', 'Đồng Nai', 'Quận 1', 'active', true, 4.7, 16, 342, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-243', 'Chào các bạn, thầy là Minh Quân. Vật Lý có thể phức tạp, nhưng thầy sẽ giúp các bạn đơn giản hóa nó. Thầy đi sâu vào bản chất của từng hiện tượng, sử dụng các mô hình và thí nghiệm ảo để minh họa. Thầy thích đặt câu hỏi, khuyến khích các bạn tư duy phản biện và tự tìm ra lời giải. Mục tiêu của thầy là giúp các bạn không chỉ đạt điểm cao mà còn thực sự hiểu và yêu thích môn học này.', 'Thầy Quân - Giải đáp mọi thắc mắc Vật Lý. Học hiểu bản chất, làm chủ kiến thức.', NULL, 'Thạc sĩ Vật lý Lý thuyết, Viện Khoa học Việt Nam.', NULL, NULL, 'Thầy có 5 năm kinh nghiệm dạy Vật Lý cho học sinh THPT và luyện thi Đại học. Nhiều học sinh của thầy đã trúng tuyển vào các trường Đại học danh tiếng. Thầy có khả năng phân tích sâu sắc các dạng bài tập khó.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.1, 19, 57, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-244', 'Chào các em! Mình là Lan Anh. Hóa học thật sự rất gần gũi với cuộc sống của chúng ta. Mình thích dạy Hóa học bằng cách liên hệ với các hiện tượng hàng ngày, các sản phẩm chúng ta sử dụng. Mình sẽ giúp các em xây dựng kiến thức từ cơ bản đến nâng cao, tập trung vào phương pháp giải bài tập và kỹ năng thực hành thí nghiệm (qua mô phỏng). Mình tin rằng Hóa học có thể trở nên thật hấp dẫn!', 'Cô Lan Anh - Hóa học thực tiễn. Kết nối lý thuyết với cuộc sống muôn màu.', NULL, 'Cử nhân ngành Sư phạm Hóa học, trường Đại học Sư phạm.', NULL, NULL, 'Mình có 4 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Mình đã giúp nhiều bạn vượt qua nỗi sợ Hóa học và đạt kết quả tốt trong các kỳ thi. Mình có kinh nghiệm ôn thi học sinh giỏi và thi THPT.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.9, 21, 307, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-245', 'Chào các em, thầy là Trọng Nghĩa. Thầy tin rằng mỗi người đều có một cách cảm thụ và diễn đạt văn chương độc đáo. Thầy sẽ đồng hành cùng các em khám phá những tầng ý nghĩa sâu sắc của các tác phẩm văn học, đồng thời hướng dẫn các em rèn luyện kỹ năng viết sao cho mạch lạc, cảm xúc và có chiều sâu. Chúng ta sẽ cùng nhau phân tích tác phẩm, luyện tập viết đoạn văn, bài văn và trau chuốt ngôn ngữ.', 'Thầy Nghĩa - Ngữ văn sáng tạo. Giúp bạn tìm thấy giọng văn riêng.', NULL, 'Tốt nghiệp ngành Văn học Ứng dụng, trường Đại học Sân khấu Điện ảnh.', NULL, NULL, 'Với 3 năm kinh nghiệm, thầy đã giúp nhiều học sinh cải thiện kỹ năng cảm thụ văn học và viết văn. Thầy đặc biệt có kinh nghiệm bồi dưỡng năng khiếu viết văn và luyện thi vào các trường chuyên. Phương pháp của thầy đề cao sự sáng tạo cá nhân.', 'Hà Nội', 'Quận 7', 'active', true, 4.3, 21, 334, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-246', 'Chào các bạn! Mình là Hà My. Sinh học có rất nhiều kiến thức thú vị về cơ thể sống và thế giới tự nhiên. Mình thích sử dụng sơ đồ, hình ảnh minh họa và các ví dụ sinh động để giúp các bạn học bài hiệu quả hơn. Mình sẽ giúp các bạn nắm vững kiến thức trọng tâm, rèn luyện kỹ năng phân tích và giải các dạng bài tập từ cơ bản đến nâng cao. Cùng mình khám phá thế giới Sinh học đầy màu sắc nhé!', 'Cô My - Sinh học trực quan. Dễ hiểu, dễ nhớ, dễ thi!', NULL, 'Cử nhân ngành Sinh học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Mình đã giúp nhiều bạn cải thiện đáng kể kết quả học tập, đặc biệt là các phần kiến thức về Tế bào, Di truyền và Tiến hóa. Mình quen với việc dạy online.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.3, 63, 270, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-247', 'Chào các em! Thầy là Minh Hiếu. Lịch sử không chỉ là những sự kiện khô khan, mà là những câu chuyện đầy hấp dẫn về cha ông ta. Thầy thích kể chuyện lịch sử một cách lôi cuốn, kết hợp hình ảnh, bản đồ và các tài liệu tham khảo để các em dễ hình dung và ghi nhớ. Thầy sẽ giúp các em hiểu được cái hồn của lịch sử, từ đó yêu thích và học tốt môn học này. Thầy luôn tạo không khí học tập vui vẻ, cởi mở.', 'Thầy Hiếu - Lịch sử sống động. Đưa quá khứ đến gần bạn hơn.', NULL, 'Tốt nghiệp ngành Sư phạm Lịch sử, trường Đại học Vinh.', NULL, NULL, 'Thầy có 4 năm kinh nghiệm dạy Lịch sử cho học sinh cấp 3. Thầy đã giúp nhiều học sinh đạt điểm cao trong các kỳ thi, đặc biệt là kỳ thi THPT Quốc gia. Thầy có kinh nghiệm ôn luyện theo từng chuyên đề.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.6, 56, 199, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-248', 'Xin chào các bạn! Mình là Minh Châu. Mình tin rằng Địa lý là môn học giúp chúng ta mở rộng tầm nhìn, hiểu về con người, thiên nhiên và văn hóa trên khắp thế giới. Mình thích sử dụng bản đồ, số liệu thống kê, hình ảnh và các câu chuyện thực tế để bài học thêm sinh động. Mình sẽ giúp các bạn nắm vững kiến thức, rèn luyện kỹ năng phân tích bản đồ, biểu đồ và liên hệ thực tế. Cùng nhau khám phá vẻ đẹp của Địa lý nhé!', 'Cô Châu - Địa lý thực tế. Hiểu thế giới, yêu quê hương.', NULL, 'Cử nhân ngành Địa lý học, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy kèm Địa lý cho học sinh THCS và THPT. Mình đã giúp nhiều bạn cải thiện kết quả học tập, đặc biệt là các phần kiến thức về Tự nhiên và Kinh tế - Xã hội. Mình có kinh nghiệm dạy online hiệu quả.', 'Đồng Nai', 'Quận 1', 'active', true, 4.2, 60, 354, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-249', 'Chào các bạn! Mình là Thanh Tùng. Trong thời đại số, Tin học là một kỹ năng vô cùng quan trọng. Mình chuyên dạy Tin học ứng dụng, giúp các bạn làm chủ các công cụ văn phòng như Word, Excel, PowerPoint một cách thành thạo. Ngoài ra, mình cũng có thể hướng dẫn các bạn bắt đầu với lập trình cơ bản (Python, Scratch). Phương pháp của mình là thực hành nhiều, đi từ dễ đến khó, giúp các bạn tự tin áp dụng kiến thức vào học tập và công việc.', 'Thầy Tùng - Tin học ứng dụng. Nắm vững Excel, Word và lập trình cơ bản.', NULL, 'Kỹ sư Công nghệ Thông tin, trường Đại học FPT.', NULL, NULL, 'Mình có 4 năm kinh nghiệm làm việc trong lĩnh vực phát triển phần mềm và 2 năm kinh nghiệm dạy Tin học văn phòng, lập trình cơ bản. Mình đã giúp nhiều học viên từ không biết gì trở nên thành thạo các kỹ năng này. Mình dạy kèm cá nhân và nhóm.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.1, 13, 273, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-250', 'Xin chào các bạn! Mình là Lan Phương. Nếu bạn đang tìm kiếm một người đồng hành để chinh phục band điểm cao trong IELTS Speaking và Writing, mình rất sẵn lòng. Mình tập trung vào việc xây dựng ý tưởng, cấu trúc bài nói/viết mạch lạc, sử dụng từ vựng và ngữ pháp đa dạng, chính xác. Mình sẽ sửa lỗi chi tiết, đưa ra feedback mang tính xây dựng và hướng dẫn các bạn các chiến thuật làm bài hiệu quả. Chúng ta sẽ cùng nhau luyện tập để bạn ngày càng tự tin hơn!', 'Luyện IELTS Speaking & Writing hiệu quả cùng cô Phương. Tự tin giao tiếp, đạt điểm mơ ước!', NULL, 'Đạt IELTS 7.5 (Speaking 8.0, Writing 7.0), tốt nghiệp ngành Quản trị Kinh doanh.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy IELTS Speaking và Writing. Mình đã giúp nhiều học viên đạt được mục tiêu band điểm của mình, từ 5.5 lên 6.5, 7.0. Mình hiểu rõ những khó khăn mà người học thường gặp phải.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.7, 22, 309, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-251', 'Chào phụ huynh và các em học sinh! Thầy là Văn Duy. Mình hiểu rằng Toán THCS là nền tảng quan trọng cho các cấp học sau. Phương pháp của mình là đi từ lý thuyết đến thực hành, luôn giải thích cặn kẽ các bước làm và dạng bài. Mình đặc biệt chú trọng việc rèn luyện kỹ năng tư duy logic và phương pháp giải toán cho học sinh. Mình luôn kiên nhẫn, lắng nghe và hỗ trợ các em hết mình.', 'Thầy Duy - Toán THCS. Giúp con bạn hiểu sâu, làm chắc bài tập.', NULL, 'Cử nhân Sư phạm Toán học, trường Đại học Sư phạm.', NULL, NULL, 'Mình có 4 năm kinh nghiệm dạy Toán cho học sinh THCS. Mình đã giúp nhiều em cải thiện điểm số và xây dựng sự tự tin với môn Toán. Mình có kinh nghiệm dạy kèm cá nhân và nhóm nhỏ.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.9, 45, 243, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-252', 'Xin chào! Nếu bạn cảm thấy Tiếng Anh như một ngôn ngữ xa lạ và muốn bắt đầu lại từ đầu, mình ở đây để giúp bạn. Mình chuyên dạy cho người mất gốc, xây dựng lại nền tảng ngữ pháp, từ vựng và phát âm một cách bài bản. Mình sử dụng giáo trình phù hợp, nhiều bài tập thực hành và tạo không khí học tập thân thiện để bạn không còn áp lực. Chúng ta sẽ đi từng bước thật vững chắc nhé!', 'Cô Trang - Tiếng Anh cho người mất gốc. Lấy lại căn bản, tự tin giao tiếp.', NULL, 'Cử nhân ngành Ngôn ngữ Anh, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy Tiếng Anh cho người mới bắt đầu và người mất gốc. Mình đã giúp nhiều học viên lấy lại kiến thức cơ bản và có thể giao tiếp những câu đơn giản. Mình ưu tiên dạy kèm 1-1 để sát sao với từng học viên.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.7, 33, 413, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-253', 'Chào các bạn! Thầy là Minh Đức. Nếu bạn đang tìm kiếm sự hỗ trợ để chinh phục Vật Lý ở mức độ nâng cao hoặc luyện thi vào Đại học, thầy có thể giúp bạn. Thầy tập trung vào việc phân tích sâu các chủ đề khó, rèn luyện kỹ năng giải các bài toán phức tạp và chiến thuật làm bài thi hiệu quả. Thầy luôn cập nhật các dạng bài mới và phương pháp giải tối ưu. Chúng ta sẽ cùng nhau chinh phục mục tiêu điểm số cao nhất!', 'Thầy Đức - Vật lý nâng cao & Luyện thi Đại học. Phân tích chuyên sâu, bứt phá điểm số.', NULL, 'Thạc sĩ Vật lý Kỹ thuật, Đại học Bách Khoa.', NULL, NULL, 'Thầy có 6 năm kinh nghiệm dạy Vật Lý luyện thi Đại học. Nhiều học sinh của thầy đạt điểm 9+ trong kỳ thi THPT Quốc gia và đỗ vào các trường top đầu. Thầy có kinh nghiệm dạy lớp lớn và lớp luyện chuyên sâu.', 'Bình Dương', 'Quận 7', 'active', true, 4.6, 16, 62, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-254', 'Xin chào các bạn! Mình là Thuỳ Linh. Hóa học THPT có nhiều phần kiến thức đòi hỏi sự logic và khả năng ghi nhớ. Mình sẽ giúp các bạn hệ thống hóa lại toàn bộ kiến thức theo từng chuyên đề, từ đó xây dựng phương pháp giải bài tập hiệu quả. Mình chú trọng vào việc luyện tập đa dạng các dạng bài từ cơ bản đến nâng cao, giúp các bạn làm quen và thực hành nhuần nhuyễn. Mục tiêu của mình là giúp các bạn tự tin và đạt kết quả tốt nhất.', 'Cô Linh - Hóa học THPT. Hệ thống kiến thức, luyện tập nhuần nhuyễn.', NULL, 'Cử nhân ngành Hóa học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Mình có 3 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Mình đã giúp nhiều bạn cải thiện điểm số và xây dựng sự yêu thích với môn Hóa. Mình có kinh nghiệm dạy theo chương trình sách mới.', 'Bình Dương', 'Quận 1', 'active', true, 4.8, 6, 51, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-255', 'Chào các em! Thầy là Anh Khoa. Văn học là một thế giới đầy màu sắc và cảm xúc. Thầy sẽ giúp các em khám phá vẻ đẹp của các tác phẩm văn học, hiểu rõ hơn về tâm tư, tình cảm của nhân vật. Đồng thời, thầy sẽ hướng dẫn các em cách diễn đạt ý tưởng một cách mạch lạc, sáng tạo và giàu hình ảnh trong bài viết. Thầy luôn tạo môi trường học tập vui vẻ, khuyến khích các em đặt câu hỏi và chia sẻ suy nghĩ.', 'Thầy Khoa - Ngữ văn THCS. Giúp con bạn yêu văn, viết hay.', NULL, 'Cử nhân ngành Sư phạm Ngữ văn, trường Đại học Sư phạm.', NULL, NULL, 'Mình có 4 năm kinh nghiệm dạy Ngữ văn cho học sinh THCS. Mình đã giúp nhiều em cải thiện kỹ năng cảm thụ văn học và viết văn, đạt kết quả tốt trong các bài kiểm tra và thi học kỳ. Mình rất kiên nhẫn và yêu trẻ.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.6, 58, 390, '2026-06-19 02:55:51.922429', '2026-06-19 02:55:51.922429', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-256', 'Mình là Hà, một cô giáo Tiếng Anh yêu trẻ và đầy nhiệt huyết. Mình tin rằng học Tiếng Anh không cần phải khô khan, mà có thể vui vẻ và hiệu quả qua các hoạt động tương tác, trò chơi. Đặc biệt, mình có kinh nghiệm giúp các bạn mất gốc lấy lại căn bản và tự tin giao tiếp.', 'Tiếng Anh giao tiếp - Giúp bạn tự tin nói tiếng Anh như người bản xứ!', NULL, 'Tốt nghiệp Đại học Sư phạm Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho học sinh cấp 2 và cấp 3. Từng là sinh viên trao đổi tại Anh Quốc, giúp mình hiểu sâu sắc về văn hóa và cách sử dụng ngôn ngữ thực tế. Nhiều học sinh của mình đã đạt thành tích cao trong các kỳ thi học sinh giỏi.', 'TP.HCM', 'Ninh Kiều', 'active', true, 5, 28, 403, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-257', 'Chào các bạn, mình là Minh Anh, một cựu học sinh chuyên Toán. Mình có phương pháp giảng dạy logic, bám sát chương trình nhưng luôn tìm cách mở rộng và liên hệ thực tế. Mình hướng tới việc giúp học sinh hiểu sâu bản chất vấn đề, thay vì học thuộc lòng.', 'Toán nâng cao - Khai phá tư duy logic, chinh phục điểm số mơ ước!', NULL, 'Sinh viên năm cuối ngành Toán Tin, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Đã đồng hành cùng hơn 30 học sinh chinh phục Toán học trong 4 năm qua. Kinh nghiệm ôn luyện thi vào lớp 10 chuyên Toán và các trường THPT chất lượng cao. Các bạn học sinh dưới sự hướng dẫn của mình đều có sự tiến bộ rõ rệt về điểm số và tư duy.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.7, 30, 285, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-258', 'Mình là Mai Hương, rất yêu thích văn chương và việc truyền cảm hứng học Văn cho các bạn trẻ. Mình luôn cố gắng làm cho giờ học Văn trở nên sinh động, gần gũi bằng cách liên hệ bài học với cuộc sống hiện đại. Đặc biệt, mình giúp các bạn rèn luyện kỹ năng phân tích đề và viết bài văn mạch lạc, có chiều sâu.', 'Ngữ Văn - Nâng tầm cảm thụ văn học, viết bài văn giàu cảm xúc.', NULL, 'Tốt nghiệp thủ khoa ngành Sư phạm Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy và luyện thi môn Ngữ Văn. Từng là thành viên ban cố vấn cho các CLB Văn học tuổi trẻ. Đã giúp nhiều học sinh cải thiện điểm số từ trung bình lên khá, giỏi, đặc biệt là trong các bài thi tự luận.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.5, 19, 191, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-259', 'Xin chào, mình là Hoàng Nam. Mình có niềm đam mê với Vật lý và muốn chia sẻ niềm đam mê ấy tới các bạn. Phương pháp của mình là lấy ví dụ từ đời sống, giúp các bạn hình dung rõ ràng các khái niệm trừu tượng. Mình tập trung vào việc luyện tập kỹ năng giải bài tập từ cơ bản đến nâng cao.', 'Vật Lý thực tế - Giải thích định luật bằng hiện tượng, thi đâu đỗ đó!', NULL, 'Cựu sinh viên Vật lý Kỹ thuật, Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Gia sư Vật Lý được 6 năm, chuyên luyện thi THPT Quốc gia. Có kinh nghiệm dạy cho cả lớp học nhóm và học 1 kèm 1. Nhiều học sinh của mình đạt điểm cao môn Vật lý trong kỳ thi Đại học.', 'Đồng Nai', 'Quận 7', 'active', true, 4.8, 13, 87, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-260', 'Chào bạn, mình là Kim Chi, một người bạn đồng hành tin cậy trên con đường chinh phục IELTS. Mình hiểu rằng mỗi người có một điểm mạnh, điểm yếu và mục tiêu riêng, vì vậy mình xây dựng lộ trình học tập phù hợp nhất cho từng bạn. Mục tiêu của mình là giúp bạn đạt được band điểm mong muốn một cách hiệu quả và tiết kiệm thời gian.', 'IELTS 7.5+ - Lộ trình cá nhân hóa, cam kết band điểm.', NULL, 'IELTS 8.0, tốt nghiệp ngành Kinh tế Quốc tế, Đại học Ngoại Thương.', NULL, NULL, 'Có 4 năm kinh nghiệm luyện thi IELTS. Từng làm việc cho một trung tâm Anh ngữ uy tín, phụ trách các lớp IELTS từ 5.0 lên 6.5+. Nhiều học viên đạt 7.0, 7.5, thậm chí 8.0 sau khóa học.', 'Hà Nội', 'Quận 3', 'active', true, 4.6, 48, 447, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-261', 'Mình là Tấn Phát, một lập trình viên trẻ đầy nhiệt huyết. Mình yêu thích việc chia sẻ kiến thức Tin học, đặc biệt là lập trình. Mình tin rằng ai cũng có thể học lập trình nếu có phương pháp đúng và sự kiên trì. Mình sẽ hướng dẫn các bạn từ những khái niệm cơ bản nhất, giúp các bạn tự tin xây dựng các dự án đầu tiên của mình.', 'Tin Học căn bản & Lập trình Python - Hướng dẫn từng bước, biến ý tưởng thành code.', NULL, 'Tốt nghiệp ngành Khoa học Máy tính, Đại học Công nghệ Thông tin - ĐHQG TP.HCM.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tin học văn phòng và lập trình Python cho học sinh, sinh viên. Đã hướng dẫn thành công nhiều bạn nhỏ làm quen với Scratch và Arduino. Giúp các bạn sinh viên năm nhất làm quen với lập trình cơ bản.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4.3, 38, 167, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-262', 'Chào bạn, mình là Bích Thủy. Mình có một niềm yêu thích đặc biệt với Hóa học, nhất là những phản ứng thú vị và ứng dụng của nó trong đời sống. Phương pháp dạy của mình là kết hợp lý thuyết với các thí nghiệm minh họa (nếu có thể) và bài tập thực hành đa dạng. Mình sẽ giúp bạn yêu Hóa học hơn!', 'Hóa Học dễ hiểu - Chinh phục bảng tuần hoàn và các phản ứng khó.', NULL, 'Tốt nghiệp ngành Hóa học, Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, 'Đã có 4 năm kinh nghiệm dạy Hóa cho học sinh cấp 3, ôn thi tốt nghiệp và đại học. Thành tích nổi bật là giúp các bạn có kiến thức nền tảng vững chắc và tự tin giải các dạng bài tập từ cơ bản đến nâng cao.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.7, 42, 343, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-263', 'Mình là Quang Huy, một người yêu thiên nhiên và khoa học. Mình tin rằng Sinh học không chỉ là sách vở mà là cả một thế giới kỳ diệu xung quanh ta. Mình muốn truyền tải sự hứng thú đó tới các bạn qua những bài giảng trực quan, sinh động, kết nối kiến thức với thực tế cuộc sống và các vấn đề môi trường.', 'Sinh Học ứng dụng - Khám phá thế giới vi sinh và di truyền học.', NULL, 'Sinh viên năm cuối ngành Công nghệ Sinh học, Học viện Nông nghiệp Việt Nam.', NULL, NULL, 'Có 2 năm kinh nghiệm làm trợ giảng và gia sư môn Sinh học cho học sinh THPT. Đặc biệt có kinh nghiệm ôn luyện cho các bạn thi chuyên Sinh. Giúp các bạn nắm vững kiến thức cốt lõi và phương pháp làm bài thi hiệu quả.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.1, 11, 102, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-264', 'Xin chào, mình là Lan Anh, cô giáo yêu trẻ và tận tâm. Mình tin rằng mỗi em bé đều có khả năng học Toán tuyệt vời. Phương pháp của mình là biến những con số khô khan thành những câu chuyện, trò chơi hấp dẫn, giúp các con hứng thú và không còn sợ Toán. Mình tập trung vào việc xây dựng cho con nền tảng tư duy toán học vững chắc từ những bước đầu tiên.', 'Toán tiểu học - Xây nền tảng vững chắc, khơi dậy niềm vui học Toán.', NULL, 'Tốt nghiệp Cao đẳng Sư phạm Mầm non, chuyên ngành Giáo dục Tiểu học.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Toán cho học sinh tiểu học. Từng làm việc tại một trường tư thục uy tín. Rất mát tay trong việc giúp các con làm quen với các phép tính, hình học và tư duy logic ban đầu.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.7, 33, 442, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-265', 'Chào các bạn, mình là Gia Bảo, một người đam mê Lịch sử. Mình không dạy Lịch sử theo kiểu thuộc lòng dates and names. Thay vào đó, mình muốn kể cho các bạn nghe những câu chuyện, phân tích nguyên nhân - kết quả, và giúp các bạn thấy được sự logic, hấp dẫn của dòng chảy lịch sử. Đặc biệt phù hợp với các bạn thấy môn Sử nhàm chán.', 'Lịch Sử thú vị - Từ sử Việt đến lịch sử thế giới, hiểu quá khứ để tương lai.', NULL, 'Cử nhân ngành Lịch sử, Trường Đại học Khoa học Xã hội và Nhân văn - ĐHQG TP.HCM.', NULL, NULL, 'Có 3 năm kinh nghiệm gia sư Lịch sử cho học sinh THPT. Từng đạt giải Ba học sinh giỏi môn Lịch sử cấp tỉnh. Giúp nhiều học sinh có cái nhìn mới mẻ và điểm số cao hơn.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.5, 58, 117, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-266', 'Hello! Mình là Thảo My, mình có kinh nghiệm làm việc trong môi trường quốc tế nên hiểu rõ tầm quan trọng của Tiếng Anh trong công việc. Mình tập trung vào việc rèn luyện kỹ năng nghe, nói, phản xạ nhanh qua các tình huống thực tế như họp hành, thuyết trình, đàm phán. Mình tin rằng bạn hoàn toàn có thể giao tiếp tiếng Anh trôi chảy.', 'Tiếng Anh giao tiếp cho người đi làm - Tự tin đàm phán, thuyết trình.', NULL, 'Thạc sĩ ngành Quản trị Kinh doanh, từng du học tại Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người lớn và người đi làm. Nhiều học viên của mình đã cải thiện đáng kể khả năng tiếng Anh, giúp họ tự tin hơn trong công việc.', 'Bình Dương', 'Quận 1', 'active', true, 4.7, 62, 230, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-267', 'Chào các em, thầy là Minh Đức. Với kinh nghiệm nhiều năm luyện thi Toán cho học sinh cuối cấp, thầy hiểu rõ những dạng bài hay gặp và cách giải tối ưu nhất. Thầy không chỉ cung cấp kiến thức mà còn rèn luyện kỹ năng làm bài thi, kỹ năng quản lý thời gian để các em tự tin bước vào kỳ thi quan trọng.', 'Toán ôn thi Đại học - Phương pháp giải nhanh, bám sát đề thi Bộ GD&ĐT.', NULL, 'Thủ khoa đầu ra ngành Sư phạm Toán, Đại học Vinh.', NULL, NULL, 'Đã đào tạo và hướng dẫn hơn 1000 học sinh ôn thi Đại học môn Toán với tỷ lệ đỗ nguyện vọng 1 cao. Kinh nghiệm dày dặn với các đề thi thử, đề thi thật qua các năm.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.9, 46, 315, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-268', 'Mình là Kim Ngân, một người yêu thích khám phá thế giới và những câu chuyện đằng sau mỗi vùng đất. Mình muốn mang đến cho các bạn những bài học Địa lý sinh động, dễ nhớ bằng cách sử dụng bản đồ, hình ảnh, video và các hoạt động tương tác. Mình giúp các bạn hiểu sâu về các yếu tố tự nhiên, kinh tế, xã hội và mối liên hệ giữa chúng.', 'Địa Lý trực quan - Khám phá thế giới qua bản đồ và số liệu.', NULL, 'Tốt nghiệp ngành Địa lý học, Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm gia sư Địa lý cho học sinh THPT, ôn thi tốt nghiệp và đại học. Giúp học sinh nắm vững kiến thức lý thuyết và kỹ năng phân tích biểu đồ, bản đồ.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.6, 50, 91, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-269', 'Hello! Mình là Văn Hoàng, mình đã có kinh nghiệm sinh sống và học tập tại nước ngoài. Mình tập trung vào việc giúp các bạn cải thiện kỹ năng Speaking và Writing một cách thực tế nhất. Mình sẽ chỉ cho các bạn cách diễn đạt ý tưởng một cách mạch lạc, sử dụng từ vựng và cấu trúc phù hợp để đạt điểm cao.', 'IELTS Speaking & Writing - Luyện phát âm chuẩn, viết bài học thuật.', NULL, 'IELTS 8.0, tốt nghiệp ngành Kinh tế, Đại học RMIT Việt Nam.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy IELTS, đặc biệt là hai kỹ năng Speaking và Writing. Từng là giám khảo cho các cuộc thi nói tiếng Anh. Giúp nhiều học viên đạt mục tiêu band điểm mong muốn.', 'Biên Hòa', 'Quận 3', 'active', true, 4.2, 27, 415, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-270', 'Xin chào, mình là Thanh Tuyền. Mình rất vui khi được chia sẻ vẻ đẹp của tiếng Việt và văn hóa Việt Nam với bạn bè quốc tế. Phương pháp của mình là tập trung vào giao tiếp thực tế, các bài học về văn hóa, phong tục tập quán. Mình muốn bạn không chỉ nói tiếng Việt mà còn cảm nhận được tâm hồn Việt trong ngôn ngữ.', 'Tiếng Việt cho người nước ngoài - Giao tiếp tự nhiên, hiểu văn hóa Việt.', NULL, 'Tốt nghiệp ngành Ngôn ngữ học, Đại học Hà Nội.', NULL, NULL, 'Có 4 năm kinh nghiệm dạy Tiếng Việt cho người nước ngoài. Đã làm việc với học viên đến từ nhiều quốc gia khác nhau, từ người mới bắt đầu đến trình độ trung cấp.', 'TP.HCM', 'Quận 3', 'active', true, 4.5, 41, 261, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-271', 'Mình là Tuấn Kiệt, một sinh viên Vật lý đầy năng lượng. Mình biết nhiều bạn thấy Vật lý hơi khó nhằn, nhưng đừng lo! Mình sẽ giúp bạn tiếp cận môn học này một cách đơn giản, dễ hiểu nhất qua các ví dụ minh họa gần gũi và phương pháp giải bài tập hiệu quả. Mục tiêu là giúp bạn tự tin vượt qua mọi bài kiểm tra.', 'Vật Lý THPT - Làm chủ công thức, giải bài tập nhanh như chớp.', NULL, 'Sinh viên năm 3 ngành Vật lý Kỹ thuật, Đại học Công nghệ - ĐHQG Hà Nội.', NULL, NULL, 'Gia sư Vật lý cho học sinh THPT được 3 năm. Có kinh nghiệm ôn luyện thi học kỳ và thi tốt nghiệp. Giúp học sinh nắm vững kiến thức và cải thiện kỹ năng làm bài.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.3, 62, 301, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-272', 'Mình là Hồng Vân, một người luôn tò mò về thế giới tự nhiên. Mình tin rằng Sinh học là môn học rất gần gũi và quan trọng với cuộc sống của chúng ta. Mình sẽ giúp các bạn hiểu rõ hơn về các kiến thức cơ bản như tế bào, di truyền, sinh thái qua những bài giảng dễ hiểu, gần gũi và có tính ứng dụng.', 'Sinh học cơ bản - Hiểu về cơ thể, môi trường sống và sự sống.', NULL, 'Cử nhân ngành Sinh học, Trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Có 2 năm kinh nghiệm gia sư môn Sinh học cho học sinh THCS và THPT. Giúp các bạn củng cố kiến thức nền tảng và chuẩn bị tốt cho các kỳ thi.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.8, 11, 418, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-273', 'Chào bạn, mình là Tuấn Dũng. Mình chuyên sâu về các kỹ năng Tin học văn phòng, đặc biệt là Excel. Mình tin rằng việc sử dụng thành thạo các công cụ này sẽ giúp bạn làm việc hiệu quả hơn rất nhiều. Mình có phương pháp giảng dạy thực tế, đi thẳng vào vấn đề và giúp bạn áp dụng ngay vào công việc hoặc học tập.', 'Tin học văn phòng & Excel nâng cao - Tối ưu công việc, làm chủ dữ liệu.', NULL, 'Tốt nghiệp ngành Hệ thống Thông tin Quản lý, Đại học Kinh tế Quốc dân.', NULL, NULL, 'Có 4 năm kinh nghiệm đào tạo Tin học văn phòng cho sinh viên và người đi làm. Đã hướng dẫn hàng trăm người sử dụng Excel thành thạo các hàm, biểu đồ, pivot table để phân tích dữ liệu.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.6, 36, 167, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-274', 'Mình là Mai Phương, một giáo viên mầm non với niềm yêu thích đặc biệt dành cho Toán. Mình tin rằng việc học Toán cần bắt đầu từ sự vui vẻ và khám phá. Mình thiết kế các hoạt động học tập sáng tạo, sử dụng nhiều hình ảnh, đồ chơi để giúp các con làm quen với các khái niệm số đếm, hình khối, đo lường một cách tự nhiên và hào hứng.', 'Toán tư duy cho trẻ mầm non - Khám phá thế giới số qua trò chơi.', NULL, 'Tốt nghiệp Đại học Sư phạm, chuyên ngành Giáo dục Mầm non.', NULL, NULL, 'Có 6 năm kinh nghiệm giảng dạy và làm quen Toán cho trẻ mầm non. Từng làm việc tại các trường quốc tế, có kinh nghiệm áp dụng các phương pháp giáo dục hiện đại.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4, 62, 295, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-275', 'Mình là Hữu Thịnh, mình đã trải qua giai đoạn ôn thi Hóa cấp 3 và hiểu rõ những khó khăn mà các bạn đang gặp phải. Mình tập trung vào việc củng cố kiến thức Hóa học 12, đặc biệt là các chuyên đề quan trọng, và rèn luyện kỹ năng giải nhanh các dạng bài tập trắc nghiệm. Mình cũng hướng dẫn cách trình bày bài tự luận logic, dễ hiểu.', 'Hóa học 12 - Chinh phục bài tập trắc nghiệm và tự luận.', NULL, 'Sinh viên năm 3 ngành Hóa dược, Trường Đại học Dược Hà Nội.', NULL, NULL, 'Gia sư Hóa học cho học sinh lớp 12 trong 3 năm. Giúp các bạn nắm vững kiến thức để đạt điểm cao trong các kỳ thi quan trọng.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 4.9, 33, 122, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-276', 'Xin chào! Mình là Hải Yến, một cô giáo yêu trẻ và luôn mang đến những giờ học Tiếng Anh tràn đầy tiếng cười. Mình sử dụng các bài hát, câu chuyện, trò chơi, hoạt động sáng tạo để các bé tiếp thu ngôn ngữ một cách tự nhiên và hứng thú nhất. Mình muốn xây dựng cho bé tình yêu với Tiếng Anh ngay từ nhỏ.', 'Tiếng Anh cho thiếu nhi - Học mà chơi, chơi mà học.', NULL, 'Tốt nghiệp Cao đẳng Sư phạm Tiếng Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Tiếng Anh cho trẻ em từ 3-10 tuổi. Từng làm việc tại các trung tâm Anh ngữ dành cho thiếu nhi. Các bé học với mình đều rất tự tin và thích thú.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.5, 29, 170, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-277', 'Chào các bạn, mình là Quốc Bảo. Mình có niềm yêu thích đặc biệt với các tác phẩm văn học Việt Nam và thế giới. Mình sẽ giúp các bạn tiếp cận môn Văn một cách có hệ thống, từ việc phân tích sâu sắc các tác phẩm, hiểu ý nghĩa, nghệ thuật cho đến việc rèn luyện kỹ năng viết bài nghị luận văn học ấn tượng và giàu cảm xúc.', 'Ngữ Văn thi THPT - Phân tích tác phẩm, làm chủ kiến thức.', NULL, 'Cử nhân ngành Văn học, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm luyện thi môn Ngữ Văn cho học sinh cuối cấp. Giúp các bạn hệ thống hóa kiến thức, nắm vững phương pháp làm bài và đạt kết quả tốt trong các kỳ thi.', 'Cần Thơ', 'Quận 1', 'active', true, 4.7, 37, 404, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-278', 'Mình là Minh Ngọc, mình có nền tảng Toán học vững vàng và kinh nghiệm giảng dạy cho sinh viên các ngành kỹ thuật, kinh tế. Mình tập trung vào việc giúp các bạn hiểu sâu các khái niệm trừu tượng, nắm vững phương pháp giải các bài toán phức tạp như giải tích, đại số tuyến tính. Mình luôn sẵn sàng giải đáp mọi thắc mắc của các bạn.', 'Toán cao cấp cho sinh viên - Nền tảng vững chắc cho các ngành khoa học.', NULL, 'Thạc sĩ ngành Toán học ứng dụng, Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Có 4 năm kinh nghiệm dạy Toán cao cấp cho sinh viên đại học. Giúp nhiều thế hệ sinh viên vượt qua các môn học khó nhằn và đạt kết quả cao.', 'Cần Thơ', 'Quận 1', 'active', true, 4.9, 48, 448, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-279', 'Hi, mình là Thành Long. Mình đã giúp nhiều bạn đạt mục tiêu IELTS General Training cho việc định cư, du học hoặc làm việc ở nước ngoài. Mình tập trung vào các kỹ năng thực tế cần thiết, cung cấp chiến lược làm bài hiệu quả và luyện tập với đề thi sát với thực tế nhất. Mình tin bạn sẽ làm được!', 'IELTS General Training - Luyện kỹ năng cho mục đích định cư, du học.', NULL, 'IELTS 7.5, tốt nghiệp ngành Du lịch và Lữ hành, Đại học.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy IELTS General Training. Kinh nghiệm làm việc và học tập trong môi trường quốc tế giúp mình hiểu rõ nhu cầu của học viên.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.1, 46, 153, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-280', 'Mình là Lan, mình có phương pháp giảng dạy nhẹ nhàng, dễ hiểu, phù hợp với các bạn mới bắt đầu làm quen với chương trình Vật Lý cấp 3. Mình tập trung vào việc giúp các bạn nắm chắc kiến thức cơ bản, hiểu rõ bản chất của các hiện tượng vật lý và rèn luyện kỹ năng giải bài tập từng bước một.', 'Vật Lý 10 & 11 - Xây dựng kiến thức nền tảng vững chắc.', NULL, 'Cử nhân ngành Sư phạm Vật Lý, Đại học Sư phạm Đà Nẵng.', NULL, NULL, 'Có 2 năm kinh nghiệm gia sư Vật Lý cho học sinh lớp 10 và 11. Giúp các bạn xây dựng nền tảng kiến thức tốt để chuẩn bị cho lớp 12.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.6, 21, 235, '2026-06-19 02:56:24.416449', '2026-06-19 02:56:24.416449', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-31', 'Mình là Minh Anh, một cô giáo trẻ đầy nhiệt huyết với Tiếng Anh. Mình tin rằng học ngoại ngữ là cả một hành trình khám phá đầy thú vị. Phương pháp của mình tập trung vào thực hành giao tiếp qua các hoạt động tương tác, trò chơi và tình huống thực tế. Mình đặc biệt yêu thích làm việc với các bạn học sinh cấp 2, 3 muốn cải thiện khả năng giao tiếp và tự tin hơn trong học tập.', 'Chinh phục Tiếng Anh giao tiếp tự tin cùng cô Anh!', NULL, 'Tốt nghiệp chuyên ngành Sư phạm Tiếng Anh, trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho học sinh THPT. Từng giúp nhiều bạn đạt điểm cao trong các kỳ thi học kỳ và cải thiện đáng kể khả năng phản xạ ngôn ngữ.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.4, 59, 384, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-469', 'Sinh học là môn học về chính chúng ta và thế giới xung quanh. Mình dùng phương pháp giảng dạy trực quan, liên hệ kiến thức với thực tế cuộc sống và các vấn đề môi trường. Giúp bạn thấy Sinh học thật gần gũi và thú vị.', 'Sinh Học thực tế - Khám phá thế giới sống quanh ta.', NULL, 'Cử nhân Sinh học Phân tử, Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học THPT. Giúp học sinh nắm vững kiến thức và cải thiện điểm số. Có kinh nghiệm ôn thi học sinh giỏi và thi THPT Quốc gia.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.5, 6, 339, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-32', 'Chào các em, thầy là Hùng. Toán học không hề khô khan nếu chúng ta biết cách tiếp cận nó một cách khoa học và logic. Thầy luôn cố gắng truyền cảm hứng, giúp các em nhìn thấy vẻ đẹp ẩn sau những con số và công thức. Phương pháp của thầy là xây dựng nền tảng vững chắc, rèn luyện tư duy phản biện và luyện tập chuyên sâu với các dạng bài. Thầy mong được đồng hành cùng các em học sinh từ lớp 6 đến lớp 9.', 'Thầy Hùng - Giải mã Toán học, chinh phục điểm 10!', NULL, 'Thạc sĩ Toán học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Toán tại các trung tâm luyện thi uy tín. Nhiều học sinh của thầy đã đạt thành tích xuất sắc trong các kỳ thi học sinh giỏi cấp quận và thành phố.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.2, 43, 277, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-33', 'Xin chào! Mình là Bích Ngọc, yêu văn chương và tin rằng mỗi bài văn là một câu chuyện, một thế giới để khám phá. Mình sẽ giúp các bạn tiếp cận môn Văn một cách nhẹ nhàng, sáng tạo thông qua việc phân tích tác phẩm, liên hệ thực tế và phát triển kỹ năng viết độc đáo. Mình đặc biệt phù hợp với các bạn học sinh THPT đang tìm kiếm phương pháp học Văn hiệu quả để thi đại học.', 'Cô Ngọc - Khơi nguồn sáng tạo, yêu Văn chương!', NULL, 'Cử nhân Ngữ văn, trường Đại học Sài Gòn.', NULL, NULL, 'Đã có 4 năm kinh nghiệm dạy Ngữ văn, tập trung vào kỹ năng phân tích đề, lập dàn ý và viết bài văn nghị luận sắc bén. Tỷ lệ học sinh đỗ nguyện vọng 1 đại học theo môn Văn của mình luôn ở mức cao.', 'Bình Dương', 'Quận 3', 'active', true, 4.2, 14, 86, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-34', 'Chào các em, thầy Tuấn Kiệt đây. Vật lý là môn học đầy hấp dẫn, nơi chúng ta khám phá những quy luật vận hành của vũ trụ. Thầy sẽ giúp các em nắm vững kiến thức nền tảng, rèn luyện kỹ năng giải bài tập từ cơ bản đến nâng cao bằng phương pháp trực quan, ví dụ thực tế và các thí nghiệm mô phỏng. Thầy rất vui được hỗ trợ các bạn học sinh lớp 10, 11, 12 chinh phục môn Vật lý.', 'Thầy Kiệt - Lý giải Vật lý, bay cao ước mơ khoa học!', NULL, 'Kỹ sư Vật lý Kỹ thuật, trường Đại học Bách Khoa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm gia sư Vật lý cho học sinh cuối cấp. Giúp các em nắm chắc lý thuyết và phương pháp giải nhanh các dạng bài tập trắc nghiệm, tự luận.', 'Biên Hòa', 'Quận 1', 'active', true, 4.7, 62, 180, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-35', 'Hi there! Mình là Thu Trang, một người đam mê IELTS và đã chinh phục band điểm 8.0. Mình hiểu rõ những khó khăn khi ôn luyện cho kỳ thi này. Phương pháp học của mình đề cao sự cá nhân hóa, tập trung vào việc xây dựng chiến lược làm bài hiệu quả cho từng kỹ năng (Reading, Listening, Speaking, Writing) và luyện tập với đề thi thật. Mình rất mong được đồng hành cùng các bạn đặt mục tiêu điểm IELTS cao.', 'IELTS 8.0 - Chinh phục mục tiêu điểm số cùng cô Trang!', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Ngoại Thương.', NULL, NULL, 'Có kinh nghiệm 3 năm luyện thi IELTS cho sinh viên và người đi làm. Giúp nhiều học viên đạt được band điểm mong muốn, từ 6.5 đến 7.5+, phục vụ cho mục đích du học và công việc.', 'Cần Thơ', 'Hoàng Mai', 'active', true, 4.4, 39, 409, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-36', 'Chào các bạn, mình là Minh Khang. Nếu bạn đang muốn tìm hiểu về thế giới lập trình, xây dựng website hay ứng dụng, mình sẵn sàng chia sẻ kiến thức và kinh nghiệm. Phương pháp của mình là "học đi đôi với hành", luôn khuyến khích các bạn tự tay code, sửa lỗi và sáng tạo. Mình phù hợp với các bạn trẻ yêu thích công nghệ, muốn học lập trình từ cơ bản hoặc nâng cao.', 'Thầy Khang - Lập trình từ A-Z, bứt phá cùng Tin học!', NULL, 'Sinh viên năm cuối ngành Khoa học Máy tính, trường Đại học Công nghệ.', NULL, NULL, 'Từng tham gia nhiều dự án phát triển phần mềm trong và ngoài trường. Có kinh nghiệm hướng dẫn các bạn mới bắt đầu với Python và Web Development.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.9, 56, 206, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-37', 'Xin chào các em, mình là Thảo Vy! Sinh học là một môn học vô cùng thú vị, giúp chúng ta hiểu rõ hơn về cuộc sống xung quanh. Mình sẽ giúp các em tiếp cận kiến thức Sinh học một cách trực quan, sinh động qua sơ đồ tư duy, hình ảnh minh họa và các ví dụ gần gũi. Mình tin rằng với phương pháp phù hợp, các em sẽ yêu thích môn học này hơn.', 'Cô Vy - Khám phá thế giới Sinh học diệu kỳ!', NULL, 'Sinh viên ngành Sinh học Ứng dụng, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Tích cực tham gia các hoạt động nghiên cứu khoa học trong trường. Có kinh nghiệm hỗ trợ các em học sinh THPT ôn tập kiến thức Sinh học để chuẩn bị cho các kỳ thi.', 'Bình Dương', 'Quận 3', 'active', true, 4, 29, 444, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-38', 'Xin chào! Thầy là Quang Huy. Hóa học không chỉ là những phương trình phản ứng khô khan mà còn là chìa khóa để hiểu biết về thế giới vật chất. Phương pháp dạy của thầy là kết hợp lý thuyết với các thí nghiệm, ví dụ ứng dụng thực tế để các em dễ hình dung và ghi nhớ. Thầy mong muốn giúp các bạn học sinh lớp 9, 10, 11 cảm thấy môn Hóa học trở nên gần gũi và thú vị hơn.', 'Thầy Huy - Hóa học thực tiễn, ứng dụng cuộc sống!', NULL, 'Kỹ sư Hóa học, trường Đại học Bách Khoa TP. Hồ Chí Minh.', NULL, NULL, 'Có 2 năm kinh nghiệm làm gia sư Hóa học, tập trung vào việc đơn giản hóa các khái niệm khó và rèn luyện kỹ năng giải bài tập định lượng.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.4, 7, 209, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-39', 'Hello everyone! Mình là Mai Lan, một người yêu thích Tiếng Anh và mong muốn lan tỏa niềm yêu thích đó đến các bạn. Mình tin rằng học Tiếng Anh là một hành trình khám phá, không áp lực. Phương pháp của mình thiên về sự tương tác, luyện nghe nói thường xuyên qua các hoạt động vui nhộn và sử dụng Tiếng Anh trong các tình huống đời sống. Phù hợp cho mọi lứa tuổi muốn cải thiện khả năng giao tiếp.', 'Tiếng Anh giao tiếp tự tin - Cô Lan luôn đồng hành!', NULL, 'Chuyên ngành Ngôn ngữ Anh, trường Đại học Kinh tế Quốc dân.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người mất gốc và người đi làm. Giúp học viên tự tin hơn khi giao tiếp trong công việc và cuộc sống hàng ngày.', 'Đồng Nai', 'Quận 3', 'active', true, 5, 9, 70, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-40', 'Chào các em, thầy Nam đây! Thầy tin rằng mỗi bạn đều có khả năng tư duy toán học tuyệt vời. Thay vì chỉ học thuộc công thức, thầy tập trung vào việc rèn luyện cho các em cách suy luận, phân tích và tìm ra lời giải một cách thông minh. Phương pháp của thầy là đặt câu hỏi gợi mở, sử dụng các bài toán thực tế và xây dựng sự tự tin cho học sinh. Thầy sẽ là người bạn đồng hành tuyệt vời cho các em từ cấp 1 đến cấp 3.', 'Toán tư duy - Thầy Nam, khai mở tiềm năng toán học!', NULL, 'Cử nhân Toán học, trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Toán theo hướng tư duy và phát triển kỹ năng giải quyết vấn đề. Giúp nhiều học sinh cải thiện kết quả học tập và phát triển tình yêu với môn Toán.', 'Cần Thơ', 'Quận 3', 'active', true, 5, 21, 131, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-41', 'Xin chào! Mình là Thu Hà. Nhiều bạn thấy Lịch sử khô khan và khó nhớ, nhưng mình tin rằng đằng sau mỗi sự kiện đều là những câu chuyện hấp dẫn, ý nghĩa. Mình sẽ giúp các bạn tiếp cận Lịch sử bằng cách kể chuyện, liên hệ với hiện tại và sử dụng các phương pháp ghi nhớ khoa học. Mình rất vui được hỗ trợ các bạn học sinh THCS và THPT tìm thấy niềm vui trong môn học này.', 'Lịch sử không nhàm chán - Cô Hà giúp bạn yêu Sử!', NULL, 'Cử nhân Lịch sử, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch sử. Chú trọng phương pháp giảng dạy sinh động, giúp học sinh hiểu bản chất sự kiện và ghi nhớ kiến thức hiệu quả, đặc biệt cho các kỳ thi quan trọng.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.6, 61, 397, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-42', 'Hey! Mình là Gia Bảo, IELTS 7.5, chuyên trị mảng Speaking và Writing. Mình hiểu rằng nhiều bạn gặp khó khăn trong việc diễn đạt ý tưởng một cách mạch lạc và học thuật. Phương pháp của mình là "practice makes perfect" kết hợp với "smart work" - tập trung vào các chiến lược thông minh, từ vựng nâng cao và cấu trúc câu phức tạp. Cùng mình chinh phục mục tiêu IELTS nhé!', 'IELTS Speaking & Writing - Thầy Bảo, bật "idea"!', NULL, 'Sinh viên ngành Kinh tế đối ngoại, Đại học Ngoại Thương.', NULL, NULL, 'Kinh nghiệm 2 năm luyện thi IELTS, đặc biệt là Speaking và Writing. Giúp học viên nâng band điểm nhanh chóng nhờ các mẹo làm bài hiệu quả và luyện tập cường độ cao.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.9, 32, 242, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-43', 'Chào các con, cô là Thu Trang. Cô yêu trẻ nhỏ và yêu môn Toán. Cô tin rằng việc học Toán từ nhỏ cần sự kiên nhẫn, vui vẻ và khám phá. Phương pháp của cô là sử dụng hình ảnh trực quan, trò chơi học tập và các ví dụ gần gũi với thế giới của các con để các con không còn sợ Toán nữa. Cô rất vui được giúp các con lớp 1, 2, 3, 4, 5 yêu Toán và học tốt Toán.', 'Toán cấp 1 - Cô Trang, xây nền tảng vững chắc!', NULL, 'Cử nhân Giáo dục Tiểu học, trường Đại học Giáo dục.', NULL, NULL, '4 năm kinh nghiệm dạy Toán cho học sinh tiểu học. Giúp các em nắm vững kiến thức cơ bản, hình thành tư duy logic và có nền tảng tốt cho các cấp học tiếp theo.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.5, 11, 102, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-44', 'Chào các bạn, mình là Minh Tuấn. Mình có niềm đam mê lớn với Văn học và mong muốn chia sẻ sự thú vị của nó với các bạn. Phương pháp của mình là đi sâu vào phân tích tâm lý nhân vật, ý nghĩa biểu tượng và khám phá các trường phái văn học. Mình sẽ giúp các bạn không chỉ học thuộc mà còn "cảm" được tác phẩm. Mình đặc biệt phù hợp với các bạn học sinh cấp 3 muốn nâng cao kỹ năng phân tích và cảm thụ văn học.', 'Thầy Tuấn - Giải nghĩa Văn chương, bay bổng cảm xúc!', NULL, 'Thạc sĩ Văn học Việt Nam, trường Đại học Văn hóa.', NULL, NULL, '3 năm kinh nghiệm giảng dạy Ngữ văn, tập trung vào các tác phẩm văn học Việt Nam hiện đại và cổ điển. Giúp học sinh phát triển khả năng bình giảng và viết văn nghị luận văn học.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.9, 13, 283, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-45', 'Xin chào! Mình là Thanh Mai, một người yêu thích Vật lý và luôn tìm cách làm cho môn học này trở nên gần gũi hơn. Mình áp dụng phương pháp giảng dạy trực quan, sử dụng nhiều hình ảnh, video minh họa và các ví dụ thực tế. Mình cũng thường xuyên đặt câu hỏi để khơi gợi tư duy phản biện cho học sinh. Mình mong muốn giúp các bạn học sinh THPT chinh phục thành công môn Vật lý.', 'Cô Mai - Vật lý thực hành, dễ hiểu, dễ nhớ!', NULL, 'Cử nhân Vật lý Đại cương, trường Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm gia sư Vật lý, giúp học sinh nắm vững các khái niệm vật lý khó, rèn luyện kỹ năng giải bài tập và chuẩn bị tốt cho các kỳ thi.', 'Cần Thơ', 'Hải Châu', 'active', true, 4.7, 61, 175, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-46', 'Chào các bạn, mình là Tấn Phát. Nếu bạn đang cần cải thiện kỹ năng Tin học văn phòng (Word, Excel, PowerPoint) để phục vụ công việc hay học tập, hoặc muốn bắt đầu làm quen với lập trình (ví dụ Python), mình đều có thể hỗ trợ. Phương pháp của mình là thực hành nhiều, đi thẳng vào vấn đề và giải đáp mọi thắc mắc của bạn một cách dễ hiểu nhất. Cùng nhau làm chủ công nghệ nào!', 'Tin học văn phòng & Lập trình cơ bản - Thầy Phát!', NULL, 'Cử nhân Công nghệ Thông tin, trường Đại học FPT.', NULL, NULL, '1 năm kinh nghiệm làm việc trong ngành IT và kiêm gia sư Tin học. Đã hướng dẫn nhiều người làm quen và thành thạo các kỹ năng Tin học cơ bản.', 'Biên Hòa', 'Thủ Đức', 'active', true, 4.4, 22, 97, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-47', 'Xin chào các em! Địa lý là một môn học vô cùng sống động, giúp chúng ta hiểu về Trái Đất và con người. Mình sẽ giúp các em học Địa lý một cách hứng thú thông qua các bản đồ, hình ảnh, video và các câu chuyện thực tế. Phương pháp của mình là kết nối kiến thức với cuộc sống hàng ngày, giúp các em không chỉ học thuộc mà còn hiểu sâu và nhớ lâu. Phù hợp với học sinh THCS và THPT.', 'Địa lý thú vị - Cô Dung, mở rộng thế giới quan!', NULL, 'Cử nhân Địa lý học, trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý, tập trung vào việc giúp học sinh nắm vững kiến thức, hiểu bản đồ và liên hệ các hiện tượng địa lý với thực tế.', 'Đồng Nai', 'Quận 1', 'active', true, 4.8, 21, 450, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-48', 'Chào các em, thầy là Công Sơn. Sinh học không chỉ có trong sách vở mà còn hiện hữu xung quanh ta. Thầy sẽ giúp các em khám phá thế giới sinh vật qua các ví dụ thực tế, hình ảnh sinh động và các kiến thức ứng dụng. Phương pháp của thầy là xây dựng sự tò mò, khuyến khích đặt câu hỏi và tìm hiểu sâu. Thầy mong được đồng hành cùng các em học sinh THPT để yêu thích và học tốt môn Sinh học.', 'Thầy Sơn - Sinh học ứng dụng, khám phá muôn loài!', NULL, 'Thạc sĩ Sinh học Phân tử, trường Đại học Y Dược.', NULL, NULL, '2 năm kinh nghiệm giảng dạy Sinh học, đặc biệt là các chuyên đề về Di truyền và Sinh học Phân tử cho học sinh THPT.', 'Cần Thơ', 'Hoàng Mai', 'active', true, 4.4, 17, 385, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-49', 'Hello! Mình là Kim Ngân, mình tin rằng Hóa học hoàn toàn có thể học một cách nhẹ nhàng và hiệu quả. Phương pháp của mình là chia nhỏ kiến thức, tập trung vào việc xây dựng nền tảng vững chắc và rèn luyện kỹ năng giải các dạng bài tập từ cơ bản đến nâng cao. Mình sẽ giúp các bạn học sinh lớp 10, 11, 12 cảm thấy tự tin hơn khi đối mặt với Hóa học.', 'Hóa học dễ học - Cô Ngân, chinh phục các dạng bài tập!', NULL, 'Cử nhân Hóa dược, trường Đại học Dược Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học, đặc biệt là Hóa học Vô cơ và Hữu cơ. Giúp học sinh nắm vững phương pháp giải bài tập và đạt kết quả cao trong các kỳ thi.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.2, 19, 349, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-50', 'Xin chào các em, thầy là Đức Duy. Thầy chuyên sâu vào Toán học dành cho học sinh lớp 10, 11, 12, đặc biệt là luyện thi THPT Quốc gia. Phương pháp của thầy là bám sát chương trình, phân tích kỹ các dạng toán trọng tâm, cung cấp hệ thống bài tập từ dễ đến khó và hướng dẫn phương pháp làm bài thi khoa học, tiết kiệm thời gian. Mục tiêu là giúp các em đạt điểm tối đa.', 'Toán lớp 10-12 - Thầy Duy, ôn thi hiệu quả!', NULL, 'Cử nhân Sư phạm Toán học, trường Đại học Sư phạm TP. Hồ Chí Minh.', NULL, NULL, '4 năm kinh nghiệm dạy Toán ôn thi đại học. Tỷ lệ học sinh của thầy đỗ nguyện vọng 1 với điểm Toán cao luôn đạt trên 90%.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.5, 24, 95, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-51', 'Hi! Mình là Yến Nhi. Nếu bạn mới bắt đầu học Tiếng Anh hoặc muốn cải thiện phát âm và sự tự tin khi nói, mình sẽ là người bạn đồng hành tuyệt vời. Phương pháp của mình tập trung vào việc xây dựng lại nền tảng ngữ âm, ngữ pháp cơ bản và luyện tập giao tiếp theo chủ đề. Mình tạo môi trường học thoải mái, khuyến khích học viên chủ động tham gia.', 'Tiếng Anh nền tảng - Cô Nhi, phát âm chuẩn, tự tin nói!', NULL, 'Cử nhân Ngôn ngữ Anh, trường Đại học Mở.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh cho người mới bắt đầu và học viên mất gốc. Giúp học viên xây dựng sự tự tin và phát âm chuẩn xác.', 'Cần Thơ', 'Hoàng Mai', 'active', true, 4.6, 57, 206, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-52', 'Chào các em, thầy là Văn Tùng. Thầy hiểu rằng Vật lý có thể là một thử thách đối với nhiều bạn. Thầy sẽ giúp các em vượt qua khó khăn đó bằng cách giảng giải lý thuyết một cách cô đọng, dễ hiểu và kết hợp với nhiều ví dụ thực tế, thí nghiệm minh họa. Mục tiêu của thầy là giúp các em nắm vững kiến thức và áp dụng tốt vào giải bài tập.', 'Vật lý THCS & THPT - Thầy Tùng, lý thuyết đi đôi thực hành!', NULL, 'Cử nhân Sư phạm Vật lý, trường Đại học Vinh.', NULL, NULL, '3 năm kinh nghiệm giảng dạy và gia sư Vật lý. Có khả năng truyền đạt kiến thức phức tạp một cách đơn giản và hiệu quả cho học sinh THCS và THPT.', 'Hà Nội', 'Quận 3', 'active', true, 4.4, 6, 100, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-53', 'Chào các bạn, mình là Thu Hương. Mình yêu thích việc khám phá chiều sâu tâm hồn con người qua từng câu chữ. Mình sẽ giúp các bạn học Văn không chỉ để thi cử mà còn để cảm nhận và yêu hơn văn học. Phương pháp của mình là phân tích tác phẩm dưới nhiều góc độ, liên hệ với đời sống và bồi dưỡng cảm xúc thẩm mỹ. Mình rất vui được đồng hành cùng các bạn lớp 10, 11, 12.', 'Văn lớp 10-12 - Cô Hương, cảm thụ văn chương tinh tế!', NULL, 'Thạc sĩ Văn học Ứng dụng, trường Đại học Văn hóa Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Văn cho học sinh cuối cấp, tập trung vào các tác phẩm văn học Việt Nam. Giúp học sinh phát triển khả năng cảm thụ và bình luận tác phẩm.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.3, 42, 328, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-54', 'Hello! Mình là Minh Đức, sẵn sàng giúp bạn chinh phục IELTS ở cả hai dạng General Training và Academic. Mình sẽ tập trung vào việc xây dựng từ vựng, ngữ pháp và các kỹ năng làm bài thi hiệu quả. Phương pháp của mình là thực hành thường xuyên với các dạng đề đa dạng và đưa ra phản hồi chi tiết để bạn tiến bộ nhanh chóng. Let''s get your target score!', 'IELTS General Training & Academic - Thầy Đức!', NULL, 'IELTS 8.0, Cử nhân Quản trị Kinh doanh, Đại học RMIT.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS, giúp nhiều học viên đạt được band điểm mong muốn cho mục đích học tập và định cư.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.5, 50, 193, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-55', 'Xin chào các bạn nhỏ! Cô là Gia Hân, một người yêu trẻ và yêu Toán. Cô tin rằng học Toán có thể rất vui và thú vị. Cô sẽ dùng các trò chơi, câu đố và những câu chuyện hấp dẫn để giúp các con tiếp cận Toán học một cách tự nhiên nhất. Mục tiêu của cô là giúp các con lớp 1-5 yêu thích việc học và xây dựng nền tảng Toán học vững chắc.', 'Toán tư duy - Cô Hân, vui học, giỏi Toán!', NULL, 'Cử nhân Sư phạm Toán học, trường Đại học Sài Gòn.', NULL, NULL, '3 năm kinh nghiệm dạy Toán cho học sinh tiểu học theo phương pháp tư duy và khám phá. Giúp các em có hứng thú học tập và đạt kết quả tốt.', 'Đồng Nai', 'Quận 7', 'active', true, 4.6, 54, 158, '2026-06-19 02:56:36.30847', '2026-06-19 02:56:36.30847', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-281', 'Chào các em, mình là Minh Anh. Mình thích biến những con số khô khan thành những câu chuyện thú vị. Phương pháp của mình là đi từ gốc rễ vấn đề, giúp các em hiểu sâu thay vì học thuộc lòng. Mình vui tính, kiên nhẫn và luôn sẵn sàng giải đáp mọi thắc mắc của các em.', 'Gia sư Toán Lý chuyên Toán nâng cao, giúp học sinh giỏi toàn diện.', NULL, 'Sinh viên năm 3, ngành Sư phạm Toán, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Toán và Lý cho học sinh cấp 2, 3. Từng giúp nhiều học sinh cải thiện điểm số từ trung bình lên khá, giỏi. Nhiều em đạt điểm cao trong các kỳ thi khảo sát đầu năm và cuối năm.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.6, 7, 343, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-282', 'Xin chào! Mình là Thu Trang. Mình tin rằng học Tiếng Anh là một hành trình khám phá thú vị. Mình tập trung vào việc xây dựng sự tự tin cho người học qua các hoạt động tương tác, trò chơi và tình huống thực tế. Mình kiên nhẫn, nhiệt tình và luôn tạo môi trường học tập thoải mái, vui vẻ.', 'Tiếng Anh giao tiếp tự tin cho mọi lứa tuổi, phương pháp học hiệu quả.', NULL, 'Cử nhân ngành Ngôn ngữ Anh, Đại học Ngoại ngữ Quốc gia Hà Nội.', NULL, NULL, 'Hơn 4 năm kinh nghiệm dạy Tiếng Anh cho người mất gốc, học sinh phổ thông và người đi làm. Đã giúp nhiều học viên chinh phục thành công các kỳ thi chứng chỉ A, B. Mở các lớp giao tiếp nhỏ, hiệu quả tại nhà.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4.8, 65, 376, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-283', 'Chào các bạn, mình là Hoàng Nam. Vật Lý không hề khó nếu chúng ta có cách tiếp cận đúng. Mình sẽ cùng các bạn xây dựng nền tảng vững chắc, rèn luyện kỹ năng giải bài tập từ dễ đến khó. Mình có kinh nghiệm giảng dạy và luôn cố gắng truyền cảm hứng học tập cho học sinh.', 'Chinh phục Vật Lý lớp 10-12, phương pháp tư duy logic, điểm cao.', NULL, 'Cựu học sinh chuyên Lý trường THPT chuyên Hà Nội - Amsterdam.', NULL, NULL, 'Dạy kèm Vật Lý cho học sinh cấp 3 được 5 năm. Giúp các em nắm vững kiến thức sách giáo khoa và các dạng bài thi quan trọng. Nhiều học sinh của mình đã đạt điểm 8, 9 trong các bài kiểm tra.', 'Biên Hòa', 'Quận 1', 'active', true, 5, 41, 422, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-284', 'Chào em, chị là Bích Ngọc. Văn học là thế giới diệu kỳ, chị muốn cùng các em khám phá vẻ đẹp của ngôn từ. Phương pháp của chị là phân tích sâu tác phẩm, hướng dẫn cách cảm thụ và diễn đạt. Chị tỉ mỉ, tận tâm và mong muốn giúp các em yêu thích môn Văn hơn.', 'Gia sư Ngữ văn THPT, bồi dưỡng cảm thụ văn chương, thi tốt.', NULL, 'Sinh viên năm 4, ngành Sư phạm Ngữ văn, Đại học Sư phạm TP. Hồ Chí Minh.', NULL, NULL, '4 năm kinh nghiệm dạy Ngữ văn THCS và THPT. Tập trung vào việc rèn luyện kỹ năng làm văn nghị luận, phân tích. Hỗ trợ ôn thi học sinh giỏi và thi vào lớp 10.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.4, 36, 415, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-285', 'Xin chào, mình là Gia Bảo. Mình yêu thích công nghệ và muốn chia sẻ kiến thức Tin học một cách dễ hiểu nhất. Mình chuyên dạy các kỹ năng Tin học văn phòng, lập trình Scratch, Python cơ bản. Phương pháp thực hành là chính, đảm bảo học viên có thể ứng dụng ngay.', 'Tin học văn phòng & Lập trình cơ bản cho mọi trình độ, nhanh chóng.', NULL, 'Kỹ sư Công nghệ Thông tin, Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học cho học sinh, sinh viên và người đi làm. Đã hướng dẫn hàng trăm học viên thành thạo Word, Excel, PowerPoint. Tổ chức các khóa học lập trình cơ bản cho thiếu nhi.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.5, 24, 399, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-286', 'Hello! Mình là Mai. Mình đã trải qua hành trình chinh phục IELTS và hiểu rõ những khó khăn các bạn đang gặp phải. Mình sẽ cùng bạn xây dựng lộ trình học tập hiệu quả, tập trung vào 4 kỹ năng nghe, nói, đọc, viết. Sự kiên trì và phương pháp phù hợp sẽ giúp bạn đạt điểm số mong muốn.', 'IELTS 7.5+, lộ trình cá nhân hóa, cam kết tiến bộ.', NULL, 'Thạc sĩ Ngôn ngữ Anh, chuyên ngành TESOL, Đại học City, Anh Quốc.', NULL, NULL, 'Gia sư luyện thi IELTS online và offline với 5 năm kinh nghiệm. Giúp nhiều học viên đạt IELTS 6.0, 6.5, 7.0+. Chuyên luyện thi cho từng kỹ năng và toàn bộ bài thi.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.6, 37, 230, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-287', 'Chào các con và bố mẹ, con là Minh Tuấn. Con thích học Toán và muốn lan tỏa niềm vui học Toán đến các bạn nhỏ. Con sử dụng các trò chơi, bài toán thực tế để việc học trở nên hấp dẫn. Con kiên nhẫn, yêu trẻ và luôn cố gắng tạo không khí học tập tích cực.', 'Toán tư duy cho trẻ tiểu học và THCS, phương pháp vui nhộn, hiệu quả.', NULL, 'Sinh viên năm 2, ngành Khoa học máy tính, Đại học Bách khoa Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Toán cho học sinh tiểu học và THCS. Tập trung vào việc phát triển tư duy logic, khả năng giải quyết vấn đề. Nhiều em đã tiến bộ rõ rệt về kỹ năng làm bài.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.9, 43, 129, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-288', 'Xin chào các bé và bố mẹ! Em là Thúy Quỳnh, em yêu trẻ con và thích dạy Tiếng Anh. Em xây dựng các bài học qua bài hát, câu chuyện, hoạt động vận động để các bé tiếp thu ngôn ngữ một cách tự nhiên nhất. Em luôn tạo không khí vui vẻ, hứng khởi để các con không sợ Tiếng Anh.', 'Tiếng Anh thiếu nhi, phát âm chuẩn, phản xạ nhanh, môi trường học vui.', NULL, 'Cử nhân Sư phạm Tiếng Anh, Đại học Sài Gòn.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho trẻ em từ 3-10 tuổi. Tập trung vào phát triển kỹ năng nghe, nói cơ bản và làm quen với mặt chữ. Đã tổ chức thành công các lớp học theo chủ đề.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.3, 63, 298, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-289', 'Chào các bạn, mình là Huy Hoàng. Hóa Học có thể rất thú vị nếu bạn hiểu bản chất của các phản ứng. Mình sẽ giúp các bạn nắm vững lý thuyết, thực hành giải các dạng bài tập từ dễ đến khó, đặc biệt là các câu hỏi vận dụng cao. Mình nghiêm túc, khoa học và luôn hướng tới kết quả tốt nhất cho học viên.', 'Hóa Học từ cơ bản đến nâng cao, ôn thi hiệu quả, giải bài tập khó.', NULL, 'Thạc sĩ Hóa học Vô cơ, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Từng là trợ giảng tại các trung tâm luyện thi. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi quan trọng.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.6, 19, 371, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-290', 'Chào các em, chị là Thu Hà. Chị tin rằng văn học giúp chúng ta hiểu sâu sắc hơn về cuộc sống và con người. Chị tập trung vào việc rèn luyện kỹ năng đọc hiểu văn bản, phân tích tác phẩm và đặc biệt là cách viết bài văn mạch lạc, thuyết phục. Chị rất mong được đồng hành cùng các em.', 'Ngữ văn THCS & THPT, nâng cao kỹ năng đọc hiểu và viết luận.', NULL, 'Cử nhân Ngữ văn, Đại học Văn hóa Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Ngữ văn cho học sinh cấp 2 và cấp 3. Giúp các em xây dựng được kiến thức nền tảng và cải thiện kỹ năng làm bài kiểm tra, thi cử.', 'Cần Thơ', 'Quận 1', 'active', true, 4.7, 45, 434, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-291', 'Chào các bạn sinh viên, mình là Văn Bình. Toán cao cấp thường gây khó khăn cho nhiều bạn, nhưng với phương pháp giảng dạy trực quan, mình sẽ giúp các bạn hiểu rõ bản chất từng khái niệm. Mình tập trung vào việc luyện tập các dạng bài tập thường gặp trong đề thi.', 'Toán cao cấp cho sinh viên các ngành kỹ thuật, giải bài tập sát đề.', NULL, 'Kỹ sư Xây dựng, Đại học Xây dựng.', NULL, NULL, 'Dạy Toán cao cấp cho sinh viên các trường đại học kỹ thuật được 4 năm. Nhiều sinh viên đã vượt qua môn học một cách dễ dàng nhờ sự hỗ trợ của mình.', 'Bình Dương', 'Quận 7', 'active', true, 4.1, 31, 141, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-292', 'Hello everyone! Mình là Mỹ Linh. Mình có kinh nghiệm dạy Tiếng Anh cho nhiều đối tượng, đặc biệt là các bạn muốn đạt chứng chỉ Cambridge. Mình sẽ giúp các bạn ôn luyện toàn diện 4 kỹ năng, cung cấp các mẹo làm bài hiệu quả và tăng cường sự tự tin khi giao tiếp.', 'Tiếng Anh giao tiếp chuyên sâu, luyện thi chứng chỉ Cambridge (KET, PET, FCE).', NULL, 'Cử nhân Anh ngữ Thương mại, Đại học Kinh tế Quốc dân.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh, tập trung vào các lớp giao tiếp và luyện thi chứng chỉ. Đã giúp nhiều học sinh đạt điểm cao trong các kỳ thi KET, PET, FCE.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.8, 65, 388, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-293', 'Chào các em, mình là Tuấn Dũng. Mình thích Vật Lý và muốn chia sẻ niềm yêu thích đó. Mình sẽ giúp các em tiếp cận kiến thức một cách logic, dễ hiểu nhất. Mình sẽ tập trung vào việc củng cố kiến thức trên lớp và luyện tập các bài tập cơ bản.', 'Gia sư Vật Lý THPT, phương pháp dễ hiểu, bám sát chương trình.', NULL, 'Sinh viên năm 3, ngành Kỹ thuật Hạt nhân, Học viện Kỹ thuật Quân sự.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Vật Lý cho học sinh lớp 10-12. Chủ yếu hỗ trợ các em củng cố kiến thức và cải thiện điểm số trên lớp.', 'Biên Hòa', 'Quận 7', 'active', true, 4.2, 29, 211, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-294', 'Chào các em, chị là Lan Anh. Sinh học là môn học thú vị về thế giới tự nhiên. Chị sẽ giúp các em hiểu rõ các khái niệm phức tạp, từ cấu trúc tế bào đến di truyền học. Phương pháp của chị là kết hợp hình ảnh, sơ đồ tư duy và các ví dụ thực tế.', 'Sinh học THPT, giải thích khái niệm khó, luyện thi hiệu quả.', NULL, 'Cử nhân Sinh học, Đại học Khoa học Tự nhiên - Đại học Quốc gia TP. Hồ Chí Minh.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học cho học sinh THPT. Tập trung vào các chuyên đề quan trọng và giúp các em làm quen với các dạng bài thi trắc nghiệm.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.7, 28, 446, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-295', 'Chào các bạn, mình là Minh Khôi. Mình tin rằng Lịch sử không chỉ là những con số và sự kiện, mà là những câu chuyện đầy cảm hứng. Mình sẽ giúp các bạn học Lịch sử một cách sinh động, dễ nhớ bằng cách liên hệ với thực tế và sử dụng các phương pháp ghi nhớ hiệu quả.', 'Lịch sử THPT - Khơi gợi sự hứng thú, ghi nhớ kiến thức dễ dàng.', NULL, 'Sinh viên năm 3, ngành Quan hệ Quốc tế, Học viện Ngoại giao.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch sử cho học sinh cấp 3. Tập trung vào việc giúp học sinh có cái nhìn tổng quan và nhớ các mốc thời gian, sự kiện quan trọng.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.5, 49, 284, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-296', 'Xin chào, mình là Hoàng Yến. Địa lý giúp chúng ta hiểu thêm về thế giới xung quanh. Mình sẽ cùng các bạn khám phá các kiến thức về tự nhiên, dân cư, kinh tế. Mình chú trọng rèn luyện kỹ năng đọc bản đồ, biểu đồ và liên hệ kiến thức với các vấn đề thời sự.', 'Địa lý từ cơ bản đến nâng cao, kỹ năng đọc bản đồ, liên hệ thực tế.', NULL, 'Cử nhân Địa lý học, Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia TP. Hồ Chí Minh.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý cho học sinh THCS và THPT. Giúp các em nắm vững kiến thức sách giáo khoa và cải thiện kỹ năng làm bài thi.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4.3, 5, 417, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-297', 'Hi! Mình là Gia Huy. Mình đã đạt IELTS 8.0 và có kinh nghiệm chia sẻ những bí quyết để cải thiện điểm Writing và Speaking. Mình tập trung vào việc xây dựng cấu trúc bài viết, phát triển ý tưởng và luyện tập các tình huống giao tiếp. Mình vui vẻ, nhiệt tình và luôn khuyến khích học viên nói nhiều hơn.', 'IELTS Writing & Speaking - Bí quyết đạt điểm cao, tự tin thể hiện.', NULL, 'Cử nhân Kinh tế đối ngoại, Đại học Ngoại thương.', NULL, NULL, '4 năm kinh nghiệm luyện thi IELTS Writing và Speaking. Giúp nhiều học viên vượt qua band điểm mục tiêu, đặc biệt là trong hai kỹ năng này.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.8, 24, 366, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-298', 'Chào các em, chị là Kim Chi. Chị hiểu rằng Toán THPT và ôn thi Đại học có nhiều áp lực. Chị sẽ cùng các em xây dựng kiến thức nền tảng vững chắc, rèn luyện các kỹ năng giải toán và phương pháp làm bài thi trắc nghiệm, tự luận. Chị tỉ mỉ, có trách nhiệm và luôn theo sát tiến độ của học viên.', 'Toán THPT, phương pháp giải nhanh, luyện thi Đại học hiệu quả.', NULL, 'Sinh viên năm 4, ngành Sư phạm Toán học, Đại học Khoa học Tự nhiên.', NULL, NULL, '3 năm kinh nghiệm dạy Toán THPT và ôn thi Đại học. Tập trung vào các chuyên đề quan trọng và các dạng bài tập thường gặp trong đề thi.', 'Hà Nội', 'Quận 3', 'active', true, 4.6, 61, 67, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-300', 'Chào các em, mình là Thúy Vy. Vật Lý có thể rất thú vị và dễ hiểu nếu được giải thích một cách khoa học, logic. Mình sẽ giúp các em nắm vững kiến thức từ cơ bản đến nâng cao, rèn luyện kỹ năng giải bài tập. Mình kiên nhẫn, thân thiện và luôn cố gắng truyền cảm hứng học tập cho học sinh.', 'Vật Lý THCS & THPT, xây dựng nền tảng, phương pháp học dễ tiếp thu.', NULL, 'Sinh viên năm 3, ngành Sư phạm Vật lý, Đại học Khoa học.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Vật Lý cho học sinh THCS và THPT. Giúp các em hiểu bài và cải thiện kết quả học tập.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4, 15, 237, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-301', 'Chào các bạn, mình là Văn Hùng. Mình chuyên luyện thi Hóa học cho kỳ thi tốt nghiệp THPT. Mình sẽ giúp các bạn hệ thống hóa kiến thức, nắm vững các phương pháp giải nhanh các dạng bài tập thường gặp, đặc biệt là phần bài tập định lượng và tính toán.', 'Hóa Học ôn thi tốt nghiệp THPT, tập trung vào các dạng bài trọng tâm.', NULL, 'Cựu sinh viên ngành Hóa học, Đại học Bách khoa TP. Hồ Chí Minh.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa học, tập trung vào ôn thi tốt nghiệp THPT. Đã giúp nhiều học sinh đạt điểm cao trong kỳ thi này.', 'Đồng Nai', 'Quận 1', 'active', true, 4.6, 54, 93, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-302', 'Chào các em, chị là Lan Hương. Chị yêu văn chương và muốn chia sẻ tình yêu đó đến các em. Chị tập trung vào việc giúp các em đọc hiểu sâu sắc các văn bản, cảm thụ vẻ đẹp của ngôn ngữ và diễn đạt ý của mình một cách mạch lạc, giàu cảm xúc.', 'Ngữ văn cho học sinh lớp 6-9, khơi gợi tư duy đọc hiểu và cảm thụ.', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Thủ đô.', NULL, NULL, '3 năm kinh nghiệm dạy Ngữ văn cho học sinh THCS. Giúp các em xây dựng nền tảng văn học vững chắc và có hứng thú với môn học.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.1, 56, 110, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-303', 'Xin chào, mình là Đức Anh. Mình tin rằng Tin học là kỹ năng cần thiết cho mọi người. Mình sẽ hướng dẫn các bạn sử dụng thành thạo các phần mềm văn phòng như Word, Excel, PowerPoint một cách nhanh chóng và hiệu quả nhất qua các bài tập thực hành.', 'Tin học cơ bản, Excel, Word cho mọi người, hướng dẫn thực hành dễ hiểu.', NULL, 'Kỹ sư Công nghệ thông tin, Đại học FPT.', NULL, NULL, '2 năm kinh nghiệm dạy Tin học văn phòng cho người mới bắt đầu. Đã giúp nhiều người làm quen và sử dụng thành thạo các công cụ Tin học cơ bản.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.3, 34, 276, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-304', 'Hello! Mình là Thảo. Mình hiểu rằng người đi làm thường bận rộn nhưng vẫn muốn cải thiện Tiếng Anh. Mình cung cấp các khóa học IELTS linh hoạt, tập trung vào các tình huống giao tiếp thực tế, từ vựng chuyên ngành và luyện phản xạ nhanh để bạn tự tin hơn trong công việc.', 'IELTS cho người đi làm, luyện phản xạ giao tiếp, nâng cao từ vựng.', NULL, 'Thạc sĩ Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Tiếng Anh, trong đó có 3 năm tập trung vào luyện thi IELTS cho người đi làm. Giúp học viên đạt mục tiêu về điểm số và sự tự tin.', 'Đồng Nai', 'Phú Nhuận', 'active', true, 4.8, 39, 395, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-305', 'Chào các bạn, mình là Quang Huy. Mình đam mê Toán học và có kinh nghiệm bồi dưỡng học sinh giỏi. Mình sẽ cùng các bạn khám phá những bài toán hay, rèn luyện tư duy logic, sáng tạo và kỹ năng giải quyết vấn đề phức tạp. Mục tiêu là giúp các bạn chinh phục các kỳ thi Toán.', 'Toán Olympic & Luyện thi HSG Toán, tư duy logic sắc bén.', NULL, 'Thạc sĩ Toán học Lý thuyết, Viện Toán học.', NULL, NULL, '6 năm kinh nghiệm giảng dạy và bồi dưỡng đội tuyển học sinh giỏi Toán các cấp. Nhiều học sinh của mình đã đạt giải cao trong các kỳ thi quốc gia và quốc tế.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.5, 60, 184, '2026-06-19 02:56:53.033022', '2026-06-19 02:56:53.033022', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-206', 'Mình là Trang, rất vui được đồng hành cùng bạn trên con đường chinh phục Tiếng Anh. Mình tin rằng học ngoại ngữ là cả một hành trình khám phá, không chỉ là học thuộc lòng. Phương pháp của mình tập trung vào việc xây dựng nền tảng vững chắc, phát triển kỹ năng nghe nói đọc viết một cách tự nhiên và hứng thú. Mình đặc biệt thích tạo không khí lớp học vui vẻ, khuyến khích học viên đặt câu hỏi và chia sẻ ý kiến. Phù hợp cho các bạn mất gốc, muốn giao tiếp tốt hoặc chuẩn bị cho các kỳ thi.', 'Tiếng Anh giao tiếp & luyện thi IELTS - Giúp bạn tự tin tỏa sáng!', NULL, 'Tốt nghiệp Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Tiếng Anh cho học sinh cấp 2, 3 và người đi làm. Từng giúp nhiều học viên đạt điểm cao trong các kỳ thi chứng chỉ như TOEIC, IELTS. Đã làm việc tại các trung tâm Anh ngữ uy tín tại Hà Nội.', 'Biên Hòa', 'Quận 7', 'active', true, 4, 18, 350, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-207', 'Chào các bạn, mình là Khôi. Mình thích Toán học và muốn lan tỏa niềm yêu thích đó đến các bạn học sinh. Phương pháp giảng dạy của mình là làm cho Toán học trở nên dễ hiểu, trực quan, gắn liền với các ví dụ thực tế. Mình kiên nhẫn, lắng nghe để hiểu rõ những khó khăn của từng bạn và đưa ra lộ trình học phù hợp nhất. Mình không chỉ dạy kiến thức mà còn rèn luyện tư duy logic và khả năng giải quyết vấn đề cho học viên. Rất phù hợp với các bạn đang gặp khó khăn với môn Toán hoặc muốn nâng cao thành tích.', 'Gia sư Toán - Kiến thức nền tảng vững chắc, phương pháp giải đa dạng.', NULL, 'Sinh viên năm 4, Khoa Toán - Tin, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Đã dạy kèm Toán cho học sinh THPT được 3 năm. Nhiều học sinh tiến bộ rõ rệt, từ điểm trung bình lên khá giỏi. Thường xuyên ôn thi cho học sinh vào lớp 10 và luyện thi Đại học khối A, A1.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.8, 40, 134, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-208', 'Xin chào! Mình là Bích Ngọc, một người yêu văn chương tha thiết. Mình tin rằng Văn học không chỉ là những con chữ khô khan mà là cả một thế giới cảm xúc, tư tưởng. Mình sẽ cùng các bạn khám phá từng tác phẩm, từng nhân vật qua lăng kính đời sống, giúp các bạn cảm thụ văn chương một cách tinh tế và sâu sắc. Phương pháp của mình đề cao sự tương tác, thảo luận, khuyến khích các bạn tự tìm tòi và phát triển giọng văn của riêng mình. Mình rất vui khi được đồng hành cùng các bạn trên hành trình này.', 'Ngữ văn THPT - Khơi nguồn cảm hứng, chinh phục điểm cao.', NULL, 'Cử nhân Sư phạm Ngữ văn, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Gia sư Ngữ văn 4 năm kinh nghiệm, chuyên bồi dưỡng học sinh giỏi và luyện thi Đại học môn Văn. Tỷ lệ học sinh đỗ nguyện vọng 1 cao, nhiều em đạt điểm 8, 9 trong kỳ thi THPT Quốc gia.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.7, 62, 385, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-209', 'Chào mọi người, mình là Hoàng Long. Vật Lý luôn là môn học thú vị nếu ta biết cách tiếp cận nó. Mình có khả năng diễn giải các khái niệm Vật Lý phức tạp thành những ý tưởng đơn giản, dễ hiểu, kèm theo hình ảnh trực quan sinh động. Mình tập trung vào việc giúp học sinh xây dựng được phương pháp tư duy mạch lạc khi giải bài tập, chứ không chỉ học thuộc công thức. Mình là người khá kiên nhẫn và luôn khuyến khích học sinh đặt câu hỏi, thậm chí là những câu hỏi ''ngớ ngẩn'' nhất. Phù hợp với học sinh THPT muốn nắm vững kiến thức và đạt điểm cao.', 'Vật Lý THPT - Giải thích cặn kẽ, bài tập đa dạng, tư duy khoa học.', NULL, 'Sinh viên năm 3, ngành Vật lý kỹ thuật, Trường Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Gia sư Vật Lý 2 năm. Đã giúp nhiều học sinh cải thiện đáng kể kết quả học tập, đặc biệt là những phần kiến thức khó như Điện xoay chiều, Dao động cơ. Có kinh nghiệm ôn thi học sinh giỏi cấp tỉnh.', 'Hà Nội', 'Quận 1', 'active', true, 4.5, 46, 69, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-210', 'Hi! Mình là Thanh Mai, rất thích Hóa học vì nó giải thích thế giới xung quanh chúng ta. Mình có cách dạy logic, hệ thống hóa kiến thức từ dễ đến khó, giúp các bạn học sinh không còn cảm thấy Hóa học là môn học ''khó nhằn''. Mình sẽ cùng các bạn làm thật nhiều bài tập, từ cơ bản đến nâng cao, đặc biệt là các dạng bài tự luận và bài tập định lượng. Mình luôn kiên nhẫn giải thích cho đến khi các bạn hiểu rõ vấn đề. Phù hợp với học sinh THPT muốn lấy lại gốc Hóa hoặc nâng cao điểm số.', 'Hóa Học THPT - Từ dễ đến khó, xây dựng nền tảng vững chắc.', NULL, 'Tốt nghiệp Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM, chuyên ngành Hóa học.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Hóa học cho học sinh THPT. Nhiều học sinh đã đạt điểm 8, 9 trong các bài kiểm tra và thi học kỳ. Có kinh nghiệm ôn thi học sinh giỏi Hóa.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 4.8, 44, 292, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-211', 'Xin chào! Mình là Cường, một người yêu thích Toán học và mong muốn giúp các em học sinh cấp 2 tìm lại niềm vui với môn học này. Mình có phương pháp giảng dạy bám sát chương trình, kết hợp với các dạng bài tập đa dạng, từ dễ đến khó, giúp các em rèn luyện kỹ năng giải toán. Mình đặc biệt chú trọng việc xây dựng sự tự tin và tư duy logic cho học sinh, giúp các em vượt qua những khó khăn ban đầu. Mình kiên nhẫn, nhiệt tình và luôn tạo không khí học tập thoải mái, thân thiện.', 'Toán lớp 6-9 - Nền tảng vững vàng, vượt qua nỗi sợ Toán.', NULL, 'Sinh viên năm cuối, ngành Sư phạm Toán học, Trường Đại học Sư phạm TP.HCM.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy kèm Toán cho học sinh khối THCS. Nhiều học sinh của mình đã cải thiện kết quả học tập rõ rệt, đạt điểm cao trong các kỳ thi và học sinh giỏi Toán cấp quận/thành phố.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.9, 63, 84, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-212', 'Hello! Mình là Minh Anh, rất hào hứng được cùng các con khám phá thế giới Tiếng Anh đầy màu sắc. Mình yêu trẻ con và có phương pháp tiếp cận Tiếng Anh cho lứa tuổi nhỏ rất hiệu quả, kết hợp bài hát, trò chơi, hình ảnh sinh động. Mình tập trung vào việc xây dựng phản xạ ngôn ngữ tự nhiên, phát âm chuẩn và sự tự tin khi giao tiếp. Mình tin rằng học mà chơi, chơi mà học sẽ giúp các con tiếp thu kiến thức một cách nhẹ nhàng và bền vững nhất. Phù hợp với các bé tiểu học và THCS muốn làm quen hoặc cải thiện Tiếng Anh.', 'Tiếng Anh tiểu học & THCS - Vui học, hiệu quả, phát triển toàn diện.', NULL, 'Cử nhân Ngôn ngữ Anh, Trường Đại học Kinh tế - Tài chính TP.HCM.', NULL, NULL, 'Gia sư Tiếng Anh cho trẻ em 4 năm. Nhiều học sinh đã có khả năng giao tiếp tốt, phát âm chuẩn và yêu thích môn Tiếng Anh hơn. Có kinh nghiệm dạy theo giáo trình Cambridge.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.2, 23, 189, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-213', 'Chào bạn, mình là Tuấn Dũng, người sẽ giúp bạn chinh phục band điểm IELTS mơ ước. Mình đã từng trải qua hành trình thi IELTS và hiểu rõ những thử thách. Phương pháp của mình tập trung vào việc cung cấp các chiến lược làm bài hiệu quả, xây dựng vốn từ vựng học thuật và ngữ pháp chính xác, đặc biệt cho kỹ năng Speaking và Writing. Mình sẽ giúp bạn luyện tập có mục tiêu, phân tích lỗi sai và cải thiện từng ngày. Mình có lối nói chuyện thân thiện, cởi mở, giúp bạn tự tin hơn khi thực hành.', 'IELTS Speaking & Writing - Target band 7+, chiến lược hiệu quả.', NULL, 'IELTS 8.0 (Listening 9.0, Reading 8.5, Writing 7.0, Speaking 7.0), đang học Thạc sĩ tại Anh Quốc.', NULL, NULL, 'Đã hướng dẫn và luyện thi IELTS cho hơn 50 học viên, giúp họ đạt được band điểm mong muốn, trung bình tăng 1.0-1.5 band so với đầu vào. Chuyên sâu vào Speaking và Writing.', 'Biên Hòa', 'Quận 1', 'active', true, 4.1, 37, 393, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-309', 'Anh là Nam, đam mê khám phá thế giới qua lăng kính Vật Lý. Anh luôn tìm cách đưa các khái niệm trừu tượng về gần gũi với cuộc sống hàng ngày. Anh thích dùng thí nghiệm mô phỏng và ví dụ thực tế để các em dễ hình dung. Nếu em thấy Vật Lý khó nhằn, hãy để anh giúp em thấy nó thật dễ dàng!', 'Vật Lý Thực Tế: Biến những công thức khô khan thành trải nghiệm thú vị.', NULL, 'Kỹ sư Vật lý Kỹ thuật, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '3 năm dạy thêm Vật Lý cho học sinh THPT. Tỷ lệ học sinh đạt điểm khá giỏi trên 90%. Có kinh nghiệm ôn thi Đại học khối A.', 'Đồng Nai', 'Quận 3', 'active', true, 4.7, 27, 232, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-214', 'Xin chào! Mình là Thu Hà, rất vui được đồng hành cùng các bạn nhỏ khối 6, 7, 8 trong môn Toán. Mình hiểu rằng giai đoạn chuyển cấp hoặc bắt đầu học Toán THCS có thể khiến các bạn bỡ ngỡ. Phương pháp của mình là đi từ những khái niệm cơ bản nhất, làm thật nhiều ví dụ minh họa sinh động và bài tập áp dụng đa dạng. Mình kiên nhẫn, nhẹ nhàng, tạo cảm giác học tập thoải mái, giúp các bạn yêu thích môn Toán hơn. Mình mong muốn xây dựng cho các bạn một nền tảng kiến thức thật vững chắc để tự tin bước vào các cấp học cao hơn.', 'Toán THCS & Đầu cấp - Nhập môn dễ dàng, nền tảng vững chắc.', NULL, 'Cử nhân Sư phạm Toán học, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy kèm Toán cho học sinh THCS. Nhiều học sinh đã tiến bộ vượt bậc, tự tin hơn khi làm bài và đạt điểm cao trong các bài kiểm tra.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.7, 40, 439, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-215', 'Chào các bạn, mình là Gia Bảo. Mình đam mê công nghệ và muốn chia sẻ kiến thức Tin học đến mọi người. Mình có kinh nghiệm dạy Tin học văn phòng (Word, Excel, PowerPoint) cho người đi làm và các bạn sinh viên. Mình cũng có thể hướng dẫn lập trình cơ bản (Python, C++) cho người mới bắt đầu, với phương pháp giảng dạy logic, thực tế, giúp các bạn hiểu bản chất và ứng dụng ngay. Mình là người năng động, nhiệt tình và luôn cập nhật kiến thức mới. Phù hợp cho những ai muốn nâng cao kỹ năng Tin học phục vụ công việc và học tập.', 'Tin Học Văn Phòng & Lập trình cơ bản - Tự tin làm chủ công nghệ.', NULL, 'Sinh viên năm 3, ngành Khoa học Máy tính, Trường Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Đã hướng dẫn Tin học văn phòng cho hơn 30 người, giúp họ cải thiện hiệu suất làm việc. Có kinh nghiệm dạy lập trình Python cho sinh viên năm nhất, giúp các bạn hoàn thành tốt các bài tập lớn.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.9, 50, 387, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-216', 'Hello! Mình là Mai Lan. Với kinh nghiệm luyện thi Đại học môn Tiếng Anh, mình hiểu rõ những gì các bạn cần để đạt điểm số mong muốn. Phương pháp của mình là kết hợp nhuần nhuyễn giữa kiến thức ngữ pháp, từ vựng, và các kỹ năng Nghe, Nói, Đọc, Viết. Mình sẽ giúp các bạn phân tích cấu trúc đề thi, luyện tập với các dạng bài tập thường gặp và xây dựng chiến lược làm bài hiệu quả. Mình luôn động viên, khích lệ học viên, tạo không khí học tập sôi nổi và tập trung. Phù hợp với học sinh cuối cấp đang ôn thi Đại học.', 'Tiếng Anh THPT - Luyện thi Đại học, kỹ năng chuyên sâu.', NULL, 'Tốt nghiệp Đại học Hà Nội, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, 'Gia sư luyện thi Đại học môn Tiếng Anh 5 năm. Đã giúp hàng trăm học sinh đạt điểm cao, nhiều em đạt điểm 9, 10 môn Tiếng Anh. Có kinh nghiệm dạy các lớp ôn thi cấp tốc.', 'Hà Nội', 'Quận 7', 'active', true, 4.9, 63, 334, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-217', 'Chào các bạn, mình là Minh Hiếu. Sinh Học không chỉ là sách vở mà là cả một thế giới kỳ diệu của sự sống. Mình có khả năng truyền đạt kiến thức Sinh Học một cách sinh động, dễ hiểu, liên hệ với thực tế cuộc sống. Mình tập trung vào việc phát triển tư duy khoa học cho học sinh, giúp các bạn hiểu sâu bản chất vấn đề thay vì học thuộc lòng. Mình luôn khuyến khích các bạn đặt câu hỏi, tìm tòi và thảo luận. Phù hợp với học sinh THPT muốn nắm vững kiến thức Sinh Học, chuẩn bị cho các kỳ thi hoặc yêu thích môn học này.', 'Sinh Học THPT - Khám phá thế giới sống động, tư duy khoa học.', NULL, 'Sinh viên năm cuối, ngành Sinh học phân tử, Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Gia sư Sinh Học 3 năm. Giúp học sinh hiểu rõ các phần kiến thức khó như Di truyền, Sinh thái. Nhiều học sinh có sự tiến bộ rõ rệt và đạt điểm cao trong các kỳ thi.', 'Bình Dương', 'Quận 3', 'active', true, 4.4, 42, 299, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-218', 'Xin chào các em và quý phụ huynh! Mình là Kim Oanh, yêu văn chương và mong muốn chia sẻ tình yêu đó. Mình có phương pháp dạy Ngữ văn THCS bám sát chương trình, giúp các em hiểu sâu nội dung bài học, nắm vững kiến thức cơ bản và nâng cao. Mình chú trọng rèn luyện kỹ năng làm văn, phát triển khả năng cảm thụ văn học, diễn đạt ý tưởng mạch lạc. Mình là người kiên nhẫn, nhiệt tình, luôn lắng nghe và động viên học sinh. Phù hợp với các em muốn củng cố kiến thức, chuẩn bị cho các kỳ thi hoặc nâng cao kỹ năng viết văn.', 'Ngữ văn THCS - Nền tảng vững chắc, cảm thụ văn chương tinh tế.', NULL, 'Cử nhân Sư phạm Ngữ văn, Trường Đại học Sư phạm Đà Nẵng.', NULL, NULL, 'Đã dạy kèm Ngữ văn cho học sinh THCS được 4 năm. Giúp nhiều học sinh cải thiện điểm số, tự tin hơn khi làm bài và yêu thích môn học hơn.', 'TP.HCM', 'Quận 1', 'active', true, 4.6, 42, 344, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-219', 'Chào bạn, mình là Minh Đức. Nếu bạn đang gặp khó khăn với Toán cao cấp hoặc Lượng giác, mình sẵn sàng giúp bạn. Mình có khả năng phân tích và trình bày các khái niệm phức tạp một cách logic, dễ hiểu. Mình tập trung vào việc xây dựng nền tảng vững chắc và phương pháp giải bài tập hiệu quả. Mình sẽ cùng bạn đi qua từng bước, giải quyết từng vấn đề, và chắc chắn bạn sẽ thấy môn học này trở nên quen thuộc và thú vị hơn. Phù hợp cho sinh viên các ngành cần Toán cao cấp hoặc học sinh THPT ôn thi chuyên sâu.', 'Toán cao cấp & Lượng giác - Giải thích rõ ràng, bài tập thực tế.', NULL, 'Thạc sĩ Toán học Lý thuyết, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, 'Giảng dạy Toán cao cấp tại trung tâm luyện thi cho sinh viên được 2 năm. Có kinh nghiệm hướng dẫn sinh viên làm bài tập và đồ án liên quan đến Toán. Tỷ lệ học viên qua môn cao.', 'TP.HCM', 'Hải Châu', 'active', true, 4.5, 35, 282, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-310', 'Xin chào, mình là Ngân! Mình tin Hóa học không hề đáng sợ. Mình có cách truyền đạt kiến thức một cách logic, dễ hiểu, kết hợp sơ đồ tư duy và bài tập bám sát. Mình tập trung giúp học sinh xây dựng nền tảng vững chắc và kỹ năng giải bài tập hiệu quả. Rất mong được đồng hành cùng các bạn!', 'Hóa Học Cùng Ngân: Dễ hiểu, dễ nhớ, dễ điểm cao!', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa học cho học sinh lớp 9, 10, 11. Đã giúp nhiều học sinh cải thiện đáng kể kết quả học tập, từ trung bình lên khá giỏi.', 'Biên Hòa', 'Quận 1', 'active', true, 5, 18, 303, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-220', 'Hi there! Mình là Thảo Vy, một người đam mê ngôn ngữ và văn hóa. Mình tin rằng học Tiếng Anh giao tiếp là cả một quá trình thực hành và trải nghiệm. Phương pháp của mình tập trung vào việc tạo ra một môi trường học tập cởi mở, khuyến khích học viên nói nhiều, mắc lỗi và học hỏi từ đó. Mình sử dụng đa dạng các hoạt động như đóng vai, thảo luận, kể chuyện để tăng cường phản xạ và sự tự tin cho người học. Mình kiên nhẫn, vui vẻ và luôn truyền cảm hứng. Rất phù hợp với các bạn muốn cải thiện khả năng giao tiếp, phát âm và sự tự tin khi nói Tiếng Anh.', 'Tiếng Anh Giao tiếp & Luyện Nói - Tự tin, trôi chảy, phản xạ nhanh.', NULL, 'Cử nhân Sư phạm Tiếng Anh, Trường Đại học Sài Gòn.', NULL, NULL, 'Gia sư Tiếng Anh giao tiếp 4 năm. Giúp nhiều học viên từ mất gốc đến giao tiếp trôi chảy. Có kinh nghiệm dạy cho người đi làm và các bạn sinh viên cần Tiếng Anh cho công việc.', 'Đồng Nai', 'Quận 7', 'active', true, 4.3, 37, 75, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-221', 'Chào các bạn, mình là Quang Huy. Vật Lý là môn học đòi hỏi sự hiểu sâu và tư duy logic. Mình sẽ giúp các bạn tiếp cận môn học này một cách hệ thống, từ lý thuyết đến bài tập. Phương pháp của mình là tập trung vào việc xây dựng nền tảng kiến thức vững chắc, sau đó áp dụng vào giải các dạng bài tập từ cơ bản đến nâng cao. Mình có khả năng giải thích các vấn đề phức tạp một cách đơn giản, dễ hiểu và cung cấp nhiều mẹo giải nhanh. Mình là người nghiêm túc, có trách nhiệm và luôn theo sát tiến độ học tập của học viên. Phù hợp với học sinh THPT muốn đạt điểm cao môn Vật Lý.', 'Vật Lý THPT & Ôn thi Đại học - Tư duy vật lý, giải bài tập thông minh.', NULL, 'Kỹ sư Điện tử - Viễn thông, Trường Đại học Bách Khoa TP.HCM.', NULL, NULL, 'Gia sư Vật Lý 3 năm kinh nghiệm. Nhiều học sinh đạt điểm giỏi trong các kỳ thi học kỳ và thi tốt nghiệp. Có kinh nghiệm ôn thi Đại học khối A.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.1, 51, 381, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-222', 'Xin chào bố mẹ và các con! Mình là Phương Thảo, một cô giáo mầm non yêu trẻ và có kinh nghiệm giảng dạy. Mình rất vui được đồng hành cùng các con trong môn Toán. Phương pháp của mình là biến những con số khô khan thành những bài học thú vị qua trò chơi, hình ảnh, câu chuyện. Mình tập trung vào việc xây dựng cho các con nền tảng tư duy toán học ban đầu, sự yêu thích với môn học và sự tự tin khi giải quyết các bài toán nhỏ. Mình kiên nhẫn, nhẹ nhàng và luôn tạo không khí học tập vui vẻ, khám phá.', 'Toán lớp 1-5 - Bé học vui, thông minh, tự tin.', NULL, 'Cử nhân Giáo dục Mầm non, Trường Đại học Sư phạm.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Toán cho trẻ tiểu học. Giúp các bé làm quen với các con số, phép tính cơ bản và phát triển tư duy logic thông qua các hoạt động sáng tạo.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.5, 30, 187, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-223', 'Hello! Mình là Quang Huy. Mình đã chinh phục IELTS với điểm số cao và sẵn sàng chia sẻ những chiến lược hiệu quả nhất cho kỹ năng Listening và Reading. Phương pháp của mình là phân tích kỹ các dạng bài, cung cấp các mẹo làm bài nhanh và chính xác, cũng như rèn luyện khả năng nghe hiểu và đọc lướt. Mình sẽ giúp bạn nhận diện các ''bẫy'' thường gặp trong đề thi và cách vượt qua chúng. Mình là người có phương pháp rõ ràng, tỉ mỉ và luôn khuyến khích học viên luyện tập chăm chỉ. Phù hợp với những bạn muốn cải thiện nhanh điểm số hai kỹ năng này.', 'IELTS Listening & Reading - Chiến lược thông minh, điểm số bứt phá.', NULL, 'IELTS 8.0 (Listening 9.0, Reading 8.5), Tốt nghiệp ngành Kinh tế Quốc tế.', NULL, NULL, 'Hơn 3 năm kinh nghiệm luyện thi IELTS cho các kỹ năng Listening và Reading. Nhiều học viên đã đạt điểm 8.0-9.0 ở hai kỹ năng này. Có kinh nghiệm xây dựng lộ trình học cá nhân hóa.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.6, 16, 302, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-224', 'Xin chào! Mình là Quỳnh Anh. Mình nhận thấy Hóa học và Sinh học có mối liên hệ chặt chẽ với nhau, và việc học theo hướng liên môn sẽ giúp các bạn hiểu sâu và rộng hơn. Mình có phương pháp giảng dạy giúp kết nối kiến thức giữa hai môn, xây dựng tư duy hệ thống và khả năng vận dụng vào giải bài tập. Mình sẽ làm cho các khái niệm Hóa - Sinh trở nên gần gũi, dễ hiểu bằng các ví dụ thực tế. Mình là người nhiệt tình, kiên nhẫn và luôn mong muốn truyền cảm hứng học tập cho các bạn. Phù hợp với học sinh THPT muốn học tốt cả hai môn hoặc chuẩn bị cho các kỳ thi.', 'Hóa Học & Sinh Học THPT - Liên môn khoa học, tư duy hệ thống.', NULL, 'Sinh viên năm 3, ngành Dược học, Trường Đại học Dược Hà Nội.', NULL, NULL, 'Gia sư Hóa học và Sinh học được 2 năm. Giúp học sinh nắm vững kiến thức và cải thiện điểm số. Có kinh nghiệm ôn thi học sinh giỏi liên môn.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.3, 9, 399, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-225', 'Chào các bạn, mình là Văn Nam. Mình yêu thích Ngữ văn và đã dành nhiều thời gian nghiên cứu về các tác phẩm văn học Việt Nam. Mình có phương pháp giảng dạy giúp các bạn đi sâu vào phân tích tâm lý nhân vật, ý nghĩa tư tưởng của tác phẩm, cũng như rèn luyện kỹ năng nghị luận văn học sắc bén. Mình không chỉ dạy kiến thức mà còn giúp các bạn phát triển tư duy phản biện và khả năng diễn đạt mạch lạc, thuyết phục. Mình là người có kiến thức chuyên môn sâu, phong cách nói chuyện cuốn hút và luôn tạo động lực cho học viên. Phù hợp với học sinh THPT muốn đạt điểm cao môn Văn hoặc yêu thích văn chương.', 'Ngữ văn THPT - Phân tích tác phẩm sâu sắc, rèn luyện kỹ năng viết.', NULL, 'Tốt nghiệp ngành Báo chí, Học viện Báo chí và Tuyên truyền.', NULL, NULL, 'Có kinh nghiệm hướng dẫn học sinh THPT viết bài văn nghị luận và phân tích tác phẩm văn học trong 4 năm. Nhiều học sinh đạt điểm giỏi, xuất sắc trong các kỳ thi.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.3, 7, 328, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-226', 'Xin chào! Mình là Ngọc Ánh, với kinh nghiệm nhiều năm làm việc với trẻ nhỏ, mình hiểu tâm lý và cách tiếp cận hiệu quả nhất cho các con. Mình tin rằng Toán học có thể rất thú vị nếu được dạy đúng cách. Phương pháp của mình là kết hợp kiến thức sách giáo khoa với các hoạt động thực tế, trò chơi trí tuệ, giúp các con vừa học vừa chơi, hình thành tư duy logic và yêu thích môn học. Mình kiên nhẫn, yêu trẻ và luôn theo sát sự tiến bộ của từng bé. Phù hợp cho các bé tiểu học và THCS muốn học tốt môn Toán.', 'Toán tiểu học & THCS - Xây dựng tình yêu Toán học cho con.', NULL, 'Cử nhân Giáo dục Tiểu học, chuyên ngành Sư phạm Toán.', NULL, NULL, 'Gia sư Toán cho học sinh tiểu học và THCS 5 năm. Giúp nhiều học sinh từ trung bình lên khá, giỏi. Có kinh nghiệm dạy kèm các chương trình song ngữ.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.1, 30, 61, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-227', 'Chào các bạn, mình là Minh Quân. Lịch sử không chỉ là những con số và sự kiện khô khan mà là những câu chuyện hấp dẫn về quá khứ. Mình có khả năng truyền đạt kiến thức Lịch sử một cách sinh động, dễ hiểu, giúp các bạn hình dung rõ ràng về các giai đoạn lịch sử và các nhân vật. Phương pháp của mình tập trung vào việc xây dựng tư duy lịch sử, khả năng liên hệ, phân tích và ghi nhớ kiến thức một cách hiệu quả. Mình là người trẻ trung, năng động và luôn tìm cách làm cho bài học trở nên thú vị. Phù hợp với học sinh THPT muốn học tốt môn Sử và đạt điểm cao.', 'Lịch Sử THPT - Kể chuyện quá khứ, tư duy lịch sử, dễ nhớ.', NULL, 'Sinh viên năm 3, ngành Lịch sử, Trường Đại học Khoa học Xã hội & Nhân văn.', NULL, NULL, 'Gia sư Lịch sử 2 năm. Giúp nhiều học sinh nắm vững kiến thức, cải thiện kết quả học tập và yêu thích môn học hơn. Có kinh nghiệm ôn thi học sinh giỏi Lịch sử.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.5, 35, 122, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-228', 'Xin chào! Mình là Bích Hằng, một người yêu thích khám phá thế giới qua bản đồ và các hiện tượng địa lý. Mình có phương pháp giảng dạy giúp các bạn hình dung rõ ràng về không gian địa lý, các mối quan hệ giữa tự nhiên và con người. Mình tập trung vào việc xây dựng tư duy logic, khả năng phân tích bản đồ, biểu đồ và các số liệu. Mình sẽ giúp các bạn thấy Địa Lý không chỉ là học thuộc mà còn là môn học của tư duy và sự liên tưởng. Mình là người cẩn thận, nhiệt tình và luôn sẵn sàng giải đáp mọi thắc mắc. Phù hợp với học sinh THPT và sinh viên cần kiến thức Địa Lý đại cương.', 'Địa Lý THPT & Đại cương - Khám phá thế giới, tư duy không gian.', NULL, 'Cử nhân Địa lý học, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Gia sư Địa lý 3 năm. Giúp học sinh hiểu sâu các kiến thức về tự nhiên, kinh tế - xã hội và đạt kết quả tốt trong học tập. Có kinh nghiệm ôn thi học sinh giỏi Địa lý.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.8, 34, 195, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-229', 'Chào các bạn, mình là Văn Bình. Với kinh nghiệm ôn thi Đại học môn Toán nhiều năm, mình hiểu rõ những yêu cầu và thách thức mà các bạn học sinh cuối cấp phải đối mặt. Phương pháp của mình là xây dựng lộ trình học tập khoa học, bám sát chương trình và đề thi minh họa. Mình tập trung vào việc rèn luyện kỹ năng giải toán nhanh, chính xác và có hệ thống. Mình sẽ cùng các bạn chinh phục mọi dạng bài từ cơ bản đến nâng cao, từ đó tự tin bước vào kỳ thi quan trọng. Mình là người nghiêm túc, kỷ luật và luôn thúc đẩy học viên đạt mục tiêu.', 'Toán THPT - Chinh phục kỳ thi Đại học, nền tảng vững chắc.', NULL, 'Thủ khoa ngành Toán ứng dụng, Trường Đại học Công nghệ - Đại học Quốc gia TP.HCM.', NULL, NULL, 'Gia sư Toán luyện thi Đại học 5 năm. Đã giúp hơn 100 học sinh đỗ nguyện vọng 1 vào các trường Đại học top đầu. Điểm thi môn Toán của học sinh đạt trung bình 8.5.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.9, 57, 181, '2026-06-19 02:57:14.374598', '2026-06-19 02:57:14.374598', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-306', 'Mình là Mai Anh, yêu thích việc truyền cảm hứng học Tiếng Anh. Mình tin rằng học ngôn ngữ là một hành trình khám phá bản thân. Phương pháp của mình tập trung vào thực hành giao tiếp tự nhiên, sửa lỗi tinh tế và xây dựng sự tự tin. Mình hợp với các bạn muốn cải thiện phản xạ nói, hoặc cần lấy lại gốc Tiếng Anh.', 'Tiếng Anh Giao Tiếp & Luyện Thi: Fluency & Confidence Building!', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Hà Nội. Chứng chỉ TESOL quốc tế.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm và sinh viên. Giúp hơn 50 học viên đạt điểm IELTS mong muốn. Từng làm trợ giảng cho các khóa học Tiếng Anh tổng quát.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4.9, 26, 319, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-307', 'Chào các em, anh là Quân! Anh không chỉ dạy công thức mà còn giúp các em hiểu bản chất, yêu Toán hơn. Anh thích cách tiếp cận vấn đề một cách logic, tìm ra nhiều hướng giải sáng tạo. Nếu các em đang gặp khó khăn với Toán hoặc muốn nâng cao kỹ năng, anh sẵn sàng đồng hành.', 'Toán Tư Duy: Phá đảo mọi bài toán khó - Cùng chinh phục điểm 10!', NULL, 'Thạc sĩ Toán học Ứng dụng, Đại học Bách Khoa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán cấp 2, 3. Nhiều học sinh đạt giải Olympic Toán cấp thành phố. Đã luyện thi thành công cho hàng trăm em vào các trường THPT chuyên và Đại học.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.7, 33, 87, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-308', 'Mình là Hoài, một cô giáo Văn đầy nhiệt huyết. Mình yêu văn chương và muốn lan tỏa tình yêu đó đến các bạn. Phương pháp của mình là "chạm", đi từ cảm xúc, kết nối với thực tế để hiểu sâu sắc tác phẩm. Mình đặc biệt phù hợp với các bạn muốn viết văn hay, phân tích văn học sâu sắc.', 'Ngữ Văn Chạm Cảm Xúc: Khơi nguồn sáng tạo và tư duy phản biện.', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, '4 năm kinh nghiệm giảng dạy Ngữ văn tại trường THPT. Giúp học sinh đạt điểm cao trong các kỳ thi Tốt nghiệp THPT. Từng phụ trách nhóm học sinh năng khiếu môn Văn.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.7, 52, 270, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-311', 'Chào mọi người, mình là Tuấn. Mình yêu lập trình và muốn chia sẻ niềm đam mê này. Mình có thể hướng dẫn từ những khái niệm cơ bản nhất về máy tính, đến các ngôn ngữ lập trình phổ biến như Python, Java. Phương pháp của mình là "học đi đôi với hành", làm nhiều bài tập thực tế. Phù hợp cho mọi lứa tuổi muốn tiếp cận Tin học.', 'Tin Học Căn Bản & Nâng Cao: Code từ đầu, làm chủ công nghệ!', NULL, 'Kỹ sư Công nghệ Thông tin, Học viện Công nghệ Bưu chính Viễn thông.', NULL, NULL, '3 năm kinh nghiệm dạy lập trình cơ bản cho học sinh, sinh viên. Đã hướng dẫn nhiều dự án cá nhân. Có kinh nghiệm làm việc trong môi trường IT.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.4, 49, 253, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-312', 'Mình là Linh, chuyên gia luyện thi IELTS. Mình có phương pháp độc đáo giúp bạn cải thiện kỹ năng Speaking và Writing một cách nhanh chóng. Mình tập trung vào việc xây dựng ý tưởng, từ vựng học thuật và cấu trúc bài viết/nói mạch lạc. Đừng lo, mình sẽ giúp bạn tự tin tỏa sáng trong phòng thi!', 'IELTS Speaking & Writing: Tự tin chinh phục band điểm mơ ước!', NULL, 'Thạc sĩ TESOL, Đại học Ngoại ngữ, ĐHQG Hà Nội. IELTS 8.5 overall.', NULL, NULL, '6 năm kinh nghiệm luyện thi IELTS. Đã giúp hàng trăm học viên đạt target điểm, từ 5.5 lên 7.0+ chỉ sau 3-6 tháng.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.5, 16, 171, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-313', 'Chào các bạn, anh là Bảo. Anh thích Sinh học vì nó giải thích mọi thứ về sự sống quanh ta. Anh có phương pháp dạy dễ hiểu, tập trung vào việc xây dựng sơ đồ tư duy và liên hệ kiến thức với thực tế. Anh sẽ giúp các bạn nắm vững kiến thức nền tảng và kỹ năng giải bài tập, đặc biệt là phần Sinh học phân tử và Di truyền.', 'Sinh Học Thực Quản: Hiểu sâu gốc rễ, nhớ lâu bền vững.', NULL, 'Cử nhân Sinh học Phân tử, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Giúp học sinh có kết quả tốt trong các kỳ thi và olimpic Sinh học.', 'Hà Nội', 'Hải Châu', 'active', true, 4.4, 6, 201, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-314', 'Mình là Ngọc, một người yêu thích Lịch Sử. Mình muốn mang đến một cách học Lịch Sử sinh động, không còn khô khan. Mình sẽ kể chuyện, phân tích dựa trên tư liệu và kết nối các sự kiện lịch sử với nhau. Mình giúp các bạn hình thành tư duy phản biện và cách nhìn nhận vấn đề một cách khách quan. Rất phù hợp cho các bạn muốn học tốt môn Sử và mở rộng hiểu biết.', 'Lịch Sử Gần Gũi: Khám phá quá khứ, hiểu hiện tại.', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội & Nhân văn, ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Lịch sử cho học sinh cấp 3. Đã giúp nhiều học sinh cải thiện điểm số và yêu thích môn học hơn.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.4, 12, 248, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-315', 'Tôi là Hùng, một người đam mê khám phá thế giới. Tôi tin rằng Địa lý không chỉ là những con số, biểu đồ mà là những câu chuyện về con người và cảnh quan. Tôi sử dụng nhiều hình ảnh, video và bản đồ để bài học thêm sinh động. Tôi mong muốn giúp các bạn yêu thích môn Địa lý, hiểu sâu sắc các vấn đề kinh tế - xã hội và tự nhiên.', 'Địa Lý Thực Tế: Thế giới quanh ta - Từ kiến thức sách vở đến đời sống.', NULL, 'Cử nhân Địa lý học, Đại học Sư phạm Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Địa lý cấp 2, 3. Có kinh nghiệm bồi dưỡng học sinh giỏi Địa lý. Giúp học sinh đạt thành tích cao trong các kỳ thi.', 'TP.HCM', 'Quận 7', 'active', true, 4.1, 51, 112, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-316', 'Chào các bạn, mình là Trang. Mình có kinh nghiệm dạy Tiếng Anh cho nhiều trình độ khác nhau. Phương pháp của mình là cá nhân hóa lộ trình học, tập trung vào cả 4 kỹ năng. Mình thích tạo không khí lớp học vui vẻ, thoải mái để học viên không ngại mắc lỗi. Mình rất vui được giúp bạn tự tin hơn với Tiếng Anh.', 'Tiếng Anh Tổng Quát & Luyện Thi: Nghe Nói Đọc Viết - Toàn diện!', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Kinh tế Quốc dân.', NULL, NULL, '3 năm dạy Tiếng Anh cho học viên từ 15-30 tuổi. Hỗ trợ học sinh ôn thi chứng chỉ A2, B1, B2. Giúp nhiều bạn giao tiếp tự tin hơn trong công việc và học tập.', 'Cần Thơ', 'Hải Châu', 'active', true, 4.1, 10, 378, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-317', 'Tôi là Khôi, chuyên gia luyện thi Toán THPT. Tôi có phương pháp systematize kiến thức, giúp học sinh nắm vững từng chuyên đề. Tôi tập trung vào việc rèn luyện kỹ năng giải đề thi nhanh và chính xác. Nếu bạn đang lo lắng về kỳ thi Tốt nghiệp THPT hoặc Đại học, hãy để tôi đồng hành cùng bạn.', 'Toán THPT: Nắm chắc nền tảng, chinh phục mọi dạng bài.', NULL, 'Thạc sĩ Lý thuyết Xác suất và Thống kê Toán học, Đại học Công nghệ - ĐHQG. Cựu học sinh trường THPT Chuyên Amsterdam.', NULL, NULL, '6 năm kinh nghiệm luyện thi Toán cho học sinh cuối cấp. Tỷ lệ học sinh đỗ nguyện vọng 1 đại học luôn trên 90%.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.9, 38, 320, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-318', 'Mình là Nhi, một người bạn đồng hành trên con đường khám phá Văn học. Mình tin mỗi bài văn, bài thơ đều ẩn chứa những câu chuyện, cảm xúc đáng để ta tìm hiểu. Mình thích cách dạy gần gũi, lắng nghe và chia sẻ, giúp các bạn tìm ra giọng văn riêng. Phù hợp với các bạn học sinh THCS và THPT muốn yêu thích môn Văn.', 'Văn Học Tuổi Trẻ: Đồng hành cùng cảm xúc, khơi nguồn sáng tạo.', NULL, 'Cử nhân Văn học, Đại học Văn hóa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Văn cho học sinh cấp 2. Giúp các em có hứng thú với việc đọc và viết văn.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.5, 14, 64, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-319', 'Hello mọi người! Mình là Hoàng Anh. Mình có kinh nghiệm làm việc với trẻ em và có cách truyền đạt Tiếng Anh thật vui và gần gũi. Mình chú trọng phát âm chuẩn, phản xạ nhanh và sự tự tin khi giao tiếp. Bé nhà bạn sẽ vừa học vừa chơi, không hề cảm thấy áp lực. Hãy để mình giúp bé khám phá thế giới Tiếng Anh đầy màu sắc!', 'Tiếng Anh Thiếu Nhi & Thiếu Niên: Vui học, tự tin nói!', NULL, 'Cử nhân Marketing, Đại học RMIT. Chứng chỉ CELTA.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh cho trẻ em 6-14 tuổi. Giúp các bé phát triển toàn diện 4 kỹ năng, đặc biệt là giao tiếp.', 'TP.HCM', 'Quận 7', 'active', true, 4.4, 45, 269, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-320', 'Mình là Hà, mình yêu Hóa học và muốn giúp các bạn chinh phục nó. Mình có phương pháp hệ thống hóa kiến thức từ cơ bản đến nâng cao, đặc biệt chú trọng vào các dạng bài tập thường gặp. Mình thích cùng học viên phân tích lỗi sai và tìm ra cách khắc phục hiệu quả nhất. Hóa học sẽ không còn là nỗi ám ảnh!', 'Hóa Học THPT: Cấu trúc - Phản ứng - Bài tập, giải quyết tất tần tật!', NULL, 'Cử nhân Hóa dược, Đại học Dược Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa cho học sinh lớp 10, 11, 12. Hỗ trợ ôn thi Tốt nghiệp và Đại học khối B.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.6, 50, 363, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-321', 'Chào các bạn, tôi là Huy. Tôi có nền tảng Vật lý vững chắc và kinh nghiệm giảng dạy cho học sinh THPT. Tôi tập trung vào việc xây dựng tư duy khoa học, kỹ năng phân tích và giải quyết vấn đề. Tôi sử dụng nhiều ví dụ minh họa và bài tập vận dụng cao để các bạn làm quen với các dạng đề thi.', 'Vật Lý THPT Chuyên Sâu: Từ lý thuyết đến ứng dụng thực tế.', NULL, 'Cử nhân Vật lý lý thuyết, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Vật Lý. Nhiều học sinh đạt điểm cao trong các kỳ thi học sinh giỏi cấp thành phố và quốc gia.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.3, 10, 350, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-322', 'Mình là Mai Phương, mình rất vui khi được đồng hành cùng các con ở lứa tuổi tiểu học và THCS. Mình tin rằng Toán học có thể rất thú vị và không hề nhàm chán. Phương pháp của mình là kết hợp trò chơi, hình ảnh và các hoạt động tương tác để các con tiếp thu kiến thức một cách tự nhiên và yêu thích môn học này.', 'Toán Tiểu Học & THCS: Xây nền móng vững chắc, nuôi dưỡng tình yêu Toán.', NULL, 'Cử nhân Giáo dục Tiểu học, Đại học Giáo dục, ĐHQG Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán tiểu học và THCS. Giúp các em nắm vững kiến thức, cải thiện kết quả học tập và phát triển tư duy logic.', 'Biên Hòa', 'Quận 3', 'active', true, 4.8, 54, 109, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-323', 'Tôi là Toàn, người sẽ giúp bạn "giải mã" Listening và Reading. Tôi có các chiến lược hiệu quả để tối ưu hóa thời gian làm bài và tăng khả năng hiểu. Tôi tập trung vào việc nhận diện từ khóa, cấu trúc câu và các dạng bài tập phổ biến. Cùng tôi, bạn sẽ tự tin hơn rất nhiều với 2 kỹ năng này.', 'IELTS Listening & Reading: Chiến lược thông minh, điểm số bứt phá!', NULL, 'Cử nhân Kinh tế Đối ngoại, Đại học Ngoại Thương. IELTS 8.0.', NULL, NULL, '4 năm kinh nghiệm luyện thi IELTS Listening & Reading. Giúp học viên tăng trung bình 1.0 - 1.5 band điểm sau khóa học.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.1, 26, 310, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-324', 'Chào các bạn, mình là Thư! Mình yêu Sinh học vì nó giúp ta hiểu rõ về cơ thể mình và thế giới tự nhiên. Mình có cách dạy sinh động, sử dụng nhiều ví dụ thực tế và hình ảnh minh họa. Mình mong muốn giúp các bạn không chỉ thuộc bài mà còn hiểu sâu, nhớ lâu và áp dụng vào thực tế cuộc sống.', 'Sinh Học Thực Tiễn: Khám phá thế giới sống quanh ta.', NULL, 'Cử nhân Y Đa khoa, Đại học Y Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Giúp các em có cái nhìn tổng quan và hứng thú hơn với môn học.', 'Bình Dương', 'Hải Châu', 'active', true, 4.8, 5, 415, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-325', 'Tôi là Huy, sẵn sàng dẫn dắt bạn vào thế giới lập trình Python. Tôi có kinh nghiệm giảng dạy cho người chưa biết gì về code. Phương pháp của tôi là chia nhỏ kiến thức, làm bài tập thực hành ngay lập tức và xây dựng các dự án nhỏ mang tính ứng dụng cao. Bạn sẽ có sản phẩm đầu tay chỉ sau vài buổi học!', 'Lập Trình Python Cho Người Mới Bắt Đầu: Từ A-Z, xây dựng ứng dụng thực tế.', NULL, 'Kỹ sư Phần mềm, Đại học FPT.', NULL, NULL, '3 năm kinh nghiệm làm Developer và dạy lập trình Python. Đã đào tạo cho hơn 100 học viên cá nhân và nhóm.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.8, 25, 250, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-326', 'Mình là Quỳnh Chi, một người mê mẩn những câu chuyện lịch sử. Mình có cách dạy rất khác biệt, không chỉ là thuộc niên đại mà là hiểu bối cảnh, động cơ và hệ quả của các sự kiện. Mình tin rằng Lịch sử sẽ trở nên vô cùng thú vị nếu ta biết cách tiếp cận nó. Phù hợp cho các bạn muốn học Sử một cách tự nhiên, nhớ lâu.', 'Lịch Sử Hấp Dẫn: Kể chuyện quá khứ, mở rộng tầm nhìn.', NULL, 'Cử nhân Lịch sử Đảng, Học viện Chính trị Quốc gia Hồ Chí Minh.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử cho học sinh THPT. Giúp các em có phương pháp học tập hiệu quả, đạt điểm cao.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.2, 15, 273, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-327', 'Tôi là Duy, chuyên gia hỗ trợ sinh viên các môn Toán Cao cấp và Toán Đại cương. Tôi hiểu rõ những khó khăn mà sinh viên thường gặp phải. Phương pháp của tôi là đi thẳng vào vấn đề, giải thích cặn kẽ các khái niệm khó và cung cấp nhiều dạng bài tập mẫu. Mục tiêu của tôi là giúp bạn vượt qua môn Toán một cách dễ dàng.', 'Toán Cao Cấp & Toán Đại Cương: Nền tảng vững cho sinh viên.', NULL, 'Thạc sĩ Toán học Thuần túy, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '7 năm kinh nghiệm dạy Toán đại cương cho sinh viên các trường Đại học. Đã giúp hàng ngàn sinh viên vượt qua các môn Toán khó.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.6, 55, 383, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-328', 'Mình là Trúc, mình giúp bạn nói Tiếng Anh trôi chảy và tự tin trong môi trường công sở. Mình tập trung vào từ vựng chuyên ngành, cách diễn đạt chuyên nghiệp và xử lý tình huống giao tiếp thường gặp. Mình tin rằng với sự luyện tập đúng phương pháp, bạn sẽ nhanh chóng đạt được mục tiêu của mình.', 'Tiếng Anh Thương Mại & Giao Tiếp Công Sở: Tự tin làm việc chuyên nghiệp.', NULL, 'Cử nhân Kinh tế Đối ngoại, Đại học Ngoại thương TP.HCM. Chứng chỉ TEFL.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh cho người đi làm. Đã đào tạo cho nhân viên của nhiều công ty lớn.', 'TP.HCM', 'Quận 7', 'active', true, 4.2, 63, 320, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-329', 'Chào bạn, mình là Tuấn! Mình yêu thích Vật Lý và cách nó giải thích mọi thứ diễn ra xung quanh. Mình có cách dạy rất sáng tạo, dùng các thí nghiệm đơn giản, hình ảnh trực quan và câu chuyện thú vị để truyền tải kiến thức. Mình tin rằng ai cũng có thể yêu Vật Lý nếu được học đúng cách. Hãy cùng nhau khám phá nhé!', 'Vật Lý Vui Nhộn Cho Mọi Lứa Tuổi: Khám phá khoa học qua trải nghiệm.', NULL, 'Cử nhân Khoa học Vật liệu, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý cho học sinh THCS. Giúp các em có nền tảng tốt và niềm yêu thích với môn học.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.5, 53, 438, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-330', 'Mình là Châu, mình tin rằng hiểu biết về Địa lý là chìa khóa để hiểu thế giới. Mình có cách dạy kết hợp giữa kiến thức sách vở và thông tin thực tế, bản đồ, hình ảnh sinh động. Mình sẽ giúp bạn khám phá sự đa dạng của các châu lục, quốc gia và những vấn đề địa lý quan trọng. Rất vui được cùng bạn chinh phục môn Địa Lý!', 'Địa Lý Thế Giới & Việt Nam: Hiểu biết về Trái Đất và con người.', NULL, 'Cử nhân Địa lý học, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý cho học sinh cấp 2. Giúp các em có cái nhìn bao quát và yêu thích môn học hơn.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.3, 6, 194, '2026-06-19 02:57:21.867682', '2026-06-19 02:57:21.867682', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-331', 'Chào các em, thầy là Minh Anh. Thầy tin rằng Toán học không hề khô khan nếu chúng ta tìm được cách tiếp cận phù hợp. Phương pháp của thầy là kết hợp lý thuyết với các bài tập thực tế, đa dạng từ cơ bản đến nâng cao. Thầy rất kiên nhẫn và luôn lắng nghe để hiểu rõ những khó khăn của từng em, giúp các em tự tin hơn với môn học này. Em nào mất gốc hay muốn chinh phục điểm 10 thì gặp thầy nhé!', 'Thầy Minh Anh - Gia sư Toán Lý chuyên sâu, giúp học sinh lấy lại gốc và bứt phá điểm số.', NULL, 'Tốt nghiệp Cử nhân ngành Sư phạm Toán học tại Trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Với 5 năm kinh nghiệm dạy kèm, thầy đã giúp hàng trăm học sinh cải thiện kết quả học tập rõ rệt, nhiều em đạt điểm cao trong các kỳ thi học sinh giỏi. Thầy đã dạy cho nhiều nhóm học sinh từ lớp 6 đến lớp 12.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.3, 15, 148, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-332', 'Xin chào! Mình là Thu Hà, rất vui được đồng hành cùng các bạn trên con đường chinh phục Tiếng Anh. Mình có một niềm đam mê lớn với ngôn ngữ này và luôn muốn chia sẻ nó. Phương pháp học của mình tập trung vào việc thực hành thường xuyên, từ vựng theo ngữ cảnh và ngữ pháp được giải thích một cách logic, dễ hiểu nhất. Mình rất thân thiện và luôn tạo không khí học tập thoải mái, vui vẻ. Các bạn muốn cải thiện khả năng giao tiếp hay chuẩn bị cho các kỳ thi thì nhắn mình nha!', 'Cô Hà - Tiếng Anh giao tiếp & Luyện thi chứng chỉ, phương pháp học dễ nhớ, hiệu quả.', NULL, 'Tốt nghiệp Thạc sĩ chuyên ngành Ngôn ngữ Anh tại Trường Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Mình đã có hơn 4 năm kinh nghiệm dạy Tiếng Anh cho mọi lứa tuổi, từ người mới bắt đầu đến trình độ nâng cao. Mình từng giúp nhiều học viên đạt điểm cao trong các kỳ thi như TOEIC, IELTS. Đặc biệt, mình có kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm và học sinh mất gốc.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.4, 40, 403, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-333', 'Chào các em, thầy là Duy Khang. Vật Lý có thể là một thử thách, nhưng cũng là một môn học vô cùng thú vị nếu ta hiểu bản chất của nó. Thầy luôn cố gắng truyền đạt kiến thức một cách trực quan, sinh động qua các ví dụ thực tế và thí nghiệm (nếu có thể). Mục tiêu của thầy là giúp các em không chỉ nhớ công thức mà còn hiểu sâu sắc các định luật. Thầy khá nghiêm khắc trong việc rèn luyện phương pháp làm bài nhưng cũng rất tâm lý. Phù hợp với các bạn cần hệ thống hóa kiến thức và chuẩn bị cho các kỳ thi quan trọng.', 'Thầy Khang - Gia sư Lý thuyết từ cơ bản đến nâng cao, khơi gợi niềm yêu thích khoa học.', NULL, 'Tốt nghiệp Kỹ sư Vật lý Kỹ thuật tại Trường Đại học Bách khoa Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm làm gia sư Vật Lý cho học sinh THPT. Thầy đã hỗ trợ nhiều học sinh đạt kết quả tốt trong các kỳ thi chuyển cấp và tốt nghiệp. Kinh nghiệm dạy kèm các chuyên đề Vật Lý nâng cao.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.5, 35, 372, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-334', 'Xin chào! Mình là Bích Ngọc, một cô giáo Hóa học đầy nhiệt huyết. Mình biết nhiều bạn cảm thấy Hóa học khá trừu tượng và khó nhớ. Vì vậy, mình luôn cố gắng đưa các khái niệm hóa học vào cuộc sống hàng ngày qua những ví dụ gần gũi, dễ hình dung. Mình sẽ cùng các bạn luyện tập giải thật nhiều dạng bài tập khác nhau, từ cơ bản đến phức tạp, đảm bảo các bạn nắm vững kiến thức và kỹ năng giải đề. Mình là người vui vẻ, hòa đồng và rất kiên nhẫn. Em nào thấy Hóa học là nỗi ám ảnh thì về đội của cô nha!', 'Cô Ngọc - Hóa Học dễ hiểu, bài tập thực hành đa dạng, chinh phục mọi dạng đề thi.', NULL, 'Tốt nghiệp Cử nhân ngành Hóa học tại Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Với 2 năm kinh nghiệm, mình đã giúp nhiều học sinh lớp 10, 11, 12 vượt qua rào cản môn Hóa. Mình có kinh nghiệm dạy theo chương trình sách mới và ôn thi Tốt nghiệp THPT.', 'TP.HCM', 'Hoàng Mai', 'active', true, 5, 41, 230, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-335', 'Chào các em, thầy là Văn Hùng. Văn học là cánh cửa để ta hiểu sâu sắc hơn về con người, cuộc sống và tâm hồn. Phương pháp dạy của thầy tập trung vào việc cảm thụ văn chương, phân tích tinh tế các tác phẩm văn học Việt Nam và thế giới. Bên cạnh đó, thầy sẽ hướng dẫn các em cách tư duy để viết bài văn mạch lạc, giàu ý tưởng và có chiều sâu. Thầy là người có kiến thức sâu rộng, cách truyền đạt lôi cuốn, giúp các em yêu thích môn Văn hơn. Phù hợp với các bạn muốn nâng cao khả năng cảm thụ và kỹ năng làm văn.', 'Thầy Hùng - Gia sư Ngữ văn giàu cảm xúc, phân tích sâu tác phẩm, rèn luyện kỹ năng viết văn.', NULL, 'Tốt nghiệp Cử nhân ngành Sư phạm Ngữ văn tại Trường Đại học Sư phạm TP.HCM.', NULL, NULL, 'Đã có 5 năm kinh nghiệm dạy Ngữ văn tại các trung tâm và dạy kèm cá nhân. Thầy đã giúp nhiều học sinh đạt điểm cao trong các kỳ thi tuyển sinh vào lớp 10 và thi Tốt nghiệp THPT. Có kinh nghiệm luyện thi học sinh giỏi Văn.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.8, 59, 346, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-336', 'Xin chào các bạn! Mình là Mai, một người yêu thích Sinh học và mong muốn lan tỏa tình yêu đó. Mình tin rằng Sinh học không chỉ là những kiến thức sách vở mà còn gắn liền với cuộc sống của chúng ta. Phương pháp của mình là giúp các bạn kết nối bài học với các vấn đề thực tế, từ sức khỏe con người đến thế giới tự nhiên. Mình sẽ giải thích những khái niệm khó một cách đơn giản nhất, có thể sử dụng hình ảnh minh họa hoặc các ví dụ thực tế. Mình là người kiên nhẫn, dễ gần và luôn khuyến khích học sinh đặt câu hỏi. Phù hợp với các bạn học sinh THPT muốn hiểu sâu hơn về cơ thể người, di truyền và sinh thái.', 'Cô Mai - Sinh Học thực tiễn, dễ hiểu, liên hệ bài học với cuộc sống và y khoa.', NULL, 'Tốt nghiệp Cử nhân ngành Sinh học tại Trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, 'Mình đã có 3 năm kinh nghiệm dạy kèm Sinh học cho học sinh cấp 3. Mình đã giúp nhiều bạn cải thiện điểm số và có cái nhìn tích cực hơn về môn học này. Có kinh nghiệm ôn tập kiến thức cho kỳ thi Tốt nghiệp.', 'Hà Nội', 'Hải Châu', 'active', true, 4.2, 35, 318, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-337', 'Chào các bạn, tôi là Quốc Tuấn. Nhiều người nghĩ Lịch Sử là môn học khô khan, chỉ toàn ngày tháng và sự kiện. Nhưng với tôi, Lịch Sử là những câu chuyện đầy cảm hứng, là bài học quý báu cho hiện tại và tương lai. Tôi tiếp cận Lịch Sử bằng cách kể chuyện, phân tích những nguyên nhân - kết quả sâu xa, và giúp các bạn thấy được sự liên hệ giữa các sự kiện lịch sử với thế giới ngày nay. Tôi mong muốn khơi dậy sự tò mò và niềm yêu thích Lịch Sử trong các bạn. Phù hợp với các bạn muốn học Lịch Sử một cách nhẹ nhàng, dễ nhớ và có chiều sâu.', 'Thầy Tuấn - Lịch Sử sống động, kể chuyện hấp dẫn, dễ nhớ, kết nối quá khứ với hiện tại.', NULL, 'Tốt nghiệp Cử nhân ngành Lịch sử tại Trường Đại học Khoa học Xã hội và Nhân văn - ĐHQG Hà Nội.', NULL, NULL, 'Tôi có 4 năm kinh nghiệm dạy Lịch Sử cho học sinh THPT. Tôi đã giúp nhiều học sinh đạt điểm cao trong các bài kiểm tra và thi tuyển sinh. Có kinh nghiệm ôn tập các giai đoạn lịch sử Việt Nam và thế giới.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.3, 5, 405, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-338', 'Xin chào các em! Mình là Lan Anh. Địa Lý không chỉ là tên các quốc gia hay thủ đô, đó là cả một thế giới kỳ thú xung quanh chúng ta. Mình thích sử dụng bản đồ, hình ảnh và các ví dụ thực tế để giúp các bạn hình dung rõ hơn về các hiện tượng địa lý, kinh tế, xã hội. Phương pháp học của mình là xây dựng bản đồ tư duy để hệ thống kiến thức một cách logic, dễ nhớ. Mình là người vui vẻ, tận tâm và luôn tạo môi trường học tập thân thiện. Em nào thấy Địa Lý khó nhằn thì cứ mạnh dạn tìm đến mình nhé!', 'Cô Lan Anh - Địa Lý trực quan, bản đồ tư duy, liên hệ thực tế, dễ học, dễ nhớ.', NULL, 'Tốt nghiệp Cử nhân ngành Địa lý học tại Trường Đại học Khoa học Tự nhiên.', NULL, NULL, 'Mình đã có 3 năm kinh nghiệm dạy Địa lý cho học sinh THCS và THPT. Mình đã giúp nhiều học sinh nắm vững kiến thức, cải thiện kỹ năng đọc và phân tích bản đồ. Có kinh nghiệm ôn tập cho kỳ thi Tốt nghiệp.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.2, 61, 426, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-339', 'Chào các em, thầy là Minh Tuấn. Nếu các em muốn bước vào thế giới công nghệ, lập trình là một kỹ năng không thể thiếu. Thầy sẽ hướng dẫn các em từ những khái niệm cơ bản nhất về máy tính, thuật toán, đến việc xây dựng các chương trình hoàn chỉnh bằng các ngôn ngữ phổ biến như Python, C++. Phương pháp của thầy là ''học đi đôi với hành'', chúng ta sẽ cùng nhau code, sửa lỗi và hoàn thành các dự án nhỏ. Thầy là người kiên nhẫn, tỉ mỉ và có khả năng giải thích các vấn đề kỹ thuật một cách dễ hiểu. Phù hợp với các bạn đam mê công nghệ, muốn học lập trình từ đầu.', 'Thầy Tuấn - Tin Học lập trình từ A-Z, xây dựng tư duy thuật toán, dự án thực tế.', NULL, 'Tốt nghiệp Kỹ sư Công nghệ Thông tin tại Trường Đại học Công nghệ - ĐHQG Hà Nội.', NULL, NULL, 'Có 5 năm kinh nghiệm làm việc trong ngành phát triển phần mềm và 3 năm kinh nghiệm dạy lập trình cho sinh viên, học sinh. Tôi đã hướng dẫn nhiều bạn hoàn thành các dự án cá nhân và tham gia các cuộc thi lập trình.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.6, 22, 158, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-340', 'Hello mọi người! Mình là Mai Phương, rất vui được đồng hành cùng các bạn trên hành trình chinh phục IELTS. Mình hiểu rằng mỗi bạn có một điểm mạnh, điểm yếu và mục tiêu riêng. Vì vậy, mình sẽ xây dựng lộ trình cá nhân hóa, tập trung vào chiến lược làm bài hiệu quả cho từng kỹ năng (Nghe, Nói, Đọc, Viết) và luyện tập phát âm chuẩn. Mình không chỉ dạy kiến thức mà còn truyền cảm hứng, giúp các bạn giữ vững động lực và tự tin. Mình rất nhiệt tình và luôn sẵn sàng giải đáp mọi thắc mắc của các bạn. Dù bạn là người mới bắt đầu hay đang tìm cách nâng điểm, mình đều có thể giúp bạn!', 'Cô Phương - Luyện IELTS điểm cao, chiến lược thông minh, tự tin giao tiếp chuẩn.', NULL, 'Tốt nghiệp Thạc sĩ Ngôn ngữ Anh, đạt IELTS 8.5.', NULL, NULL, 'Với 6 năm kinh nghiệm giảng dạy IELTS, mình đã giúp hàng trăm học viên đạt được mục tiêu điểm số mong muốn, từ 5.5 lên 7.0, 7.5 và cao hơn nữa. Mình có kinh nghiệm dạy IELTS cho học sinh, sinh viên và người đi làm.', 'Đồng Nai', 'Quận 1', 'active', true, 5, 10, 66, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-341', 'Xin chào! Mình là Minh Hiếu. Mình không dạy các em chỉ cách giải một bài toán cụ thể, mà mình muốn giúp các em phát triển tư duy để có thể giải quyết mọi bài toán. Phương pháp của mình là sử dụng các trò chơi, câu đố logic và các dạng bài tập sáng tạo để các em tiếp cận Toán học một cách tự nhiên, hứng thú. Mục tiêu là làm cho việc học trở nên vui vẻ và hiệu quả. Mình rất kiên nhẫn, thích làm việc với các bạn nhỏ và giúp các bạn tìm thấy niềm vui trong Toán học.', 'Thầy Hiếu - Toán tư duy, phát triển kỹ năng giải quyết vấn đề, học mà chơi, chơi mà học.', NULL, 'Tốt nghiệp Cử nhân ngành Toán ứng dụng tại Trường Đại học FPT.', NULL, NULL, 'Có 2 năm kinh nghiệm làm gia sư Toán cho học sinh tiểu học và THCS. Tôi đã giúp nhiều em hình thành tư duy logic và yêu thích môn Toán hơn. Kinh nghiệm dạy các lớp học phát triển tư duy.', 'TP.HCM', 'Hải Châu', 'active', true, 4.3, 44, 133, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-342', 'Chào các bé và các bố mẹ! Mình là Bích Thảo. Mình yêu trẻ con và yêu Tiếng Anh! Mình tin rằng cách tốt nhất để trẻ học Tiếng Anh là thông qua các hoạt động vui chơi, ca hát, kể chuyện và đóng kịch. Mình sẽ tạo ra một môi trường học tập sinh động, đầy màu sắc, nơi các bé có thể thỏa sức khám phá ngôn ngữ một cách tự nhiên nhất. Mình rất nhẹ nhàng, yêu trẻ và luôn biết cách truyền cảm hứng cho các con. Bé nhà mình chưa quen Tiếng Anh hay muốn bé tiếp xúc với ngôn ngữ một cách vui vẻ, hãy tìm đến mình nha!', 'Cô Thảo - Tiếng Anh trẻ em, phương pháp vui nhộn, giao tiếp tự tin từ sớm.', NULL, 'Tốt nghiệp Sư phạm Tiếng Anh Mầm non tại Trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Với 4 năm kinh nghiệm dạy Tiếng Anh cho trẻ em ở lứa tuổi mầm non và tiểu học, mình đã giúp nhiều bé làm quen và yêu thích Tiếng Anh. Mình có kinh nghiệm dạy tại các trường quốc tế và trung tâm ngoại ngữ.', 'Cần Thơ', 'Quận 3', 'active', true, 4.4, 52, 162, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-343', 'Chào các em, thầy là Văn Nam. Mục tiêu của thầy là giúp các em nắm vững kiến thức Vật lý theo chương trình THPT, từ cơ bản đến nâng cao. Thầy sẽ giúp các em hệ thống hóa lại toàn bộ kiến thức một cách logic, dễ nhớ, đồng thời rèn luyện kỹ năng giải các dạng bài tập từ dễ đến khó. Thầy có phương pháp giảng dạy rõ ràng, mạch lạc, bám sát sách giáo khoa và các quy định thi cử. Thầy là người nghiêm túc, trách nhiệm và luôn đặt hiệu quả học tập của học sinh lên hàng đầu. Phù hợp với các bạn muốn củng cố kiến thức nền tảng và chuẩn bị cho các kỳ thi quan trọng.', 'Thầy Nam - Lý thuyết Vật lý THPT, hệ thống hóa kiến thức, ôn thi hiệu quả.', NULL, 'Tốt nghiệp Cử nhân ngành Sư phạm Vật lý tại Trường Đại học Vinh.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy kèm Vật lý cho học sinh THPT. Tôi đã giúp nhiều thế hệ học sinh vượt qua môn Vật lý và đạt điểm cao trong các kỳ thi tốt nghiệp. Kinh nghiệm ôn thi đại học khối A.', 'TP.HCM', 'Hải Châu', 'active', true, 4.2, 62, 153, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-344', 'Xin chào! Mình là Thu Trang. Mình hiểu rằng Hóa học Đại cương và Hóa học Hữu cơ thường là hai phần kiến thức gây nhiều khó khăn cho sinh viên và học sinh. Mình có phương pháp giảng dạy chi tiết, đi sâu vào bản chất của từng phản ứng, từng loại hợp chất. Mình sẽ cung cấp cho các bạn hệ thống bài tập đa dạng, được chọn lọc kỹ lưỡng để các bạn có thể áp dụng kiến thức đã học một cách hiệu quả. Mình là người tỉ mỉ, cẩn thận và luôn sẵn lòng giải thích lại cho đến khi các bạn hiểu rõ. Phù hợp với các bạn sinh viên năm nhất, học sinh lớp 11, 12 và ôn thi.', 'Cô Trang - Hóa học đại cương & Hữu cơ, giải thích cặn kẽ, bài tập bám sát.', NULL, 'Tốt nghiệp Thạc sĩ ngành Hóa hữu cơ tại Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, 'Đã có 4 năm kinh nghiệm dạy Hóa học cho sinh viên đại học và học sinh THPT. Tôi đã giúp nhiều bạn nắm vững kiến thức và cải thiện điểm số môn Hóa học. Kinh nghiệm dạy Hóa Đại cương và Hóa Hữu cơ.', 'Bình Dương', 'Quận 7', 'active', true, 4.8, 57, 403, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-345', 'Chào các bạn, tôi là Minh Quân. Tôi tin rằng Văn học không chỉ là những trang sách cũ mà còn là những câu chuyện đầy sức sống, phản ánh những vấn đề của xã hội hiện đại. Phương pháp của tôi là tiếp cận các tác phẩm văn học một cách chủ động, phân tích các khía cạnh tâm lý nhân vật, các tầng nghĩa ẩn dụ và mối liên hệ với đời sống đương đại. Tôi muốn các bạn đọc văn không chỉ để thi cử mà còn để cảm nhận, để suy ngẫm. Tôi là người có kiến thức sâu rộng, cách diễn đạt lôi cuốn và có khả năng truyền lửa cho học trò. Phù hợp với các bạn muốn khám phá chiều sâu của văn học và phát triển khả năng cảm thụ văn chương.', 'Thầy Quân - Văn học hiện đại, phân tích tác phẩm theo hướng mới, khơi gợi cảm xúc.', NULL, 'Tốt nghiệp Cử nhân ngành Văn học tại Trường Đại học Văn hóa.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Văn, chủ yếu tập trung vào các tác phẩm văn học hiện đại và phương pháp nghị luận văn học. Tôi đã giúp nhiều học sinh có cái nhìn mới mẻ và yêu thích môn Văn hơn.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.5, 56, 210, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-346', 'Xin chào các bạn! Mình là Thúy Vy. Sinh học là môn học kết nối chúng ta với chính cơ thể mình và thế giới xung quanh. Mình thích chia sẻ kiến thức Sinh học qua lăng kính ứng dụng thực tế, đặc biệt là trong lĩnh vực Y học và Bảo vệ môi trường. Mình sẽ giúp các bạn hiểu rõ hơn về các quá trình sinh học phức tạp một cách dễ hiểu nhất, có thể thông qua các ví dụ minh họa, hình ảnh trực quan hoặc thảo luận về các vấn đề thời sự liên quan. Mình là người nhiệt tình, sáng tạo và luôn mong muốn tạo ra những giờ học bổ ích, thú vị. Phù hợp với các bạn muốn hiểu sâu hơn về sức khỏe, sinh thái và các vấn đề khoa học đời sống.', 'Cô Vy - Sinh học ứng dụng, liên hệ Y học & Môi trường, bài giảng sinh động.', NULL, 'Tốt nghiệp Cử nhân ngành Công nghệ sinh học tại Trường Đại học Công nghệ.', NULL, NULL, '', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.2, 44, 191, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-347', 'Chào các em, thầy là Minh Đức. Lịch sử Việt Nam giai đoạn cận đại là một chương vô cùng quan trọng, với nhiều biến động và bài học sâu sắc. Phương pháp của tôi là đi sâu vào phân tích bối cảnh lịch sử, nguyên nhân, diễn biến và hệ quả của các sự kiện, giúp các em không chỉ nhớ mà còn hiểu rõ bản chất vấn đề. Tôi luôn khuyến khích các em đặt câu hỏi, đưa ra quan điểm cá nhân và liên hệ với tình hình hiện tại. Tôi là người có kiến thức chuyên sâu, cách trình bày mạch lạc và mang tính học thuật. Phù hợp với các bạn học sinh muốn tìm hiểu kỹ lưỡng về lịch sử dân tộc và rèn luyện tư duy phân tích.', 'Thầy Đức - Lịch sử Việt Nam cận đại, phân tích sự kiện, bài học lịch sử.', NULL, 'Tốt nghiệp Thạc sĩ Lịch sử Việt Nam tại Trường Đại học Khoa học Xã hội và Nhân văn - ĐHQG TP.HCM.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Lịch sử Việt Nam, tập trung vào giai đoạn cận đại và hiện đại. Tôi đã hỗ trợ nhiều học sinh đạt kết quả tốt trong các kỳ thi và cuộc thi học thuật về Lịch sử.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.2, 7, 411, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-348', 'Xin chào các bạn! Mình là Bích Hằng. Mình tin rằng Địa lý kinh tế và Địa lý Việt Nam không chỉ là những con số khô khan mà còn là bức tranh sinh động về sự phát triển của đất nước và thế giới. Mình sẽ sử dụng bản đồ, biểu đồ, số liệu thống kê và các ví dụ thực tế để giúp các bạn hiểu rõ hơn về các mối quan hệ kinh tế, xã hội, vị trí địa lý và tài nguyên thiên nhiên. Phương pháp học của mình là kết hợp lý thuyết với bài tập thực hành, giúp các bạn rèn luyện kỹ năng phân tích và nhận định. Mình là người cẩn thận, nhiệt huyết và luôn cố gắng làm cho giờ học trở nên bổ ích nhất. Phù hợp với các bạn muốn nắm vững kiến thức Địa lý kinh tế và Địa lý Việt Nam.', 'Cô Hằng - Địa lý kinh tế & Việt Nam, bản đồ, số liệu, liên hệ thực tế.', NULL, 'Tốt nghiệp Cử nhân ngành Địa lý Kinh tế tại Trường Đại học Kinh tế Quốc dân.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Địa lý cho học sinh THPT, tập trung vào các kiến thức Địa lý kinh tế và Địa lý Việt Nam. Tôi đã giúp nhiều học sinh hiểu sâu hơn về các vấn đề kinh tế - xã hội và cải thiện kỹ năng làm bài thi.', 'Hà Nội', 'Ninh Kiều', 'active', true, 5, 32, 418, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-349', 'Xin chào! Tôi là Gia Bảo. Trong môi trường làm việc hiện đại, kỹ năng Tin học văn phòng, đặc biệt là sử dụng thành thạo Excel, là vô cùng quan trọng. Tôi không chỉ dạy bạn cách sử dụng các chức năng cơ bản, mà còn đi sâu vào các kỹ thuật nâng cao như Pivot Table, VLOOKUP, Macros, VBA để bạn có thể phân tích dữ liệu, tự động hóa các tác vụ một cách hiệu quả. Phương pháp của tôi là thực hành liên tục với các tình huống thực tế, giúp bạn áp dụng ngay kiến thức vào công việc. Tôi là người kiên nhẫn, có kinh nghiệm làm việc trong môi trường doanh nghiệp. Phù hợp với các bạn sinh viên chuẩn bị đi làm, người đi làm muốn nâng cao kỹ năng văn phòng.', 'Thầy Bảo - Tin học văn phòng, Excel nâng cao, kỹ năng số cho công việc.', NULL, 'Tốt nghiệp Kỹ sư Hệ thống Thông tin tại Trường Đại học Công nghệ - ĐHQG TP.HCM.', NULL, NULL, 'Có 5 năm kinh nghiệm làm việc trong lĩnh vực phân tích dữ liệu và tư vấn công nghệ. Tôi đã đào tạo và hướng dẫn hàng trăm nhân viên sử dụng thành thạo các công cụ tin học văn phòng, đặc biệt là Excel.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.6, 41, 154, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-350', 'Hello các bạn! Mình là Thùy Linh. Mình biết rằng Speaking và Writing là hai kỹ năng thường gây nhiều áp lực nhất cho người học IELTS. Mình có phương pháp giúp các bạn cải thiện khả năng phản xạ Speaking một cách tự nhiên và xây dựng cấu trúc bài Writing mạch lạc, logic, sử dụng từ vựng và ngữ pháp đa dạng. Mình thường xuyên cập nhật các xu hướng ra đề thi và cung cấp cho các bạn các bài mẫu chất lượng. Mình là người vui vẻ, năng động và luôn tạo động lực cho học viên. Hãy cùng mình chinh phục band điểm mong muốn nhé!', 'Cô Linh - Luyện Speaking & Writing IELTS, phản xạ nhanh, cấu trúc bài chuẩn.', NULL, 'Tốt nghiệp Đại học chuyên ngành Ngôn ngữ Anh, từng đạt IELTS 7.5.', NULL, NULL, 'Với 4 năm kinh nghiệm dạy IELTS, mình đã giúp nhiều học viên tăng điểm số Speaking và Writing đáng kể. Kinh nghiệm dạy kèm cá nhân và nhóm nhỏ, tập trung vào hai kỹ năng chính.', 'Đồng Nai', 'Quận 7', 'active', true, 4.8, 13, 203, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-351', 'Chào các em, thầy là Hoàng Hải. Toán học THPT đòi hỏi sự chắc chắn về kiến thức nền tảng và khả năng áp dụng linh hoạt. Thầy sẽ giúp các em hệ thống hóa kiến thức một cách logic, đồng thời trang bị cho các em các phương pháp giải nhanh các dạng toán trắc nghiệm và tự luận. Chúng ta sẽ cùng nhau luyện tập qua rất nhiều đề thi thử, phân tích lỗi sai và rút kinh nghiệm. Thầy là người nghiêm túc, kỷ luật nhưng cũng rất tâm huyết với nghề. Phù hợp với các bạn học sinh đang cần củng cố kiến thức và luyện thi hiệu quả cho các kỳ thi quan trọng.', 'Thầy Hải - Gia sư Toán THPT, phương pháp giải nhanh, luyện đề chuyên sâu.', NULL, 'Tốt nghiệp Kỹ sư Xây dựng tại Trường Đại học Giao thông Vận tải.', NULL, NULL, 'Có 6 năm kinh nghiệm dạy kèm Toán THPT. Tôi đã giúp nhiều học sinh đạt điểm cao trong kỳ thi Tốt nghiệp và thi đại học. Có kinh nghiệm ôn luyện cho các lớp chuyên Toán.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.2, 22, 67, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-352', 'Xin chào mọi người! Mình là Mỹ Linh. Mình tin rằng Tiếng Anh là chìa khóa để mở ra nhiều cơ hội trong cuộc sống. Mình muốn giúp các bạn xây dựng nền tảng Tiếng Anh vững chắc, từ ngữ pháp đến từ vựng, và quan trọng nhất là sự tự tin khi giao tiếp. Phương pháp của mình là kết hợp bài giảng chi tiết, các hoạt động thực hành tương tác và cung cấp nhiều ví dụ thực tế để các bạn có thể áp dụng ngay. Mình là người thân thiện, kiên nhẫn và luôn tạo không khí học tập tích cực. Dù bạn ở trình độ nào, mình đều có thể giúp bạn tiến bộ!', 'Cô Linh - Tiếng Anh tổng quát, giao tiếp tự tin, ngữ pháp vững chắc.', NULL, 'Tốt nghiệp Cử nhân ngành Ngôn ngữ Anh tại Trường Đại học Kinh tế - Tài chính.', NULL, NULL, 'Với 5 năm kinh nghiệm dạy Tiếng Anh tổng quát cho người đi làm và học sinh, mình đã giúp nhiều học viên cải thiện khả năng giao tiếp và tự tin hơn khi sử dụng Tiếng Anh trong công việc và cuộc sống.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.7, 21, 358, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-353', 'Chào các em, thầy là Tuấn Anh. Vật lý là môn học khám phá những quy luật của tự nhiên, và việc hiểu bản chất của các hiện tượng vật lý là điều quan trọng nhất. Thầy sẽ giúp các em nắm vững các khái niệm cốt lõi, phân tích sâu các định luật và công thức. Chúng ta sẽ cùng nhau giải quyết nhiều dạng bài tập khác nhau, từ cơ bản đến nâng cao, để các em có thể tự tin áp dụng kiến thức vào bài thi. Thầy là người có phương pháp giảng dạy rõ ràng, logic và có khả năng truyền cảm hứng cho học sinh. Phù hợp với các bạn cần một nền tảng Vật lý vững chắc và cải thiện điểm số.', 'Thầy Anh - Vật lý THPT, giải thích bản chất, bài tập ứng dụng đa dạng.', NULL, 'Tốt nghiệp Kỹ sư Điện tử Viễn thông tại Trường Đại học Bách khoa TP.HCM.', NULL, NULL, 'Có 4 năm kinh nghiệm dạy kèm Vật lý cho học sinh THPT. Tôi đã giúp nhiều học sinh hiểu sâu bài học và đạt kết quả tốt trong các kỳ thi. Có kinh nghiệm dạy các chuyên đề Vật lý về Điện - Điện từ.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.9, 55, 294, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-354', 'Xin chào các bạn! Mình là Ngọc Mai. Hóa học lớp 10, 11, 12 có thể khá thử thách, nhưng mình tin rằng với phương pháp phù hợp, các bạn hoàn toàn có thể chinh phục môn học này. Mình tập trung vào việc giải thích các khái niệm hóa học một cách đơn giản, dễ hiểu, có thể bằng sơ đồ hoặc ví dụ minh họa. Mình sẽ cùng các bạn luyện tập giải các dạng bài tập từ cơ bản đến nâng cao, bám sát chương trình học và các dạng đề thi. Mình là người kiên nhẫn, thân thiện và luôn sẵn sàng hỗ trợ các bạn. Phù hợp với các bạn học sinh THPT muốn cải thiện kết quả học tập môn Hóa.', 'Cô Mai - Hóa học lớp 10-12, bài giảng dễ hiểu, ôn thi hiệu quả.', NULL, 'Tốt nghiệp Cử nhân ngành Sư phạm Hóa học tại Trường Đại học Sài Gòn.', NULL, NULL, 'Với 3 năm kinh nghiệm dạy Hóa học cho học sinh THPT, tôi đã giúp nhiều em vượt qua khó khăn và đạt điểm số mong muốn. Kinh nghiệm ôn tập kiến thức cho kỳ thi Tốt nghiệp THPT.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.8, 13, 132, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-355', 'Chào các em, thầy là Minh Quang. Văn học giúp chúng ta khám phá thế giới nội tâm phong phú và những giá trị nhân văn sâu sắc. Phương pháp của thầy là giúp các em xây dựng kỹ năng làm văn mạch lạc, có luận điểm rõ ràng và lập luận chặt chẽ. Đồng thời, thầy sẽ hướng dẫn các em cách cảm thụ và phân tích các tác phẩm văn học một cách tinh tế, từ đó khơi gợi tình yêu văn chương trong các em. Thầy là người có kiến thức sâu rộng, cách truyền đạt lôi cuốn và luôn tạo động lực học tập cho học sinh. Phù hợp với các bạn muốn cải thiện kỹ năng làm văn và yêu thích môn Văn.', 'Thầy Quang - Ngữ văn THCS & THPT, rèn luyện kỹ năng làm văn, cảm thụ văn chương.', NULL, 'Tốt nghiệp Cử nhân ngành Sư phạm Ngữ văn tại Trường Đại học Giáo dục - ĐHQG Hà Nội.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Ngữ văn cho học sinh THCS và THPT. Tôi đã giúp nhiều học sinh đạt điểm cao trong các kỳ thi và cải thiện khả năng cảm thụ văn chương.', 'Đồng Nai', 'Quận 3', 'active', true, 4.9, 58, 111, '2026-06-19 02:58:03.969021', '2026-06-19 02:58:03.969021', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-356', 'Chào các em, cô Mai Anh đây! Với kinh nghiệm giảng dạy Tiếng Anh lâu năm, cô tin rằng mình có thể giúp các em chinh phục môn học này. Phương pháp của cô tập trung vào việc phát triển toàn diện 4 kỹ năng Nghe - Nói - Đọc - Viết, đặc biệt chú trọng phản xạ giao tiếp. Cô vui tính, nhiệt tình và kiên nhẫn, luôn tạo không khí học tập thoải mái và hiệu quả nhất.', 'Giáo viên Tiếng Anh 9 năm kinh nghiệm, giúp học sinh đạt điểm cao', NULL, 'Tốt nghiệp Đại học Sư phạm Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 9 năm kinh nghiệm dạy Tiếng Anh cho học sinh từ cấp 2 đến cấp 3. Từng giúp nhiều học sinh cải thiện điểm số rõ rệt và tự tin hơn trong giao tiếp. Thành thạo luyện thi chứng chỉ Starters, Movers, Flyers.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.2, 16, 219, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-357', 'Xin chào! Em là Hùng, cựu Thủ khoa ngành Toán Tin của ĐH Bách Khoa. Em có niềm đam mê lớn với Toán học và mong muốn truyền lửa cho các bạn. Em áp dụng phương pháp giảng dạy logic, đi sâu vào bản chất vấn đề, giúp các bạn không chỉ giải được bài tập mà còn hiểu sâu sắc kiến thức. Em rất kiên trì, tỉ mỉ, phù hợp với các bạn học sinh cần lấy lại gốc hoặc muốn bứt phá điểm số.', 'Thủ khoa Toán ĐH Bách Khoa, luyện thi THPT Quốc gia hiệu quả', NULL, 'Thủ khoa ngành Toán Tin, Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Đã có 3 năm kinh nghiệm dạy Toán online và offline. Kinh nghiệm luyện thi THPT Quốc gia cho nhiều khóa học sinh, tỷ lệ đỗ nguyện vọng 1 cao. Phụ trách dạy các dạng bài từ cơ bản đến nâng cao, đặc biệt là các chuyên đề luyện thi.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.8, 61, 314, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-358', 'Chào bạn, mình là Trang. Mình tin rằng Văn học không chỉ là những con chữ khô khan mà là cả một thế giới cảm xúc và tư tưởng. Mình sẽ đồng hành cùng bạn khám phá vẻ đẹp ấy qua những câu chuyện, những tác phẩm ý nghĩa. Phương pháp của mình là khơi gợi sự sáng tạo, giúp bạn diễn đạt ý tưởng một cách mạch lạc, giàu cảm xúc. Mình là người bạn đồng hành thân thiện, dễ gần, đặc biệt hợp với các bạn ngại Văn hoặc muốn nâng cao khả năng cảm thụ văn học.', 'Yêu Văn, yêu đời! Cô Trang giúp bạn tìm thấy vẻ đẹp của Ngữ Văn', NULL, 'Sinh viên năm cuối ngành Văn học, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Từng đạt giải Nhì học sinh giỏi Văn cấp Tỉnh. Có 2 năm kinh nghiệm dạy kèm Ngữ Văn cho học sinh THPT. Đã giúp nhiều bạn cải thiện điểm số và có cái nhìn tích cực hơn về môn Văn.', 'Hà Nội', 'Quận 7', 'active', true, 4.4, 34, 383, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-359', 'Xin chào! Em là Đức, cử nhân Vật Lý. Em có khả năng nhìn nhận vấn đề một cách logic và diễn giải các khái niệm Vật Lý phức tạp một cách đơn giản, dễ hiểu nhất. Phương pháp của em là kết hợp lý thuyết với thực nghiệm, giúp các em hình dung rõ ràng hiện tượng vật lý. Em rất kỷ luật, nghiêm túc trong học tập nhưng cũng rất gần gũi, sẵn sàng giải đáp mọi thắc mắc của học trò. Phù hợp với các bạn đang gặp khó khăn với môn Vật Lý hoặc cần ôn luyện thi chuyên sâu.', 'Chuyên gia Vật Lý, giải thích dễ hiểu, luyện thi hiệu quả', NULL, 'Cử nhân Vật Lý, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 4 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Đã có nhiều học sinh đạt điểm cao trong các kỳ thi, một số em theo học các ngành kỹ thuật, y dược. Chuyên luyện thi theo chương trình sách mới và các dạng bài nâng cao.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.9, 33, 326, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-360', 'Chào các bạn, mình là Ngọc. Mình đã chinh phục IELTS 8.0 và hiểu rõ những khó khăn các bạn đang gặp phải. Mình sẽ xây dựng lộ trình học IELTS cá nhân hóa, tập trung vào việc cải thiện từng kỹ năng còn yếu, cung cấp chiến lược làm bài hiệu quả và nguồn tài liệu chọn lọc. Mình rất kiên trì, động viên và luôn truyền cảm hứng học tập. Phù hợp với mọi trình độ, đặc biệt là các bạn muốn đạt điểm IELTS cao trong thời gian ngắn.', 'IELTS 8.0, cam kết band điểm mục tiêu, lộ trình cá nhân hóa', NULL, 'Tốt nghiệp ngành Ngôn ngữ Anh, Đại học Ngoại thương.', NULL, NULL, 'Có 3 năm kinh nghiệm luyện thi IELTS. Tỷ lệ học viên đạt mục tiêu band điểm cao (6.5 - 8.0) lên đến 90%. Đã huấn luyện cho nhiều đối tượng: học sinh, sinh viên, người đi làm.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.4, 26, 331, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-361', 'Xin chào! Em là Tuấn, một lập trình viên Fullstack. Em yêu thích việc chia sẻ kiến thức về Tin học, từ những khái niệm cơ bản nhất đến các kỹ năng lập trình chuyên sâu. Phương pháp của em là "học đi đôi với hành", luôn khuyến khích học viên thực hành qua các dự án thực tế. Em là người hướng dẫn tận tâm, kiên nhẫn, giúp học viên tự tin làm chủ công nghệ. Phù hợp với mọi lứa tuổi, đặc biệt là các bạn yêu thích máy tính và muốn khám phá thế giới lập trình.', 'Lập trình viên, dạy Tin học từ cơ bản đến nâng cao, thực hành nhiều', NULL, 'Kỹ sư Công nghệ Thông tin, Đại học Công nghệ.', NULL, NULL, 'Có 5 năm kinh nghiệm làm lập trình viên. Đã tham gia giảng dạy Tin học văn phòng và lập trình cơ bản cho nhiều khóa học. Kinh nghiệm hướng dẫn học sinh, sinh viên làm các dự án cá nhân và đồ án tốt nghiệp.', 'Biên Hòa', 'Bình Thạnh', 'active', true, 4.1, 9, 305, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-362', 'Chào các bạn, mình là My. Mình đang học năm 3 ngành Y đa khoa và có niềm yêu thích đặc biệt với môn Sinh học. Mình tin rằng Sinh học rất gần gũi với cuộc sống và mình sẽ giúp các bạn nhìn thấy điều đó qua các ví dụ thực tế, dễ hiểu. Phương pháp của mình là giải thích cặn kẽ, liên kết kiến thức giữa các phần và hướng dẫn cách học hiệu quả. Mình là một người bạn nhiệt tình, vui vẻ, sẵn sàng hỗ trợ các bạn học tốt môn Sinh.', 'Sinh viên Y khoa, dạy Sinh học dễ hiểu, kết nối kiến thức thực tế', NULL, 'Sinh viên Y khoa, Đại học Y Hà Nội.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy kèm Sinh học cho học sinh THPT. Giúp nhiều học sinh cải thiện điểm số và xây dựng nền tảng kiến thức vững chắc. Có khả năng giải thích các khái niệm sinh học phức tạp một cách đơn giản.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.4, 25, 279, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-363', 'Xin chào! Em là Huy, có bằng Thạc sĩ chuyên ngành Hóa học. Em có kinh nghiệm dày dặn trong việc giảng dạy và nghiên cứu Hóa học. Phương pháp của em là xây dựng kiến thức một cách hệ thống, logic, đi từ cơ bản đến nâng cao, kết hợp các thí nghiệm minh họa (nếu có thể). Em rất nghiêm túc, tỉ mỉ và luôn đặt mục tiêu cao cho học viên. Em mong muốn giúp các bạn yêu thích và làm chủ môn Hóa học, đặc biệt là ôn luyện hiệu quả cho kỳ thi đại học.', 'Thạc sĩ Hóa học, phương pháp khoa học, luyện thi đại học', NULL, 'Thạc sĩ Hóa học, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 6 năm kinh nghiệm dạy Hóa học tại trung tâm và dạy kèm. Đã đào tạo nhiều học sinh đạt điểm cao môn Hóa trong các kỳ thi tuyển sinh đại học. Chuyên sâu về luyện thi theo chương trình cải cách và các dạng bài tập khó.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.1, 25, 262, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-364', 'Chào các em, cô là Thu Trang. Hiện tại cô đang là giáo viên Toán tại một trường THCS. Cô có kinh nghiệm giảng dạy lâu năm và hiểu rõ những khó khăn học sinh thường gặp phải ở cấp THCS. Phương pháp của cô là đi từ gốc, xây dựng nền tảng kiến thức vững chắc, giúp các em tự tin giải quyết mọi dạng bài tập. Cô luôn kiên nhẫn, lắng nghe và động viên học trò. Cô mong muốn đồng hành cùng các em chinh phục môn Toán một cách nhẹ nhàng và hiệu quả.', 'Giáo viên Toán THCS, xây dựng nền tảng vững chắc', NULL, 'Cử nhân Sư phạm Toán học, Đại học Sư phạm.', NULL, NULL, 'Có 10 năm kinh nghiệm giảng dạy Toán học cấp THCS. Tỷ lệ học sinh khá giỏi môn Toán luôn đạt mức cao. Có kinh nghiệm phụ đạo cho học sinh yếu kém và bồi dưỡng học sinh giỏi.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.1, 36, 449, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-365', 'Hi everyone! Em là Khang, sinh viên năm 3 Sư phạm Tiếng Anh. Em có niềm đam mê với ngôn ngữ này và luôn cố gắng trau dồi kỹ năng bản thân. Em tin rằng học Tiếng Anh cần sự chủ động và thực hành liên tục. Phương pháp của em là tập trung vào luyện phát âm chuẩn, xây dựng vốn từ vựng theo chủ đề và thực hành giao tiếp qua các hoạt động tương tác. Em là người năng động, nhiệt tình và luôn tạo môi trường học tập vui vẻ, thoải mái.', 'Sinh viên Sư phạm Anh, phát âm chuẩn, giao tiếp tự tin', NULL, 'Sinh viên Sư phạm Tiếng Anh, Đại học Sư phạm.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy Tiếng Anh cho người mới bắt đầu và học sinh cấp 2. Giúp học viên cải thiện phát âm, phản xạ giao tiếp và tự tin hơn khi nói. Đã từng tham gia các câu lạc bộ Tiếng Anh và tổ chức hoạt động ngoại khóa.', 'Bình Dương', 'Quận 7', 'active', true, 4.5, 54, 88, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-366', 'Chào các bạn, mình là Hằng. Mình yêu thích môn Địa lý vì nó giúp mình hiểu hơn về thế giới xung quanh, về con người và văn hóa. Mình sẽ cùng các bạn khám phá những điều thú vị đó qua cách học trực quan, sinh động, kết hợp bản đồ, hình ảnh và những câu chuyện. Phương pháp của mình là làm cho Địa lý trở nên gần gũi, dễ nhớ và thú vị hơn. Mình là người bạn đồng hành nhiệt tình, dễ mến, đặc biệt phù hợp với các bạn muốn tìm lại hứng thú với môn Địa.', 'Yêu Địa lý, giúp bạn khám phá thế giới qua từng trang sách', NULL, 'Sinh viên ngành Địa lý học, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 1 năm kinh nghiệm dạy kèm Địa lý cho học sinh THCS. Đã giúp các bạn nhỏ hình dung rõ hơn về các khu vực địa lý và nhớ kiến thức một cách dễ dàng. Có khả năng trình bày bài giảng sinh động.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.9, 13, 370, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-367', 'Xin chào! Em là Đạt. Em có một tình yêu sâu sắc với văn chương và mong muốn chia sẻ niềm yêu thích ấy. Em tin rằng mỗi người đều có khả năng cảm thụ và diễn đạt văn học theo cách riêng. Phương pháp của em là khơi gợi tư duy phản biện, hướng dẫn cách phân tích tác phẩm sâu sắc và rèn luyện kỹ năng viết sao cho mạch lạc, giàu hình ảnh, cảm xúc. Em rất kiên nhẫn, thấu hiểu và luôn tạo không khí học tập cởi mở, thân thiện.', 'Yêu văn chương, giúp bạn diễn đạt mạch lạc, giàu cảm xúc', NULL, 'Cử nhân Ngữ văn, Đại học Sư phạm.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Ngữ văn cho học sinh THPT. Tỷ lệ học sinh tiến bộ rõ rệt về điểm số và kỹ năng làm bài. Đã từng ôn luyện cho học sinh thi học sinh giỏi Văn.', 'Hà Nội', 'Phú Nhuận', 'active', true, 5, 10, 437, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-368', 'Xin chào ba mẹ và các con! Cô là Lan Hương, giáo viên Tiếng Anh tiểu học. Cô rất yêu trẻ con và luôn tìm cách làm cho giờ học Tiếng Anh trở nên thật vui nhộn, bổ ích. Phương pháp của cô là lồng ghép kiến thức vào các trò chơi, bài hát, hoạt động tương tác để các con tiếp thu một cách tự nhiên và hứng thú nhất. Cô kiên nhẫn, dịu dàng và luôn quan tâm đến sự phát triển của từng bé. Cô tin rằng mọi đứa trẻ đều có thể học tốt Tiếng Anh.', 'Giáo viên Tiếng Anh tiểu học, phương pháp vui nhộn, yêu trẻ', NULL, 'Cử nhân Sư phạm Tiếng Anh, Đại học Sư phạm.', NULL, NULL, 'Có 7 năm kinh nghiệm dạy Tiếng Anh cho học sinh tiểu học. Giúp hàng trăm bé làm quen và yêu thích môn Tiếng Anh. Có kinh nghiệm luyện thi các chứng chỉ Cambridge (Starters, Movers, Flyers) cho lứa tuổi thiếu nhi.', 'Đồng Nai', 'Ninh Kiều', 'active', true, 4.9, 63, 277, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-369', 'Chào mọi người, em là Quân. Em đang theo học ngành Khoa học Máy tính và có nền tảng Toán học khá vững chắc. Em có phương pháp học Toán theo hướng logic, giải quyết vấn đề một cách có hệ thống. Em sẽ giúp các bạn nắm vững kiến thức sách giáo khoa, làm quen với các dạng bài tập từ cơ bản đến nâng cao và rèn luyện kỹ năng giải đề thi. Em là người nghiêm túc, có trách nhiệm và luôn cố gắng truyền đạt kiến thức một cách dễ hiểu nhất.', 'Sinh viên Khoa học Máy tính, giải Toán logic, bám sát chương trình', NULL, 'Sinh viên Khoa học Máy tính, Đại học Công nghệ.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy kèm Toán cho học sinh THPT. Giúp nhiều học sinh cải thiện đáng kể kết quả học tập. Có kinh nghiệm ôn luyện thi học kỳ và thi THPT Quốc gia.', 'Bình Dương', 'Quận 1', 'active', true, 4, 36, 231, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-370', 'Chào các em, cô là Thuý. Cô hiểu rằng nhiều bạn cảm thấy Hóa học thật khô khan và khó nhớ. Cô có kinh nghiệm giúp các bạn vượt qua rào cản này. Phương pháp của cô là làm cho Hóa học trở nên sống động bằng cách liên hệ với thực tế, giải thích cặn kẽ cơ chế phản ứng và cung cấp mẹo ghi nhớ hiệu quả. Cô luôn kiên nhẫn, lắng nghe và động viên các em. Cô tin rằng với sự hướng dẫn đúng đắn, các bạn sẽ yêu thích môn Hóa.', 'Chuyên Hóa học, giúp bạn vượt qua nỗi sợ Hóa', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Đã giúp nhiều học sinh từ mất gốc lấy lại kiến thức và đạt điểm số mong muốn. Chuyên ôn luyện thi học kỳ và thi đại học khối A, B.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 5, 25, 343, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-371', 'Xin chào! Em là Bình. Em từng là học sinh chuyên Lý và đã đạt nhiều thành tích trong các kỳ thi. Em hiểu rõ những yêu cầu của chương trình Vật Lý, đặc biệt là các dạng bài thi học sinh giỏi và thi vào lớp chuyên. Phương pháp của em là đi sâu vào bản chất, rèn luyện kỹ năng giải quyết vấn đề nhanh chóng và chính xác. Em là người nghiêm túc, có kỷ luật và luôn mong muốn truyền đạt kiến thức một cách hiệu quả nhất cho học trò.', 'Cựu học sinh chuyên Lý, luyện thi THPT Quốc gia và lớp chuyên', NULL, 'Cựu học sinh chuyên Vật Lý, giành Huy chương Bạc Olympic Vật Lý.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Vật Lý. Đã hướng dẫn thành công nhiều học sinh thi đỗ vào các trường chuyên Vật Lý và đạt điểm cao trong kỳ thi THPT Quốc gia. Chuyên bồi dưỡng các đội tuyển học sinh giỏi.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.3, 64, 123, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-372', 'Hi there! Mình là Nhung, đạt IELTS 7.5. Mình rất vui được chia sẻ kinh nghiệm và chiến lược chinh phục IELTS với các bạn. Mình tin rằng mỗi người có một cách học khác nhau, vì vậy mình sẽ lắng nghe và xây dựng kế hoạch học tập phù hợp nhất cho từng bạn, từ ngữ pháp, từ vựng, phát âm đến kỹ năng làm bài thi. Mình là người năng động, nhiệt huyết và luôn cố gắng tạo động lực cho học viên.', 'IELTS 7.5, kinh nghiệm luyện thi cho mọi trình độ', NULL, 'Tốt nghiệp ngành Kinh tế đối ngoại, Đại học Ngoại thương.', NULL, NULL, 'Có 2 năm kinh nghiệm luyện thi IELTS. Đã giúp nhiều học viên đạt được band điểm mục tiêu, từ 5.5 lên 7.0+. Phù hợp với các bạn chuẩn bị du học, xin việc hoặc nâng cao trình độ Tiếng Anh.', 'Biên Hòa', 'Bình Thạnh', 'active', true, 4.3, 24, 442, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-373', 'Xin chào! Em là Hải, chuyên gia về Tin học ứng dụng. Em có kinh nghiệm giảng dạy cả về lập trình (đặc biệt là Python) và Tin học văn phòng (Excel nâng cao). Phương pháp của em là thực hành là chính, giúp học viên áp dụng ngay kiến thức vào công việc hoặc học tập. Em là người tỉ mỉ, kiên nhẫn và có khả năng giải thích các vấn đề kỹ thuật một cách dễ hiểu. Em phù hợp với các bạn muốn học lập trình từ đầu hoặc muốn nâng cao kỹ năng sử dụng Excel.', 'Chuyên gia Tin học, lập trình Python, Excel cho mọi đối tượng', NULL, 'Kỹ sư Công nghệ thông tin, Đại học FPT.', NULL, NULL, 'Có 4 năm kinh nghiệm làm việc trong lĩnh vực IT. Đã trực tiếp giảng dạy và đào tạo về Python, SQL, Excel cho nhiều cá nhân và doanh nghiệp. Có kinh nghiệm xây dựng các ứng dụng đơn giản bằng Python.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.3, 47, 439, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-374', 'Chào các em và quý phụ huynh, cô là Bích Thủy. Cô là giáo viên Toán tiểu học và rất yêu mến các con. Cô hiểu rằng Toán học ở lứa tuổi này cần sự sinh động, gần gũi. Phương pháp của cô là sử dụng nhiều hình ảnh minh họa, đồ dùng học tập, trò chơi để các con tiếp thu kiến thức một cách tự nhiên và hứng thú. Cô rất kiên nhẫn, dịu dàng và luôn quan tâm đến cảm xúc của từng học sinh. Cô mong muốn giúp các con xây dựng nền tảng Toán học vững chắc ngay từ đầu.', 'Giáo viên Toán tiểu học, yêu trẻ, phương pháp trực quan', NULL, 'Cử nhân Sư phạm Toán học, Đại học Sư phạm.', NULL, NULL, 'Có 8 năm kinh nghiệm dạy Toán cho học sinh tiểu học. Giúp hàng trăm bé hình thành tình yêu với môn Toán và đạt kết quả tốt. Có kinh nghiệm luyện thi vào các trường chuyên cấp 2.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.1, 55, 314, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-375', 'Chào bạn, mình là Hiếu. Mình có một niềm đam mê cháy bỏng với Văn học và luôn tìm tòi những góc nhìn mới mẻ về các tác phẩm. Mình tin rằng Văn học là cách để chúng ta hiểu sâu sắc hơn về cuộc sống và con người. Phương pháp của mình là khuyến khích tư duy sáng tạo, rèn luyện cách cảm thụ tác phẩm tinh tế và hướng dẫn bạn diễn đạt ý tưởng một cách độc đáo, giàu hình ảnh. Mình là người bạn đồng hành thú vị, có khả năng lắng nghe và thấu hiểu.', 'Thích Văn học, giúp bạn tìm cảm hứng và diễn đạt tinh tế', NULL, 'Cử nhân Văn học, Đại học Văn hóa.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy kèm Ngữ văn. Đã giúp nhiều học sinh phát huy khả năng viết luận và phân tích văn học. Có khả năng khơi gợi hứng thú học Văn cho những bạn cảm thấy nhàm chán.', 'Cần Thơ', 'Quận 3', 'active', true, 4.5, 40, 416, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-376', 'Xin chào! Em là Ngọc Ánh. Em đã từng học Vật Lý ở bậc đại học và có kinh nghiệm làm quen với các dạng bài tập từ cơ bản đến nâng cao. Em sẽ giúp các bạn hiểu rõ bản chất của từng định luật, công thức và hướng dẫn cách áp dụng để giải các bài tập một cách logic, nhanh chóng. Em là người cẩn thận, tỉ mỉ và luôn sẵn lòng giải đáp mọi thắc mắc. Em phù hợp với các bạn học sinh THPT đang cần củng cố kiến thức Vật Lý.', 'Cựu sinh viên Vật Lý, hướng dẫn học và làm bài tập hiệu quả', NULL, 'Cựu sinh viên Vật Lý, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 2 năm kinh nghiệm dạy kèm Vật Lý. Đã giúp nhiều học sinh nắm vững kiến thức và cải thiện điểm số trong các bài kiểm tra. Có kinh nghiệm ôn tập kiến thức sách giáo khoa.', 'Đồng Nai', 'Quận 7', 'active', true, 4.2, 5, 212, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-377', 'Hi! Tớ là Tuấn Anh, đạt IELTS 8.0. Tớ có kinh nghiệm dày dặn trong việc luyện thi IELTS, đặc biệt là hai kỹ năng Speaking và Writing vốn là thách thức của nhiều bạn. Tớ sẽ chia sẻ những bí quyết, cấu trúc và từ vựng ăn điểm, giúp bạn tự tin thể hiện bản thân trong bài thi. Tớ là người năng động, dí dỏm và luôn tạo không khí học tập hứng khởi.', 'IELTS 8.0, luyện Speaking và Writing chuyên sâu', NULL, 'Tốt nghiệp ngành Tài chính Ngân hàng, Đại học Kinh tế Quốc dân.', NULL, NULL, 'Có 3 năm kinh nghiệm luyện thi IELTS. Giúp nhiều học viên đạt điểm cao cho kỹ năng Speaking và Writing (7.0 - 8.0). Đã đào tạo cho nhiều đối tượng, từ học sinh, sinh viên đến người đi làm.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.8, 22, 71, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-378', 'Chào các bạn, mình là Xuân. Mình có niềm yêu thích đặc biệt với thế giới sinh vật, từ những loài nhỏ bé đến những hệ sinh thái phức tạp. Mình tin rằng Sinh học là môn học vô cùng thú vị nếu chúng ta biết cách tiếp cận. Phương pháp của mình là sử dụng các hình ảnh trực quan, video sinh động và các ví dụ thực tế để giúp các bạn dễ dàng hình dung và ghi nhớ kiến thức. Mình là người vui vẻ, thân thiện và luôn sẵn sàng hỗ trợ các bạn học tốt môn Sinh.', 'Yêu Sinh học, giúp bạn khám phá thế giới vi sinh vật', NULL, 'Sinh viên ngành Sinh học, Đại học Khoa học Tự nhiên.', NULL, NULL, 'Có 1 năm kinh nghiệm dạy kèm Sinh học cho học sinh THCS. Giúp các bạn có cái nhìn mới mẻ và hứng thú hơn với môn học. Có khả năng giải thích các khái niệm về vi sinh vật và di truyền một cách dễ hiểu.', 'Hà Nội', 'Quận 1', 'active', true, 4.4, 45, 70, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-379', 'Xin chào! Em là Thắng. Em có một tình yêu đặc biệt với những câu chuyện quá khứ và mong muốn chia sẻ niềm đam mê ấy. Em tin rằng Lịch sử không hề khô khan mà đầy những bài học ý nghĩa và những sự kiện ly kỳ. Phương pháp của em là kể chuyện một cách sinh động, hấp dẫn, kết hợp tư liệu hình ảnh và bản đồ để các bạn dễ dàng tiếp thu và ghi nhớ. Em là người nhiệt tình, có kiến thức sâu rộng và luôn tạo không khí học tập hứng khởi.', 'Yêu Lịch sử, kể chuyện lịch sử hấp dẫn, dễ nhớ', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy kèm Lịch sử. Đã giúp nhiều học sinh cải thiện điểm số và có cái nhìn tích cực hơn về môn Sử. Có khả năng khơi gợi sự tò mò và yêu thích lịch sử ở học viên.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.4, 40, 333, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-380', 'Chào các con, cô là Kim Chi. Cô có kinh nghiệm giảng dạy Địa lý cho học sinh THCS. Cô hiểu rằng môn Địa lý đòi hỏi sự ghi nhớ kiến thức về các vùng miền, hiện tượng tự nhiên và kinh tế - xã hội. Phương pháp của cô là trình bày kiến thức một cách khoa học, dễ hiểu, có hệ thống, kết hợp bản đồ và hình ảnh minh họa. Cô luôn kiên nhẫn, dịu dàng và quan tâm đến từng học sinh. Cô mong muốn giúp các con học tốt môn Địa lý và yêu thêm quê hương đất nước.', 'Cô Chi dạy Địa lý, kiến thức bám sát sách giáo khoa, dễ hiểu', NULL, 'Cử nhân Địa lý học, Đại học Sư phạm.', NULL, NULL, 'Có 5 năm kinh nghiệm dạy Địa lý THCS. Đã giúp nhiều học sinh nắm vững kiến thức, làm bài kiểm tra và thi học kỳ đạt kết quả tốt. Chuyên ôn luyện kiến thức theo chương trình sách giáo khoa.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.8, 16, 269, '2026-06-19 02:58:38.186696', '2026-06-19 02:58:38.186696', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-381', 'Chào các em, mình là Minh Anh. Mình tin rằng Toán học không hề khô khan nếu biết cách tiếp cận. Mình thường dùng các ví dụ thực tế, sơ đồ tư duy để bài học trở nên sinh động. Mình phù hợp với các bạn đang mất gốc hoặc muốn nâng cao kiến thức Toán THPT, đặc biệt là ôn thi Đại học.', 'Thầy Toán 9-12: Giúp học sinh vượt qua nỗi sợ, chinh phục điểm cao!', NULL, 'Tốt nghiệp ngành Sư phạm Toán học, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Có 4 năm kinh nghiệm dạy kèm Toán cho học sinh từ lớp 9 đến 12. Tỷ lệ học sinh đạt điểm khá giỏi trên 90%. Đã giúp nhiều em đạt điểm 8+ trong kỳ thi THPT Quốc gia.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.6, 16, 379, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-382', 'Xin chào, mình là Bích Ngọc. Mình yêu thích việc giúp học viên khám phá vẻ đẹp của Tiếng Anh. Phương pháp của mình tập trung vào giao tiếp thực tế, luyện nghe nói thường xuyên và xây dựng sự tự tin. Rất vui được đồng hành cùng các bạn ở mọi lứa tuổi, đặc biệt là học sinh cần cải thiện điểm số trên lớp.', 'Giáo viên Tiếng Anh: Giao tiếp tự tin, phát âm chuẩn, thi cử đạt kết quả tốt.', NULL, 'Cử nhân chuyên ngành Ngôn ngữ Anh, Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho mọi lứa tuổi. Đã giúp nhiều học sinh cải thiện rõ rệt khả năng giao tiếp và điểm số trên trường. Thành thạo các chương trình học phổ thông.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.7, 8, 149, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-383', 'Hello mọi người, mình là Hoàng Nam. Mình có niềm đam mê lớn với Vật Lý và muốn truyền lửa đó cho các bạn. Mình luôn cố gắng làm cho các định luật, công thức trở nên trực quan, sinh động qua thí nghiệm ảo và bài tập ứng dụng. Phù hợp với học sinh THPT, đặc biệt là các bạn chuẩn bị thi Đại học khối A.', 'Thầy Lý: Giải thích mọi khái niệm Vật lý phức tạp một cách dễ hiểu nhất.', NULL, 'Sinh viên năm 4 ngành Vật lý Kỹ thuật, Đại học Bách khoa Hà Nội.', NULL, NULL, 'Đã dạy kèm Vật Lý cho hơn 30 học sinh trong 3 năm qua. Nhiều em đã tiến bộ vượt bậc, đạt điểm cao trong các kỳ thi. Có kinh nghiệm ôn thi Đại học và các kỳ thi học sinh giỏi.', 'Đà Nẵng', 'Thủ Đức', 'active', true, 4, 52, 428, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-384', 'Chào các em, mình là Thu Trang. Mình tin rằng Hóa học không đáng sợ như các bạn nghĩ đâu. Mình có cách dạy dễ hiểu, bám sát chương trình và đặc biệt là giúp các em nhớ các phản ứng, công thức một cách logic. Mình rất kiên nhẫn và luôn động viên học sinh của mình. Ưu tiên dạy cho học sinh THPT.', 'Cô Hóa: Từ Hóa học cơ bản đến nâng cao, chinh phục mọi dạng bài.', NULL, 'Tốt nghiệp ngành Hóa học, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy kèm Hóa học. Đã hỗ trợ nhiều học sinh cải thiện điểm số, đặc biệt là các phần kiến thức khó. Có kinh nghiệm ôn thi học sinh giỏi cấp tỉnh.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.2, 56, 99, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-385', 'Xin chào, mình là Gia Bảo. Mình yêu văn chương và muốn chia sẻ niềm yêu thích đó với các bạn. Mình sẽ cùng các em đi sâu vào từng tác phẩm, phân tích tâm lý nhân vật, và rèn luyện kỹ năng viết sao cho giàu cảm xúc, mạch lạc. Mình hợp với các bạn muốn cải thiện điểm Văn, thi học sinh giỏi hoặc đơn giản là yêu thích môn học này.', 'Thầy Văn: Khơi nguồn cảm hứng, phân tích tác phẩm sâu sắc, viết văn hay.', NULL, 'Sinh viên năm 3 ngành Văn học, Trường Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Văn cho học sinh THCS và THPT. Giúp nhiều em đạt điểm 8+ trong các bài kiểm tra và thi học kỳ. Có khả năng phát hiện và bồi dưỡng năng khiếu viết văn.', 'TP.HCM', 'Quận 3', 'active', true, 4.7, 27, 352, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-386', 'Chào mọi người, mình là Kim Chi. Mình có một cách tiếp cận Sinh học rất gần gũi và thực tế, giúp các bạn không còn thấy môn học này khô khan. Mình thường dùng hình ảnh, sơ đồ và liên hệ bài học với cuộc sống xung quanh. Phù hợp với học sinh THCS và THPT muốn nắm vững kiến thức cơ bản.', 'Cô Sinh: Sinh học gần gũi, dễ hiểu, kiến thức bám sát sách giáo khoa.', NULL, 'Tốt nghiệp ngành Sư phạm Sinh học, Đại học Sư phạm TP.HCM.', NULL, NULL, '1.5 năm kinh nghiệm dạy kèm Sinh học. Đã giúp nhiều học sinh cải thiện điểm số và hiểu sâu hơn về các khái niệm sinh học. Kinh nghiệm dạy các chương trình mới.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.7, 16, 156, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-387', 'Xin chào, mình là Minh Tuấn. Mình tin rằng Lịch sử không phải là những con số và sự kiện khô khan, mà là những câu chuyện đầy ý nghĩa. Mình sẽ giúp các bạn khám phá những góc nhìn mới, ghi nhớ kiến thức một cách khoa học và tự tin chinh phục các bài kiểm tra, thi cử. Mình đặc biệt phù hợp với học sinh THPT.', 'Thầy Sử: Lịch sử sống động, khắc sâu kiến thức, thi cử tự tin.', NULL, 'Cử nhân ngành Lịch sử, Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Lịch sử. Đã giúp nhiều học sinh cải thiện đáng kể kết quả học tập, đặc biệt là với các phần kiến thức khó nhớ. Có kinh nghiệm ôn thi tốt nghiệp THPT.', 'Cần Thơ', 'Quận 1', 'active', true, 4.4, 47, 140, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-388', 'Chào các em, mình là Mai Phương. Mình yêu thích Địa lý và mong muốn lan tỏa tình yêu đó tới các bạn. Mình sẽ cùng các em ''du lịch'' khắp nơi qua bản đồ, tìm hiểu về các hiện tượng tự nhiên, kinh tế, xã hội một cách sinh động và dễ nhớ nhất. Phù hợp với học sinh THCS và THPT.', 'Cô Địa: Khám phá thế giới qua bản đồ, hiểu về đất nước và con người.', NULL, 'Tốt nghiệp ngành Địa lý học, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '1 năm kinh nghiệm dạy kèm Địa lý. Đã giúp nhiều học sinh nắm vững kiến thức, cải thiện kỹ năng đọc bản đồ và phân tích số liệu. Có kinh nghiệm ôn thi học kỳ.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.7, 5, 101, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-389', 'Hi mọi người, mình là Tuấn Kiệt. Nếu bạn đang tìm cách để làm quen với thế giới lập trình hoặc muốn nâng cao kỹ năng giải thuật, mình sẵn sàng giúp đỡ. Mình thích dạy theo hướng thực hành, giải thích các khái niệm trừu tượng bằng ví dụ cụ thể. Phù hợp với các bạn học sinh, sinh viên muốn học lập trình và tư duy thuật toán.', 'Thầy Tin: Lập trình dễ dàng, thuật toán thông minh, tư duy logic phát triển.', NULL, 'Sinh viên năm 3 ngành Khoa học Máy tính, Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Đã hướng dẫn 2 khóa học lập trình cơ bản cho sinh viên. Có kinh nghiệm giải bài tập Tin học cho học sinh cấp 3. Thành thạo Python và C++.', 'Đồng Nai', 'Quận 3', 'active', true, 4.5, 41, 65, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-390', 'Xin chào, mình là Minh Châu. Mình đã chinh phục IELTS và mong muốn giúp bạn cũng làm được điều đó. Mình tập trung vào việc xây dựng chiến lược học tập phù hợp với từng bạn, luyện tập kỹ năng nghe, nói, đọc, viết một cách bài bản và chiến thuật làm bài thi. Rất vui được đồng hành cùng bạn đạt mục tiêu IELTS của mình.', 'Chuyên gia IELTS: Cam kết band điểm, lộ trình cá nhân hóa, luyện thi hiệu quả.', NULL, 'IELTS 8.0 Overall. Tốt nghiệp ngành Ngôn ngữ Anh, Đại học RMIT Việt Nam.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS. Đã giúp hơn 50 học viên đạt target band điểm mong muốn, từ 6.0 đến 7.5+. Có kinh nghiệm dạy cả online và offline.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.1, 18, 246, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-391', 'Chào các em, mình là Văn Hùng. Mình thích cách tiếp cận Toán học từ những điều cơ bản nhất, giúp các em hiểu sâu bản chất thay vì chỉ học thuộc lòng. Mình thường sử dụng nhiều dạng bài tập đa dạng để các em làm quen và tự tin hơn. Mình đặc biệt phù hợp với các bạn học sinh THCS.', 'Gia sư Toán THCS: Xây nền tảng vững chắc, khơi dậy niềm yêu thích học Toán.', NULL, 'Sinh viên năm 2 ngành Sư phạm Toán học, Đại học Sư phạm Hà Nội.', NULL, NULL, '1 năm kinh nghiệm dạy kèm Toán cho học sinh lớp 6-9. Nhiều em đã cải thiện điểm số rõ rệt. Có kinh nghiệm ôn tập theo chương trình sách giáo khoa mới.', 'Đồng Nai', 'Phú Nhuận', 'active', true, 4.7, 27, 383, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-392', 'Xin chào! Mình là Mai Lan. Mình yêu thích việc giúp mọi người vượt qua rào cản ngôn ngữ. Phương pháp của mình là tạo môi trường học tập vui vẻ, tương tác, tập trung vào việc sử dụng Tiếng Anh trong đời sống. Mình rất kiên nhẫn và luôn tạo điều kiện để học viên thực hành. Phù hợp với người đi làm, sinh viên và học sinh muốn giao tiếp tốt.', 'Tiếng Anh giao tiếp: Tự tin nói chuyện, ngữ pháp chắc, từ vựng phong phú.', NULL, 'Cử nhân ngành Biên phiên dịch, Đại học Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp. Đã giúp nhiều học viên tự tin hơn khi nói chuyện với người nước ngoài. Có kinh nghiệm dạy các lớp Tiếng Anh thương mại cơ bản.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.7, 49, 212, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-393', 'Chào các bạn, mình là Minh Khôi. Mình có cách tiếp cận Vật Lý theo hướng tư duy logic và giải quyết vấn đề. Mình sẽ cùng các bạn phân tích từng dạng bài, tìm ra phương pháp giải nhanh và chính xác nhất. Mục tiêu của mình là giúp các bạn không còn sợ Vật Lý và đạt kết quả cao trong các kỳ thi.', 'Thầy Lý THPT: Giải bài tập Vật Lý khó, thi Đại học điểm cao.', NULL, 'Thạc sĩ ngành Vật lý Lý thuyết, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Tỷ lệ học sinh đỗ Đại học các trường top là rất cao. Có kinh nghiệm ôn thi các chuyên đề Vật Lý nâng cao.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.2, 17, 375, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-394', 'Xin chào các em, mình là Minh Thư. Mình có niềm say mê với Văn học và muốn chia sẻ điều đó. Mình sẽ giúp các em hiểu rõ yêu cầu của từng dạng đề, cách tìm ý, lập dàn ý và triển khai bài viết một cách logic, mạch lạc, giàu cảm xúc. Mình rất mong được đồng hành cùng các em trên con đường chinh phục điểm cao môn Văn.', 'Cô Văn THPT: Phân tích đề thi, rèn luyện kỹ năng viết bài nghị luận.', NULL, 'Tốt nghiệp ngành Sư phạm Ngữ văn, Đại học Sư phạm Huế.', NULL, NULL, '4 năm kinh nghiệm dạy Văn cho học sinh THPT. Nhiều học sinh của mình đã đạt điểm xuất sắc trong kỳ thi tốt nghiệp và các cuộc thi học sinh giỏi Văn.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.8, 53, 354, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-395', 'Xin chào các bạn sinh viên, mình là Thành Đạt. Mình chuyên hỗ trợ các bạn giải quyết khó khăn với Toán Cao cấp như Giải tích, Đại số tuyến tính, Xác suất thống kê. Mình có cách giải thích cặn kẽ, dễ hiểu, giúp các bạn nắm vững kiến thức để hoàn thành tốt môn học của mình.', 'Toán Cao cấp: Hỗ trợ sinh viên Đại học, Cao đẳng các môn Toán.', NULL, 'Thạc sĩ ngành Toán học ứng dụng, Đại học Kinh tế Quốc dân.', NULL, NULL, '6 năm kinh nghiệm dạy Toán Cao cấp cho sinh viên các trường Đại học, Cao đẳng. Đã giúp hàng trăm sinh viên qua môn thành công. Có kinh nghiệm dạy online qua zoom.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.8, 46, 311, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-396', 'Chào các bé! Cô là Thảo Uyên đây! Cô tin rằng học Tiếng Anh sẽ thật vui và thú vị. Chúng mình sẽ cùng nhau học qua bài hát, trò chơi, truyện kể và các hoạt động sáng tạo. Mục tiêu là để các con không còn sợ Tiếng Anh mà thấy yêu thích môn học này ngay từ đầu.', 'Tiếng Anh cho thiếu nhi: Vui học, hát ca, làm quen với Tiếng Anh.', NULL, 'Cử nhân ngành Sư phạm Tiếng Anh mầm non, Đại học Sài Gòn.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh cho trẻ em lứa tuổi 3-10. Phương pháp giảng dạy sáng tạo, tạo hứng thú học tập cho trẻ. Nhiều phụ huynh phản hồi tích cực.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.7, 29, 184, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-397', 'Hi, mình là Đức Huy. Nếu bạn đang gặp khó khăn với kỹ năng Viết và Nói trong IELTS, mình có thể giúp bạn. Mình sẽ hướng dẫn bạn cách xây dựng ý tưởng, cấu trúc bài viết, phát triển từ vựng và ngữ pháp, cũng như luyện tập kỹ năng phản xạ nói một cách tự nhiên và mạch lạc nhất.', 'Luyện thi IELTS Writing & Speaking: Đạt điểm cao, tự tin thể hiện.', NULL, 'IELTS 8.0 (Listening 8.5, Reading 8.5, Writing 7.0, Speaking 7.5). Sinh viên năm 4 ngành Kinh tế Đối ngoại, Đại học Ngoại thương.', NULL, NULL, '1.5 năm kinh nghiệm luyện thi IELTS Writing & Speaking. Đã giúp nhiều học viên cải thiện điểm số đáng kể và đạt mục tiêu. Có kiến thức sâu về các tiêu chí chấm thi.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.9, 32, 312, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-439', 'Mình là Lan Hương, rất vui được đồng hành cùng các bạn học sinh khá giỏi Toán. Mình tập trung vào việc phát triển tư duy logic, khả năng phân tích và sáng tạo trong giải toán. Phương pháp của mình là cùng học sinh tìm ra nhiều cách giải khác nhau cho một bài toán, khuyến khích sự chủ động và tự học.', 'Cô Hương: Toán nâng cao, phương pháp tư duy sáng tạo', NULL, 'Thạc sĩ Toán học ứng dụng, Đại học Công nghệ TP.HCM.', NULL, NULL, '6 năm kinh nghiệm dạy Toán cho học sinh THPT chuyên và nâng cao. Giúp nhiều học sinh đạt giải trong các kỳ thi Toán quốc gia và quốc tế.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.5, 48, 65, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-398', 'Chào các em, mình là Thanh Hà. Mình có phương pháp dạy Hóa học dễ hiểu, bám sát chương trình phổ thông. Mình sẽ giúp các em hệ thống lại kiến thức, làm quen với các dạng bài tập từ cơ bản đến nâng cao, đặc biệt là các phần khó như hữu cơ và vô cơ. Rất mong được giúp các em học tốt môn Hóa.', 'Hóa học THPT: Ôn tập kiến thức, giải bài tập hóa.', NULL, 'Tốt nghiệp ngành Sư phạm Hóa học, Đại học Vinh.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Hóa học cho học sinh THPT. Giúp nhiều em vượt qua các kỳ thi với kết quả tốt. Kinh nghiệm dạy theo chương trình sách giáo khoa mới.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.2, 34, 320, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-399', 'Xin chào, mình là Quang Minh. Mình chuyên dạy Tin học văn phòng cho người mới bắt đầu hoặc những ai muốn nâng cao kỹ năng sử dụng Word, Excel, PowerPoint. Mình tập trung vào các kỹ năng thực tế, giúp các bạn sử dụng thành thạo các công cụ này để phục vụ học tập và công việc một cách hiệu quả.', 'Tin học văn phòng: Word, Excel, PowerPoint chuyên nghiệp.', NULL, 'Tốt nghiệp Đại học chuyên ngành Công nghệ Thông tin.', NULL, NULL, '3 năm kinh nghiệm giảng dạy Tin học văn phòng. Đã đào tạo cho nhiều cá nhân và nhóm nhỏ, giúp họ tự tin ứng dụng vào công việc. Có chứng chỉ MOS.', 'Bình Dương', 'Quận 1', 'active', true, 4.8, 51, 402, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-400', 'Chào các em, mình là Thu Hương. Mình yêu thích Lịch sử và có cách kể chuyện làm cho các sự kiện lịch sử trở nên sống động, dễ nhớ. Mình sẽ giúp các em không chỉ học thuộc lòng mà còn hiểu được bối cảnh, ý nghĩa của từng giai đoạn lịch sử. Phù hợp với học sinh THCS và THPT.', 'Lịch sử hấp dẫn: Từ quá khứ đến hiện tại, hiểu sâu sắc ý nghĩa.', NULL, 'Cử nhân ngành Lịch sử Đảng Cộng sản Việt Nam, Học viện Báo chí và Tuyên truyền.', NULL, NULL, '1.5 năm kinh nghiệm dạy kèm Lịch sử. Giúp học sinh có cái nhìn toàn diện hơn về lịch sử, cải thiện điểm số trên lớp. Có khả năng truyền cảm hứng học tập.', 'Bình Dương', 'Thủ Đức', 'active', true, 4.7, 44, 378, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-401', 'Chào các em, mình là Bá Long. Mình có kinh nghiệm ôn luyện Sinh học cho kỳ thi THPT Quốc gia. Mình sẽ giúp các em hệ thống hóa kiến thức theo từng chuyên đề, luyện tập các dạng câu hỏi thường gặp và cung cấp các mẹo làm bài hiệu quả. Mục tiêu là giúp các em đạt điểm số tốt nhất có thể.', 'Sinh học THPT: Chuẩn bị tốt cho kỳ thi THPT Quốc gia.', NULL, 'Sinh viên năm 4 ngành Y Đa khoa, Đại học Y Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Sinh học. Chuyên sâu về kiến thức Sinh học THPT và ôn thi Đại học. Tỷ lệ học sinh đạt điểm 7+ cao.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.1, 61, 226, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-402', 'Chào các con! Cô là Phương Linh. Cô rất vui được đồng hành cùng các con khám phá thế giới Toán học qua những bài toán tư duy, logic. Cô sẽ giúp các con làm quen với các dạng bài, rèn luyện sự nhạy bén và yêu thích môn Toán từ sớm. Cô rất kiên nhẫn và yêu trẻ nhỏ.', 'Toán tư duy: Phát triển kỹ năng giải quyết vấn đề cho trẻ Tiểu học.', NULL, 'Tốt nghiệp ngành Giáo dục Tiểu học, chuyên ngành Toán, Đại học Thủ đô.', NULL, NULL, '2 năm kinh nghiệm dạy Toán tư duy cho học sinh Tiểu học. Phát triển nhiều hoạt động học tập sáng tạo, giúp trẻ hứng thú với môn học. Phụ huynh đánh giá cao sự tận tâm.', 'Hà Nội', 'Quận 1', 'active', true, 4.8, 47, 450, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-403', 'Hi, mình là Văn Tùng. Nếu bạn đang làm việc hoặc học tập trong lĩnh vực IT và cần trau dồi Tiếng Anh chuyên ngành, mình có thể giúp bạn. Mình tập trung vào từ vựng, thuật ngữ chuyên ngành, cách đọc hiểu tài liệu và giao tiếp trong môi trường IT. Đảm bảo bạn sẽ tự tin hơn khi làm việc với các dự án quốc tế.', 'Tiếng Anh chuyên ngành IT: Thuật ngữ, giao tiếp, tài liệu.', NULL, 'Cử nhân ngành Kỹ thuật Phần mềm, Đại học FPT.', NULL, NULL, '2 năm kinh nghiệm làm việc trong ngành IT và đã từng tham gia các dự án quốc tế. Có kinh nghiệm hướng dẫn Tiếng Anh chuyên ngành cho đồng nghiệp và các bạn sinh viên.', 'Hà Nội', 'Hải Châu', 'active', true, 4.9, 44, 413, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-404', 'Xin chào, mình là Khánh Vy. Mình có kinh nghiệm và phương pháp ôn luyện toàn diện cho kỳ thi IELTS. Mình sẽ giúp bạn đánh giá trình độ, xây dựng lộ trình học tập hiệu quả, rèn luyện từng kỹ năng và làm quen với áp lực phòng thi. Cam kết đồng hành cùng bạn đạt mục tiêu IELTS.', 'Luyện thi IELTS: Nghe, Đọc, Viết, Nói - Trọn bộ kỹ năng.', NULL, 'IELTS 7.5 Overall. Cử nhân ngành Kinh tế, Đại học Kinh tế TP.HCM.', NULL, NULL, '2.5 năm kinh nghiệm luyện thi IELTS. Đã giúp nhiều học viên đạt band điểm mong muốn, từ 6.0 đến 7.0. Có kinh nghiệm luyện thi cho cả mục đích học thuật và định cư.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.9, 26, 118, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-405', 'Chào các bạn, mình là Anh Khoa. Mình có cách học Địa lý bám sát đề thi THPT Quốc gia, tập trung vào việc sử dụng bản đồ, phân tích số liệu và nắm vững các kiến thức trọng tâm. Mình sẽ giúp các bạn làm quen với các dạng bài tập, rèn luyện kỹ năng để tự tin bước vào kỳ thi.', 'Địa lý thi THPT: Bản đồ, kiến thức, kỹ năng làm bài.', NULL, 'Sinh viên năm 3 ngành Địa lý học, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, '1 năm kinh nghiệm dạy kèm Địa lý THPT. Giúp học sinh ôn tập hiệu quả và cải thiện kết quả thi. Có kinh nghiệm hệ thống hóa kiến thức theo từng vùng, miền.', 'TP.HCM', 'Quận 3', 'active', true, 4.7, 39, 434, '2026-06-19 02:58:59.709144', '2026-06-19 02:58:59.709144', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-406', 'Chào các em, cô Lan Anh đây! Cô có 5 năm kinh nghiệm giảng dạy Tiếng Anh cho học sinh cấp 2, 3. Phương pháp của cô là kết hợp học qua trò chơi, hoạt động tương tác để các em không bị nhàm chán. Cô đặc biệt thích làm việc với những bạn hơi rụt rè, muốn xây dựng sự tự tin khi giao tiếp.', 'Giáo viên Tiếng Anh giàu kinh nghiệm, giúp học sinh chinh phục mọi kỳ thi', NULL, 'Tốt nghiệp Đại học Ngoại ngữ Quốc gia Hà Nội, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, 'Đã giúp hơn 100 học sinh đạt điểm cao trong các bài kiểm tra. Luyện thi chứng chỉ Starters, Movers, Flyers cho các em nhỏ. Có kinh nghiệm dạy theo chương trình Cambridge.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 4.2, 38, 101, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-407', 'Xin chào, mình là Hùng, cựu sinh viên Toán Tin ĐH Khoa học Tự nhiên. Mình có niềm đam mê lớn với Toán học và cách truyền đạt nó một cách dễ hiểu nhất. Phương pháp của mình là đi từ gốc rễ vấn đề, luyện tập có hệ thống và khai thác sâu các dạng bài thi. Mình phù hợp với các bạn đang cần lấy lại gốc hoặc muốn chinh phục điểm cao thi THPT Quốc gia.', 'Thầy Hùng - Chuyên gia Toán lý thuyết và luyện thi Đại học', NULL, 'Cử nhân Toán học, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy kèm Toán, đặc biệt là ôn thi vào lớp 10 và thi THPT. Tỷ lệ đỗ Đại học của học sinh mình luôn trên 90%. Đã từng dạy các lớp chuyên Toán và lớp chọn.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.7, 5, 192, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-408', 'Chào các bạn, mình là Mai. Mình tin rằng Văn học không chỉ là những con chữ khô khan mà là cả một thế giới cảm xúc. Mình sẽ cùng các bạn khám phá vẻ đẹp của từng tác phẩm, từ đó rèn luyện kỹ năng phân tích, cảm thụ văn chương. Phương pháp của mình là khơi gợi sự sáng tạo, khuyến khích các bạn thể hiện quan điểm cá nhân. Phù hợp với các bạn yêu Văn hoặc đang gặp khó khăn trong môn học này.', 'Cô Mai - Lửa đam mê Văn học, nuôi dưỡng tâm hồn', NULL, 'Thạc sĩ Văn học Việt Nam, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm giảng dạy Văn tại trường THPT. Đã đào tạo nhiều học sinh giỏi môn Văn cấp thành phố. Có kinh nghiệm luyện thi Đại học môn Văn theo các khối C, D.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.2, 65, 427, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-409', 'Xin chào, mình là Tuấn. Mình muốn mang đến cho các bạn một cái nhìn hoàn toàn mới về Vật lý. Mình tập trung vào việc xây dựng nền tảng lý thuyết vững chắc, sau đó áp dụng vào giải quyết các bài tập từ cơ bản đến nâng cao. Mình thích phương pháp đặt câu hỏi, thảo luận để học sinh tự tìm ra lời giải. Phù hợp với các bạn đang tìm kiếm sự logic và ứng dụng thực tế trong Vật lý.', 'Thầy Tuấn - Lý thuyết Vật lý mạch lạc, bài tập vận dụng đa dạng', NULL, 'Kỹ sư Vật lý Kỹ thuật, Đại học Bách khoa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm gia sư Vật lý, giúp học sinh cải thiện điểm số rõ rệt. Đã hỗ trợ nhiều bạn chuẩn bị cho kỳ thi tuyển sinh vào các trường chuyên, lớp chọn.', 'Hà Nội', 'Quận 1', 'active', true, 4.9, 15, 424, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-410', 'Hi there! Mình là Diễm, rất vui được đồng hành cùng bạn trên con đường chinh phục IELTS. Mình đã đạt 7.5 overall và hiểu rõ những gì cần thiết để đạt band điểm mong muốn. Phương pháp của mình là tập trung vào điểm yếu của từng bạn, cung cấp chiến thuật làm bài hiệu quả và thực hành liên tục. Mình rất kiên nhẫn và luôn tạo không khí học tập thoải mái, đầy động lực.', 'Chinh phục IELTS 7.5+, lộ trình cá nhân hóa', NULL, 'Sinh viên năm cuối chuyên ngành Kinh tế Quốc tế, Đại học Kinh tế TP.HCM.', NULL, NULL, 'Gia sư IELTS cho hơn 50 học viên, giúp nhiều bạn đạt target điểm từ 6.0 lên 7.0+. Có kinh nghiệm luyện thi IELTS cho mục đích du học và định cư.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.9, 8, 299, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-411', 'Chào mọi người, mình là Bình. Mình đam mê công nghệ và muốn chia sẻ kiến thức về Tin học. Từ những khái niệm cơ bản nhất về máy tính, Internet, đến các ngôn ngữ lập trình như Python, C++. Phương pháp của mình là vừa học vừa thực hành, làm các dự án nhỏ để củng cố kiến thức. Mình thích cách dạy chậm rãi, giải thích kỹ từng bước, phù hợp với các bạn mới bắt đầu hoặc muốn xây dựng dự án cá nhân.', 'Thầy Bình - Tin học căn bản đến lập trình ứng dụng', NULL, 'Cử nhân Công nghệ Thông tin, Đại học FPT.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học văn phòng và lập trình cơ bản. Đã hướng dẫn sinh viên thực hiện các đồ án môn học. Có kinh nghiệm dạy kèm cho học sinh từ THCS đến Đại học.', 'Bình Dương', 'Hải Châu', 'active', true, 4, 14, 205, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-412', 'Xin chào, mình là Thủy. Hóa học đôi khi làm nhiều bạn thấy khó khăn, nhưng mình tin rằng với cách tiếp cận đúng, môn học này sẽ trở nên thú vị. Mình tập trung vào việc liên hệ lý thuyết với các hiện tượng thực tế, giúp các bạn hình dung rõ hơn. Mình rất chú trọng vào việc giải các dạng bài tập hóa học phổ biến và luyện tập thường xuyên. Phù hợp với các bạn muốn cải thiện kết quả học tập hoặc chuẩn bị cho các kỳ thi.', 'Cô Thủy - Hóa học thực tế, dễ hiểu, bám sát chương trình', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên, ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm gia sư Hóa học cấp 3. Giúp nhiều học sinh đạt điểm khá, giỏi trong các kỳ thi cuối kỳ và thi THPT. Có kinh nghiệm dạy các lớp nâng cao.', 'TP.HCM', 'Quận 7', 'active', true, 4.1, 61, 147, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-413', 'Chào các em, mình là Khang, một người yêu thích khám phá sự sống. Mình muốn truyền tải niềm yêu thích đó đến các em thông qua những giờ học sinh động. Phương pháp của mình là kết hợp lý thuyết với hình ảnh trực quan, sơ đồ tư duy và các ví dụ minh họa gần gũi. Mình đặc biệt chú trọng vào việc giúp các em hiểu bản chất vấn đề thay vì học thuộc lòng. Phù hợp với các bạn đang học Sinh từ cấp 2 đến cấp 3.', 'Thầy Khang - Khám phá thế giới Sinh học', NULL, 'Sinh viên Y Đa khoa, Đại học Y Hà Nội.', NULL, NULL, '2 năm kinh nghiệm gia sư Sinh học. Đã giúp nhiều học sinh tiến bộ rõ rệt về kiến thức và kỹ năng làm bài. Có kinh nghiệm luyện thi môn Sinh cho kỳ thi tốt nghiệp THPT.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.2, 32, 381, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-414', 'Hi everyone! Mình là Yến Nhi, sinh viên ngành Ngôn ngữ Anh. Mình rất thích giúp mọi người tìm thấy niềm vui khi học Tiếng Anh. Mình tập trung vào việc cải thiện kỹ năng nói và nghe, đồng thời xây dựng nền tảng ngữ pháp thật vững. Mình thích sử dụng các hoạt động thực tế, các bài hát, phim ảnh để việc học trở nên sinh động và hiệu quả. Mình phù hợp với các bạn muốn giao tiếp tốt hơn, tự tin hơn hoặc cần ôn luyện kiến thức Tiếng Anh cơ bản.', 'Tiếng Anh giao tiếp tự tin, ngữ pháp vững chắc', NULL, 'Sinh viên năm 3, ngành Ngôn ngữ Anh, Đại học Greenwich Việt Nam.', NULL, NULL, '1 năm kinh nghiệm gia sư Tiếng Anh cho học sinh THCS. Giúp các em cải thiện điểm số trên lớp và tự tin hơn khi phát biểu.', 'Cần Thơ', 'Quận 1', 'active', true, 4.9, 50, 185, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-415', 'Xin chào, mình là Tuấn Anh. Mình có kinh nghiệm dạy Toán cho các lớp chuyên và lớp chọn. Mình tập trung vào việc phát triển tư duy logic, khả năng giải quyết vấn đề và phương pháp làm bài thi hiệu quả. Mình thích phương pháp đặt câu hỏi gợi mở, hướng dẫn học sinh tự tìm ra lời giải. Phù hợp với các bạn học sinh khá giỏi, muốn thử thách bản thân với các dạng Toán khó hoặc chuẩn bị cho các kỳ thi học sinh giỏi.', 'Thầy Tuấn Anh - Toán nâng cao, tư duy logic', NULL, 'Thạc sĩ Toán học ứng dụng, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '6 năm kinh nghiệm giảng dạy và gia sư Toán. Nhiều học sinh đạt giải trong các kỳ thi học sinh giỏi cấp tỉnh/thành phố. Đã từng là trợ giảng tại các trung tâm luyện thi.', 'Bình Dương', 'Bình Thạnh', 'active', true, 5, 53, 140, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-416', 'Hey there! I''m Hoang Anh. My IELTS score is 8.0, and I''m passionate about helping students achieve their target scores efficiently. I focus on tailored strategies for each skill – Reading, Writing, Listening, and Speaking – based on your current level and goals. My approach involves practical exercises, error analysis, and building confidence. I work best with motivated learners aiming for university or career advancement.', 'IELTS Strategy - Target Band Score', NULL, 'Master''s degree in International Business, University of Westminster, UK.', NULL, NULL, 'Over 3 years of experience coaching IELTS candidates. Successfully helped students improve their scores by 1-2 bands within months. Specializes in strategies for academic writing and advanced speaking.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.4, 24, 142, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-417', 'Chào các em, cô Trang đây. Cô hiểu những áp lực khi chuẩn bị cho kỳ thi tốt nghiệp môn Văn. Với kinh nghiệm 7 năm ôn thi, cô sẽ giúp các em nắm vững kiến thức, phân tích sâu các tác phẩm trọng tâm và luyện kỹ năng viết bài nghị luận thuyết phục. Phương pháp của cô là bám sát đề thi, luyện đề thường xuyên và chữa bài chi tiết. Cô mong muốn giúp các em không còn sợ môn Văn mà còn yêu thích nó.', 'Ngữ Văn lớp 12 - Chinh phục điểm 9+ thi THPT', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, '7 năm kinh nghiệm luyện thi Đại học môn Văn. Tỷ lệ học sinh đỗ nguyện vọng 1 luôn đạt trên 95%. Đã biên soạn tài liệu ôn tập cho nhiều trường.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.2, 25, 153, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-418', 'Chào các em, mình là Đức. Mình tin rằng Vật lý không hề khó nếu chúng ta có phương pháp học đúng đắn. Mình sẽ cùng các em xây dựng nền tảng kiến thức một cách logic, giải thích các khái niệm phức tạp bằng ngôn ngữ đơn giản và áp dụng vào các bài tập thực tế. Mình thích cách dạy tương tác, khuyến khích học sinh đặt câu hỏi và cùng nhau tìm lời giải. Phù hợp với các bạn đang học Vật lý từ lớp 10 đến lớp 12.', 'Vật Lý THPT - Từ cơ bản đến nâng cao, dễ hiểu', NULL, 'Kỹ sư Điện tử Viễn thông, Đại học Bách khoa Đà Nẵng.', NULL, NULL, '3 năm kinh nghiệm gia sư Vật lý. Giúp học sinh cải thiện đáng kể kết quả học tập, nhiều em đạt điểm giỏi trong các kỳ thi. Có kinh nghiệm dạy kèm cho cả chương trình chuẩn và chương trình nâng cao.', 'Bình Dương', 'Quận 7', 'active', true, 4.6, 64, 273, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-419', 'Xin chào, mình là Minh Ngọc. Mình yêu thích Sinh học và mong muốn chia sẻ niềm đam mê đó. Mình thường liên hệ kiến thức Sinh học với những điều quen thuộc trong cuộc sống hàng ngày, từ đó giúp các bạn dễ hình dung và ghi nhớ hơn. Phương pháp của mình là sử dụng sơ đồ mindmap, hình ảnh minh họa và các thí nghiệm đơn giản (nếu có thể). Mình rất kiên nhẫn với các bạn cần củng cố kiến thức nền tảng.', 'Sinh học ứng dụng - Liên hệ thực tế, dễ nhớ', NULL, 'Cử nhân Công nghệ Sinh học, Đại học Nông Lâm TP.HCM.', NULL, NULL, '2 năm kinh nghiệm gia sư Sinh học cho học sinh THPT. Giúp các em nắm vững kiến thức cơ bản và ôn thi hiệu quả. Có kinh nghiệm dạy theo sách giáo khoa mới.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.9, 5, 316, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-420', 'Chào bạn, mình là Huy. Mình có thể giúp bạn làm chủ máy tính với các kỹ năng Tin học văn phòng như Word, Excel, PowerPoint. Nếu bạn muốn học lập trình, mình sẽ bắt đầu với Python - ngôn ngữ dễ học và ứng dụng rộng rãi. Phương pháp của mình là thực hành liên tục, làm bài tập ứng dụng thực tế để bạn nhớ lâu hơn. Mình rất thích dạy cho những người mới bắt đầu, giúp họ tự tin tiếp cận công nghệ.', 'Tin học văn phòng & Lập trình Python cho người mới bắt đầu', NULL, 'Sinh viên ngành Khoa học Máy tính, Đại học Công nghệ, ĐHQG Hà Nội.', NULL, NULL, '1 năm kinh nghiệm hướng dẫn Tin học văn phòng cho người đi làm. Vừa bắt đầu dạy lập trình Python cho học sinh THPT. Có kinh nghiệm làm trợ giảng các khóa học lập trình online.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.5, 57, 172, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-421', 'Chào các con, cô Thanh Mai đây. Cô có kinh nghiệm nhiều năm dạy Toán cho các em nhỏ cấp 1 và cấp 2. Cô biết rằng giai đoạn này rất quan trọng để xây dựng nền tảng. Phương pháp của cô là biến những bài toán khô khan thành những câu chuyện thú vị, sử dụng hình ảnh trực quan và trò chơi để các con không còn sợ Toán. Cô rất yêu trẻ và luôn kiên nhẫn với từng bạn nhỏ.', 'Toán cấp 1 & 2 - Xây dựng nền tảng vững chắc', NULL, 'Tốt nghiệp Cao đẳng Sư phạm Mầm non, chuyên ngành Giáo dục Tiểu học.', NULL, NULL, '8 năm kinh nghiệm dạy Toán tiểu học và THCS. Giúp hàng trăm học sinh cải thiện kết quả học tập và yêu thích môn Toán hơn. Có kinh nghiệm dạy các lớp bồi dưỡng học sinh năng khiếu.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.2, 50, 258, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-422', 'Xin chào, mình là Long. Mình tin rằng Lịch sử là một câu chuyện hấp dẫn về quá khứ của dân tộc và thế giới. Mình sẽ cùng các bạn đi sâu vào từng sự kiện, nhân vật lịch sử, giúp các bạn hiểu rõ bối cảnh và ý nghĩa của chúng. Phương pháp của mình là kể chuyện, phân tích các nguồn sử liệu và kết nối với các vấn đề hiện tại. Phù hợp với các bạn muốn học Sử một cách có chiều sâu hoặc chuẩn bị cho các kỳ thi.', 'Lịch sử không còn nhàm chán - Khám phá quá khứ', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội và Nhân văn, ĐHQG TP.HCM.', NULL, NULL, '3 năm kinh nghiệm gia sư Lịch sử. Giúp học sinh có cái nhìn mới mẻ và hứng thú hơn với môn học. Có kinh nghiệm luyện thi tốt nghiệp THPT môn Lịch sử.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.3, 10, 406, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-423', 'Chào các bạn, mình là Thu Hà. Địa lý giúp chúng ta hiểu về thế giới xung quanh, từ những dãy núi, dòng sông đến văn hóa các quốc gia. Mình sẽ cùng các bạn khám phá từng vùng đất, từng châu lục qua bản đồ, hình ảnh và những câu chuyện thú vị. Phương pháp của mình là trực quan hóa kiến thức, liên hệ các yếu tố tự nhiên và kinh tế - xã hội. Phù hợp với các bạn muốn học tốt Địa lý hoặc đơn giản là muốn mở rộng hiểu biết về thế giới.', 'Địa lý Việt Nam & Thế giới - Khám phá bản đồ', NULL, 'Cử nhân Địa lý học, Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Địa lý cấp 2 và cấp 3. Giúp học sinh nắm vững kiến thức địa lý Việt Nam và thế giới, cải thiện điểm số. Có kinh nghiệm ôn thi THPT.', 'Biên Hòa', 'Quận 7', 'active', true, 4, 11, 378, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-424', 'Hey! Mình là Tuấn Kiệt, rất vui được giúp bạn nâng cao khả năng Tiếng Anh. Mình tập trung vào việc làm cho việc học trở nên thực tế và vui vẻ. Mình có kinh nghiệm luyện thi các chứng chỉ như PET, FCE nên có thể đưa ra lộ trình và bài tập phù hợp. Phương pháp của mình là kết hợp học từ vựng, ngữ pháp với thực hành giao tiếp thường xuyên. Mình phù hợp với các bạn muốn giao tiếp tự tin hoặc cần chứng chỉ Tiếng Anh.', 'Tiếng Anh giao tiếp & Luyện thi chứng chỉ PET/FCE', NULL, 'Cựu học sinh trường chuyên Nguyễn Thượng Hiền, TP.HCM.', NULL, NULL, '2 năm kinh nghiệm gia sư Tiếng Anh. Giúp nhiều học sinh đạt chứng chỉ PET, FCE với điểm số tốt. Có kinh nghiệm dạy kèm Tiếng Anh cho người mất gốc.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.8, 41, 68, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-425', 'Chào các em, cô Phương đây. Cô biết Hóa học là môn học cần sự tỉ mỉ và tư duy logic. Cô sẽ giúp các em hệ thống lại kiến thức một cách khoa học, tập trung vào các dạng bài tập thường gặp và phương pháp giải nhanh. Mình tin rằng với sự kiên trì, ai cũng có thể học tốt Hóa học. Phương pháp của cô là chữa bài chi tiết, chỉ ra lỗi sai và hướng dẫn cách khắc phục. Phù hợp với các bạn muốn cải thiện điểm Hóa hoặc ôn thi.', 'Hóa học THPT - Giải bài tập dễ dàng', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '5 năm kinh nghiệm gia sư Hóa học. Giúp học sinh tiến bộ rõ rệt về kỹ năng giải bài tập và hiểu sâu kiến thức. Có kinh nghiệm dạy kèm cho cả chương trình phổ thông và chương trình chuyên.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.5, 49, 328, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-426', 'Xin chào, mình là An. Mình có kinh nghiệm dạy Toán cho học sinh THCS. Mình hiểu rằng đây là giai đoạn quan trọng để xây dựng nền tảng cho các cấp học cao hơn. Phương pháp của mình là đi từ những kiến thức cơ bản nhất, giải thích cặn kẽ, sau đó nâng dần độ khó của bài tập. Mình thích cách dạy gần gũi, tạo không khí thoải mái để học sinh không ngại hỏi. Phù hợp với các bạn muốn củng cố kiến thức hoặc nâng cao điểm số.', 'Toán lớp 6-9: Nền tảng vững, bứt phá điểm số', NULL, 'Sinh viên năm 4, ngành Sư phạm Toán học, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm gia sư Toán THCS. Giúp nhiều học sinh cải thiện điểm số, tự tin hơn với môn học. Có kinh nghiệm luyện thi vào lớp 10 các trường chuyên và trường công lập.', 'Biên Hòa', 'Hoàng Mai', 'active', true, 4.3, 14, 199, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-427', 'Hi! Mình là Bằng, chuyên viên biên phiên dịch với kinh nghiệm làm việc trong môi trường quốc tế. Mình hiểu những khó khăn khi giao tiếp bằng Tiếng Anh trong công việc. Mình cung cấp các khóa học Tiếng Anh thực tế, tập trung vào giao tiếp hàng ngày, thuyết trình, đàm phán. Phương pháp của mình là mô phỏng tình huống công việc, luyện tập đóng vai và cung cấp phản hồi tức thì. Phù hợp với người đi làm muốn nâng cao khả năng Tiếng Anh.', 'Tiếng Anh giao tiếp cho người đi làm', NULL, 'Cử nhân Tiếng Anh Thương mại, Đại học Kinh tế Quốc dân.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm. Giúp nhiều học viên tự tin hơn trong các cuộc họp và giao dịch quốc tế. Từng là phiên dịch viên cho các tập đoàn nước ngoài.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.5, 32, 378, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-428', 'Xin chào, mình là Minh Đức. Mình có kinh nghiệm chuyên sâu về Vật lý, đặc biệt là các phần kiến thức nâng cao và luyện thi học sinh giỏi. Mình giúp học sinh phát triển tư duy phân tích, kỹ năng giải các bài toán phức tạp và phương pháp tiếp cận sáng tạo. Phương pháp của mình là đi sâu vào bản chất vật lý, áp dụng các định luật một cách linh hoạt và luyện tập các dạng đề thi chuyên. Phù hợp với các bạn học sinh khá giỏi và có định hướng thi chuyên/đại học.', 'Vật lý nâng cao & Luyện thi HSG', NULL, 'Thạc sĩ Vật lý Lý thuyết, Đại học Khoa học Tự nhiên, ĐHQG Hà Nội.', NULL, NULL, '5 năm kinh nghiệm gia sư Vật lý, đặc biệt là bồi dưỡng học sinh giỏi. Nhiều học sinh đạt giải cao trong các kỳ thi Vật lý. Từng là thành viên đội tuyển Vật lý quốc gia.', 'Bình Dương', 'Hải Châu', 'active', true, 4.4, 47, 153, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-429', 'Hello! I''m Phuong Thao. Scoring 8.0 in IELTS myself, I specialize in helping students master the Speaking and Writing sections. My approach focuses on developing fluency, improving vocabulary, and structuring coherent arguments. I provide personalized feedback on pronunciation, grammar, and task achievement. I love creating a supportive learning environment where students feel encouraged to express themselves and improve.', 'IELTS Speaking & Writing: Fluency & Cohesion', NULL, 'Bachelor of Arts in English Linguistics, University of Foreign Language Studies, HCMC.', NULL, NULL, '2 years of dedicated IELTS coaching, with a strong focus on Speaking and Writing modules. Helped numerous students achieve their target bands for study abroad and immigration purposes.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.8, 24, 196, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-449', 'Mình là Thảo My, rất vui được chia sẻ niềm yêu thích Sinh học với các bạn. Mình có cách giảng dạy sinh động, sử dụng nhiều hình ảnh minh họa và ví dụ thực tế để các bạn dễ dàng hình dung và ghi nhớ kiến thức. Mình tin rằng học Sinh học cũng chính là học cách yêu thiên nhiên và hiểu về chính mình.', 'Cô My: Sinh học thú vị - Từ tế bào đến hệ sinh thái', NULL, 'Thạc sĩ Sinh thái học, Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Sinh học cho học sinh THPT. Giúp học sinh có hứng thú với môn học và đạt điểm cao trong các bài kiểm tra, thi cử.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.2, 35, 141, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-430', 'Chào các bạn, mình là Cường. Mình yêu thích việc tìm tòi và phân tích các tác phẩm Văn học Việt Nam. Mình sẽ giúp các bạn khám phá những tầng nghĩa sâu sắc trong từng câu chữ, hiểu rõ hơn về tư tưởng, nghệ thuật của tác giả. Phương pháp của mình là kết hợp đọc hiểu, bình giảng và hướng dẫn cách viết bài văn nghị luận chặt chẽ, logic. Phù hợp với các bạn muốn học Văn một cách có chiều sâu và chuẩn bị tốt cho kỳ thi.', 'Ngữ Văn THPT: Phân tích tác phẩm sâu sắc', NULL, 'Cử nhân Văn học, Đại học Văn hóa Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Văn. Giúp học sinh có cái nhìn sâu sắc hơn về các tác phẩm văn học và cải thiện kỹ năng làm bài. Có kinh nghiệm ôn thi tốt nghiệp THPT.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4, 58, 273, '2026-06-19 02:59:31.418972', '2026-06-19 02:59:31.418972', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-431', 'Chào các bạn, mình là Minh Anh. Mình yêu thích việc giúp các bạn trẻ làm quen và sử dụng tiếng Anh một cách tự nhiên nhất qua các hoạt động vui nhộn. Mình tin rằng học ngôn ngữ là một hành trình khám phá thú vị chứ không hề khô khan. Hãy cùng mình xây dựng nền tảng tiếng Anh vững chắc nhé!', 'Chinh phục Tiếng Anh giao tiếp tự tin cùng cô Minh Anh', NULL, 'Tốt nghiệp Đại học Ngoại ngữ - Đại học Quốc gia Hà Nội, chuyên ngành Ngôn ngữ Anh.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy tiếng Anh cho học sinh cấp 2, cấp 3. Từng là trợ giảng tại các trung tâm Anh ngữ uy tín. Nhiều học sinh đạt điểm cao trong các kỳ thi học kỳ.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.5, 20, 442, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-432', 'Xin chào, mình là Hùng, một người đam mê Toán học và đặc biệt là Toán tư duy. Mình luôn cố gắng tìm ra những cách giải thích dễ hiểu nhất, kết nối kiến thức với thực tế để các em thấy Toán học thật gần gũi. Phương pháp của mình là ''hiểu bản chất, không học vẹt''. Mình rất mong được đồng hành cùng các em.', 'Thầy Hùng - Giải pháp tối ưu cho Toán tư duy', NULL, 'Thạc sĩ Toán học, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '6 năm kinh nghiệm dạy Toán THPT. Giúp nhiều học sinh cải thiện điểm số và đạt giải học sinh giỏi cấp thành phố. Có kinh nghiệm ôn luyện thi vào lớp 10 chuyên Toán.', 'Bình Dương', 'Quận 7', 'active', true, 4.8, 62, 185, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-433', 'Mình là Thu Trang, một cô giáo yêu văn chương tha thiết. Mình tin rằng mỗi bài văn là một câu chuyện, mỗi tác phẩm văn học là một thế giới để khám phá. Mình sẽ cùng các bạn đi sâu vào cảm xúc, phân tích tinh tế và tìm ra giọng văn riêng của mình. Mình hợp với các bạn thích tìm tòi, suy ngẫm.', 'Cô Trang - Thắp lửa đam mê Văn học cho học trò', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Sư phạm Hà Nội.', NULL, NULL, '5 năm dạy Văn tại trường THPT công lập. Hướng dẫn thành công nhiều học sinh đạt điểm cao môn Văn. Chuyên bồi dưỡng học sinh giỏi Văn.', 'Cần Thơ', 'Quận 3', 'active', true, 4.8, 16, 127, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-434', 'Chào bạn, mình là Minh Đức. Mình có kinh nghiệm giúp học sinh vượt qua nỗi sợ Vật Lý bằng cách hệ thống hóa kiến thức một cách logic, dễ hiểu nhất. Mình chú trọng vào việc xây dựng nền tảng vững chắc và luyện tập các dạng bài tập từ cơ bản đến nâng cao. Mình kiên nhẫn và luôn sẵn sàng giải đáp mọi thắc mắc của học trò.', 'Thầy Đức: Lý thuyết Vật Lý mạch lạc, bài tập thực hành hiệu quả', NULL, 'Kỹ sư Vật lý Kỹ thuật, Học viện Kỹ thuật Quân sự.', NULL, NULL, '4 năm kinh nghiệm dạy Vật Lý cho học sinh cấp 3. Giúp đỡ nhiều em lấy lại kiến thức căn bản và cải thiện điểm số đáng kể. Phụ đạo cho các em chuẩn bị thi đại học.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.7, 34, 111, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-435', 'Hi there! Mình là Bích Ngọc, rất vui được đồng hành cùng bạn trên con đường chinh phục IELTS. Mình tập trung vào việc phát triển kỹ năng toàn diện, đặc biệt là Writing và Speaking, với phương pháp cá nhân hóa cho từng học viên. Mình tin rằng với sự luyện tập đúng hướng, bạn hoàn toàn có thể đạt được band điểm mơ ước.', 'Ngọc - Chinh phục IELTS 7.0+ dễ dàng', NULL, 'Thạc sĩ TESOL, University of Education, Singapore.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS. Tỷ lệ học viên đạt mục tiêu 7.0+ chiếm 80%. Đã từng sống và làm việc tại nước ngoài.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.1, 17, 115, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-436', 'Chào các bạn, mình là Văn Nam. Nếu bạn muốn làm quen với thế giới lập trình, xây dựng website hay ứng dụng, mình sẵn sàng hướng dẫn từ những khái niệm cơ bản nhất. Mình có kinh nghiệm dạy Python, Java và lập trình web. Phương pháp của mình là ''học đi đôi với hành'', luôn có bài tập thực tế để các bạn áp dụng.', 'Thầy Nam - Lập trình căn bản và nâng cao cho mọi lứa tuổi', NULL, 'Cử nhân Công nghệ Thông tin, Đại học Bách Khoa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm làm việc trong ngành IT. 2 năm kinh nghiệm dạy lập trình cho sinh viên và người đi làm. Đã hướng dẫn nhiều dự án nhỏ thành công.', 'Đà Nẵng', 'Quận 3', 'active', true, 4, 52, 422, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-437', 'Mình là Thảo Vy, rất vui được chia sẻ niềm yêu thích Hóa học với các bạn. Mình có cách tiếp cận Hóa học gần gũi, liên hệ với đời sống hàng ngày để các bạn không còn thấy môn học này xa vời. Mình sẽ giúp bạn nắm vững lý thuyết và giải thành thạo các dạng bài tập từ dễ đến khó.', 'Cô Vy: Hóa học thực tiễn, bài tập dễ hiểu', NULL, 'Cử nhân Hóa học, Trường Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa cấp 3 và ôn thi đại học. Giúp đỡ nhiều học sinh cải thiện điểm số, đạt kết quả tốt trong kỳ thi THPT Quốc gia.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.5, 8, 136, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-438', 'Chào bạn, mình là Minh Quân. Mình tin rằng Sinh học không chỉ là những con số, những thuật ngữ khô khan mà là cả một thế giới sống động đầy kỳ diệu. Mình sẽ giúp bạn khám phá những bí ẩn của cơ thể, thế giới tự nhiên một cách trực quan và dễ hiểu nhất. Mình kiên nhẫn và luôn khuyến khích sự tò mò của học trò.', 'Thầy Quân - Khám phá thế giới Sinh học sống động', NULL, 'Cử nhân Sinh học, Đại học Khoa học Tự nhiên - Đại học Quốc gia TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Sinh học cho học sinh THPT. Có kinh nghiệm bồi dưỡng học sinh giỏi môn Sinh. Nhiều học sinh đạt điểm cao môn Sinh trong kỳ thi tốt nghiệp.', 'Bình Dương', 'Quận 1', 'active', true, 4.6, 11, 104, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-440', 'Xin chào, mình là Văn Tuấn. Mình yêu thích môn Địa lý và mong muốn truyền cảm hứng cho các bạn về sự phong phú, đa dạng của thế giới xung quanh. Mình kết hợp kiến thức sách vở với các thông tin cập nhật, những câu chuyện thực tế để bài học thêm sinh động và dễ nhớ. Mình hợp với các bạn muốn hiểu sâu về Địa lý.', 'Thầy Tuấn: Địa lý Việt Nam và Thế giới, kiến thức thực tế', NULL, 'Cử nhân Địa lý học, Trường Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý THCS và THPT. Giúp học sinh có cái nhìn tổng quan và chi tiết về các vấn đề địa lý. Có kinh nghiệm ôn thi học sinh giỏi.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.3, 27, 210, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-441', 'Mình là Mỹ Linh, một người yêu thích khám phá những câu chuyện quá khứ. Mình tin rằng học Lịch sử là học cách hiểu về cội nguồn và những bài học từ quá khứ. Mình sẽ cùng bạn đi qua những dòng thời gian, những sự kiện lịch sử đầy hấp dẫn, giúp bạn ghi nhớ kiến thức một cách tự nhiên và có chiều sâu.', 'Cô Linh: Lịch sử Việt Nam và Thế giới qua câu chuyện', NULL, 'Cử nhân Lịch sử, Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh tiếp cận môn Lịch sử một cách hứng thú, có khả năng phân tích và liên hệ các sự kiện. Nhiều học sinh đạt điểm cao.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.9, 65, 259, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-442', 'Hey guys, mình là Gia Huy. Nếu bạn đang gặp khó khăn với IELTS Writing và Speaking, mình có thể giúp bạn. Mình tập trung vào việc xây dựng cấu trúc bài viết mạch lạc, sử dụng từ vựng và ngữ pháp chính xác, đồng thời luyện phản xạ giao tiếp tự tin. Mình có phương pháp luyện tập cá nhân hóa để bạn đạt kết quả nhanh nhất.', 'Huy - Luyện thi IELTS Writing & Speaking đột phá', NULL, 'IELTS 8.0 (Listening 8.5, Reading 8.0, Writing 7.5, Speaking 7.5), Đại học Kinh tế Quốc dân.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS cho sinh viên và người đi làm. Giúp nhiều học viên cải thiện rõ rệt kỹ năng Writing và Speaking trong thời gian ngắn.', 'Bình Dương', 'Hoàng Mai', 'active', true, 4.6, 53, 198, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-443', 'Xin chào, mình là Bích Thủy. Mình có niềm vui lớn khi giúp các bạn làm quen và tự tin sử dụng tiếng Anh trong giao tiếp hàng ngày. Mình cũng có kinh nghiệm luyện thi các chứng chỉ A2, B1 cho học sinh THCS. Phương pháp của mình là vui vẻ, kiên trì và tập trung vào thực hành.', 'Cô Thủy: Tiếng Anh giao tiếp và luyện thi chứng chỉ A2-B1', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy tiếng Anh cho người mới bắt đầu và học sinh THCS. Nhiều học sinh đạt chứng chỉ B1 với điểm số tốt.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.2, 38, 313, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-444', 'Chào các bạn, mình là Quang Huy. Mình chuyên dạy Toán cấp 2, giúp các em xây dựng nền tảng kiến thức vững chắc và phát triển tư duy giải toán một cách logic. Mình luôn tìm cách làm cho các bài toán trở nên thú vị, dễ hiểu và gần gũi với lứa tuổi học sinh. Sự kiên nhẫn và phương pháp đồng hành là điểm mạnh của mình.', 'Thầy Huy: Toán cấp 2 - Nền tảng vững chắc, tư duy hiệu quả', NULL, 'Sinh viên năm cuối ngành Sư phạm Toán, Đại học Sư phạm TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Toán cấp 2. Giúp nhiều em lấy lại kiến thức và cải thiện kết quả học tập. Phụ đạo cho các em chuẩn bị vào lớp 10.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.7, 36, 161, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-445', 'Mình là Thanh Mai, rất hào hứng được chia sẻ niềm yêu thích Văn học với các bạn. Mình không chỉ giúp các bạn hiểu sâu sắc các tác phẩm văn học mà còn rèn luyện kỹ năng viết bài văn mạch lạc, có lập luận chặt chẽ và giàu cảm xúc. Mình tin mỗi bạn đều có thể tìm thấy tiếng nói riêng trong từng bài viết.', 'Cô Mai: Văn học và Kỹ năng viết bài văn thuyết phục', NULL, 'Cử nhân Ngữ văn, Đại học Văn hóa Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Văn cấp 2, cấp 3. Giúp học sinh nâng cao khả năng cảm thụ văn học và viết văn sáng tạo. Có kinh nghiệm ôn luyện thi học sinh giỏi Văn.', 'TP.HCM', 'Quận 1', 'active', true, 4.2, 44, 358, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-446', 'Xin chào, mình là Hoàng Minh. Mình có phương pháp giảng dạy Vật Lý tập trung vào việc giải thích cặn kẽ các khái niệm, công thức và ứng dụng thực tế. Mình luôn chuẩn bị hệ thống bài tập phong phú, bám sát chương trình và có tính phân loại cao. Mình luôn cố gắng tạo không khí học tập thoải mái, khuyến khích học sinh đặt câu hỏi.', 'Thầy Minh: Vật Lý THPT - Giải thích tường tận, bài tập đa dạng', NULL, 'Thạc sĩ Vật lý Lý thuyết, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Vật Lý THPT. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi và ôn luyện thi đại học khối A, A1.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.7, 39, 356, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-447', 'Mình là Thúy An, rất vui được giúp các bạn chinh phục môn Hóa học. Mình có kinh nghiệm giảng dạy từ Hóa lớp 8 đến Hóa luyện thi đại học. Phương pháp của mình là đi từ những kiến thức nền tảng nhất, xây dựng sự logic và kết nối các phần kiến thức với nhau. Mình có nhiều bài tập thực hành để củng cố kiến thức.', 'Cô An: Hóa học dễ hiểu - Từ căn bản đến nâng cao', NULL, 'Cử nhân Sư phạm Hóa học, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa cấp 3. Giúp học sinh nắm vững kiến thức cơ bản và nâng cao, đạt kết quả tốt trong các kỳ thi.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.8, 62, 290, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-448', 'Chào bạn, mình là Văn Long. Nếu bạn muốn bước vào thế giới lập trình, mình sẽ là người đồng hành đáng tin cậy. Mình chuyên dạy Python, lập trình web (HTML, CSS, JavaScript) cho người chưa có kinh nghiệm. Phương pháp của mình là thực hành ngay, làm các dự án nhỏ để bạn thấy được kết quả học tập của mình.', 'Thầy Long: Lập trình Python và Web cho người mới bắt đầu', NULL, 'Cử nhân Khoa học Máy tính, Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm làm lập trình viên và 2 năm kinh nghiệm dạy lập trình online. Đã hướng dẫn thành công nhiều học viên tự code được website đơn giản.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.9, 30, 263, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-450', 'Hey! Mình là Tiến Đạt. Nếu bạn muốn cải thiện band điểm IELTS Speaking và Writing, mình có thể giúp bạn. Mình tập trung vào việc cung cấp chiến lược làm bài hiệu quả, từ vựng học thuật và cách phát triển ý tưởng. Mình có kinh nghiệm luyện thi IELTS cho nhiều đối tượng, từ sinh viên đến người đi làm.', 'Đạt IELTS - Luyện kỹ năng Speaking & Writing hiệu quả', NULL, 'IELTS 8.0 (Speaking 8.0, Writing 7.5), Đại học Kinh tế TP.HCM.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS. Giúp nhiều học viên đạt mục tiêu band điểm mong muốn, đặc biệt là về Speaking và Writing.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.8, 22, 312, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-451', 'Mình là Hồng, rất vui được đồng hành cùng các bé ở lứa tuổi tiểu học trên hành trình khám phá Toán học. Mình có phương pháp dạy nhẹ nhàng, vui tươi, giúp các con làm quen với các con số và phép tính một cách tự nhiên. Mình chú trọng rèn luyện sự tập trung và tư duy logic cho các bé từ sớm.', 'Cô Hồng: Toán tiểu học - Bé học, bố mẹ vui', NULL, 'Cử nhân Sư phạm Toán Tiểu học, Đại học Giáo dục - Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Toán tiểu học tại nhà. Giúp nhiều bé nắm vững kiến thức, yêu thích môn Toán và tự tin hơn trong học tập.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.3, 57, 169, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-452', 'Chào bạn, mình là Minh Khang. Nếu bạn cảm thấy tiếng Anh quá khó và muốn bắt đầu lại từ đầu, mình sẵn sàng giúp đỡ. Mình có phương pháp dạy kiên nhẫn, tập trung vào phát âm chuẩn, ngữ pháp cơ bản và vốn từ giao tiếp thiết yếu. Mục tiêu của mình là giúp bạn tự tin nói tiếng Anh sau mỗi buổi học.', 'Thầy Khang: Tiếng Anh giao tiếp cho người mất gốc', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Sư phạm TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy tiếng Anh cho người mới bắt đầu và người đi làm. Giúp nhiều học viên vượt qua rào cản tâm lý và giao tiếp cơ bản.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4, 17, 299, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-453', 'Mình là Bích Hà, rất vui được chia sẻ niềm yêu thích Địa lý với các bạn. Mình có cách tiếp cận môn học một cách trực quan, sinh động thông qua bản đồ, hình ảnh và các câu chuyện thực tế. Mình giúp các bạn không chỉ thuộc lòng kiến thức mà còn hiểu được bản chất và mối liên hệ giữa các hiện tượng địa lý.', 'Cô Hà: Địa lý trực quan, kiến thức dễ nhớ', NULL, 'Cử nhân Địa lý học, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Địa lý THCS và THPT. Giúp học sinh có cái nhìn tổng quan, dễ dàng ghi nhớ kiến thức và đạt kết quả tốt trong các kỳ thi.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.6, 38, 392, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-454', 'Xin chào, mình là Quốc Bảo. Mình tin rằng Lịch sử không chỉ là những sự kiện khô khan mà là chuỗi nhân quả mang lại bài học sâu sắc. Mình tập trung vào việc rèn luyện cho học sinh tư duy phân tích, đánh giá các sự kiện và nhân vật lịch sử. Mình giúp các bạn nhìn nhận lịch sử một cách khách quan và có chiều sâu.', 'Thầy Bảo: Lịch sử Việt Nam & Thế giới - Tư duy phân tích', NULL, 'Thạc sĩ Lịch sử Việt Nam, Đại học Khoa học Xã hội và Nhân văn - Đại học Quốc gia Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Lịch sử THPT. Giúp học sinh có phương pháp học tập hiệu quả, nâng cao khả năng phân tích và làm bài thi môn Lịch sử.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.3, 55, 89, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-455', 'Chào bạn, mình là Nhật Minh. Mình có kinh nghiệm dày dặn trong việc giảng dạy Hóa học, đặc biệt là cho các bạn đang ôn thi đại học. Mình tập trung vào việc xây dựng nền tảng vững chắc, hướng dẫn giải nhanh các dạng bài tập và cung cấp các phương pháp giải tối ưu. Sự kiên trì và nhiệt huyết là điều mình luôn mang đến cho học trò.', 'Thầy Minh: Hóa học ứng dụng và luyện thi đại học', NULL, 'Kỹ sư Hóa học, Đại học Bách Khoa TP.HCM.', NULL, NULL, '6 năm kinh nghiệm dạy Hóa luyện thi đại học. Tỷ lệ học sinh đỗ đại học khối B, A với điểm cao môn Hóa chiếm trên 90%.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.3, 14, 332, '2026-06-19 02:59:50.074136', '2026-06-19 02:59:50.074136', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-456', 'Mình tin rằng học Tiếng Anh không chỉ là học ngữ pháp mà là khám phá một thế giới mới. Với phương pháp học qua trải nghiệm, lồng ghép văn hóa, mình giúp bạn cảm thấy thoải mái và hào hứng. Mình đặc biệt phù hợp với các bạn mất gốc hoặc ngại giao tiếp.', 'Tiếng Anh giao tiếp tự tin - Cùng bạn chinh phục mọi cuộc hội thoại!', NULL, 'Tốt nghiệp chuyên ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho học sinh cấp 2, 3. Từng giúp nhiều bạn cải thiện đáng kể điểm số và sự tự tin khi nói. Tập trung vào phát âm chuẩn và phản xạ nhanh.', 'Hà Nội', 'Hải Châu', 'active', true, 4.5, 28, 51, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-457', 'Toán học là những câu chuyện logic và sự khám phá thú vị. Mình áp dụng phương pháp giảng dạy linh hoạt, bám sát chương trình nhưng luôn tìm cách mở rộng và đào sâu vấn đề. Phù hợp với học sinh muốn nâng cao kiến thức và rèn luyện tư duy phản biện.', 'Toán tư duy - Khơi nguồn sáng tạo, giải mọi bài toán khó!', NULL, 'Thủ khoa ngành Sư phạm Toán học, Đại học Sư phạm Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Toán THPT. Tỷ lệ học sinh đỗ đại học nguyện vọng 1 đạt 95%. Thường xuyên tổ chức các buổi luyện đề chuyên sâu và chữa bài cá nhân.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.5, 44, 99, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-458', 'Mình yêu văn chương và muốn truyền tình yêu ấy đến các bạn. Phương pháp của mình là khám phá tác phẩm qua góc nhìn đa chiều, kết nối với cuộc sống hiện đại. Mình tin rằng mỗi bài văn đều có thể trở nên sinh động và ý nghĩa.', 'Ngữ Văn lay động cảm xúc - Khơi gợi đam mê văn chương.', NULL, 'Cử nhân Ngữ văn, Đại học Khoa học Xã hội và Nhân văn.', NULL, NULL, '4 năm kinh nghiệm dạy Văn từ cấp 2 đến lớp 12. Giúp học sinh đạt điểm cao trong các kỳ thi học sinh giỏi. Kinh nghiệm bồi dưỡng học sinh yếu kém, giúp các em lấy lại hứng thú học Văn.', 'Hà Nội', 'Hoàng Mai', 'active', true, 4.9, 37, 180, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-459', 'Mình muốn biến những công thức khô khan thành những hiện tượng kỳ thú. Phương pháp của mình là giải thích cặn kẽ bản chất, ứng dụng vào thực tế và dùng ví dụ minh họa sinh động. Rất phù hợp với các bạn thấy Vật Lý khó hiểu hoặc nhàm chán.', 'Vật Lý thực tế - Liên hệ bài học với cuộc sống muôn màu.', NULL, 'Kỹ sư Vật lý Kỹ thuật, Đại học Bách Khoa Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Vật Lý cấp 3 và ôn thi đại học. Nhiều học sinh đạt điểm xuất sắc môn Vật Lý. Có kinh nghiệm dạy kèm cá nhân và nhóm nhỏ.', 'Bình Dương', 'Hải Châu', 'active', true, 4.6, 45, 103, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-460', 'Mình hiểu những áp lực khi ôn thi IELTS. Với kinh nghiệm từng đạt điểm cao và phương pháp học tập hiệu quả, mình sẽ cùng bạn xây dựng lộ trình phù hợp nhất. Mình chú trọng cả 4 kỹ năng và chiến thuật làm bài thi.', 'IELTS bứt phá - Target 7.0+ với lộ trình cá nhân hóa.', NULL, 'Thạc sĩ TESOL, Đại học Cambridge (online).', NULL, NULL, '6 năm kinh nghiệm luyện thi IELTS. Giúp hàng trăm học viên đạt điểm mục tiêu, từ 5.5 lên 7.0, 7.5. Có kinh nghiệm luyện thi cho sinh viên và người đi làm.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.5, 50, 425, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-461', 'Mình yêu thích sự logic và sáng tạo của lập trình. Mình sẽ giúp bạn làm quen với máy tính, các ngôn ngữ lập trình cơ bản một cách dễ hiểu nhất. Phương pháp ''học đi đôi với hành'' sẽ giúp bạn nhanh chóng làm chủ kiến thức.', 'Tin Học căn bản & Lập trình - Từ Zero đến Hero với code!', NULL, 'Cử nhân Công nghệ Thông tin, Đại học FPT.', NULL, NULL, '3 năm kinh nghiệm dạy Tin học văn phòng và lập trình Python cho người mới bắt đầu. Từng hướng dẫn các dự án nhỏ cho sinh viên. Phù hợp với mọi lứa tuổi.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.5, 21, 93, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-462', 'Mình muốn Hóa Học không còn là nỗi ám ảnh mà là một môn học đầy hứng thú. Mình sử dụng các thí nghiệm ảo, mô hình trực quan và bài tập thực tế để giải thích các khái niệm khó. Phù hợp với học sinh cấp 3 đang ôn thi.', 'Hóa Học dễ hiểu - Khám phá thế giới phân tử kỳ diệu.', NULL, 'Tốt nghiệp ngành Hóa học, Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Hóa học. Giúp học sinh nắm vững lý thuyết và giải nhanh các dạng bài tập. Kinh nghiệm ôn thi THPT Quốc gia môn Hóa.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.4, 43, 301, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-463', 'Mình tin rằng mọi đứa trẻ đều có khả năng học tốt Toán nếu được hướng dẫn đúng cách. Mình tập trung vào việc xây dựng tư duy logic, sự tự tin cho học sinh qua các bài tập vui nhộn và phương pháp giảng dạy kiên nhẫn, gần gũi.', 'Toán cấp 1, 2 - Nền tảng vững chắc cho tương lai.', NULL, 'Sinh viên năm 3, ngành Sư phạm Toán học, Đại học Thủ đô.', NULL, NULL, 'Có kinh nghiệm dạy kèm Toán cho học sinh tiểu học và THCS. Giúp các em cải thiện điểm số và yêu thích môn học hơn. Khả năng truyền đạt dễ hiểu, tạo không khí học tập thoải mái.', 'Bình Dương', 'Quận 7', 'active', true, 4.1, 44, 268, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-464', 'Mình hiểu rõ tầm quan trọng của Tiếng Anh trong môi trường công sở. Mình thiết kế các bài học tập trung vào tình huống giao tiếp thực tế, từ vựng chuyên ngành và kỹ năng thuyết trình. Giúp bạn tự tin hơn trong công việc.', 'Tiếng Anh cho người đi làm - Giao tiếp chuyên nghiệp, tự tin.', NULL, 'Cử nhân Tài chính Ngân hàng, có chứng chỉ TESOL.', NULL, NULL, '5 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm. Từng làm việc tại môi trường quốc tế. Giúp nhiều học viên thăng tiến trong sự nghiệp nhờ cải thiện Tiếng Anh.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.6, 51, 104, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-465', 'Mình đam mê Vật Lý và muốn chia sẻ niềm đam mê ấy. Mình tập trung vào việc làm rõ bản chất vấn đề, sử dụng hình ảnh trực quan và phương pháp giải toán sáng tạo. Giúp học sinh có cái nhìn toàn diện và giải quyết bài tập hiệu quả.', 'Vật Lý THCS - Giải thích bản chất, bứt phá điểm số.', NULL, 'Sinh viên năm cuối, ngành Kỹ thuật Y sinh, Đại học Y Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý cấp 2 và cấp 3. Giúp nhiều học sinh tiến bộ nhanh chóng. Có khả năng phân tích điểm mạnh, điểm yếu của từng học sinh để có phương pháp phù hợp.', 'Biên Hòa', 'Hải Châu', 'active', true, 4.2, 61, 53, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-466', 'Mình yêu thích những câu chuyện và chiều sâu tâm hồn trong Văn học. Mình dạy bằng cách kể chuyện, phân tích tâm lý nhân vật và liên hệ với cuộc sống. Phương pháp này giúp bài học trở nên sinh động, dễ nhớ và khơi gợi cảm xúc.', 'Văn học Việt Nam - Lối kể chuyện cuốn hút, cảm thụ tinh tế.', NULL, 'Tốt nghiệp ngành Văn hóa học, Đại học Văn hóa.', NULL, NULL, '4 năm kinh nghiệm dạy Văn cho học sinh THPT. Chú trọng phát triển kỹ năng cảm thụ văn học và viết bài văn nghị luận sâu sắc. Kinh nghiệm bồi dưỡng học sinh giỏi Văn.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.6, 9, 166, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-467', 'Mình có kinh nghiệm dày dạn trong việc giảng dạy Toán cao cấp cho sinh viên các ngành kinh tế. Mình tập trung vào việc xây dựng nền tảng vững chắc, cung cấp các phương pháp giải nhanh và hiệu quả, bám sát đề thi của các trường.",
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-468', 'Mình giúp bạn xây dựng sự tự tin trong Writing và Speaking. Mình tập trung vào cách phát triển ý tưởng, sử dụng từ vựng học thuật một cách tự nhiên và cấu trúc câu đa dạng. Cùng mình biến những ý tưởng của bạn thành bài nói/viết ấn tượng.', 'IELTS Writing & Speaking - Từ vựng phong phú, ý tưởng mạch lạc.', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Sư phạm Ngoại ngữ.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS, chuyên sâu về kỹ năng Viết và Nói. Giúp nhiều học viên đạt điểm Writing 7.0, Speaking 7.5. Hướng dẫn cách tư duy và lập dàn ý hiệu quả.', 'Cần Thơ', 'Quận 3', 'active', true, 4.5, 29, 232, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-470', 'Mình tin rằng Lịch sử không chỉ là những con số và sự kiện khô khan. Mình kể chuyện bằng cả trái tim, giúp bạn cảm nhận được chiều sâu và ý nghĩa của từng giai đoạn lịch sử. Phương pháp của mình là liên hệ quá khứ với hiện tại.', 'Lịch Sử sinh động - Khơi dậy niềm yêu thích quá khứ.', NULL, 'Cử nhân Lịch sử, Đại học Sư phạm.', NULL, NULL, '5 năm kinh nghiệm dạy Lịch sử cho học sinh cấp 2, 3. Giúp học sinh có cái nhìn khách quan, tránh học thuộc lòng. Tỷ lệ học sinh đạt điểm cao trong các kỳ thi tốt. Kinh nghiệm bồi dưỡng đội tuyển HSG.', 'Đồng Nai', 'Hải Châu', 'active', true, 4.6, 32, 381, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-471', 'Mình có khả năng giải thích các khái niệm Hóa học phức tạp một cách đơn giản và dễ hiểu. Mình tập trung vào việc rèn luyện kỹ năng giải bài tập, từ các dạng cơ bản đến các bài toán vận dụng cao. Đảm bảo bạn sẽ tự tin khi làm bài kiểm tra.', 'Hóa học THPT - Giải quyết mọi dạng bài tập từ cơ bản đến nâng cao.', NULL, 'Sinh viên năm cuối ngành Hóa dược, Đại học Dược Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học. Giúp học sinh cải thiện điểm số rõ rệt. Kinh nghiệm ôn thi THPT môn Hóa, đặc biệt là các phần khó như Đại cương, Hữu cơ.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.4, 25, 247, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-472', 'Mình muốn bạn thấy Địa lý không chỉ là bản đồ mà là cả một thế giới đầy thú vị. Mình sử dụng hình ảnh, video và các câu chuyện thực tế để làm bài học sinh động. Giúp bạn hiểu và yêu thích môn Địa lý hơn.', 'Địa Lý khám phá - Thế giới rộng lớn ngay trong tầm tay bạn.', NULL, 'Cử nhân Địa lý học, Đại học Khoa học Tự nhiên.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý cấp 2, 3. Giúp học sinh có kiến thức nền tảng vững chắc và hứng thú với môn học. Kinh nghiệm ôn thi vào lớp 10.', 'Hà Nội', 'Hải Châu', 'active', true, 4.6, 33, 75, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-473', 'Mình tin rằng Tin học là công cụ mạnh mẽ giúp bạn làm việc hiệu quả hơn. Mình sẽ hướng dẫn bạn sử dụng thành thạo các phần mềm văn phòng và làm quen với lập trình. Phương pháp thực hành liên tục sẽ giúp bạn nhanh chóng làm chủ kỹ năng.', 'Tin học văn phòng & Lập trình cơ bản - Tối ưu công việc, khơi dậy sáng tạo.', NULL, 'Kỹ sư Phần mềm, Đại học Công nghệ.', NULL, NULL, '4 năm kinh nghiệm giảng dạy Tin học văn phòng và lập trình Scratch, Python cho học sinh. Giúp các em làm quen với tư duy lập trình và ứng dụng vào các dự án nhỏ.', 'TP.HCM', 'Hải Châu', 'active', true, 4, 38, 163, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-474', 'Mình yêu trẻ con và mong muốn giúp các bé có một khởi đầu thuận lợi với môn Toán. Mình sử dụng các trò chơi, bài tập sáng tạo và phương pháp giảng dạy gần gũi, kiên nhẫn. Mục tiêu là giúp bé tự tin, yêu thích Toán học.', 'Toán Tiểu học - Bé vui học, mẹ an tâm.', NULL, 'Sinh viên ngành Sư phạm Toán học, Đại học Sư phạm.', NULL, NULL, 'Có kinh nghiệm dạy kèm Toán cho học sinh tiểu học. Giúp các bé nắm vững kiến thức cơ bản, cải thiện kỹ năng làm bài và tăng sự hứng thú với môn học.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.3, 21, 222, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-475', 'Mình tập trung vào việc luyện kỹ năng nghe-nói, giúp bạn xây dựng phản xạ tự nhiên khi giao tiếp. Mình sử dụng các hoạt động tương tác, thảo luận nhóm và tình huống thực tế. Phù hợp với các bạn muốn cải thiện khả năng giao tiếp nhanh chóng.', 'Tiếng Anh giao tiếp - Luyện phản xạ, tự tin nói tiếng Anh như gió.', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Sài Gòn.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh giao tiếp. Kinh nghiệm luyện thi chứng chỉ Starters, Movers, Flyers cho thiếu nhi. Giúp học viên tự tin sử dụng Tiếng Anh trong đời sống.', 'Đồng Nai', 'Thủ Đức', 'active', true, 4.2, 59, 137, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-476', 'Mình muốn giúp các em học sinh cấp 2 cảm nhận vẻ đẹp và giá trị của Văn học. Mình tập trung vào phân tích tác phẩm, rèn luyện kỹ năng đọc hiểu và viết văn nghị luận. Giúp các em có nền tảng vững chắc cho các cấp học cao hơn.', 'Ngữ văn THCS - Cảm thụ văn chương, làm giàu tâm hồn.', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học Cần Thơ.', NULL, NULL, '4 năm kinh nghiệm dạy Văn cấp 2. Giúp học sinh nắm vững kiến thức, cải thiện kỹ năng làm bài và đạt kết quả tốt trong các kỳ thi. Có kinh nghiệm dạy kèm cá nhân.', 'TP.HCM', 'Thủ Đức', 'active', true, 5, 7, 105, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-477', 'Mình tin rằng Listening và Reading không chỉ cần kiến thức mà còn cần chiến thuật. Mình sẽ chia sẻ các mẹo làm bài hiệu quả, cách nhận biết bẫy và từ vựng thường gặp. Giúp bạn tối ưu thời gian và đạt điểm số mong muốn.', 'IELTS Listening & Reading - Chiến thuật thông minh, điểm số ấn tượng.', NULL, 'Du học sinh Úc, chuyên ngành Kinh doanh Quốc tế.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS. Từng đạt 7.5 IELTS. Giúp học viên nâng cao điểm số Listening và Reading một cách hiệu quả. Có kinh nghiệm dạy online.', 'Cần Thơ', 'Hải Châu', 'active', true, 4.4, 35, 405, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-478', 'Mình mong muốn mang đến một cách tiếp cận mới mẻ, giúp học sinh thấy Vật Lý không hề đáng sợ. Mình sử dụng các thí nghiệm mô phỏng, bài tập tình huống và giải thích sâu về bản chất vật lý. Phù hợp với học sinh cần củng cố kiến thức.', 'Vật Lý THPT - Phương pháp tiếp cận sáng tạo, dễ hiểu.', NULL, 'Cử nhân Vật lý, Đại học Khoa học.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý. Giúp học sinh nắm vững kiến thức cơ bản, cải thiện kỹ năng giải bài tập. Có kinh nghiệm ôn thi học sinh giỏi và THPTQG.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.3, 50, 275, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-479', 'Sinh học là môn học về sự sống, về chính chúng ta. Mình dùng phương pháp giảng dạy kết hợp lý thuyết và thực hành, liên hệ kiến thức với các vấn đề sức khỏe và môi trường. Giúp bạn hiểu sâu sắc hơn về thế giới tự nhiên.', 'Sinh học cấp 2 & 3 - Khám phá thế giới vi sinh vật đến cơ thể người.', NULL, 'Sinh viên năm cuối, ngành Y Đa khoa, Đại học Y Dược.', NULL, NULL, '2 năm kinh nghiệm dạy kèm Sinh học. Giúp học sinh nắm vững kiến thức cơ bản, chuẩn bị tốt cho các kỳ thi. Có khả năng truyền đạt kiến thức y khoa một cách dễ hiểu.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 5, 20, 368, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-480', 'Mình đam mê Toán học và có kinh nghiệm dày dạn trong việc bồi dưỡng học sinh giỏi. Mình tập trung vào việc phát triển tư duy logic, kỹ năng giải các bài toán khó và sáng tạo. Giúp học sinh đạt thành tích cao trong các kỳ thi.', 'Toán Olympic - Chinh phục các kỳ thi Toán năng khiếu.', NULL, 'Thạc sĩ Toán học, Đại học Sư phạm.', NULL, NULL, '8 năm kinh nghiệm giảng dạy Toán cho các lớp chuyên Toán và bồi dưỡng học sinh giỏi. Tỷ lệ học sinh đạt giải cao trong các kỳ thi quốc gia và quốc tế. Phương pháp giảng dạy chuyên sâu, bám sát chương trình bồi dưỡng.', 'Cần Thơ', 'Quận 3', 'active', true, 4.5, 58, 274, '2026-06-19 03:00:15.623131', '2026-06-19 03:00:15.623131', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-230', 'Mình là Lan Anh, một giáo viên Tiếng Anh đầy nhiệt huyết với hơn 5 năm kinh nghiệm. Mình tin rằng học ngôn ngữ là một hành trình khám phá thú vị. Phương pháp của mình tập trung vào việc tạo môi trường học tập tương tác, lấy học viên làm trung tâm, giúp các bạn phát triển kỹ năng nghe, nói, đọc, viết một cách tự nhiên và hiệu quả nhất. Mình đặc biệt phù hợp với các bạn học sinh THPT và sinh viên muốn cải thiện điểm số hoặc chuẩn bị cho các kỳ thi quan trọng.', 'Giáo viên Tiếng Anh giàu kinh nghiệm, giúp bạn tự tin giao tiếp và chinh phục mọi kỳ thi!', NULL, 'Tốt nghiệp loại Giỏi chuyên ngành Ngôn ngữ Anh tại Trường Đại học Sư phạm Hà Nội.', NULL, NULL, 'Đã đồng hành cùng hàng trăm học sinh đạt kết quả cao trong các kỳ thi học kỳ và tốt nghiệp. Giảng dạy tại các trung tâm Anh ngữ uy tín, có kinh nghiệm luyện thi IELTS cho nhiều lứa tuổi.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.2, 20, 393, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-481', 'Chào các bạn, mình là Minh Quân. Mình yêu Toán học và đã từng trải qua giai đoạn ôn thi đại học đầy thử thách. Mình sẽ chia sẻ những bí quyết, phương pháp tư duy logic để giải quyết bài toán khó một cách nhanh chóng và chính xác. Mình có cách tiếp cận gần gũi, giúp các bạn lấy lại sự tự tin với môn Toán. Phù hợp cho học sinh lớp 10-12 luyện thi đại học.', 'Thủ khoa Toán ĐH Bách Khoa, luyện thi đại học hiệu quả, điểm số đột phá!', NULL, 'Thủ khoa đầu ra ngành Toán Tin, Trường Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Gần 4 năm kinh nghiệm dạy Toán online và offline. Nhiều học trò đạt điểm 9+ môn Toán trong kỳ thi THPT Quốc gia. Đã xây dựng bộ đề luyện thi bám sát cấu trúc Bộ Giáo dục.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.9, 21, 181, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-482', 'Mình là Thu Trang, cô giáo Văn với tâm hồn bay bổng và tình yêu lớn dành cho văn chương. Mình tin rằng mỗi bài văn đều có thể trở thành một tác phẩm nghệ thuật. Phương pháp của mình là kết hợp kiến thức nền tảng vững chắc với việc khơi gợi cảm xúc, tư duy phản biện và khả năng diễn đạt của học sinh. Mình muốn giúp các bạn thấy Văn không chỉ là học thuộc mà là thấu hiểu và trải lòng.', 'Giáo viên Văn giàu cảm xúc, khơi nguồn sáng tạo, chinh phục điểm cao!', NULL, 'Cử nhân Sư phạm Ngữ văn, Trường Đại học Giáo dục - ĐHQG Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm giảng dạy tại trường THPT. Tỉ lệ học sinh đạt điểm giỏi môn Văn trên 80%. Thường xuyên tổ chức các buổi ngoại khóa văn học sáng tạo.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.6, 57, 400, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-483', 'Xin chào, mình là Tuấn Anh, một người đam mê Vật Lý. Mình biết nhiều bạn cảm thấy môn này khô khan và khó hiểu. Mình sẽ giúp các bạn tiếp cận Vật Lý một cách trực quan, sinh động thông qua các thí nghiệm ảo, ví dụ thực tế. Mục tiêu của mình là giúp bạn xây dựng nền tảng kiến thức vững chắc và phát triển tư duy giải quyết vấn đề. Rất vui được đồng hành cùng các bạn học sinh.', 'Chuyên gia Vật Lý, giúp bạn ''hiểu sâu, nhớ lâu'', vượt qua nỗi sợ môn Lý!', NULL, 'Thạc sĩ Vật lý Kỹ thuật, Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, '5 năm kinh nghiệm giảng dạy Vật Lý cho học sinh THPT. Thành công trong việc giúp nhiều học sinh cải thiện đáng kể điểm số, từ trung bình lên khá, giỏi. Có kinh nghiệm luyện thi học sinh giỏi cấp tỉnh.', 'Bình Dương', 'Hải Châu', 'active', true, 4.7, 34, 425, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-484', 'Chào bạn, mình là Bích Ngọc, người sẽ cùng bạn chinh phục band điểm IELTS mơ ước. Mình hiểu rằng mỗi người có một điểm mạnh, điểm yếu và mục tiêu khác nhau. Vì vậy, mình xây dựng lộ trình học tập riêng biệt, tập trung vào việc cải thiện từng kỹ năng (Listening, Speaking, Reading, Writing) một cách hiệu quả nhất. Mình luôn tạo không khí học tập thoải mái, truyền cảm hứng và động lực để bạn không ngừng tiến bộ.', 'Chuyên gia IELTS 8.0, lộ trình cá nhân hóa, cam kết band điểm mục tiêu!', NULL, 'Chứng chỉ IELTS 8.0 (Listening 9.0, Reading 8.5, Speaking 7.5, Writing 7.0), tốt nghiệp ngành Kinh tế Đối ngoại.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS cho học viên từ 16-35 tuổi. Tỷ lệ học viên đạt mục tiêu (từ 6.0 lên 7.0+) là trên 90%. Có kinh nghiệm dạy online hiệu quả.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.5, 9, 405, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-485', 'Mình là Gia Bảo, một lập trình viên đam mê công nghệ. Mình tin rằng Tin học không chỉ là lý thuyết mà còn là kỹ năng thực hành. Mình sẽ hướng dẫn các bạn từ những khái niệm cơ bản nhất về máy tính, lập trình đến việc xây dựng các dự án phần mềm, website đơn giản. Phương pháp của mình là ''học đi đôi với hành'', giúp các bạn tự tay tạo ra sản phẩm của mình. Phù hợp với học sinh, sinh viên và người mới bắt đầu.', 'Lập trình viên kinh nghiệm, dạy Tin học từ cơ bản đến nâng cao, xây dựng dự án thực tế!', NULL, 'Cử nhân Công nghệ Thông tin, Trường Đại học Công nghệ - ĐHQG Hà Nội.', NULL, NULL, 'Hơn 5 năm kinh nghiệm làm việc trong ngành phát triển phần mềm. Từng tham gia giảng dạy các khóa học lập trình cơ bản tại trung tâm. Đã hướng dẫn nhiều bạn trẻ xây dựng thành công website và ứng dụng đầu tay.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.7, 35, 78, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-486', 'Xin chào! Mình là Hoàng Yến, một cô giáo Hóa học luôn tràn đầy năng lượng. Mình muốn chứng minh rằng Hóa học không hề đáng sợ mà vô cùng thú vị và gần gũi với cuộc sống. Mình sử dụng các phương pháp giảng dạy trực quan, ví dụ minh họa sinh động và bài tập thực hành đa dạng để các bạn nắm vững kiến thức. Mình thích tạo không khí lớp học vui vẻ, khuyến khích các bạn đặt câu hỏi và khám phá.', 'Cô giáo Hóa học vui vẻ, phương pháp dễ hiểu, giúp bạn ''yêu'' Hóa!', NULL, 'Tốt nghiệp ngành Hóa học, Trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa học cho học sinh THPT. Giúp nhiều học sinh cải thiện điểm số, đặc biệt là các phần khó như Hóa vô cơ và Hóa hữu cơ. Có kinh nghiệm ôn luyện thi học sinh giỏi.', 'Hà Nội', 'Ninh Kiều', 'active', true, 4.2, 59, 92, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-487', 'Chào các bạn, mình là Minh Khôi, người sẽ cùng bạn khám phá thế giới kỳ diệu của Sinh học. Mình tin rằng Sinh học không chỉ là những công thức, định luật mà còn là sự vận hành tinh tế của sự sống. Mình có phương pháp giảng dạy logic, hệ thống hóa kiến thức và liên hệ với thực tiễn. Mình sẽ giúp bạn xây dựng nền tảng vững chắc để không chỉ học tốt trên lớp mà còn hiểu sâu sắc hơn về thế giới xung quanh.', 'Chuyên gia Sinh học, kiến thức chuyên sâu, giúp bạn hiểu quy luật cuộc sống!', NULL, 'Thạc sĩ Sinh học Phân tử, Viện Nghiên cứu Sinh học - Viện Hàn lâm Khoa học và Công nghệ Việt Nam.', NULL, NULL, '6 năm kinh nghiệm giảng dạy và nghiên cứu Sinh học. Đã hướng dẫn nhiều học sinh làm quen với phương pháp nghiên cứu khoa học. Giúp học sinh đạt thành tích cao trong các kỳ thi chọn lọc.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.3, 17, 81, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-488', 'Mình là Thu Hà, yêu Lịch sử và tin rằng quá khứ luôn ẩn chứa những bài học quý giá cho hiện tại. Mình không dạy Lịch sử như một chuỗi sự kiện khô khan, mà thông qua việc kể chuyện, phân tích nguyên nhân - kết quả và liên hệ với bối cảnh xã hội. Mình muốn giúp các bạn cảm nhận được chiều sâu, sự hấp dẫn của Lịch sử và phát triển tư duy nhận thức. Phù hợp với học sinh muốn hiểu sâu và yêu thích môn Sử.', 'Giáo viên Lịch sử tâm huyết, biến những con số thành câu chuyện sống động!', NULL, 'Cử nhân Sư phạm Lịch sử, Trường Đại học Sư phạm TP.HCM.', NULL, NULL, '5 năm kinh nghiệm giảng dạy Lịch sử tại trường THPT. Nhiều học sinh của mình đã đạt điểm cao trong các bài kiểm tra và kỳ thi quan trọng. Thường xuyên tổ chức các buổi thảo luận, ngoại khóa về lịch sử.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.7, 36, 203, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-489', 'Xin chào, mình là Văn Long, người sẽ cùng bạn khám phá những miền đất mới và hiểu về hành tinh của chúng ta. Mình có niềm đam mê lớn với Địa lý và muốn truyền cảm hứng đó đến các bạn. Phương pháp của mình là kết hợp kiến thức sách vở với thông tin thực tế, hình ảnh sinh động và các hoạt động tương tác. Mình tin rằng Địa lý sẽ trở nên dễ dàng và thú vị hơn bao giờ hết với cách tiếp cận này.', 'Thầy Long Địa lý: bản đồ thế giới trong tầm tay, kiến thức thực tế!', NULL, 'Cử nhân Địa lý học, Trường Đại học Khoa học Xã hội và Nhân văn - ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Địa lý cho học sinh THPT. Giúp nhiều học sinh nắm vững kiến thức địa lý Việt Nam và thế giới. Có kinh nghiệm ôn thi tốt nghiệp và tuyển sinh đại học.', 'Đồng Nai', 'Quận 3', 'active', true, 4.3, 57, 279, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-490', 'Mình là Mai Phương, một giáo viên Tiếng Anh luôn cố gắng mang đến những giờ học vui vẻ và bổ ích. Mình tập trung vào việc xây dựng sự tự tin cho học viên, đặc biệt là trong giao tiếp. Mình sử dụng nhiều hoạt động thực hành, trò chơi ngôn ngữ và phương pháp lặp lại ngắt quãng để giúp các bạn ghi nhớ từ vựng, cấu trúc ngữ pháp một cách tự nhiên. Mình rất vui khi được nhìn thấy sự tiến bộ của học trò.', 'Giáo viên Tiếng Anh thân thiện, giao tiếp tự tin, phát âm chuẩn!', NULL, 'Tốt nghiệp ngành Sư phạm Tiếng Anh, Trường Đại học Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh cho học sinh tiểu học và THCS. Chú trọng phát triển kỹ năng nghe nói cho trẻ. Giúp các em hình thành thói quen học Tiếng Anh một cách hứng thú.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.7, 41, 147, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-491', 'Chào các bạn, mình là Minh Hoàng. Mình có kinh nghiệm dày dạn trong việc luyện thi Toán cho kỳ thi THPT Quốc gia. Mình không chỉ truyền đạt kiến thức mà còn rèn luyện cho các bạn kỹ năng phân tích đề, tư duy phản biện và chiến thuật làm bài hiệu quả. Mình tin rằng mọi học sinh đều có thể đạt điểm cao nếu có phương pháp đúng đắn và sự kiên trì. Cùng mình chinh phục đỉnh cao Toán học nhé!', 'Thầy Hoàng Toán: Luyện thi THPT, tư duy phản biện, bứt phá điểm số!', NULL, 'Cử nhân Toán học ứng dụng, Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, '6 năm kinh nghiệm luyện thi đại học môn Toán. Tỷ lệ học sinh đỗ nguyện vọng 1 cao. Thành thạo các dạng bài tập từ cơ bản đến nâng cao, có bộ tài liệu luyện thi độc quyền.', 'Cần Thơ', 'Quận 3', 'active', true, 4.2, 16, 383, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-492', 'Mình là Kim Ngân, một người bạn đồng hành tin cậy trên con đường chinh phục IELTS. Với kinh nghiệm giảng dạy và thành tích cá nhân 7.5, mình hiểu rõ những khó khăn học viên thường gặp phải. Mình áp dụng phương pháp học tập cá nhân hóa, tập trung vào điểm yếu và cung cấp các chiến lược làm bài hiệu quả cho từng kỹ năng. Mình luôn lắng nghe và hỗ trợ học viên hết mình.', 'IELTS 7.5, luyện thi chuyên sâu, lộ trình hiệu quả cho mọi trình độ!', NULL, 'IELTS 7.5 (Listening 8.0, Reading 8.0, Speaking 7.0, Writing 7.0), tốt nghiệp ngành Quản trị Kinh doanh.', NULL, NULL, '2 năm kinh nghiệm dạy luyện thi IELTS cho sinh viên và người đi làm. Giúp nhiều học viên cải thiện điểm số nhanh chóng, đạt mục tiêu du học và làm việc. Có kinh nghiệm dạy online.', 'Hà Nội', 'Quận 7', 'active', true, 4.9, 56, 75, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-493', 'Chào các bạn, mình là Duy Khang. Mình yêu Văn học và muốn chia sẻ niềm đam mê đó. Mình tập trung vào việc phân tích các tác phẩm văn học một cách chi tiết, khai thác những tầng nghĩa sâu sắc và hướng dẫn các bạn kỹ năng viết văn nghị luận sắc bén, logic. Mình tin rằng với sự hướng dẫn đúng đắn, môn Văn sẽ trở nên hấp dẫn và dễ dàng đạt điểm cao.', 'Thầy Khang Văn: Phân tích tác phẩm sâu sắc, luyện viết văn nghị luận đỉnh cao!', NULL, 'Cử nhân Văn học, Trường Đại học Khoa học Xã hội và Nhân văn - ĐHQG TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Văn và luyện thi đại học. Giúp nhiều học sinh đạt điểm giỏi môn Văn. Có kinh nghiệm soạn giáo án và bài tập bám sát chương trình.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.2, 11, 382, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-494', 'Mình là Minh Thư, một cô giáo Vật Lý đầy năng lượng. Mình tin rằng Vật Lý không phải là những công thức khó nhằn mà là những quy luật thú vị của vũ trụ. Mình sử dụng các thí nghiệm minh họa, hình ảnh động và bài tập ứng dụng thực tế để giúp các bạn hình dung rõ ràng hơn về các khái niệm. Mục tiêu của mình là làm cho môn Vật Lý trở nên dễ tiếp cận và hấp dẫn hơn với mọi học sinh.', 'Cô giáo Lý trẻ trung, phương pháp trực quan, giải mã bí ẩn Vật lý!', NULL, 'Cử nhân Vật lý Lý thuyết, Trường Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Có khả năng truyền đạt kiến thức phức tạp một cách dễ hiểu. Giúp học sinh xây dựng nền tảng kiến thức vững chắc cho các cấp học cao hơn.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.2, 12, 399, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-495', 'Chào bạn, mình là Văn Bảo. Nếu bạn đang muốn bắt đầu hành trình khám phá thế giới lập trình, mình rất sẵn lòng đồng hành. Mình chuyên dạy các ngôn ngữ lập trình phổ biến như Python, C++ và các kiến thức cơ bản về phát triển web. Phương pháp của mình là thực hành liên tục, xây dựng từng bước nhỏ và giải quyết vấn đề cùng học viên. Mình tin rằng ai cũng có thể học lập trình.', 'Tự tin lập trình cùng thầy Bảo: Python, C++, Web căn bản!', NULL, 'Cử nhân Khoa học Máy tính, Trường Đại học CNTT - ĐHQG TP.HCM.', NULL, NULL, '3 năm kinh nghiệm làm việc trong lĩnh vực phát triển phần mềm. Đã hướng dẫn các khóa học lập trình cơ bản cho người mới bắt đầu. Giúp học viên làm quen với các công cụ và môi trường lập trình.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.6, 55, 321, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-496', 'Mình là Thảo My, một người yêu thiên nhiên và luôn tò mò về các quy luật sinh học. Mình mong muốn chia sẻ kiến thức Sinh học một cách gần gũi, giúp các bạn hiểu về cơ thể mình, môi trường xung quanh và tầm quan trọng của việc bảo vệ sức khỏe. Phương pháp của mình là đặt câu hỏi, khuyến khích tìm tòi và liên hệ kiến thức với các vấn đề thực tế. Mình phù hợp với các bạn muốn hiểu thêm về thế giới sống.', 'Tư vấn Sinh học, giúp bạn khám phá thế giới tự nhiên và sức khỏe!', NULL, 'Cử nhân Sinh học, Trường Đại học Y Dược - Đại học Huế.', NULL, NULL, '2 năm kinh nghiệm làm trợ giảng Sinh học tại trường đại học. Có kinh nghiệm tổ chức các buổi thực hành cơ bản về sinh học cho sinh viên năm nhất.', 'TP.HCM', 'Bình Thạnh', 'active', true, 4.8, 19, 110, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-497', 'Xin chào, mình là Hoàng Nam. Mình có kinh nghiệm trong việc giảng dạy và giải đáp các dạng bài tập Hóa học từ cơ bản đến nâng cao. Mình tập trung vào việc giúp học sinh hiểu rõ bản chất của từng phản ứng, định luật và áp dụng chúng vào giải bài tập một cách nhanh chóng. Phương pháp của mình là thực hành nhiều bài tập, cung cấp các mẹo giải nhanh và luôn sẵn sàng giải thích mọi thắc mắc.', 'Thầy Nam Hóa: Giải bài tập Hóa, ôn thi hiệu quả, kiến thức bám sát!', NULL, 'Cử nhân Sư phạm Hóa học, Trường Đại học Vinh.', NULL, NULL, '5 năm kinh nghiệm dạy Hóa học, đặc biệt là luyện thi THPT. Đã giúp nhiều học sinh cải thiện đáng kể điểm số môn Hóa. Có kho bài tập phong phú theo từng chuyên đề.', 'Đà Nẵng', 'Ninh Kiều', 'active', true, 4.2, 21, 125, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-498', 'Mình là Thu Trang, một người yêu Lịch sử và mong muốn truyền cảm hứng học tập cho các bạn. Mình tin rằng Lịch sử không chỉ là những sự kiện mà là những câu chuyện đầy ý nghĩa. Mình sử dụng các phương pháp giảng dạy sáng tạo, kết hợp hình ảnh, tư liệu lịch sử và các câu chuyện thú vị để bài học thêm sinh động. Mình muốn giúp các bạn tiếp cận Lịch sử một cách tự nhiên và hiệu quả.', 'Cô Trang Lịch sử: Học Sử không nhàm chán, nhớ lâu, thi tốt!', NULL, 'Cử nhân Sư phạm Lịch sử, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch sử cho học sinh THCS và THPT. Chú trọng phương pháp nhớ lịch sử dễ dàng, tránh học thuộc lòng. Giúp học sinh làm quen với các dạng đề thi Lịch sử.', 'Đà Nẵng', 'Hoàng Mai', 'active', true, 4.6, 24, 447, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-499', 'Chào các bạn, mình là Gia Huy. Mình có niềm yêu thích đặc biệt với Địa lý và thế giới xung quanh. Mình muốn chia sẻ kiến thức Địa lý một cách sinh động, thực tế, giúp các bạn không chỉ nhớ bản đồ mà còn hiểu về các hiện tượng tự nhiên, kinh tế - xã hội. Phương pháp của mình là kết hợp lý thuyết với các ví dụ thực tế, tin tức thời sự và các hoạt động tương tác. Hãy cùng mình khám phá thế giới nhé!', 'Địa lý thực tế cùng Gia Huy: bản đồ, khí hậu, kinh tế - tất cả trong tầm tay!', NULL, 'Cử nhân Quản lý Tài nguyên và Môi trường, Trường Đại học Tài nguyên và Môi trường.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý cho học sinh THPT. Có kinh nghiệm ôn luyện thi THPT Quốc gia môn Địa lý. Giúp học sinh có cái nhìn tổng quan và kiến thức nền tảng vững chắc.', 'Bình Dương', 'Phú Nhuận', 'active', true, 5, 7, 269, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-500', 'Mình là Bích Liên, một giáo viên Toán kiên nhẫn và tận tâm. Mình hiểu rằng có những bạn gặp khó khăn với môn Toán và cảm thấy mất tự tin. Mình tập trung vào việc xây dựng lại kiến thức nền tảng một cách vững chắc, đi từ những khái niệm cơ bản nhất. Phương pháp của mình là chia nhỏ bài học, luyện tập nhiều dạng bài tập từ dễ đến khó và luôn động viên học sinh. Mình mong muốn giúp các bạn vượt qua rào cản với môn Toán.', 'Cô Liên Toán: Hỗ trợ học sinh yếu kém, xây dựng nền tảng vững chắc!', NULL, 'Cử nhân Sư phạm Toán học, Trường Đại học Sư phạm Đà Nẵng.', NULL, NULL, '6 năm kinh nghiệm dạy Toán, đặc biệt là hỗ trợ học sinh mất gốc và học sinh yếu kém. Giúp nhiều học sinh tiến bộ rõ rệt và đạt điểm số mong muốn trong các kỳ thi.', 'Biên Hòa', 'Bình Thạnh', 'active', true, 4.3, 53, 99, '2026-06-19 03:01:03.663812', '2026-06-19 03:01:03.663812', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-506', 'Chào bạn, mình là Minh Anh. Mình tin rằng học Tiếng Anh không hề khô khan. Mình sẽ cùng bạn xây dựng nền tảng vững chắc, đặc biệt là phản xạ giao tiếp, qua các hoạt động tương tác vui nhộn và thực tế. Bạn học sinh mất gốc hay ngại nói đều hợp với phương pháp của mình.', 'Tiếng Anh giao tiếp tự tin, luyện thi chứng chỉ quốc tế A2-B1', NULL, 'Cử nhân ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh cho học sinh THCS và THPT. Giúp nhiều bạn cải thiện điểm số và tự tin giao tiếp hơn hẳn. Đã dạy các lớp ôn thi chứng chỉ Flyers, Movers.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.8, 53, 425, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-507', 'Xin chào, mình là Hùng. Mình tập trung vào việc giúp học sinh hiểu sâu bản chất vấn đề thay vì học thuộc công thức. Phương pháp của mình là đặt câu hỏi, khuyến khích suy luận logic và làm bài tập đa dạng. Mình rất kiên nhẫn và luôn tìm cách tiếp cận phù hợp nhất với từng em.', 'Toán tư duy cho học sinh lớp 6-9, bứt phá điểm số', NULL, 'Thạc sĩ ngành Sư phạm Toán học, Đại học Sư phạm Hà Nội.', NULL, NULL, 'Gia sư Toán 5 năm. Tỉ lệ học sinh đạt điểm khá giỏi trên 90%. Từng dạy các lớp luyện thi vào lớp 10 chuyên Toán.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.3, 60, 432, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-508', 'Mình là Bích Ngọc. Mình yêu văn chương và muốn lan tỏa tình yêu đó đến các bạn. Mình sẽ giúp bạn phân tích tác phẩm một cách tinh tế, nắm vững kiến thức trọng tâm và biết cách diễn đạt ý của mình một cách mạch lạc, cảm xúc. Dành cho các bạn muốn nâng cao điểm số hoặc đơn giản là yêu thích môn Văn.', 'Chinh phục Ngữ Văn, cảm thụ văn chương qua từng câu chữ', NULL, 'Cử nhân ngành Văn học, Đại học Khoa học Xã hội và Nhân văn TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Văn cấp 2, 3. Đã giúp nhiều học sinh cải thiện kỹ năng viết bài văn nghị luận và cảm thụ văn học. Thường xuyên tổ chức các buổi thảo luận nhóm về tác phẩm.', 'Đà Nẵng', 'Quận 1', 'active', true, 4.2, 57, 450, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-509', 'Chào các bạn, mình là Tuấn Kiệt. Vật Lý đôi khi có vẻ khó nhằn, nhưng mình sẽ chứng minh điều ngược lại! Mình thích dùng ví dụ thực tế, thí nghiệm minh họa và cách giải thích từng bước một. Mục tiêu là giúp bạn không chỉ hiểu mà còn yêu thích môn học này. Phù hợp với học sinh THPT muốn nắm vững kiến thức và luyện thi đại học.', 'Vật Lý thực tế, giải thích cặn kẽ, ôn thi hiệu quả', NULL, 'Sinh viên năm cuối ngành Kỹ thuật Điện tử, Đại học Bách Khoa Hà Nội.', NULL, NULL, 'Gần 3 năm làm gia sư Vật Lý. Nhiều học trò đạt điểm cao trong các kỳ thi. Có kinh nghiệm ôn thi THPT Quốc gia môn Vật Lý.', 'Biên Hòa', 'Thủ Đức', 'active', true, 4.9, 27, 129, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-510', 'Hi, mình là Thảo Vy. Mình có kinh nghiệm luyện thi IELTS, đặc biệt là Writing và Speaking. Mình tập trung vào việc xây dựng chiến lược làm bài hiệu quả, cung cấp từ vựng học thuật và luyện tập thực hành thường xuyên. Mình là người khá kỹ tính, luôn muốn học trò của mình đạt kết quả tốt nhất có thể.', 'Luyện IELTS Writing & Speaking, điểm mục tiêu 6.5+', NULL, 'IELTS 8.0 (Listening 9.0, Reading 8.5, Writing 7.5, Speaking 7.0). Cử nhân ngành Kinh tế, Đại học Kinh tế Quốc dân.', NULL, NULL, '2 năm kinh nghiệm dạy IELTS, chủ yếu là Writing và Speaking. Giúp nhiều bạn đạt điểm mục tiêu cho du học và công việc. Có kinh nghiệm hướng dẫn bài tập về nhà và sửa lỗi chi tiết.', 'TP.HCM', 'Hải Châu', 'active', true, 4.3, 30, 377, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-511', 'Chào bạn, mình là Minh Quân. Nếu bạn muốn làm quen với máy tính, học lập trình hay cần hỗ trợ về các phần mềm văn phòng, mình đều có thể giúp. Mình thích giảng dạy một cách thực tế, từng bước một, đảm bảo bạn nắm vững kiến thức. Mình là người cởi mở, dễ gần, sẵn sàng giải đáp mọi thắc mắc.', 'Tin Học cơ bản & nâng cao, lập trình Python cho người mới bắt đầu', NULL, 'Cử nhân ngành Khoa học Máy tính, Đại học Công nghệ - Đại học Quốc gia Hà Nội.', NULL, NULL, 'Gia sư Tin học 3 năm. Đã hướng dẫn nhiều học sinh cấp 2, 3 làm quen với lập trình Scratch, Python và Word, Excel. Có kinh nghiệm làm dự án cá nhân về AI cơ bản.', 'TP.HCM', 'Quận 1', 'active', true, 4.6, 15, 428, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-512', 'Mình là Thu Trang. Hóa học có thể thú vị nếu chúng ta biết cách tiếp cận! Mình sẽ giúp bạn hệ thống lại kiến thức, nắm vững các dạng bài tập từ cơ bản đến nâng cao, và rèn luyện kỹ năng giải nhanh. Mình là người tỉ mỉ, kiên nhẫn, luôn động viên học trò của mình. Phù hợp với học sinh lớp 10-12.', 'Hóa Học dễ hiểu, ôn thi THPT Quốc gia và các kỳ thi đánh giá năng lực', NULL, 'Thạc sĩ ngành Hóa học, Đại học Khoa học Tự nhiên TP.HCM.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa học. Nhiều học sinh đạt điểm 8+ trong kỳ thi THPT. Từng dạy các lớp luyện thi chứng chỉ Hóa học.', 'Cần Thơ', 'Quận 7', 'active', true, 4.5, 21, 155, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-513', 'Xin chào, mình là Quốc Bảo. Mình muốn chia sẻ niềm đam mê với Sinh học, môn học về chính cuộc sống của chúng ta. Mình sẽ giúp bạn hiểu các khái niệm phức tạp một cách đơn giản thông qua hình ảnh, sơ đồ và ví dụ thực tế. Nếu bạn đang tìm kiếm một người đồng hành khám phá thế giới vi mô và vĩ mô, mình là lựa chọn phù hợp.', 'Sinh Học ứng dụng, giúp bạn yêu thích khám phá thế giới tự nhiên', NULL, 'Sinh viên Y Đa khoa, Đại học Y Hà Nội.', NULL, NULL, 'Gia sư Sinh học 2 năm cho học sinh THPT. Giúp các bạn nắm vững kiến thức để đạt kết quả tốt trong học tập và thi cử. Thường xuyên cập nhật những kiến thức mới về Sinh học.', 'Biên Hòa', 'Quận 3', 'active', true, 4.7, 36, 254, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-514', 'Hi there! Mình là Yến Nhi. Mình có thể dạy Tiếng Anh cho mọi đối tượng, từ các bé nhỏ làm quen với ngôn ngữ, đến các bạn học sinh cần cải thiện điểm số, hoặc người đi làm muốn giao tiếp trôi chảy hơn. Phương pháp của mình linh hoạt, kết hợp nhiều hoạt động và luôn tạo không khí thoải mái, vui vẻ. Mình rất thích làm bạn đồng hành cùng học viên trên chặng đường chinh phục Tiếng Anh.', 'Tiếng Anh cho mọi lứa tuổi, từ giao tiếp đến luyện thi', NULL, 'Cử nhân ngành Sư phạm Tiếng Anh, Đại học Sư phạm TP.HCM.', NULL, NULL, 'Gia sư Tiếng Anh 4 năm. Đã dạy qua nhiều cấp độ và lứa tuổi. Nhiều học sinh tiến bộ rõ rệt về kỹ năng nghe, nói. Kinh nghiệm ôn luyện cho kỳ thi học sinh giỏi Tiếng Anh cấp thành phố.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.8, 56, 105, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-515', 'Chào mọi người, mình là Minh Đức. Mình chuyên dạy Toán cho học sinh tiểu học và THCS. Mình tập trung vào việc xây dựng nền tảng vững chắc, rèn luyện tư duy logic và kỹ năng giải toán nhanh. Mình là người nghiêm túc trong giảng dạy nhưng cũng rất gần gũi với học trò. Nếu bạn cần một gia sư vừa giỏi chuyên môn vừa tâm lý, hãy liên hệ với mình.', 'Toán cơ bản và nâng cao, luyện thi vào lớp 6 và lớp 10', NULL, 'Cử nhân ngành Toán học Ứng dụng, Đại học Bách Khoa TP.HCM.', NULL, NULL, '5 năm kinh nghiệm dạy Toán. Nhiều học sinh đỗ vào các trường chuyên, trường chất lượng cao. Có kinh nghiệm biên soạn tài liệu ôn tập.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.1, 10, 148, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-516', 'Mình là Kim Ngân. Địa Lý không chỉ là những con số khô khan, mà là cả một thế giới để khám phá! Mình sẽ giúp bạn nhìn nhận các vấn đề địa lý dưới góc độ thực tế, liên hệ với cuộc sống hàng ngày. Phương pháp của mình là kết hợp bản đồ, hình ảnh trực quan và các câu chuyện thú vị. Mình mong muốn truyền cảm hứng học tập cho các bạn học sinh lớp 9-12.', 'Địa Lý thú vị, kiến thức thực tế, ôn thi THPT', NULL, 'Cử nhân ngành Địa lý học, Đại học Khoa học Huế.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý. Giúp học sinh hiểu bài nhanh và nhớ kiến thức lâu hơn. Có kinh nghiệm ôn luyện cho kỳ thi THPT Quốc gia môn Địa Lý.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 4.7, 45, 228, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-517', 'Chào bạn, mình là Quang Huy. Mình chuyên sâu về Vật Lý cho học sinh THPT. Mình có phương pháp giảng dạy logic, đi từ gốc rễ vấn đề, kết hợp với việc luyện tập các dạng bài tập thường gặp trong đề thi. Mình là người khá kỹ tính và luôn cố gắng truyền đạt kiến thức một cách dễ hiểu nhất. Hãy cùng mình chinh phục Vật Lý nhé!', 'Vật Lý THPT - Giải thích cặn kẽ, bài tập bám sát đề thi', NULL, 'Thạc sĩ Vật Lý Kỹ thuật, Đại học Khoa học Tự nhiên - Đại học Quốc gia Hà Nội.', NULL, NULL, '6 năm kinh nghiệm dạy Vật Lý THPT. Nhiều học trò đạt điểm cao, đỗ các trường đại học top đầu. Có kinh nghiệm luyện thi các chương trình Vật Lý chuyên sâu.', 'Bình Dương', 'Hải Châu', 'active', true, 4.3, 56, 93, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-518', 'Mình là Lan Chi. Mình tin rằng mỗi tác phẩm văn học đều chứa đựng những thông điệp và giá trị sâu sắc. Mình sẽ giúp bạn không chỉ học thuộc lòng mà còn biết cách phân tích, cảm thụ và rung động với từng câu chữ. Mình có cách truyền đạt gần gũi, tạo không gian học tập cởi mở, khuyến khích học sinh bày tỏ suy nghĩ của mình.', 'Ngữ Văn - Khơi gợi cảm xúc, nâng cao tư duy cảm thụ', NULL, 'Cử nhân ngành Sư phạm Ngữ văn, Đại học Sư phạm Đà Nẵng.', NULL, NULL, '4 năm kinh nghiệm dạy Ngữ Văn cấp 3. Giúp học sinh phát triển kỹ năng viết văn sáng tạo và lập luận chặt chẽ. Đã có kinh nghiệm bồi dưỡng học sinh giỏi Văn.', 'Hà Nội', 'Hải Châu', 'active', true, 4.8, 27, 180, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-519', 'Chào các bạn, mình là Bảo Long. Mình tập trung vào việc phát triển tư duy toán học cho các bạn học sinh khá giỏi. Mình không chỉ cung cấp kiến thức mà còn rèn luyện các kỹ năng giải toán độc đáo, sáng tạo và hiệu quả. Mình là người có kỷ luật, nghiêm khắc nhưng luôn hỗ trợ hết mình để học trò đạt được mục tiêu cao nhất.', 'Toán tư duy & phương pháp giải nhanh cho học sinh giỏi', NULL, 'Cựu học sinh chuyên Toán trường THPT Chuyên Nguyễn Huệ.', NULL, NULL, 'Gia sư Toán 5 năm. Nhiều học sinh đạt giải Olympic Toán cấp tỉnh. Có kinh nghiệm dạy các chuyên đề nâng cao và luyện thi học sinh giỏi.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.6, 47, 132, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-520', 'Hi! Mình là Hà My. Nếu bạn đang loay hoay với phần Speaking và Listening trong IELTS, mình có thể giúp bạn! Mình sẽ hướng dẫn bạn cách trả lời câu hỏi tự nhiên, phát âm chuẩn và xây dựng vốn từ vựng học thuật. Mình tạo không khí học thoải mái, khuyến khích bạn thực hành nhiều để tăng sự tự tin. Cùng nhau đạt band điểm mong muốn nhé!', 'IELTS Speaking & Listening - Tự tin phát âm, phản xạ nhanh', NULL, 'IELTS 7.5 (Speaking 8.0). Sinh viên năm 3 ngành Quan hệ Quốc tế, Học viện Ngoại giao.', NULL, NULL, '2 năm kinh nghiệm dạy IELTS Speaking & Listening. Giúp nhiều bạn cải thiện kỹ năng giao tiếp và đạt điểm số tốt. Có kinh nghiệm sửa lỗi phát âm và ngữ pháp.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.6, 13, 109, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-521', 'Xin chào, mình là Minh Nhật. Mình đam mê lập trình và muốn chia sẻ kiến thức này đến các bạn. Mình chuyên dạy Python cho người mới bắt đầu, tập trung vào việc hiểu logic lập trình và cách áp dụng vào các bài toán thực tế. Mình có cách giảng dạy sinh động, kiên nhẫn và luôn sẵn sàng giải đáp mọi thắc mắc của học viên.', 'Lập trình Python từ cơ bản, ứng dụng thực tế', NULL, 'Cử nhân ngành Kỹ thuật Phần mềm, Đại học FPT.', NULL, NULL, '3 năm kinh nghiệm dạy lập trình Python. Đã hướng dẫn nhiều học sinh, sinh viên hoàn thành các dự án nhỏ. Có kinh nghiệm tham gia các cuộc thi lập trình.', 'Hà Nội', 'Bình Thạnh', 'active', true, 4, 17, 144, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-522', 'Chào các bạn, mình là Mai Hương. Mình tin rằng Sinh học là một môn học cực kỳ thú vị nếu chúng ta biết cách học đúng phương pháp. Mình sẽ giúp bạn hệ thống lại kiến thức một cách khoa học, dễ hiểu, đồng thời rèn luyện kỹ năng làm bài tập trắc nghiệm và tự luận. Mình là người cẩn thận, luôn theo sát tiến độ học tập của từng bạn.', 'Sinh Học THPT - Nắm vững kiến thức, tự tin thi cử', NULL, 'Cử nhân ngành Công nghệ Sinh học, Đại học Nông Lâm TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Sinh học cấp 3. Nhiều học sinh của mình đã đạt điểm cao trong các kỳ thi. Có kinh nghiệm ôn thi tốt nghiệp và đại học môn Sinh.', 'Bình Dương', 'Hải Châu', 'active', true, 4.4, 13, 81, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-523', 'Chào bạn, mình là Minh Khang. Mình muốn mang đến một cái nhìn mới mẻ và thú vị về Lịch Sử. Mình sẽ giúp bạn không chỉ nhớ các sự kiện mà còn hiểu được bối cảnh, nguyên nhân và hệ quả của chúng. Phương pháp của mình là kể chuyện, sử dụng bản đồ và hình ảnh để bài học trở nên sinh động hơn. Phù hợp với các bạn muốn học Sử một cách nhẹ nhàng và hiệu quả.', 'Lịch Sử sống động, kết nối quá khứ với hiện tại', NULL, 'Cử nhân ngành Lịch sử, Đại học Sư phạm Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch Sử. Giúp học sinh có hứng thú hơn với môn học và cải thiện điểm số. Thường xuyên chia sẻ những kiến thức lịch sử thú vị ngoài sách giáo khoa.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.7, 29, 437, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-524', 'Xin chào, mình là Thu Hoài. Mình chuyên dạy Toán cho học sinh tiểu học. Mình chú trọng vào việc xây dựng cho các con tư duy logic, kỹ năng giải toán cơ bản và tình yêu với môn Toán. Mình là người nhẹ nhàng, kiên nhẫn, luôn tạo môi trường học tập vui vẻ, không áp lực. Phụ huynh hoàn toàn có thể tin tưởng giao con mình cho mình.', 'Toán tiểu học - Xây dựng nền tảng vững chắc cho tương lai', NULL, 'Cử nhân Sư phạm Toán học, Đại học Giáo dục - Đại học Quốc gia Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Toán tiểu học. Nhiều học sinh tiến bộ vượt bậc về tư duy và kết quả học tập. Đã có kinh nghiệm ôn luyện thi vào lớp 6 các trường chuyên.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.5, 41, 417, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-525', 'Hey there! Mình là Tuấn Anh. Mình có kinh nghiệm dạy Tiếng Anh cho các bạn học sinh cấp 1, cấp 2, đặc biệt là luyện thi các chứng chỉ quốc tế như KET, PET. Mình sử dụng phương pháp học tương tác, đa dạng hoạt động và tập trung vào phát triển kỹ năng nghe, nói, đọc, viết một cách cân bằng. Mình là người năng động, nhiệt huyết và luôn truyền cảm hứng học tập cho học trò.', 'Tiếng Anh giao tiếp & luyện thi chứng chỉ Cambridge (KET, PET)', NULL, 'Cử nhân ngành Kinh tế đối ngoại, Đại học Ngoại thương.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi chứng chỉ. Có kinh nghiệm tổ chức các buổi học nhóm vui nhộn.', 'Đồng Nai', 'Quận 1', 'active', true, 4.5, 60, 146, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-526', 'Mình là Mai Phương. Mình giúp các bạn học sinh THPT vượt qua nỗi sợ Hóa học bằng cách giảng dạy dễ hiểu, gần gũi. Mình tập trung vào việc xây dựng kiến thức nền tảng vững chắc, rèn luyện kỹ năng giải bài tập nhanh và chính xác. Mình là người tỉ mỉ, chu đáo, luôn theo dõi sát sao để đảm bảo học sinh nắm chắc kiến thức.', 'Hóa Học THPT - Giải thích dễ hiểu, luyện thi hiệu quả', NULL, 'Cử nhân ngành Hóa dược, Đại học Dược Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Hóa học. Nhiều học sinh của mình đã đạt điểm 8, 9 trong kỳ thi THPT Quốc gia. Có kinh nghiệm ôn luyện các dạng bài tập khó.', 'Đà Nẵng', 'Quận 3', 'active', true, 4.5, 40, 330, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-527', 'Chào các bạn, mình là Minh Quân. Mình chuyên dạy Toán cho học sinh lớp 8, 9, đặc biệt là ôn thi vào lớp 10. Mình có phương pháp giảng dạy logic, bám sát chương trình và tập trung vào việc củng cố kiến thức, rèn luyện kỹ năng giải các dạng bài thi. Mình là người nghiêm túc, có kỷ luật nhưng luôn tạo không khí học tập tích cực.', 'Toán đại số & hình học, ôn thi vào lớp 10', NULL, 'Thạc sĩ ngành Sư phạm Toán học, Đại học Sư phạm TP.HCM.', NULL, NULL, '5 năm kinh nghiệm dạy Toán lớp 8, 9. Nhiều học sinh đã đỗ vào các trường THPT chuyên, trường công lập chất lượng cao. Có kinh nghiệm luyện thi vào lớp 10.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.1, 18, 73, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-528', 'Hello! Mình là Thuỳ Linh. Mình có thể giúp bạn cải thiện toàn diện Tiếng Anh, từ ngữ pháp, từ vựng đến cả 4 kỹ năng nghe, nói, đọc, viết. Mình thích sử dụng các tài liệu đa dạng, cập nhật để bài học không bị nhàm chán. Mình là người vui vẻ, nhiệt tình và luôn cố gắng tạo điều kiện tốt nhất để học viên tiến bộ.', 'Tiếng Anh tổng quát, phát triển toàn diện 4 kỹ năng', NULL, 'Cử nhân ngành Biên phiên dịch Tiếng Anh, Đại học Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Tiếng Anh tổng quát. Đã dạy cho nhiều đối tượng học viên khác nhau. Giúp học viên tự tin hơn trong giao tiếp hàng ngày.', 'Đà Nẵng', 'Hải Châu', 'active', true, 4.8, 54, 255, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-529', 'Xin chào, mình là Gia Bảo. Mình muốn mang đến một cách tiếp cận Vật Lý gần gũi và thực tế hơn. Mình tập trung vào việc giúp bạn hiểu sâu các định luật thông qua các thí nghiệm đơn giản, phân tích dữ liệu và ứng dụng vào đời sống. Mình là người ham học hỏi, kiên nhẫn và luôn khuyến khích học trò của mình đặt câu hỏi.', 'Vật Lý thực nghiệm, nâng cao khả năng tư duy và ứng dụng', NULL, 'Sinh viên năm cuối ngành Vật Lý, Đại học Khoa học Tự nhiên TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Giúp các bạn nắm vững kiến thức cốt lõi và phát triển tư duy phản biện. Có kinh nghiệm hướng dẫn làm các dự án Vật Lý nhỏ.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.9, 19, 71, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-530', 'Chào bạn, mình là Bích Hạnh. Mình có kinh nghiệm trong việc hướng dẫn học sinh THPT phân tích tác phẩm văn học một cách sâu sắc và xây dựng bài văn nghị luận chặt chẽ, logic. Mình tin rằng sự yêu thích môn Văn sẽ đến khi bạn hiểu được vẻ đẹp và giá trị của nó. Mình là người tỉ mỉ, chu đáo và luôn đặt tâm huyết vào việc giảng dạy.', 'Ngữ Văn - Phân tích sâu, bồi dưỡng kỹ năng viết văn nghị luận', NULL, 'Cử nhân ngành Văn hóa học, Đại học Văn hóa Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Ngữ Văn. Giúp học sinh có cái nhìn đa chiều về tác phẩm và cải thiện kỹ năng làm bài thi Văn. Có kinh nghiệm luyện thi đại học môn Văn.', 'TP.HCM', 'Quận 3', 'active', true, 4.3, 60, 204, '2026-06-19 03:01:16.917264', '2026-06-19 03:01:16.917264', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-531', 'Chào bạn, mình là Minh Anh. Mình tin rằng học Tiếng Anh sẽ trở nên thú vị khi bạn hiểu rõ bản chất và có phương pháp học phù hợp. Mình thích tạo không khí lớp học vui vẻ, khuyến khích học viên tự tin nói, sửa lỗi phát âm và ngữ pháp một cách nhẹ nhàng. Nếu bạn là người mới bắt đầu hoặc muốn cải thiện kỹ năng giao tiếp, mình rất sẵn lòng đồng hành.', 'Giúp bạn chinh phục Tiếng Anh giao tiếp và thi chứng chỉ!', NULL, 'Cử nhân chuyên ngành Ngôn ngữ Anh, Đại học Hà Nội.', NULL, NULL, 'Có 3 năm kinh nghiệm dạy Tiếng Anh giao tiếp cho người đi làm và sinh viên. Từng giúp nhiều học viên đạt điểm cao trong các bài thi chứng chỉ quốc tế như TOEIC.', 'Đồng Nai', 'Bình Thạnh', 'active', true, 4.1, 65, 427, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-532', 'Mình là Hùng, một người yêu Toán và luôn tìm cách truyền cảm hứng học Toán cho các bạn. Phương pháp của mình là đi từ gốc rễ vấn đề, xây dựng nền tảng vững chắc, sau đó mới nâng cao dần. Mình kiên nhẫn, gần gũi và luôn cố gắng giúp học sinh thấy Toán học không hề khô khan. Phù hợp với học sinh THPT ôn thi.', 'Gia sư Toán từ cơ bản đến nâng cao, bứt phá điểm số!', NULL, 'Sinh viên năm 3, Khoa Toán học, Trường Đại học Khoa học Tự nhiên, ĐHQG-HCM.', NULL, NULL, 'Đã dạy kèm Toán cho học sinh THPT 4 năm. Có kinh nghiệm ôn thi Đại học, giúp nhiều em đạt điểm Toán trên 8.', 'Bình Dương', 'Quận 1', 'active', true, 4.2, 60, 161, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-533', 'Xin chào, mình là Trang. Mình yêu văn chương và tin rằng mỗi tác phẩm đều có câu chuyện riêng để kể. Mình muốn chia sẻ cách cảm thụ văn học tinh tế, phân tích sâu sắc tác phẩm và rèn luyện kỹ năng diễn đạt, viết văn mạch lạc, giàu cảm xúc. Lớp học của mình đề cao sự trao đổi, thảo luận và khơi gợi tư duy phản biện. Đặc biệt phù hợp với các bạn học sinh lớp 10-12.', 'Chinh phục Ngữ văn: từ cảm thụ văn học đến kỹ năng viết xuất sắc.', NULL, 'Cử nhân Sư phạm Ngữ văn, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm giảng dạy Ngữ văn tại trường THPT. Đã đồng hành cùng nhiều thế hệ học sinh ôn thi tốt nghiệp và đại học.', 'Đà Nẵng', 'Bình Thạnh', 'active', true, 4.8, 11, 131, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-534', 'Chào các bạn, mình là Đức. Mình có niềm đam mê lớn với Vật Lý và cách nó giải thích thế giới xung quanh. Mình tiếp cận Vật Lý không chỉ bằng công thức mà còn bằng những ví dụ thực tế, trực quan sinh động. Mình sẽ giúp các bạn nắm vững lý thuyết, làm chủ bài tập từ dễ đến khó. Mình là người khá hài hước và nghiêm túc khi giảng bài, đảm bảo không khí học tập hiệu quả. Phù hợp với học sinh THPT.', 'Vật Lý thực tế: từ định luật đến ứng dụng, điểm số bay cao!', NULL, 'Kỹ sư Điện tử Viễn thông, Trường Đại học Bách Khoa Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy thêm Vật Lý. Giúp học sinh cải thiện đáng kể kết quả học tập, nhiều em đạt điểm giỏi.', 'Bình Dương', 'Quận 3', 'active', true, 4.3, 26, 424, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-535', 'Hi everyone, I''m Dương. I specialize in helping students achieve their target IELTS scores, especially band 7.0 and above. My teaching philosophy revolves around personalized strategies, understanding each student''s weaknesses, and practicing effectively. I focus on building confidence and exam techniques for all four skills: Listening, Speaking, Reading, and Writing. Let''s work together to reach your goals!', 'IELTS Tutor: Target 7.0+, chiến lược thông minh, điểm số bứt phá!', NULL, 'Master of Applied Linguistics, University of Education, Vietnam National University, Hanoi.', NULL, NULL, '5 years teaching IELTS. Successfully guided hundreds of students to achieve their desired scores for study abroad and immigration purposes.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 4.2, 29, 351, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-536', 'Mình là Tùng, một lập trình viên thích chia sẻ kiến thức. Mình dạy Tin học từ cơ bản đến nâng cao, đặc biệt là ngôn ngữ Python. Mình tin rằng ai cũng có thể học lập trình nếu có phương pháp đúng và sự kiên trì. Lớp học của mình nhẹ nhàng, thực hành nhiều, giúp bạn hiểu logic và ứng dụng được ngay. Phù hợp cho học sinh, sinh viên và cả người mới bắt đầu.', 'Tin học căn bản & lập trình Python cho mọi lứa tuổi.', NULL, 'Cử nhân Công nghệ Thông tin, Trường Đại học Công nghệ, ĐHQG-HCM.', NULL, NULL, '2 năm kinh nghiệm dạy lập trình Python cho người mới bắt đầu và học sinh. Đã hướng dẫn thành công nhiều dự án nhỏ.', 'TP.HCM', 'Hoàng Mai', 'active', true, 4.2, 65, 279, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-537', 'Chào bạn, mình là Ngọc. Mình có cách tiếp cận Hóa Học rất trực quan, kết nối lý thuyết với các hiện tượng thực tế. Mình tập trung vào việc giúp học sinh xây dựng nền tảng vững chắc, hiểu sâu bản chất từng phản ứng, cân bằng phương trình một cách logic. Mình kiên nhẫn, tỉ mỉ và luôn khuyến khích học sinh đặt câu hỏi. Phù hợp với học sinh THCS và THPT.', 'Hóa Học dễ hiểu: từ cấu tạo nguyên tử đến phản ứng phức tạp.', NULL, 'Cử nhân Hóa học, Trường Đại học Khoa học Tự nhiên, ĐHQG-HN.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa. Giúp nhiều học sinh vượt qua nỗi sợ Hóa học và đạt kết quả tốt trong các kỳ thi.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.3, 48, 426, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-538', 'Mình là Khôi, rất vui được làm gia sư Toán cho các bạn cấp 2. Mình hiểu rằng giai đoạn này các bạn đang làm quen với nhiều dạng toán mới và cần một người hướng dẫn bài bản. Mình sẽ giúp các bạn nắm vững kiến thức sách giáo khoa, làm quen với các dạng bài thi, và quan trọng là xây dựng tư duy giải toán logic. Mình có phong cách giảng dạy thân thiện, dễ gần, luôn động viên học trò.', 'Toán THCS: Nền tảng vững chắc, tự tin chinh phục mọi bài toán.', NULL, 'Sinh viên Y Đa khoa, Trường Đại học Y Dược TP.HCM.', NULL, NULL, 'Dạy kèm Toán THCS được 2 năm. Học sinh của mình đều tiến bộ rõ rệt về điểm số và sự tự tin.', 'Bình Dương', 'Quận 7', 'active', true, 4.6, 19, 67, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-539', 'Hello! Mình là Phương, mình có kinh nghiệm dạy Tiếng Anh giao tiếp và luyện phát âm. Mình tin rằng mọi người đều có thể nói Tiếng Anh trôi chảy nếu được luyện tập đúng cách. Mình sẽ giúp bạn sửa những lỗi phát âm nhỏ nhất, luyện phản xạ nghe-nói, và xây dựng vốn từ vựng theo chủ đề. Mình là người cởi mở, vui vẻ và thích tạo môi trường học tập thoải mái nhất.', 'Tiếng Anh giao tiếp tự tin, phát âm chuẩn như người bản xứ.', NULL, 'Cử nhân Ngôn ngữ Anh, Trường Đại học Kinh tế Quốc dân.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh giao tiếp và phát âm. Từng là du học sinh trao đổi tại Mỹ.', 'Cần Thơ', 'Thủ Đức', 'active', true, 4.8, 33, 345, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-540', 'Chào các bạn, mình là Long. Mình yêu thích Vật Lý và phương pháp tư duy mạch lạc để giải quyết vấn đề. Mình không chỉ dạy công thức mà còn giúp các bạn hiểu rõ bản chất vật lý đằng sau. Mình có kinh nghiệm xử lý các dạng bài tập khó, mẹo làm bài nhanh và hiệu quả. Mình nghiêm túc, có kỷ luật nhưng cũng rất tâm huyết. Các bạn học sinh lớp 11-12 ôn thi Đại học hãy về với đội của mình!', 'Vật Lý THPT: Tư duy đột phá, chinh phục mọi dạng bài thi.', NULL, 'Sinh viên năm cuối ngành Kỹ thuật Y sinh, Trường Đại học Y Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Vật Lý THPT. Học sinh của mình đều đạt kết quả cao trong các kỳ thi.', 'Cần Thơ', 'Quận 7', 'active', true, 4.2, 55, 207, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-541', 'Mình là Lan Anh, giáo viên Ngữ văn với 5 năm kinh nghiệm. Mình mong muốn giúp các em học sinh cấp 2 không chỉ nắm vững kiến thức mà còn yêu thích môn Văn. Mình chú trọng phương pháp phân tích tác phẩm một cách sâu sắc, rèn luyện kỹ năng diễn đạt, viết đoạn văn, bài văn theo đúng cấu trúc và có cảm xúc. Mình là người nhẹ nhàng, kiên nhẫn và luôn lắng nghe học sinh.', 'Ngữ văn THCS: Nuôi dưỡng tâm hồn, bồi dưỡng kỹ năng làm văn.', NULL, 'Cử nhân Sư phạm Ngữ văn, Trường Đại học Sư phạm Huế.', NULL, NULL, '5 năm dạy Ngữ văn tại trường THCS. Có kinh nghiệm bồi dưỡng học sinh giỏi Văn cấp thành phố.', 'TP.HCM', 'Hải Châu', 'active', true, 4.9, 48, 420, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-542', 'Hey there! I''m Tuan Anh, your go-to tutor for boosting your IELTS Speaking and Writing scores. I focus on practical strategies, providing clear feedback, and helping you develop fluency and coherence. We''ll work on common mistakes, useful vocabulary, and structuring your answers effectively. My teaching style is energetic and encouraging, perfect for students aiming for that 7.0+.', 'IELTS Speaking & Writing: Tăng điểm thần tốc, tự tin phỏng vấn.', NULL, 'Bachelor of English Language and Literature, Hanoi University.', NULL, NULL, '4 years of intensive IELTS coaching. Proven track record of helping students improve their scores significantly for academic and immigration purposes.', 'Bình Dương', 'Hải Châu', 'active', true, 4.3, 64, 115, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-543', 'Xin chào, mình là Cẩm Tú. Mình yêu thích Sinh Học và muốn chia sẻ sự kỳ diệu của thế giới sinh vật với các bạn. Mình giúp học sinh hiểu rõ các khái niệm phức tạp, nắm vững quy trình, và làm tốt các dạng bài tập từ cơ bản đến nâng cao. Mình có cách diễn đạt dễ hiểu, hình ảnh sinh động và luôn kiên nhẫn giải đáp mọi thắc mắc. Phù hợp với học sinh THPT ôn thi.', 'Sinh Học THPT: Giải mã thế giới sống, đạt điểm cao thi cử.', NULL, 'Sinh viên Y khoa, Trường Đại học Y Dược Cần Thơ.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học. Giúp học sinh cải thiện điểm số và có cái nhìn hứng thú hơn với môn học.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.5, 61, 214, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-544', 'Chào các bạn, mình là Minh. Mình tin rằng Lịch Sử không chỉ là những con số và sự kiện khô khan, mà là những câu chuyện hấp dẫn về con người và dân tộc. Mình giúp các bạn xây dựng kiến thức Lịch Sử một cách logic, dễ nhớ, và biết cách liên hệ với thực tế. Lớp học của mình đề cao sự tương tác, thảo luận và tư duy phản biện. Phù hợp với học sinh THPT muốn hiểu sâu và thi tốt.', 'Lịch Sử không nhàm chán: Khám phá quá khứ, hiểu hiện tại.', NULL, 'Cử nhân Lịch sử, Trường Đại học Khoa học Xã hội và Nhân văn, ĐHQG-HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Lịch Sử. Giúp học sinh có cái nhìn mới mẻ và đạt kết quả tốt trong các kỳ thi.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.7, 22, 137, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-545', 'Chào bạn, mình là Thảo. Mình có kinh nghiệm giảng dạy Tin học văn phòng (Word, Excel, PowerPoint) và các kiến thức lập trình cơ bản cho người mới bắt đầu. Mình có phương pháp dạy dễ hiểu, thực hành nhiều, giúp bạn nhanh chóng làm quen và ứng dụng được. Mình kiên nhẫn, thân thiện và luôn sẵn sàng hỗ trợ. Phù hợp với học sinh, sinh viên và người đi làm.', 'Tin học văn phòng & Lập trình cơ bản cho mọi trình độ.', NULL, 'Cử nhân Công nghệ Thông tin, Học viện Công nghệ Bưu chính Viễn thông.', NULL, NULL, '2 năm kinh nghiệm dạy Tin học. Giúp hàng trăm học viên làm chủ các kỹ năng văn phòng và lập trình cơ bản.', 'Cần Thơ', 'Quận 1', 'active', true, 4.4, 41, 420, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-546', 'Mình là Bảo, mình có kinh nghiệm dạy Hóa học cho học sinh THPT. Mình tập trung vào việc giúp các bạn hiểu rõ bản chất các phản ứng, cách cân bằng phương trình và giải các dạng bài tập phổ biến. Mình có phương pháp giảng dạy khoa học, dễ tiếp thu, kết hợp lý thuyết với bài tập vận dụng ngay. Mình là người nhiệt huyết, có trách nhiệm cao. Phù hợp với các bạn đang cần cải thiện điểm Hóa.', 'Hóa Học THPT: Nắm chắc lý thuyết, giải thành thạo bài tập.', NULL, 'Sinh viên năm 3, Khoa Hóa học, Trường Đại học Khoa học Tự nhiên, ĐHQG-HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi học kỳ và thi thử.', 'Đà Nẵng', 'Quận 7', 'active', true, 4.6, 35, 354, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-547', 'Xin chào, mình là Vy. Mình tin rằng Địa Lý là môn học vô cùng hấp dẫn khi chúng ta nhìn nó qua lăng kính của những câu chuyện, hiện tượng và mối liên hệ thực tế. Mình giúp các bạn học sinh nắm vững kiến thức địa lý tự nhiên và kinh tế - xã hội, đặc biệt là địa lý Việt Nam. Mình có cách dạy sinh động, trực quan, giúp các bạn dễ dàng ghi nhớ và yêu thích môn học. Phù hợp với học sinh THCS và THPT.', 'Địa Lý thú vị: Khám phá Việt Nam và Thế giới.', NULL, 'Cử nhân Địa lý học, Trường Đại học Khoa học Xã hội và Nhân văn, Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý. Giúp học sinh có cái nhìn tổng quan và hứng thú với môn học.', 'Hà Nội', 'Phú Nhuận', 'active', true, 4.8, 28, 284, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-548', 'Mình là Đạt, mình chuyên dạy Toán cao cấp, Lượng giác và các kiến thức nền tảng cho các ngành STEM. Mình tiếp cận vấn đề một cách logic, có hệ thống, giúp học viên xây dựng tư duy toán học vững chắc. Mình có kinh nghiệm giảng dạy cho sinh viên và học sinh cuối cấp. Mình nghiêm túc, tập trung và mong muốn mang lại kiến thức nền tảng tốt nhất cho người học.', 'Toán cao cấp & Lượng giác: Nền tảng vững cho STEM.', NULL, 'Thạc sĩ Toán học ứng dụng, Trường Đại học Bách Khoa TP.HCM.', NULL, NULL, '6 năm kinh nghiệm dạy Toán cao cấp và Lượng giác. Giúp nhiều sinh viên vượt qua môn học khó.', 'Biên Hòa', 'Quận 3', 'active', true, 4.9, 62, 420, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-549', 'Chào bạn, mình là Mai. Mình hiểu rằng bắt đầu học Tiếng Anh khi đã mất gốc là một thử thách lớn. Mình có phương pháp dạy riêng, đi từ những điều cơ bản nhất, xây dựng lại nền tảng ngữ pháp và từ vựng cho bạn. Mình rất kiên nhẫn, tỉ mỉ và luôn động viên bạn tiến bộ từng ngày. Lớp học của mình sẽ giúp bạn tự tin hơn khi giao tiếp và sử dụng Tiếng Anh trong công việc, học tập.', 'Tiếng Anh cho người mất gốc: Tự tin giao tiếp từ con số 0.', NULL, 'Cử nhân Sư phạm Tiếng Anh, Trường Đại học Sư phạm Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Tiếng Anh cho người mất gốc và người đi làm. Nhiều học viên đã giao tiếp tốt sau khóa học.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.1, 51, 154, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-550', 'Mình là Huy, một sinh viên kỹ thuật với niềm đam mê Vật Lý. Mình có kinh nghiệm luyện thi Vật Lý cho học sinh THPT, giúp các bạn nắm vững phương pháp giải nhanh các dạng bài tập từ cơ bản đến nâng cao. Mình thích chia sẻ các mẹo làm bài hiệu quả và xây dựng tư duy logic cho học sinh. Mình khá thân thiện và luôn tạo động lực cho người học. Hãy cùng mình chinh phục điểm cao Vật Lý nhé!', 'Vật Lý THPT & Ôn thi Đại học: Tư duy giải nhanh mọi dạng bài.', NULL, 'Sinh viên năm cuối ngành Kỹ thuật Phần mềm, Trường Đại học Công nghệ, ĐHQG-HN.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý và luyện thi. Nhiều học sinh đạt điểm 9+ môn Vật Lý.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.3, 42, 104, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-551', 'Chào bạn, mình là Hoài. Mình có niềm yêu thích sâu sắc với Văn học Việt Nam và mong muốn chia sẻ những kiến thức, cảm nhận tinh tế về các tác phẩm văn học. Mình giúp học sinh phát triển khả năng cảm thụ văn học, phân tích sâu sắc nội dung và nghệ thuật, từ đó nâng cao kỹ năng viết văn nghị luận. Mình có phong cách giảng dạy nhẹ nhàng, truyền cảm hứng, phù hợp với các bạn học sinh yêu văn.', 'Văn học Việt Nam & Phân tích tác phẩm chuyên sâu.', NULL, 'Cử nhân Văn học, Trường Đại học Văn hóa Hà Nội.', NULL, NULL, '4 năm kinh nghiệm dạy Ngữ văn, đặc biệt là các tác phẩm văn học Việt Nam.', 'Biên Hòa', 'Phú Nhuận', 'active', true, 4.5, 14, 201, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-552', 'Hello! I''m Kiet, specializing in IELTS General Training. I help students prepare effectively for Listening, Speaking, Reading, and Writing, focusing on practical skills and exam strategies. My approach is student-centered, adapting to individual needs and learning styles. I aim to build confidence and ensure you''re well-equipped to achieve your target scores. Let''s make your IELTS journey smoother!', 'IELTS General Training: Chiến lược hiệu quả cho điểm số mong muốn.', NULL, 'TESOL Certified, University of Cambridge.', NULL, NULL, '3 years teaching IELTS General Training. Helped numerous students achieve their goals for immigration and work purposes.', 'TP.HCM', 'Hải Châu', 'active', true, 4.1, 25, 404, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-553', 'Mình là Triết, mình có kinh nghiệm dạy Sinh học cho cả cấp 2 và cấp 3. Mình tập trung vào việc hệ thống hóa kiến thức, giúp các bạn hiểu rõ các khái niệm sinh học một cách logic và dễ nhớ. Mình sẽ giúp bạn xây dựng lộ trình học tập phù hợp, làm quen với các dạng đề thi. Mình là người nghiêm túc, kiên nhẫn và luôn cố gắng truyền tải kiến thức một cách hiệu quả nhất.', 'Sinh Học THCS & THPT: Hệ thống hóa kiến thức, dễ nhớ, dễ thi.', NULL, 'Sinh viên Y Đa khoa, Trường Đại học Y khoa Phạm Ngọc Thạch.', NULL, NULL, '3 năm kinh nghiệm dạy Sinh học. Giúp học sinh cải thiện điểm số và có phương pháp học hiệu quả hơn.', 'Cần Thơ', 'Phú Nhuận', 'active', true, 4.8, 41, 325, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-579', 'Chào bạn, mình là Bảo Trung! Mình muốn mang đến cho bạn một cái nhìn thú vị về Vật lý, cách nó giải thích thế giới xung quanh chúng ta. Mình thường sử dụng các ví dụ thực tế, thí nghiệm mô phỏng và bài tập đa dạng. Mình mong muốn giúp bạn phát triển tư duy khoa học và niềm yêu thích môn Vật lý.', 'Vật lý và tư duy khoa học cùng thầy Trung.', NULL, 'Cử nhân Vật lý, Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Vật lý. Giúp học sinh nắm vững kiến thức cơ bản và nâng cao, phương pháp giải bài tập hiệu quả. Có kinh nghiệm ôn luyện thi THPT.', 'Bình Dương', 'Phú Nhuận', 'active', true, 4.2, 25, 221, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-554', 'Chào các bạn, mình là Yến Nhi. Mình yêu Lịch Sử và muốn mang đến cho các bạn cách học Lịch Sử thật vui vẻ, không hề nhàm chán. Mình sử dụng nhiều hình ảnh, video, câu chuyện thực tế để bài học thêm sinh động. Mình giúp các bạn nắm kiến thức một cách hệ thống, dễ hiểu và nhớ lâu. Mình là người hòa đồng, nhiệt tình và luôn khuyến khích các bạn tương tác, đặt câu hỏi.', 'Lịch Sử Việt Nam & Thế Giới: Học mà chơi, chơi mà học.', NULL, 'Cử nhân Lịch sử Đảng Cộng sản Việt Nam, Học viện Báo chí và Tuyên truyền.', NULL, NULL, '2 năm kinh nghiệm dạy Lịch Sử. Giúp học sinh có cái nhìn mới mẻ và hứng thú với môn học.', 'Biên Hòa', 'Ninh Kiều', 'active', true, 4.8, 32, 438, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-555', 'Mình là Quang, rất vui được đồng hành cùng các bạn trong môn Địa Lý. Mình có phương pháp giảng dạy bám sát chương trình, giúp các bạn nắm chắc kiến thức lý thuyết và kỹ năng phân tích biểu đồ, bản đồ. Mình thích dùng ví dụ thực tế để minh họa bài giảng, giúp các bạn dễ hình dung và ghi nhớ. Mình là người điềm đạm, kiên nhẫn và luôn sẵn lòng giải đáp mọi thắc mắc.', 'Địa Lý Việt Nam & Thế Giới: Kiến thức tổng hợp, thi cử tự tin.', NULL, 'Sinh viên năm cuối ngành Quản lý Đất đai, Trường Đại học Nông nghiệp Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Địa lý. Giúp học sinh hệ thống hóa kiến thức và làm quen với các dạng bài thi.', 'Cần Thơ', 'Quận 7', 'active', true, 4.4, 35, 122, '2026-06-19 03:01:48.235928', '2026-06-19 03:01:48.235928', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-556', 'Chào bạn, mình là Minh Anh! Mình tin rằng học Tiếng Anh có thể rất vui và thú vị. Mình luôn cố gắng tạo ra những giờ học sinh động, cá nhân hóa để phù hợp với từng bạn. Mình đặc biệt yêu thích việc giúp các bạn nhỏ vượt qua nỗi sợ Tiếng Anh và xây dựng sự tự tin.', 'Giáo viên Tiếng Anh giàu kinh nghiệm, giúp học sinh chinh phục mọi kỳ thi.', NULL, 'Tốt nghiệp Đại học Sư phạm Hà Nội, chuyên ngành Sư phạm Tiếng Anh.', NULL, NULL, 'Có 5 năm kinh nghiệm giảng dạy Tiếng Anh cho học sinh từ cấp 2 đến cấp 3. Tỉ lệ học sinh đạt điểm cao trong các bài kiểm tra luôn ở mức ấn tượng. Đã từng bồi dưỡng đội tuyển học sinh giỏi môn Tiếng Anh của trường.', 'TP.HCM', 'Thủ Đức', 'active', true, 4.9, 59, 426, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-557', 'Mình là Hoàng, một người đam mê Toán học và luôn muốn truyền lửa cho các bạn. Phương pháp của mình tập trung vào việc giúp học sinh hiểu bản chất vấn đề thay vì chỉ học thuộc công thức. Mình kiên nhẫn và luôn sẵn sàng giải đáp mọi thắc mắc, đặc biệt phù hợp với các bạn đang gặp khó khăn hoặc muốn nâng cao kiến thức.', 'Thầy Hoàng - Chinh phục Toán học, khơi nguồn tư duy cho học sinh.', NULL, 'Cử nhân Toán học, Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, 'Gia sư Toán được 7 năm, giúp nhiều học sinh cải thiện điểm số rõ rệt. Đã dạy qua các chương trình từ cơ bản đến nâng cao, bao gồm cả luyện thi đại học khối A. Nhiều học trò cũ hiện đang học tại các trường đại học danh tiếng.', 'Hà Nội', 'Hoàng Mai', 'active', true, 5, 38, 186, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-558', 'Mình là Thu Trang, yêu văn chương và muốn chia sẻ tình yêu đó với các bạn. Mình thích cách tiếp cận văn học một cách gần gũi, liên hệ với đời sống để bài học trở nên sinh động hơn. Mình tin rằng ai cũng có thể học tốt Văn nếu có phương pháp phù hợp và sự hứng thú. Đặc biệt phù hợp với các bạn muốn học viết văn hay và có chiều sâu.', 'Cô Trang - Cùng em khám phá vẻ đẹp Tiếng Việt và văn chương.', NULL, 'Thạc sĩ Ngữ văn, Đại học Sư phạm TP.HCM.', NULL, NULL, 'Hơn 4 năm kinh nghiệm dạy Văn, từng là cộng tác viên báo chí. Giúp nhiều học sinh đạt điểm cao trong các kỳ thi học sinh giỏi và tốt nghiệp. Có kinh nghiệm ôn luyện thi vào lớp 10 chuyên Văn.', 'TP.HCM', 'Quận 1', 'active', true, 4.4, 14, 427, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-559', 'Xin chào, mình là Đức Long! Mình có niềm tin mạnh mẽ rằng Vật Lý không hề khô khan mà ẩn chứa những quy luật tuyệt vời của vũ trụ. Mình luôn tìm cách diễn đạt các khái niệm phức tạp một cách trực quan, sinh động thông qua ví dụ thực tế. Nếu bạn thấy Vật Lý khó nhằn, mình sẽ giúp bạn tìm thấy niềm vui trong đó.', 'Thầy Long - Giải thích Vật Lý một cách dễ hiểu và thú vị.', NULL, 'Kỹ sư Điện tử Viễn thông, Đại học Bách Khoa Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Vật Lý cho học sinh THPT. Giúp các bạn nắm vững kiến thức cơ bản và phương pháp giải bài tập. Nhiều học sinh của mình đã đạt điểm khá giỏi môn Vật Lý trong các kỳ thi quan trọng.', 'Hà Nội', 'Quận 3', 'active', true, 4.8, 6, 125, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-560', 'Mình là Bích Ngọc, một người từng trải qua hành trình chinh phục IELTS và hiểu rõ những khó khăn. Mình sẽ đồng hành cùng bạn với lộ trình học tập được thiết kế riêng, tập trung vào việc cải thiện kỹ năng một cách hiệu quả nhất. Mình có sự kiên nhẫn và phương pháp luyện thi bài bản, giúp bạn tự tin bước vào phòng thi.', 'Chinh phục IELTS 7.0+ cùng cô Ngọc - Lộ trình cá nhân hóa.', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Ngoại ngữ - ĐHQG Hà Nội.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS. Giúp hàng trăm học viên đạt mục tiêu điểm số từ 6.0 đến 7.5+. Có kinh nghiệm dạy online và offline, tùy chỉnh bài học theo trình độ và mục tiêu của từng học viên.', 'Cần Thơ', 'Hoàng Mai', 'active', true, 4.4, 46, 198, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-561', 'Mình là Minh Tuấn, một lập trình viên thực thụ và rất hào hứng chia sẻ kiến thức Tin học. Mình không chỉ dạy lý thuyết mà còn chú trọng vào việc thực hành, giúp bạn tự tay xây dựng các sản phẩm. Phương pháp của mình là vừa học vừa chơi, tạo môi trường thoải mái để bạn tiếp thu kiến thức lập trình một cách tự nhiên nhất.', 'Tin học thực chiến cùng Tuấn - Từ lập trình cơ bản đến ứng dụng.', NULL, 'Chuyên ngành Khoa học Máy tính, Đại học Công nghệ - ĐHQG Hà Nội.', NULL, NULL, '2 năm kinh nghiệm làm việc trong ngành phát triển phần mềm. Hơn 3 năm làm gia sư Tin học, dạy lập trình Python, C++. Giúp học sinh làm quen với tư duy lập trình và hoàn thành các dự án cá nhân.', 'Đồng Nai', 'Quận 1', 'active', true, 4.1, 52, 144, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-562', 'Chào các em, mình là Thanh Mai! Hóa học có thể là một thử thách, nhưng mình tin rằng với cách tiếp cận đúng đắn, các em sẽ thấy môn học này thật sự thú vị. Mình thường dùng các thí nghiệm mô phỏng và ví dụ gần gũi để giải thích các khái niệm. Mình rất vui khi thấy học trò của mình tiến bộ và tự tin hơn với môn Hóa.', 'Cô Mai - Bí quyết học Hóa học dễ dàng và hiệu quả.', NULL, 'Cử nhân Hóa học, Đại học Khoa học Tự nhiên - TP.HCM.', NULL, NULL, 'Gia sư Hóa học 4 năm, chuyên ôn luyện cho học sinh THPT. Giúp nhiều em cải thiện điểm số từ trung bình lên khá, giỏi. Có kinh nghiệm dạy cả chương trình cơ bản và nâng cao.', 'Đồng Nai', 'Hoàng Mai', 'active', true, 5, 58, 169, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-563', 'Mình là Minh Khôi, một người luôn tò mò về thế giới tự nhiên. Mình muốn mang đến cho các bạn một cái nhìn mới mẻ về Sinh học, không chỉ là những con số và định nghĩa khô khan. Mình thích sử dụng hình ảnh, video và các hoạt động tương tác để bài học trở nên sống động. Mình rất vui khi được cùng các bạn khám phá những bí ẩn của sự sống.', 'Thầy Khôi - Khám phá thế giới Sinh học đầy kỳ diệu.', NULL, 'Cử nhân Sinh học, Đại học Khoa học Tự nhiên - ĐHQG TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Sinh học cho học sinh THPT. Giúp các em hiểu sâu bài, nhớ lâu kiến thức và làm tốt các bài kiểm tra. Có kinh nghiệm bồi dưỡng học sinh thi Violympic Sinh học.', 'Cần Thơ', 'Bình Thạnh', 'active', true, 4.2, 5, 250, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-564', 'Xin chào, mình là Thu Hà! Địa Lý là một môn học tuyệt vời để hiểu về thế giới xung quanh chúng ta. Mình thích kể chuyện, sử dụng bản đồ và hình ảnh để các bạn dễ dàng hình dung. Mình muốn khơi gợi sự tò mò và yêu thích môn học này ở các bạn, giúp các bạn không chỉ học thuộc mà còn hiểu và yêu đất nước, con người.', 'Cô Hà - Du hành thời gian và không gian qua Địa Lý.', NULL, 'Cử nhân Địa lý học, Đại học Khoa học Xã hội và Nhân văn - ĐHQG TP.HCM.', NULL, NULL, '3 năm kinh nghiệm dạy Địa Lý. Giúp học sinh nắm vững kiến thức địa lý Việt Nam và thế giới, cải thiện kết quả học tập. Có kinh nghiệm ôn luyện thi THPT môn Địa Lý.', 'Đà Nẵng', 'Phú Nhuận', 'active', true, 4.8, 64, 248, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-565', 'Mình là Văn Huy, một người yêu thích những trang sử hào hùng của dân tộc. Mình tin rằng học Lịch sử là học cách hiểu về quá khứ để xây dựng tương lai. Phương pháp của mình là biến những sự kiện lịch sử thành những câu chuyện hấp dẫn, dễ nhớ. Mình kiên nhẫn và luôn tạo không khí học tập thoải mái, giúp các bạn tìm thấy hứng thú với môn Lịch sử.', 'Thầy Huy - Lịch sử không chỉ là những con số, mà là những câu chuyện.', NULL, 'Cử nhân Lịch sử, Đại học Sư phạm Hà Nội.', NULL, NULL, '5 năm kinh nghiệm dạy Lịch sử. Giúp học sinh nắm bắt các sự kiện, nhân vật lịch sử quan trọng và phương pháp phân tích, đánh giá. Nhiều học trò đạt điểm cao trong các bài thi, đặc biệt là thi vào lớp chuyên Sử.', 'Hà Nội', 'Quận 7', 'active', true, 4.3, 8, 272, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-566', 'Hi! Mình là Lan Anh, rất vui được làm quen với bạn. Mình thích tạo ra môi trường học Tiếng Anh thật vui vẻ và tương tác. Mình sẽ giúp bạn luyện tập phát âm, từ vựng và ngữ pháp qua các hoạt động thú vị. Mình tin rằng sự tự tin là chìa khóa, và mình ở đây để giúp bạn xây dựng điều đó.', 'Gia sư Tiếng Anh thân thiện, giúp bạn tự tin giao tiếp.', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học RMIT Việt Nam.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh cho người mới bắt đầu và học sinh cấp 1, cấp 2. Giúp các em làm quen với ngôn ngữ và hình thành thói quen học tập tích cực. Đặc biệt giỏi trong việc tạo động lực cho người học.', 'Cần Thơ', 'Ninh Kiều', 'active', true, 4.1, 20, 132, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-567', 'Chào bạn, mình là Trịnh Bình. Mình không chỉ dạy bạn cách giải bài tập, mà còn giúp bạn phát triển tư duy logic và khả năng giải quyết vấn đề. Mình thường đưa ra các bài toán thực tế, đòi hỏi sự suy luận. Mình kiên nhẫn và luôn khuyến khích học sinh đặt câu hỏi để hiểu sâu vấn đề.', 'Toán học thực tế và tư duy phản biện cùng thầy Bình.', NULL, 'Thạc sĩ Toán học Ứng dụng, Đại học Công nghệ - ĐHQG Hà Nội.', NULL, NULL, '4 năm kinh nghiệm gia sư Toán, chuyên ôn luyện thi đại học khối A, A1. Đã giúp nhiều học sinh đạt điểm tối đa môn Toán. Có kinh nghiệm dạy các dạng toán khó,Olympic Toán.', 'Bình Dương', 'Bình Thạnh', 'active', true, 4.7, 17, 102, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-568', 'Mình là Ngọc Diệp, yêu văn chương và mong muốn truyền cảm hứng học Văn cho các bạn. Mình tập trung vào việc xây dựng kỹ năng phân tích đề, lập dàn ý và viết văn sáng tạo. Mình tin rằng mỗi bài văn là một câu chuyện riêng, và mình sẽ giúp bạn tìm thấy giọng văn độc đáo của mình. Phù hợp với các bạn muốn cải thiện điểm số và có bài văn hay.', 'Cô Diệp - Chắp cánh ước mơ Văn học cho học trò.', NULL, 'Cử nhân Văn học, Đại học Văn hóa Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Văn cho học sinh THPT. Giúp nhiều em vượt qua nỗi sợ môn Văn, đạt kết quả tốt trong học tập. Có kinh nghiệm bồi dưỡng học sinh thi IOE Văn.', 'Cần Thơ', 'Quận 1', 'active', true, 4.6, 62, 296, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-569', 'Mình là Quang Huy, một người rất thích Vật lý và muốn chia sẻ niềm yêu thích đó. Mình có phương pháp giảng dạy rõ ràng, logic, giúp học sinh từng bước chinh phục kiến thức. Mình thường sử dụng các mô phỏng và bài tập đa dạng để củng cố kiến thức. Mình kiên trì và luôn động viên học sinh của mình.', 'Thầy Huy - Vật lý không khó, chỉ cần đúng phương pháp.', NULL, 'Cử nhân Vật lý Kỹ thuật, Đại học Khoa học Tự nhiên - ĐHQG Hà Nội.', NULL, NULL, '2 năm kinh nghiệm dạy Vật lý. Giúp học sinh hiểu sâu các định luật, công thức và phương pháp giải bài tập. Có kinh nghiệm ôn luyện thi tốt nghiệp THPT môn Vật lý.', 'Bình Dương', 'Ninh Kiều', 'active', true, 4.5, 57, 178, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-570', 'Xin chào, mình là Thúy An! Mình tin rằng việc học IELTS có thể hiệu quả và bớt áp lực nếu có chiến lược phù hợp. Mình sẽ giúp bạn xác định điểm mạnh, điểm yếu và xây dựng kế hoạch ôn luyện chi tiết, tập trung vào các kỹ năng bạn cần cải thiện nhất. Mình luôn tạo không khí học tập tích cực và động viên.', 'Tăng band điểm IELTS hiệu quả với lộ trình thông minh từ cô An.', NULL, 'IELTS 8.0, Cử nhân Kinh tế đối ngoại, Đại học Ngoại thương.', NULL, NULL, '2 năm kinh nghiệm luyện thi IELTS. Giúp học sinh đạt mục tiêu điểm số mong muốn, đặc biệt là kỹ năng Writing và Speaking. Có kinh nghiệm dạy online cá nhân và nhóm nhỏ.', 'Hà Nội', 'Thủ Đức', 'active', true, 4.9, 45, 78, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-571', 'Mình là Gia Bảo, một người trẻ năng động và yêu thích công nghệ. Mình muốn giới thiệu Tin học và lập trình một cách gần gũi, dễ tiếp cận. Mình thích sử dụng các ví dụ thực tế và dự án nhỏ để học viên có thể tự tay làm. Phù hợp với các bạn muốn bắt đầu với lập trình hoặc nâng cao kỹ năng Tin học văn phòng.', 'Tin học cho mọi lứa tuổi - Khám phá lập trình cùng Bảo.', NULL, 'Sinh viên năm cuối ngành Khoa học Máy tính, Đại học FPT.', NULL, NULL, '1 năm kinh nghiệm dạy Tin học cơ bản và lập trình Scratch, Python cho học sinh. Giúp các em làm quen với máy tính và tư duy logic.', 'Đồng Nai', 'Quận 1', 'active', true, 4, 65, 441, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-572', 'Chào các bạn, mình là Minh Phương! Mình yêu thích Hóa học và muốn chia sẻ những kiến thức thú vị của nó với các bạn. Mình thường dùng các tình huống thực tế và hình ảnh minh họa để giải thích các khái niệm phức tạp. Mình tin rằng với sự kiên trì và phương pháp phù hợp, ai cũng có thể học tốt Hóa học.', 'Hóa học dễ hiểu qua ví dụ thực tế cùng cô Phương.', NULL, 'Cử nhân Hóa dược, Đại học Dược Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Hóa học. Chuyên ôn luyện cho học sinh THPT. Giúp các em nắm vững kiến thức, phương pháp giải bài tập và cải thiện điểm số.', 'TP.HCM', 'Phú Nhuận', 'active', true, 4.7, 56, 157, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-573', 'Mình là Bảo Nam, một người đam mê nghiên cứu Sinh học. Mình thích mang đến cho học sinh những giờ học không chỉ lý thuyết mà còn có cả thực hành (qua mô phỏng hoặc thí nghiệm đơn giản). Mình muốn khơi gợi sự tò mò và khả năng quan sát của các bạn về thế giới tự nhiên. Phù hợp với các bạn muốn hiểu sâu về Sinh học và chuẩn bị cho các kỳ thi.', 'Sinh học thực nghiệm và khám phá - Thầy Nam.', NULL, 'Thạc sĩ Sinh học Phân tử, Đại học Khoa học Tự nhiên - ĐHQG HN.', NULL, NULL, '4 năm kinh nghiệm dạy Sinh học. Giúp học sinh nắm chắc kiến thức chuyên sâu, phương pháp làm bài thi. Có kinh nghiệm hướng dẫn học sinh làm các dự án khoa học nhỏ.', 'Đồng Nai', 'Phú Nhuận', 'active', true, 4.5, 40, 210, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-574', 'Chào bạn, mình là Thúy Quỳnh! Mình yêu thích khám phá thế giới qua những trang sách Địa lý. Mình muốn truyền tải niềm đam mê đó đến bạn bằng cách sử dụng bản đồ, hình ảnh và những câu chuyện thực tế. Mình tin rằng Địa lý sẽ trở nên thú vị hơn khi bạn hiểu về sự kết nối giữa con người và môi trường.', 'Địa lý thế giới và Việt Nam - Cùng khám phá với cô Quỳnh.', NULL, 'Cử nhân Địa lý học, Đại học Sư phạm Hà Nội.', NULL, NULL, '3 năm kinh nghiệm dạy Địa lý. Giúp học sinh hiểu rõ bản đồ, các hiện tượng tự nhiên và kinh tế - xã hội. Có kinh nghiệm ôn luyện thi THPT môn Địa Lý, đạt kết quả tốt.', 'Hà Nội', 'Quận 1', 'active', true, 4.1, 20, 394, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-575', 'Mình là Minh Đức, một người yêu thích tìm hiểu về quá khứ. Mình muốn biến những bài học Lịch sử khô khan thành những câu chuyện hấp dẫn, giúp bạn dễ dàng ghi nhớ và hiểu sâu sắc hơn. Mình khuyến khích học sinh tư duy phản biện và liên hệ lịch sử với cuộc sống hiện tại. Mình luôn kiên nhẫn và nhiệt tình.', 'Thầy Đức - Lịch sử Việt Nam và Thế giới sống động.', NULL, 'Cử nhân Lịch sử Đảng, Đại học Khoa học Xã hội và Nhân văn - ĐHQG HN.', NULL, NULL, '4 năm kinh nghiệm dạy Lịch sử. Giúp học sinh nắm vững các mốc thời gian, sự kiện quan trọng và phương pháp phân tích lịch sử. Có kinh nghiệm ôn thi HSG môn Sử.', 'TP.HCM', 'Ninh Kiều', 'active', true, 4.5, 54, 407, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-577', 'Mình là Trung Kiên, một người luôn nỗ lực để giúp học sinh xây dựng một nền tảng Toán học thật vững chắc. Mình tập trung vào việc giúp bạn hiểu rõ bản chất của từng dạng bài, từ đó tự tin áp dụng vào các bài tập khó hơn. Mình kiên nhẫn, tỉ mỉ và luôn tạo không khí học tập tích cực.', 'Thầy Kiên - Nền tảng Toán học vững chắc, vượt qua mọi thử thách.', NULL, 'Cử nhân Sư phạm Toán học, Đại học Sư phạm TP.HCM.', NULL, NULL, '5 năm kinh nghiệm gia sư Toán. Giúp học sinh cải thiện đáng kể kết quả học tập, đặc biệt là các em gặp khó khăn. Có kinh nghiệm ôn luyện thi vào lớp 10 và thi đại học.', 'Biên Hòa', 'Hải Châu', 'pending_approval', true, 4, 42, 149, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-578', 'Mình là Bích Thủy, yêu văn chương và tin rằng nó có thể mang lại nhiều bài học giá trị cho cuộc sống. Mình giúp học sinh phân tích tác phẩm sâu sắc, cảm nhận vẻ đẹp ngôn từ và xây dựng kỹ năng viết văn mạch lạc, giàu cảm xúc. Mình mong muốn khơi gợi tình yêu Văn học ở các bạn.', 'Cô Thủy - Văn học và những bài học ý nghĩa.', NULL, 'Cử nhân Sư phạm Ngữ văn, Đại học An Giang.', NULL, NULL, '3 năm kinh nghiệm dạy Văn. Giúp học sinh nắm vững kiến thức, phương pháp làm bài thi học sinh giỏi và thi THPT. Có kinh nghiệm bồi dưỡng học sinh thi IOE Văn.', 'Bình Dương', 'Phú Nhuận', 'pending_approval', true, 4.8, 16, 182, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-576', 'Hi there! Mình là Thảo Nhi, rất vui được đồng hành cùng bạn trên con đường chinh phục Tiếng Anh. Mình tập trung vào việc xây dựng sự tự tin khi giao tiếp, giúp bạn nói Tiếng Anh một cách tự nhiên và trôi chảy. Mình sử dụng nhiều hoạt động tương tác, trò chơi và các tình huống thực tế để bài học thêm phần sinh động.', 'Tiếng Anh giao tiếp tự tin cho mọi lứa tuổi cùng cô Nhi.', NULL, 'Cử nhân Ngôn ngữ Anh, Đại học Kinh tế TP.HCM.', NULL, NULL, '2 năm kinh nghiệm dạy Tiếng Anh giao tiếp. Giúp học sinh từ mất gốc đến giao tiếp lưu loát. Có kinh nghiệm dạy cho người đi làm và sinh viên.', 'Cần Thơ', 'Hải Châu', 'pending_approval', true, 4.6, 55, 353, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('seed-tutor-580', 'Mình là Thanh Huyền, một người có kinh nghiệm dày dặn trong việc luyện thi IELTS. Mình hiểu rằng mỗi bạn có một thế mạnh và điểm yếu riêng, vì vậy mình luôn cá nhân hóa lộ trình học tập. Mình sẽ tập trung vào việc tối ưu hóa chiến lược làm bài và cung cấp các mẹo hữu ích để bạn đạt được band điểm mong muốn.', 'IELTS - Chinh phục mục tiêu điểm số cùng cô Huyền.', NULL, 'IELTS 7.5, Cử nhân Tài chính Ngân hàng, Đại học Kinh tế Quốc dân.', NULL, NULL, '3 năm kinh nghiệm luyện thi IELTS. Giúp nhiều học viên đạt mục tiêu điểm số từ 6.5 đến 8.0. Chuyên sâu về kỹ năng Writing và Listening.', 'Cần Thơ', 'Hải Châu', 'pending_approval', true, 4.7, 27, 225, '2026-06-19 03:02:21.980358', '2026-06-19 03:02:21.980358', NULL, 'free', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, 0, NULL, NULL, NULL, 'online');
INSERT INTO public.tutorprofiles VALUES ('d30d351d-fee5-4d4f-a074-5413a800c387', 'Cử nhân Sư phạm Toán - ĐHSP TP.HCM. 8 năm kinh nghiệm luyện thi THPT Quốc Gia môn Toán. Tỷ lệ học sinh đạt 8+ điểm là 85%. Phương pháp dạy logic, hệ thống theo dạng bài.
